// Domain Models

export interface Student {
  id: string;
  name: string;
  nis: string;
}

export interface LearningObjective { // TP (Tujuan Pembelajaran)
  id: string;
  code: string; // e.g., TP.1
  description: string;
}

export interface LearningMaterial { // LM (Lingkup Materi)
  id: string;
  code: string; // e.g., LM.1
  title: string;
}

export interface Subject {
  id: string;
  name: string;
  kktp: number; // Kriteria Ketercapaian Tujuan Pembelajaran (Passing Grade)
}

export interface GradeData {
  [studentId: string]: {
    formative: { [tpId: string]: number }; // Nilai TP
    summative: { [lmId: string]: number }; // Nilai LM
    attitude: number; // Nilai Sikap
  };
}

export interface CalculatedGrade {
  avgFormative: number;
  avgSummative: number;
  finalScore: number;
  isPassed: boolean;
}

export enum TabView {
  BLUEPRINT = 'BLUEPRINT',
