}

import { GradeData, CalculatedGrade } from '../types';

/**
 * FUNGSI PERHITUNGAN NILAI (Function 7 from Prompt)
 * 
 * Logic:
 * Final Score = (AVG(Formative) * 0.4) + (AVG(Summative) * 0.5) + (Attitude * 0.1)
 */
export const calculateStudentGrade = (
  studentId: string,
  gradeData: GradeData,
  kktp: number
): CalculatedGrade => {
  const studentGrades = gradeData[studentId];

  if (!studentGrades) {
    return { avgFormative: 0, avgSummative: 0, finalScore: 0, isPassed: false };
  }

  // 1. Calculate Average Formative (TP)
  const formativeValues = Object.values(studentGrades.formative).filter(v => v !== undefined && v !== null && !isNaN(v));
  const avgFormative = formativeValues.length > 0
    ? formativeValues.reduce((a, b) => a + b, 0) / formativeValues.length
    : 0;

  // 2. Calculate Average Summative (LM)
  const summativeValues = Object.values(studentGrades.summative).filter(v => v !== undefined && v !== null && !isNaN(v));
  const avgSummative = summativeValues.length > 0
    ? summativeValues.reduce((a, b) => a + b, 0) / summativeValues.length
    : 0;

  // 3. Get Attitude Score (Default to 0 if missing, though typically required)
  const attitude = studentGrades.attitude || 0;

  // 4. Apply Formula
  // (AVG(nilai_formatif) × 0.4) + (AVG(nilai_sumatif) × 0.5) + (nilai_sikap × 0.1)
  const finalScoreRaw = (avgFormative * 0.4) + (avgSummative * 0.5) + (attitude * 0.1);
  const finalScore = Math.round(finalScoreRaw * 100) / 100; // Round to 2 decimals

  return {
    avgFormative,
    avgSummative,
    finalScore,
    isPassed: finalScore >= kktp
  };
};

