// 1. Controller (infrastructure/controllers/GradeController.ts)
export class GradeController {
  constructor(private gradeService: GradeService) {}

  async upsertGrades(req: Request, res: Response) {
    try {
      // Expects array of { studentId, assessmentId, score }
      const result = await this.gradeService.bulkUpsert(req.body.grades);
      return res.json({ success: true, data: result });
    } catch (error) {
      return res.status(400).json({ error: error.message });
    }
  }
}

// 2. Service (app/services/GradeService.ts)
export class GradeService {
  constructor(private gradeRepo: IGradeRepository) {}

  async bulkUpsert(grades: GradeDTO[]) {
    // Validate inputs
    // Perform bulk write
    return await this.gradeRepo.saveBatch(grades);
  }

  async calculateFinalScore(studentId: string, subjectId: string) {
    const scores = await this.gradeRepo.findByStudentSubject(studentId, subjectId);

    // Implementation of the mandatory formula
    const formativeAvg = this.calculateAvg(scores.formative);
    const summativeAvg = this.calculateAvg(scores.summative);
    const attitude = scores.attitude;

    // Formula: (Formatif * 0.4) + (Sumatif * 0.5) + (Sikap * 0.1)
    const finalScore = (formativeAvg * 0.4) + (summativeAvg * 0.5) + (attitude * 0.1);

    return Math.round(finalScore * 100) / 100;
  }

  private calculateAvg(scores: number[]): number {
    if (scores.length === 0) return 0;
    return scores.reduce((a, b) => a + b, 0) / scores.length;
  }
}
