import React, { useState } from 'react';
import { Student, Subject, AttendanceData, AttendanceSession, AttendanceStatus } from '../types';

interface Props {
  students: Student[];
  subject: Subject;
  sessions: AttendanceSession[];
}

export const AttendanceSheet: React.FC<Props> = ({ students, subject, sessions }) => {
  const [attendanceData, setAttendanceData] = useState<AttendanceData>({});

  // Initialize data (optional, ensures object structure)
  // In a real app, this would be fetched from API

  const handleStatusClick = (studentId: string, sessionId: string) => {
    setAttendanceData(prev => {
      const studentRecords = prev[studentId] || {};
      const currentStatus = studentRecords[sessionId] || 'H';

      // Cycle: H -> I -> S -> A -> H
      let nextStatus: AttendanceStatus = 'H';
      if (currentStatus === 'H') nextStatus = 'I';
      else if (currentStatus === 'I') nextStatus = 'S';
      else if (currentStatus === 'S') nextStatus = 'A';
      else if (currentStatus === 'A') nextStatus = 'H';

      return {
        ...prev,
        [studentId]: {
          ...studentRecords,
          [sessionId]: nextStatus
        }
      };
    });
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'H': return 'bg-white text-gray-800';
      case 'I': return 'bg-blue-100 text-blue-800';
      case 'S': return 'bg-yellow-100 text-yellow-800';
      case 'A': return 'bg-red-100 text-red-800 font-bold';
      default: return 'bg-white';
    }
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-lg shadow border border-gray-200 overflow-hidden">
      <div className="p-4 border-b flex justify-between items-center bg-gray-50">
        <div>
          <h2 className="text-lg font-bold text-gray-800">Absensi: {subject.name}</h2>
          <p className="text-sm text-gray-500">Klik pada sel untuk mengubah status (H &rarr; I &rarr; S &rarr; A)</p>
        </div>
        <div className="flex gap-2">
           <button className="px-4 py-2 bg-white border border-gray-300 text-gray-700 rounded hover:bg-gray-50 text-sm font-medium">
            + Tambah Pertemuan
          </button>
          <button className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 text-sm font-medium">
            Simpan Absensi
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-auto relative scrollbar-thin">
        <table className="w-full border-collapse text-sm">
          <thead className="bg-gray-100 sticky top-0 z-10 shadow-sm">
            <tr>
              <th className="border p-3 min-w-[50px] text-center bg-gray-100 sticky left-0 z-20">No</th>
              <th className="border p-3 min-w-[250px] text-left bg-gray-100 sticky left-[50px] z-20">Nama Siswa</th>
              {sessions.map((session, idx) => (
                <th key={session.id} className="border p-2 min-w-[80px] text-center bg-gray-100">
                  <div className="text-xs text-gray-500">P.{idx + 1}</div>
                  <div className="font-medium">{new Date(session.date).toLocaleDateString('id-ID', {day: 'numeric', month:'short'})}</div>
                </th>
              ))}
              <th className="border p-3 w-[200px] text-center bg-gray-100">Rekap (H/I/S/A)</th>
            </tr>
          </thead>
          <tbody>
            {students.map((student, index) => {
              // Calculate summary on the fly
              const studentRecs = attendanceData[student.id] || {};
              const counts = { H: 0, I: 0, S: 0, A: 0 };
              sessions.forEach(s => {
                 const status = studentRecs[s.id] || 'H'; // Default to Present
                 counts[status]++;
              });

              return (
                <tr key={student.id} className="hover:bg-gray-50">
                  <td className="border p-2 text-center bg-white sticky left-0 z-10">{index + 1}</td>
                  <td className="border p-2 bg-white sticky left-[50px] z-10 font-medium text-gray-700">
                    <div>{student.name}</div>
                    <div className="text-xs text-gray-400">{student.nis}</div>
                  </td>
                  {sessions.map(session => {
                    const status = attendanceData[student.id]?.[session.id] || 'H';
                    return (
                      <td 
                        key={session.id} 
                        className={`border p-2 text-center cursor-pointer select-none transition-colors ${getStatusColor(status)}`}
                        onClick={() => handleStatusClick(student.id, session.id)}
                      >
                        {status}
                      </td>
                    );
                  })}
                  <td className="border p-2 text-center text-xs font-mono">
                    <span className="text-gray-900 font-bold">{counts.H}</span> / 
                    <span className="text-blue-600"> {counts.I}</span> / 
                    <span className="text-yellow-600"> {counts.S}</span> / 
                    <span className="text-red-600 font-bold"> {counts.A}</span>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

