import React, { useState, useMemo, useCallback } from 'react';
import { z } from 'zod'; // Import Zod
import ExcelJS from 'exceljs'; // Import ExcelJS
import { 
  Student, 
  LearningObjective, 
  LearningMaterial, 
  GradeData, 
  Subject 
} from '../types';
import { calculateStudentGrade } from '../utils/grading';

interface Props {
  students: Student[];
  tps: LearningObjective[];
  lms: LearningMaterial[];
  subject: Subject;
}

// 1. Zod Schema for Score Validation
const scoreSchema = z.number().min(0, "Nilai min 0").max(100, "Nilai max 100").optional();

export const GradingSheet: React.FC<Props> = ({ students, tps, lms, subject }) => {
  const [gradeData, setGradeData] = useState<GradeData>({});
  const [errorMap, setErrorMap] = useState<{[key: string]: string}>({});
  const [isExporting, setIsExporting] = useState(false);

  // Handle Input Change with Zod Validation
  const handleScoreChange = useCallback((
    studentId: string, 
    type: 'formative' | 'summative' | 'attitude', 
    id: string | 'value', 
    value: string
  ) => {
    const numValue = value === '' ? undefined : parseFloat(value);

    // Validate immediately
    const result = scoreSchema.safeParse(numValue);
    const errorKey = `${studentId}-${type}-${id}`;

    if (!result.success && value !== '') {
        setErrorMap(prev => ({...prev, [errorKey]: result.error.errors[0].message}));
    } else {
        setErrorMap(prev => {
            const newMap = {...prev};
            delete newMap[errorKey];
            return newMap;
        });
    }

    setGradeData(prev => {
      const studentData = prev[studentId] || { formative: {}, summative: {}, attitude: 0 };

      if (type === 'formative') {
        return {
          ...prev,
          [studentId]: {
            ...studentData,
            formative: { ...studentData.formative, [id]: numValue as number }
          }
        };
      } else if (type === 'summative') {
        return {
          ...prev,
          [studentId]: {
            ...studentData,
            summative: { ...studentData.summative, [id]: numValue as number }
          }
        };
      } else {
        return {
          ...prev,
          [studentId]: {
            ...studentData,
            attitude: numValue || 0
          }
        };
      }
    });
  }, []);

  // 2. ExcelJS Export Implementation
  const handleExportExcel = async () => {
    setIsExporting(true);
    try {
        const workbook = new ExcelJS.Workbook();
        const sheet = workbook.addWorksheet('Rekap Nilai');

        // Headers
        const headerRow = [
            'No', 'NIS', 'Nama Siswa',
            ...tps.map(tp => `TP: ${tp.code}`),
            ...lms.map(lm => `LM: ${lm.code}`),
            'Sikap', 'Nilai Akhir', 'Status'
        ];
        sheet.addRow(headerRow);

        // Data
        students.forEach((student, index) => {
            const res = calculateStudentGrade(student.id, gradeData, subject.kktp);
            const row = [
                index + 1,
                student.nis,
                student.name,
                ...tps.map(tp => gradeData[student.id]?.formative?.[tp.id] ?? ''),
                ...lms.map(lm => gradeData[student.id]?.summative?.[lm.id] ?? ''),
                gradeData[student.id]?.attitude ?? '',
                res.finalScore,
                res.isPassed ? 'Tuntas' : 'Belum Tuntas'
            ];
            sheet.addRow(row);
        });

        // Generate Buffer & Download
        const buffer = await workbook.xlsx.writeBuffer();
        const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const url = window.URL.createObjectURL(blob);
        const anchor = document.createElement('a');
        anchor.href = url;
        anchor.download = `Nilai-${subject.name}.xlsx`;
        anchor.click();
        window.URL.revokeObjectURL(url);
    } catch (err) {
        console.error("Export failed", err);
        alert("Gagal melakukan export excel.");
    } finally {
        setIsExporting(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-lg shadow border border-gray-200 overflow-hidden">
      {/* Header Controls */}
      <div className="p-4 border-b flex justify-between items-center bg-gray-50">
        <div>
          <h2 className="text-lg font-bold text-gray-800">Input Nilai: {subject.name}</h2>
          <p className="text-sm text-gray-500">KKTP (Batas Tuntas): <span className="font-mono font-bold text-blue-600">{subject.kktp}</span></p>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={handleExportExcel}
            disabled={isExporting}
            className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 text-sm font-medium flex items-center gap-2 disabled:opacity-50"
          >
            {isExporting ? 'Exporting...' : (
                <>
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                Export Excel
                </>
            )}
          </button>
          <button className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 text-sm font-medium">
            Simpan Nilai
          </button>
        </div>
      </div>

      {/* The Excel-like Matrix */}
      <div className="flex-1 overflow-auto relative scrollbar-thin">
        <table className="w-full border-collapse text-sm">
          <thead className="bg-gray-100 sticky top-0 z-10 shadow-sm">
            <tr>
              <th rowSpan={2} className="border p-2 min-w-[50px] text-center bg-gray-100 sticky left-0 z-20">No</th>
              <th rowSpan={2} className="border p-2 min-w-[200px] text-left bg-gray-100 sticky left-[50px] z-20">Nama Siswa</th>

              {/* Formative Header */}
              <th colSpan={tps.length} className="border p-2 bg-blue-50 text-blue-800">
                Nilai Formatif (TP) <span className="text-xs font-normal text-blue-600">Bobot 40%</span>
              </th>

              {/* Summative Header */}
              <th colSpan={lms.length} className="border p-2 bg-purple-50 text-purple-800">
                Nilai Sumatif (LM) <span className="text-xs font-normal text-purple-600">Bobot 50%</span>
              </th>

              {/* Attitude & Final */}
              <th rowSpan={2} className="border p-2 w-[80px] bg-yellow-50 text-yellow-800">Sikap (10%)</th>
              <th rowSpan={2} className="border p-2 w-[80px] bg-gray-200 font-bold">Nilai Akhir</th>
              <th rowSpan={2} className="border p-2 w-[100px] bg-gray-200">Status</th>
            </tr>
            <tr>
              {/* TP Sub-headers */}
              {tps.map(tp => (
                <th key={tp.id} className="border p-2 w-[60px] text-center bg-blue-50 font-medium text-xs">
                  <div className="group relative cursor-help">
                    {tp.code}
                    <div className="absolute hidden group-hover:block bg-black text-white p-2 rounded text-xs w-48 -left-10 top-full mt-1 z-50 font-normal">
                      {tp.description}
                    </div>
                  </div>
                </th>
              ))}

              {/* LM Sub-headers */}
              {lms.map(lm => (
                <th key={lm.id} className="border p-2 w-[60px] text-center bg-purple-50 font-medium text-xs">
                  <div className="group relative cursor-help">
                    {lm.code}
                     <div className="absolute hidden group-hover:block bg-black text-white p-2 rounded text-xs w-48 -left-10 top-full mt-1 z-50 font-normal">
                      {lm.title}
                    </div>
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {students.map((student, index) => {
              const result = calculateStudentGrade(student.id, gradeData, subject.kktp);

              return (
                <tr key={student.id} className="hover:bg-gray-50 group">
                  <td className="border p-2 text-center bg-white sticky left-0 z-10 group-hover:bg-gray-50">{index + 1}</td>
                  <td className="border p-2 bg-white sticky left-[50px] z-10 group-hover:bg-gray-50 font-medium text-gray-700">
                    <div>{student.name}</div>
                    <div className="text-xs text-gray-400">{student.nis}</div>
                  </td>

                  {/* Input Formative */}
                  {tps.map(tp => {
                    const err = errorMap[`${student.id}-formative-${tp.id}`];
                    return (
                        <td key={tp.id} className="border p-0 relative">
                        <input
                            type="number"
                            min="0"
                            max="100"
                            className={`w-full h-full p-2 text-center focus:outline-none transition-colors ${err ? 'bg-red-50 text-red-600' : 'focus:bg-blue-100'}`}
                            placeholder="-"
                            value={gradeData[student.id]?.formative?.[tp.id] ?? ''}
                            onChange={(e) => handleScoreChange(student.id, 'formative', tp.id, e.target.value)}
                            title={err}
                        />
                        </td>
                    );
                  })}

                  {/* Input Summative */}
                  {lms.map(lm => {
                    const err = errorMap[`${student.id}-summative-${lm.id}`];
                    return (
                        <td key={lm.id} className="border p-0 relative">
                        <input
                            type="number"
                            min="0"
                            max="100"
                            className={`w-full h-full p-2 text-center focus:outline-none transition-colors ${err ? 'bg-red-50 text-red-600' : 'focus:bg-purple-100'}`}
                            placeholder="-"
                            value={gradeData[student.id]?.summative?.[lm.id] ?? ''}
                            onChange={(e) => handleScoreChange(student.id, 'summative', lm.id, e.target.value)}
                            title={err}
                        />
                        </td>
                    );
                  })}

                  {/* Input Attitude */}
                  <td className="border p-0">
                     <input
                        type="number"
                        min="0"
                        max="100"
                        className="w-full h-full p-2 text-center focus:outline-none focus:bg-yellow-100 transition-colors font-medium"
                        placeholder="-"
                        value={gradeData[student.id]?.attitude || ''}
                        onChange={(e) => handleScoreChange(student.id, 'attitude', 'value', e.target.value)}
                      />
                  </td>

                  {/* Auto Calculated Results */}
                  <td className="border p-2 text-center font-bold bg-gray-50">
                    {result.finalScore > 0 ? result.finalScore : '-'}
                  </td>
                  <td className={`border p-2 text-center text-xs font-bold ${result.finalScore === 0 ? 'text-gray-400' : result.isPassed ? 'text-green-600 bg-green-50' : 'text-red-600 bg-red-50'}`}>
                    {result.finalScore === 0 ? '-' : result.isPassed ? 'TUNTAS' : 'REMEDIAL'}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <div className="bg-gray-50 p-2 text-xs text-gray-500 border-t flex justify-between">
        <span>Rumus: (Rata-rata TP × 40%) + (Rata-rata LM × 50%) + (Sikap × 10%)</span>
        <span className="text-gray-400 italic">Validasi aktif: Min 0, Max 100 (Zod)</span>
      </div>
    </div>
  );
};

