              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>
              Dashboard Utama
            </button>

            <div className="text-xs font-semibold text-gray-400 uppercase tracking-wider mb-2 mt-2 px-2">Modul</div>
            <button
              onClick={() => setActiveTab(TabView.BLUEPRINT)}
              className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === TabView.BLUEPRINT ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:bg-gray-50'}`}
            >
              Data & Blueprint
            </button>
            <button
              onClick={() => setActiveTab(TabView.GRADING)}
              className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === TabView.GRADING ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:bg-gray-50'}`}
            >
              Input Nilai
            </button>
            <button
              onClick={() => setActiveTab(TabView.ATTENDANCE)}
              className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium transition-colors ${activeTab === TabView.ATTENDANCE ? 'bg-blue-50 text-blue-700' : 'text-gray-600 hover:bg-gray-50'}`}
            >
              Input Absensi
            </button>
          </nav>

          <div className="p-4 border-t border-gray-100">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center text-blue-700 font-bold border border-blue-200">H</div>
              <div>
                <p className="text-sm font-medium">Handiswan</p>
                <p className="text-xs text-gray-500">Guru Informatika</p>
              </div>
            </div>
          </div>
        </aside>

        {/* Main Content */}
        <main className="flex-1 md:ml-64 p-4 md:p-6 overflow-x-hidden h-screen bg-white">
          {activeTab === TabView.DASHBOARD && <Dashboard onNavigate={setActiveTab} />}
          {activeTab === TabView.BLUEPRINT && <SystemBlueprint />}
          {activeTab === TabView.GRADING && (
            <div className="h-full">
              <GradingSheet 
                students={MOCK_STUDENTS}
                tps={MOCK_TPS}
                lms={MOCK_LMS}
                subject={MOCK_SUBJECT}
              />
            </div>
          )}
          {activeTab === TabView.ATTENDANCE && (
            <div className="h-full">
              <AttendanceSheet 
                students={MOCK_STUDENTS}
                subject={MOCK_SUBJECT}
                sessions={MOCK_SESSIONS}
              />
            </div>
          )}
        </main>
      </div>
    </QueryClientProvider>
  );
}

// Domain Models

export interface Student {
  id: string;
  name: string;
  nis: string;
}

export interface LearningObjective { // TP (Tujuan Pembelajaran)
  id: string;
  code: string; // e.g., TP.1
  description: string;
}

export interface LearningMaterial { // LM (Lingkup Materi)
  id: string;
  code: string; // e.g., LM.1
  title: string;
}

export interface Subject {
  id: string;
  name: string;
  kktp: number; // Kriteria Ketercapaian Tujuan Pembelajaran (Passing Grade)
}

export interface GradeData {
  [studentId: string]: {
    formative: { [tpId: string]: number }; // Nilai TP
    summative: { [lmId: string]: number }; // Nilai LM
    attitude: number; // Nilai Sikap
  };
}

export interface CalculatedGrade {
  avgFormative: number;
  avgSummative: number;
  finalScore: number;
  isPassed: boolean;
}

// Identity Data
export interface IdentityData {
  schoolName: string;
  subjectName: string;
  teacherName: string;
  nip: string;
  semester: string;
  academicYear: string;
  className: string;
  studentCount: number;
}

// Attendance Types
export type AttendanceStatus = 'H' | 'I' | 'S' | 'A'; // Hadir, Izin, Sakit, Alfa

export interface AttendanceSession {
  id: string;
  date: string;
  topic: string;
}

export interface AttendanceData {
  [studentId: string]: {
    [sessionId: string]: AttendanceStatus;
  };
}

