import React, { useState } from 'react';
import { LearningMaterial, LearningObjective, Subject } from '../types';

interface Props {
  subject: Subject;
  tps: LearningObjective[];
  lms: LearningMaterial[];
  onUpdateSubject: (kktp: number) => void;
  onUpdateTPs: (tps: LearningObjective[]) => void;
  onUpdateLMs: (lms: LearningMaterial[]) => void;
  onBack: () => void;
}

export const CurriculumManager: React.FC<Props> = ({ 
  subject, tps, lms, onUpdateSubject, onUpdateTPs, onUpdateLMs, onBack 
}) => {
  const [activeTab, setActiveTab] = useState<'TP' | 'LM'>('TP');

  // State for Inputs
  const [newTpCode, setNewTpCode] = useState('');
  const [newTpDesc, setNewTpDesc] = useState('');
  const [newLmCode, setNewLmCode] = useState('');
  const [newLmTitle, setNewLmTitle] = useState('');

  // Handlers
  const handleAddTP = () => {
    if (!newTpCode || !newTpDesc) return;
    const newTP: LearningObjective = {
      id: Date.now().toString(),
      code: newTpCode,
      description: newTpDesc
    };
    onUpdateTPs([...tps, newTP]);
    setNewTpCode('');
    setNewTpDesc('');
  };

  const handleDeleteTP = (id: string) => {
    if (confirm('Hapus Tujuan Pembelajaran ini?')) {
      onUpdateTPs(tps.filter(t => t.id !== id));
    }
  };

  const handleAddLM = () => {
    if (!newLmCode || !newLmTitle) return;
    const newLM: LearningMaterial = {
      id: Date.now().toString(),
      code: newLmCode,
      title: newLmTitle
    };
    onUpdateLMs([...lms, newLM]);
    setNewLmCode('');
    setNewLmTitle('');
  };

  const handleDeleteLM = (id: string) => {
    if (confirm('Hapus Lingkup Materi ini?')) {
      onUpdateLMs(lms.filter(l => l.id !== id));
    }
  };

  return (
    <div className="h-full flex flex-col bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Header */}
        <div className="bg-gray-50 p-6 border-b flex justify-between items-center">
            <div>
                <h2 className="text-xl font-bold text-gray-800">Manajemen Kurikulum & KKTP</h2>
                <p className="text-sm text-gray-500">Atur Tujuan Pembelajaran dan Batas Ketuntasan</p>
            </div>
             <button onClick={onBack} className="text-gray-500 hover:text-gray-700 font-medium">
                &larr; Kembali
            </button>
        </div>

        {/* KKTP Setting */}
        <div className="p-6 bg-blue-50 border-b flex items-center gap-4">
            <div className="bg-blue-100 p-2 rounded-lg text-blue-600">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" /></svg>
            </div>
            <div className="flex-1">
                <label className="text-sm font-bold text-gray-700">KKTP (Kriteria Ketercapaian Tujuan Pembelajaran)</label>
                <p className="text-xs text-gray-500">Nilai minimum agar siswa dianggap tuntas.</p>
            </div>
            <input 
                type="number" 
                value={subject.kktp}
                onChange={(e) => onUpdateSubject(Number(e.target.value))}
                className="w-24 p-2 text-center text-xl font-bold text-blue-700 border-2 border-blue-200 rounded-lg focus:ring-blue-500 focus:border-blue-500 outline-none"
            />
        </div>

        {/* Tabs */}
        <div className="flex border-b">
            <button 
                onClick={() => setActiveTab('TP')}
                className={`flex-1 py-4 text-sm font-bold text-center border-b-2 transition-colors ${activeTab === 'TP' ? 'border-blue-600 text-blue-600 bg-blue-50/50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Tujuan Pembelajaran (TP)
            </button>
            <button 
                 onClick={() => setActiveTab('LM')}
                className={`flex-1 py-4 text-sm font-bold text-center border-b-2 transition-colors ${activeTab === 'LM' ? 'border-purple-600 text-purple-600 bg-purple-50/50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Lingkup Materi (LM)
            </button>
        </div>

        {/* Content */}
        <div className="flex-1 p-6 overflow-y-auto bg-gray-50/50">
            {activeTab === 'TP' ? (
                <div className="space-y-6">
                    {/* Add TP Form */}
                    <div className="bg-white p-4 rounded-xl shadow-sm border border-blue-100 flex gap-4 items-end">
                        <div className="w-1/4">
                            <label className="text-xs font-bold text-gray-500 uppercase">Kode TP</label>
                            <input 
                                type="text" placeholder="Contoh: TP.1" 
                                value={newTpCode} onChange={e => setNewTpCode(e.target.value)}
                                className="w-full mt-1 p-2 border rounded focus:ring-2 focus:ring-blue-200 outline-none"
                            />
                        </div>
                        <div className="flex-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Deskripsi Tujuan Pembelajaran</label>
                            <input 
                                type="text" placeholder="Contoh: Menjelaskan konsep algoritma" 
                                value={newTpDesc} onChange={e => setNewTpDesc(e.target.value)}
                                className="w-full mt-1 p-2 border rounded focus:ring-2 focus:ring-blue-200 outline-none"
                            />
                        </div>
                        <button onClick={handleAddTP} className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 font-medium">
                            + Tambah
                        </button>
                    </div>

                    {/* List */}
                    <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
                        <table className="w-full text-sm">
                            <thead className="bg-gray-100 text-gray-600">
                                <tr>
                                    <th className="p-3 text-left w-24">Kode</th>
                                    <th className="p-3 text-left">Deskripsi</th>
                                    <th className="p-3 text-center w-24">Aksi</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y">
                                {tps.map(tp => (
                                    <tr key={tp.id} className="hover:bg-gray-50">
                                        <td className="p-3 font-medium text-blue-700">{tp.code}</td>
                                        <td className="p-3 text-gray-700">{tp.description}</td>
                                        <td className="p-3 text-center">
                                            <button onClick={() => handleDeleteTP(tp.id)} className="text-red-500 hover:text-red-700 px-2 py-1 rounded hover:bg-red-50">Hapus</button>
                                        </td>
                                    </tr>
                                ))}
                                {tps.length === 0 && (
                                    <tr><td colSpan={3} className="p-8 text-center text-gray-400 italic">Belum ada TP. Silahkan tambah di atas.</td></tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            ) : (
                <div className="space-y-6">
                    {/* Add LM Form */}
                    <div className="bg-white p-4 rounded-xl shadow-sm border border-purple-100 flex gap-4 items-end">
                        <div className="w-1/4">
                            <label className="text-xs font-bold text-gray-500 uppercase">Kode LM</label>
                            <input 
                                type="text" placeholder="Contoh: LM.1" 
                                value={newLmCode} onChange={e => setNewLmCode(e.target.value)}
                                className="w-full mt-1 p-2 border rounded focus:ring-2 focus:ring-purple-200 outline-none"
                            />
                        </div>
                        <div className="flex-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Judul Lingkup Materi</label>
                            <input 
                                type="text" placeholder="Contoh: Berpikir Komputasional" 
                                value={newLmTitle} onChange={e => setNewLmTitle(e.target.value)}
                                className="w-full mt-1 p-2 border rounded focus:ring-2 focus:ring-purple-200 outline-none"
                            />
                        </div>
                        <button onClick={handleAddLM} className="px-4 py-2 bg-purple-600 text-white rounded hover:bg-purple-700 font-medium">
                            + Tambah
                        </button>
                    </div>

                    {/* List */}
                    <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
                        <table className="w-full text-sm">
                            <thead className="bg-gray-100 text-gray-600">
                                <tr>
                                    <th className="p-3 text-left w-24">Kode</th>
                                    <th className="p-3 text-left">Judul Materi</th>
                                    <th className="p-3 text-center w-24">Aksi</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y">
                                {lms.map(lm => (
                                    <tr key={lm.id} className="hover:bg-gray-50">
                                        <td className="p-3 font-medium text-purple-700">{lm.code}</td>
                                        <td className="p-3 text-gray-700">{lm.title}</td>
                                        <td className="p-3 text-center">
                                            <button onClick={() => handleDeleteLM(lm.id)} className="text-red-500 hover:text-red-700 px-2 py-1 rounded hover:bg-red-50">Hapus</button>
                                        </td>
                                    </tr>
                                ))}
                                {lms.length === 0 && (
                                    <tr><td colSpan={3} className="p-8 text-center text-gray-400 italic">Belum ada LM. Silahkan tambah di atas.</td></tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}
        </div>
    </div>
  );
};

