// Domain Models

export interface Student {
  id: string;
  name: string;
  nis: string;
  className?: string; // e.g., "10-A IPA"
}

export interface ClassInfo {
  id: string;
  name: string; // e.g. "10-A IPA"
  level: string; // e.g. "Fase E (10)"
  homeroomTeacher: string;
  studentCount: number;
  curriculumStatus: 'Merdeka Mandiri' | 'Merdeka Berubah' | 'K13';
}

export interface LearningObjective { // TP (Tujuan Pembelajaran)
  id: string;
  code: string; // e.g., TP.1
  description: string;
}

export interface LearningMaterial { // LM (Lingkup Materi)
  id: string;
  code: string; // e.g., LM.1
  title: string;
}

export interface Subject {
  id: string;
  name: string;
  kktp: number; // Kriteria Ketercapaian Tujuan Pembelajaran (Passing Grade)
}

export interface GradeData {
  [studentId: string]: {
    formative: { [tpId: string]: number }; // Nilai TP
    summative: { [lmId: string]: number }; // Nilai LM
    attitude: number; // Nilai Sikap
  };
}

export interface CalculatedGrade {
  avgFormative: number;
  avgSummative: number;
  finalScore: number;
  isPassed: boolean;
}

// Identity Data
export interface IdentityData {
  schoolName: string;
  subjectName: string;
  teacherName: string;
  nip: string;
  semester: string;
  academicYear: string;
  className: string;
  studentCount: number;
}

// Attendance Types
export type AttendanceStatus = 'H' | 'I' | 'S' | 'A'; // Hadir, Izin, Sakit, Alfa

export interface AttendanceSession {
  id: string;
  date: string;
  topic: string;
}

export interface AttendanceData {
  [studentId: string]: {
    [sessionId: string]: AttendanceStatus;
  };
}

