import React, { useState } from 'react';
import { Student, Subject, AttendanceData, AttendanceSession, AttendanceStatus } from '../types';

interface Props {
  students: Student[];
  subject: Subject;
  sessions: AttendanceSession[];
}

export const AttendanceSheet: React.FC<Props> = ({ students, subject, sessions }) => {
  const [attendanceData, setAttendanceData] = useState<AttendanceData>({});

  // Initialize data (optional, ensures object structure)
  // In a real app, this would be fetched from API

  const handleStatusClick = (studentId: string, sessionId: string) => {
    setAttendanceData(prev => {
      const studentRecords = prev[studentId] || {};
      const currentStatus = studentRecords[sessionId] || 'H';

      // Cycle: H -> I -> S -> A -> H
      let nextStatus: AttendanceStatus = 'H';
      if (currentStatus === 'H') nextStatus = 'I';
      else if (currentStatus === 'I') nextStatus = 'S';
      else if (currentStatus === 'S') nextStatus = 'A';
      else if (currentStatus === 'A') nextStatus = 'H';

      return {
        ...prev,
        [studentId]: {
          ...studentRecords,
          [sessionId]: nextStatus
        }
      };
    });
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'H': return 'bg-white text-gray-800';
      case 'I': return 'bg-blue-100 text-blue-800';
      case 'S': return 'bg-yellow-100 text-yellow-800';
      case 'A': return 'bg-red-100 text-red-800 font-bold';
      default: return 'bg-white';
    }
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-lg shadow border border-gray-200 overflow-hidden">
      <div className="p-4 border-b flex justify-between items-center bg-gray-50">
        <div>
          <h2 className="text-lg font-bold text-gray-800">Absensi: {subject.name}</h2>
          <p className="text-sm text-gray-500">Klik pada sel untuk mengubah status (H &rarr; I &rarr; S &rarr; A)</p>
        </div>
        <div className="flex gap-2">
           <button className="px-4 py-2 bg-white border border-gray-300 text-gray-700 rounded hover:bg-gray-50 text-sm font-medium">
            + Tambah Pertemuan
          </button>
          <button className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 text-sm font-medium">
            Simpan Absensi
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-auto relative scrollbar-thin">
        <table className="w-full border-collapse text-sm">
          <thead className="bg-gray-100 sticky top-0 z-10 shadow-sm">
            <tr>
              <th className="border p-3 min-w-[50px] text-center bg-gray-100 sticky left-0 z-20">No</th>
              <th className="border p-3 min-w-[250px] text-left bg-gray-100 sticky left-[50px] z-20">Nama Siswa</th>
              {sessions.map((session, idx) => (
                <th key={session.id} className="border p-2 min-w-[80px] text-center bg-gray-100">
                  <div className="text-xs text-gray-500">P.{idx + 1}</div>
                  <div className="font-medium">{new Date(session.date).toLocaleDateString('id-ID', {day: 'numeric', month:'short', timeZone: 'Asia/Makassar'})}</div>
                </th>
              ))}
              <th className="border p-3 w-[200px] text-center bg-gray-100">Rekap (H/I/S/A)</th>
            </tr>
          </thead>
          <tbody>
            {students.map((student, index) => {
              // Calculate summary on the fly
              const studentRecs = attendanceData[student.id] || {};
              const counts = { H: 0, I: 0, S: 0, A: 0 };
              sessions.forEach(s => {
                 const status = studentRecs[s.id] || 'H'; // Default to Present
                 counts[status]++;
              });

              return (
                <tr key={student.id} className="hover:bg-gray-50">
                  <td className="border p-2 text-center bg-white sticky left-0 z-10">{index + 1}</td>
                  <td className="border p-2 bg-white sticky left-[50px] z-10 font-medium text-gray-700">
                    <div>{student.name}</div>
                    <div className="text-xs text-gray-400">{student.nis}</div>
                  </td>
                  {sessions.map(session => {
                    const status = attendanceData[student.id]?.[session.id] || 'H';
                    return (
                      <td 
                        key={session.id} 
                        className={`border p-2 text-center cursor-pointer select-none transition-colors ${getStatusColor(status)}`}
                        onClick={() => handleStatusClick(student.id, session.id)}
                      >
                        {status}
                      </td>
                    );
                  })}
                  <td className="border p-2 text-center text-xs font-mono">
                    <span className="text-gray-900 font-bold">{counts.H}</span> / 
                    <span className="text-blue-600"> {counts.I}</span> / 
                    <span className="text-yellow-600"> {counts.S}</span> / 
                    <span className="text-red-600 font-bold"> {counts.A}</span>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect } from 'react';
import { z } from 'zod'; 
import ExcelJS from 'exceljs';
import { 
  Student, 
  LearningObjective, 
  LearningMaterial, 
  GradeData, 
  Subject 
} from '../types';
import { calculateStudentGrade } from '../utils/grading';

interface Props {
  students: Student[];
  tps: LearningObjective[];
  lms: LearningMaterial[];
  subject: Subject;
}

const scoreSchema = z.number().min(0, "Min 0").max(100, "Max 100").optional();

export const GradingSheet: React.FC<Props> = ({ students, tps, lms, subject }) => {
  const [gradeData, setGradeData] = useState<GradeData>({});
  const [errorMap, setErrorMap] = useState<{[key: string]: string}>({});
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    // Update time every minute
    const interval = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(interval);
  }, []);

  const handleScoreChange = useCallback((
    studentId: string, 
    type: 'formative' | 'summative' | 'attitude', 
    id: string | 'value', 
    value: string
  ) => {
    const numValue = value === '' ? undefined : parseFloat(value);
    const result = scoreSchema.safeParse(numValue);
    const errorKey = `${studentId}-${type}-${id}`;

    if (!result.success && value !== '') {
        setErrorMap(prev => ({...prev, [errorKey]: result.error.errors[0].message}));
    } else {
        setErrorMap(prev => {
            const newMap = {...prev};
            delete newMap[errorKey];
            return newMap;
        });
    }

    setGradeData(prev => {
      const studentData = prev[studentId] || { formative: {}, summative: {}, attitude: 0 };
      if (type === 'formative') {
        return { ...prev, [studentId]: { ...studentData, formative: { ...studentData.formative, [id]: numValue as number } } };
      } else if (type === 'summative') {
        return { ...prev, [studentId]: { ...studentData, summative: { ...studentData.summative, [id]: numValue as number } } };
      } else {
        return { ...prev, [studentId]: { ...studentData, attitude: numValue || 0 } };
      }
    });
  }, []);

  // Stats Calculation
  const stats = students.reduce((acc, student) => {
      const res = calculateStudentGrade(student.id, gradeData, subject.kktp);
      if (res.finalScore > 0) {
          if (res.isPassed) acc.tuntas++; else acc.remedial++;
      }
      return acc;
  }, { tuntas: 0, remedial: 0 });

  return (
    <div className="max-w-[1440px] mx-auto pb-8">
      {/* Breadcrumbs */}
      <div className="flex items-center gap-2 mb-4 text-sm font-medium text-slate-500">
        <a className="hover:text-primary cursor-pointer">Dashboard</a>
        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <a className="hover:text-primary cursor-pointer">Kelas 10-A IPA</a>
        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <span className="text-slate-900 font-bold">{subject.name} - Input Nilai</span>
      </div>

      {/* Header */}
      <div className="flex flex-wrap justify-between items-end gap-4 mb-6">
        <div className="flex flex-col gap-1">
          <h1 className="text-slate-900 text-3xl font-extrabold tracking-tight">Matrix Grade Input Sheet</h1>
          <p className="text-slate-500">Kurikulum Merdeka • {subject.name} • Semester Ganjil • 10-A IPA</p>
        </div>
        <div className="flex gap-3">
          <button className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 rounded-lg text-sm font-medium hover:bg-slate-50 transition-colors text-slate-700 shadow-sm">
            <span className="material-symbols-outlined text-lg text-primary">settings</span>
            Ubah Parameter Nilai
          </button>
        </div>
      </div>

      {/* Toolbar */}
      <div className="bg-white border border-slate-200 rounded-t-xl p-3 flex justify-between items-center">
        <div className="flex gap-2">
           <button className="p-2 text-slate-500 hover:text-primary hover:bg-slate-100 rounded transition-all"><span className="material-symbols-outlined">filter_list</span></button>
           <button className="p-2 text-slate-500 hover:text-primary hover:bg-slate-100 rounded transition-all"><span className="material-symbols-outlined">sort</span></button>
        </div>
        <div className="flex items-center gap-4">
           <span className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Format: Excel Spreadsheet</span>
           <button className="flex items-center gap-2 px-4 py-2 bg-primary/10 text-primary rounded-lg text-sm font-bold hover:bg-primary/20 transition-all">
             <span className="material-symbols-outlined text-lg">download</span>
             Download Template
           </button>
        </div>
      </div>

      {/* Main Matrix Table */}
      <div className="bg-white border border-t-0 border-slate-200 rounded-b-xl overflow-hidden shadow-sm flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left border-collapse table-fixed">
            <thead>
               {/* Group Headers */}
               <tr className="bg-slate-50 border-b border-slate-200">
                  <th className="sticky-col bg-slate-50 w-12 px-4 py-2 border-r border-slate-200"></th>
                  <th className="sticky-col-2 bg-slate-50 w-64 px-4 py-2 border-r border-slate-200"></th>
                  <th className="px-4 py-2 text-center text-[11px] font-bold text-slate-400 uppercase tracking-widest border-r border-slate-200" colSpan={tps.length}>Formatif (Tujuan Pembelajaran)</th>
                  <th className="px-4 py-2 text-center text-[11px] font-bold text-slate-400 uppercase tracking-widest border-r border-slate-200" colSpan={lms.length}>Sumatif (Lingkup Materi)</th>
                  <th className="w-24 px-4 py-2 border-r border-slate-200"></th>
                  <th className="px-4 py-2 text-center text-[11px] font-bold text-slate-400 uppercase tracking-widest" colSpan={2}>Kalkulasi Akhir</th>
               </tr>
               {/* Column Headers */}
               <tr className="bg-slate-50 border-b border-slate-200">
                  <th className="sticky-col bg-slate-50 w-12 px-4 py-3 text-xs font-bold text-slate-600 border-r border-slate-200 text-center">No</th>
                  <th className="sticky-col-2 bg-slate-50 w-64 px-4 py-3 text-xs font-bold text-slate-600 border-r border-slate-200">Nama Siswa</th>
                  {tps.map(tp => (
                    <th key={tp.id} className="w-20 px-2 py-3 text-xs font-bold text-slate-600 text-center border-r border-slate-200 relative group cursor-help">
                        {tp.code}
                        <div className="absolute hidden group-hover:block bg-slate-800 text-white p-2 rounded text-xs w-40 -top-10 left-1/2 -translate-x-1/2 z-50 font-normal shadow-lg">{tp.description}</div>
                    </th>
                  ))}
                  {lms.map(lm => (
                    <th key={lm.id} className="w-20 px-2 py-3 text-xs font-bold text-slate-600 text-center border-r border-slate-200 relative group cursor-help">
                        {lm.code}
                        <div className="absolute hidden group-hover:block bg-slate-800 text-white p-2 rounded text-xs w-40 -top-10 left-1/2 -translate-x-1/2 z-50 font-normal shadow-lg">{lm.title}</div>
                    </th>
                  ))}
                  <th className="w-24 px-4 py-3 text-xs font-bold text-slate-600 text-center border-r border-slate-200">Sikap</th>
                  <th className="w-24 px-4 py-3 text-xs font-bold text-slate-600 text-center border-r border-slate-200">NA</th>
                  <th className="w-40 px-4 py-3 text-xs font-bold text-slate-600 text-center">Status</th>
               </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
                {students.map((student, index) => {
                    const result = calculateStudentGrade(student.id, gradeData, subject.kktp);
                    return (
                        <tr key={student.id} className="group hover:bg-primary/5 transition-colors">
                            <td className="sticky-col bg-white group-hover:bg-[#f2f8fe] text-center text-xs text-slate-500 border-r border-slate-100 transition-colors">{index + 1}</td>
                            <td className="sticky-col-2 bg-white group-hover:bg-[#f2f8fe] px-4 py-0 font-medium text-sm text-slate-700 border-r border-slate-100 transition-colors">
                                {student.name}
                                <div className="text-[10px] text-slate-400 font-normal">{student.nis}</div>
                            </td>
                            {/* Formative Inputs */}
                            {tps.map(tp => {
                                const err = errorMap[`${student.id}-formative-${tp.id}`];
                                return (
                                    <td key={tp.id} className="p-0 border-r border-slate-100 relative">
                                        <input 
                                            type="number" 
                                            className={`w-full h-10 border-none bg-transparent text-center text-sm focus:ring-0 focus:bg-white focus:shadow-inner ${err ? 'text-red-500 bg-red-50' : 'text-slate-800'}`}
                                            value={gradeData[student.id]?.formative?.[tp.id] ?? ''}
                                            onChange={(e) => handleScoreChange(student.id, 'formative', tp.id, e.target.value)}
                                            placeholder="-"
                                        />
                                    </td>
                                );
                            })}
                            {/* Summative Inputs */}
                            {lms.map(lm => {
                                const err = errorMap[`${student.id}-summative-${lm.id}`];
                                return (
                                    <td key={lm.id} className="p-0 border-r border-slate-100 relative">
                                        <input 
                                            type="number" 
                                            className={`w-full h-10 border-none bg-transparent text-center text-sm focus:ring-0 focus:bg-white focus:shadow-inner ${err ? 'text-red-500 bg-red-50' : 'text-slate-800'}`}
                                            value={gradeData[student.id]?.summative?.[lm.id] ?? ''}
                                            onChange={(e) => handleScoreChange(student.id, 'summative', lm.id, e.target.value)}
                                            placeholder="-"
                                        />
                                    </td>
                                );
                            })}
                            {/* Attitude */}
                             <td className="p-0 border-r border-slate-100">
                                <input 
                                    type="number"
                                    className="w-full h-10 border-none bg-transparent text-center text-sm focus:ring-0 focus:bg-white focus:shadow-inner text-slate-800"
                                    value={gradeData[student.id]?.attitude ?? ''}
                                    onChange={(e) => handleScoreChange(student.id, 'attitude', 'value', e.target.value)}
                                    placeholder="-"
                                />
                            </td>
                            {/* Final & Status */}
                            <td className="px-4 text-center font-bold text-sm bg-slate-50 border-r border-slate-200 text-primary">
                                {result.finalScore || '-'}
                            </td>
                            <td className="px-4 text-center">
                                {result.finalScore > 0 && (
                                    <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider ${result.isPassed ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                        {result.isPassed ? 'Tuntas' : 'Remedial'}
                                    </span>
