interface ScheduleCardProps {
    startTime: string;
    endTime: string;
    className: string;
    subject: string;
    room: string;
    currentTime: Date;
}

const ScheduleCard: React.FC<ScheduleCardProps> = ({ startTime, endTime, className, subject, room, currentTime }) => {
    // Logic to determine if class is live
    const isLive = () => {
        const [startH, startM] = startTime.split(':').map(Number);
        const [endH, endM] = endTime.split(':').map(Number);

        const start = new Date(currentTime);
        start.setHours(startH, startM, 0);

        const end = new Date(currentTime);
        end.setHours(endH, endM, 0);

        return currentTime >= start && currentTime <= end;
    };

    const isFinished = () => {
         const [endH, endM] = endTime.split(':').map(Number);
         const end = new Date(currentTime);
         end.setHours(endH, endM, 0);
         return currentTime > end;
    }

    const liveStatus = isLive();
    const finishedStatus = isFinished();

    return (
        <div className={`border rounded-xl p-5 flex items-center gap-6 shadow-sm relative overflow-hidden transition-all ${liveStatus ? 'bg-white border-primary border-2 ring-4 ring-primary/5' : 'bg-white border-slate-200'}`}>
            {liveStatus && (
                <div className="absolute top-0 right-0 animate-pulse">
                    <div className="bg-primary text-white text-[10px] font-bold px-3 py-1 rounded-bl-lg flex items-center gap-1">
                        <span className="material-symbols-outlined text-[10px]">sensors</span>
                        SEDANG BERLANGSUNG
                    </div>
                </div>
            )}
            <div className={`${liveStatus ? 'bg-primary/10 text-primary' : 'bg-slate-50 text-slate-600'} rounded-lg p-3 text-center min-w-[90px]`}>
                <p className="text-lg font-bold">{startTime}</p>
                <p className="text-xs font-bold opacity-70">{liveStatus ? 'S.D' : 'Hingga'}</p>
                <p className="text-sm font-bold opacity-90">{endTime}</p>
            </div>
            <div className="flex-1">
                <h4 className="font-bold text-lg text-slate-900">{subject}</h4>
                <p className="text-slate-500 text-sm">{className} • {room}</p>
                {finishedStatus && <span className="text-xs font-bold text-green-600 bg-green-50 px-2 py-0.5 rounded mt-1 inline-block">Selesai</span>}
            </div>
            <div className="flex gap-2">
                <button className={`px-3 py-1.5 border text-xs font-bold rounded transition-colors ${liveStatus ? 'border-primary text-primary hover:bg-primary/10' : 'border-slate-300 text-slate-500 hover:bg-slate-50'}`}>Absensi</button>
                <button className={`px-3 py-1.5 text-xs font-bold rounded transition-colors ${liveStatus ? 'bg-primary text-white hover:bg-blue-600' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>Input Nilai</button>
            </div>
        </div>
    );
}

