import React, { useState, useMemo } from 'react';
import { Student, Subject, AttendanceData, AttendanceSession, AttendanceStatus, ScheduleItem } from '../types';

interface Props {
  students: Student[];
  subject: Subject;
  sessions: AttendanceSession[];
  schedules: ScheduleItem[];
}

export const AttendanceSheet: React.FC<Props> = ({ students, subject, sessions, schedules }) => {
  const [attendanceData, setAttendanceData] = useState<AttendanceData>({});

  // Selection States
  const [selectedClass, setSelectedClass] = useState<string>('');
  const [selectedScheduleId, setSelectedScheduleId] = useState<string>('');

  // 1. Get Unique Classes from Schedules
  const availableClasses = useMemo(() => {
    const classes = new Set(schedules.map(s => s.className));
    return Array.from(classes).sort();
  }, [schedules]);

  // 2. Filter Schedules based on Selected Class
  const availableSchedules = useMemo(() => {
    if (!selectedClass) return [];
    return schedules
        .filter(s => s.className === selectedClass)
        .sort((a, b) => {
            // Sort by day (simple sort for now) and time
            return a.day.localeCompare(b.day) || a.startTime.localeCompare(b.startTime);
        });
  }, [selectedClass, schedules]);

  // 3. Filter Students based on Selected Class (Mocking logic since Student object has className)
  const filteredStudents = useMemo(() => {
    if (!selectedClass) return [];
    // If students don't have className in mock data (some do, some don't in initial mock), 
    // we default to showing all if no match found for demo purposes, 
    // BUT strictly we should filter.
    // Let's filter strictly if className exists.
    return students.filter(s => s.className === selectedClass || !s.className);
  }, [selectedClass, students]);

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    // We are simulating a "Today" session ID for this quick input
    const sessionId = `today-${selectedScheduleId}`;

    setAttendanceData(prev => {
        const studentRecords = prev[studentId] || {};
        return {
            ...prev,
            [studentId]: {
                ...studentRecords,
                [sessionId]: status
            }
        };
    });
  };

  const getStatus = (studentId: string) => {
      const sessionId = `today-${selectedScheduleId}`;
      return attendanceData[studentId]?.[sessionId] || 'H'; // Default 'H'
  }

  const markAll = (status: AttendanceStatus) => {
      const sessionId = `today-${selectedScheduleId}`;
      const updates: AttendanceData = { ...attendanceData };
      filteredStudents.forEach(s => {
          if (!updates[s.id]) updates[s.id] = {};
          updates[s.id][sessionId] = status;
      });
      setAttendanceData(updates);
  }

  return (
    <div className="max-w-7xl mx-auto space-y-6">
       {/* Header */}
       <div className="flex flex-col gap-1">
          <h2 className="text-slate-900 text-3xl font-extrabold tracking-tight">Presensi Kelas</h2>
          <p className="text-slate-500 text-base font-normal">Catat kehadiran siswa berdasarkan jadwal mengajar.</p>
      </div>

      {/* Control Panel */}
      <div className="bg-white border border-slate-200 rounded-xl p-6 shadow-sm">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 items-end">

            {/* Class Selector */}
            <div className="space-y-2">
                <label className="text-sm font-bold text-slate-700">Pilih Kelas</label>
                <div className="relative">
                    <select 
                        className="w-full appearance-none rounded-lg border-slate-200 bg-slate-50 py-3 px-4 text-sm font-medium focus:border-primary focus:ring-2 focus:ring-primary/20 cursor-pointer"
                        value={selectedClass}
                        onChange={(e) => {
                            setSelectedClass(e.target.value);
                            setSelectedScheduleId(''); // Reset schedule when class changes
                        }}
                    >
                        <option value="">-- Pilih Kelas --</option>
                        {availableClasses.map(cls => (
                            <option key={cls} value={cls}>{cls}</option>
                        ))}
                    </select>
                    <span className="material-symbols-outlined absolute right-4 top-3 text-slate-400 pointer-events-none">expand_more</span>
                </div>
            </div>

            {/* Schedule Selector */}
            <div className="space-y-2">
                <label className="text-sm font-bold text-slate-700">Pilih Jadwal Mata Pelajaran</label>
                <div className="relative">
                     <select 
                        className="w-full appearance-none rounded-lg border-slate-200 bg-slate-50 py-3 px-4 text-sm font-medium focus:border-primary focus:ring-2 focus:ring-primary/20 cursor-pointer disabled:opacity-50"
                        value={selectedScheduleId}
                        onChange={(e) => setSelectedScheduleId(e.target.value)}
                        disabled={!selectedClass}
                    >
                        <option value="">-- Pilih Jadwal --</option>
                        {availableSchedules.map(sch => (
                            <option key={sch.id} value={sch.id}>
                                {sch.day} {sch.startTime} - {sch.subject} ({sch.room})
                            </option>
                        ))}
                    </select>
                    <span className="material-symbols-outlined absolute right-4 top-3 text-slate-400 pointer-events-none">expand_more</span>
                </div>
            </div>

            {/* Date Display (Static for now, implies "Today") */}
            <div className="space-y-2">
                <label className="text-sm font-bold text-slate-700">Tanggal Pertemuan</label>
                 <div className="w-full rounded-lg border border-slate-200 bg-white py-3 px-4 text-sm font-medium text-slate-600 flex items-center gap-2">
                    <span className="material-symbols-outlined text-slate-400">calendar_today</span>
                    {new Date().toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Asia/Makassar' })}
                 </div>
            </div>
        </div>
      </div>

      {/* Student List */}
      {selectedClass && selectedScheduleId ? (
          <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
            {/* Toolbar */}
            <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                 <div className="flex gap-2">
                    <button onClick={() => markAll('H')} className="px-3 py-1 bg-white border border-slate-200 rounded text-xs font-bold hover:bg-green-50 text-green-700 transition-colors shadow-sm">Set Semua Hadir</button>
                    <button onClick={() => markAll('A')} className="px-3 py-1 bg-white border border-slate-200 rounded text-xs font-bold hover:bg-red-50 text-red-700 transition-colors shadow-sm">Set Semua Alfa</button>
                 </div>
                 <span className="text-xs font-bold text-slate-500">{filteredStudents.length} Siswa Terdaftar</span>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-slate-50 border-b border-slate-200 text-xs font-bold text-slate-500 uppercase tracking-wider">
                            <th className="px-6 py-3 w-16 text-center">No</th>
                            <th className="px-6 py-3">Nama Siswa</th>
                            <th className="px-6 py-3 text-center w-1/3">Status Kehadiran</th>
                            <th className="px-6 py-3">Keterangan</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {filteredStudents.map((student, index) => {
                            const status = getStatus(student.id);
                            return (
                                <tr key={student.id} className="hover:bg-slate-50 transition-colors">
                                    <td className="px-6 py-4 text-center text-sm text-slate-500">{index + 1}</td>
                                    <td className="px-6 py-4">
                                        <p className="font-bold text-slate-800 text-sm">{student.name}</p>
                                        <p className="text-xs text-slate-400">{student.nis}</p>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex justify-center gap-1">
                                            {[
                                                { id: 'H', label: 'Hadir', color: 'green' },
                                                { id: 'I', label: 'Izin', color: 'blue' },
                                                { id: 'S', label: 'Sakit', color: 'orange' },
                                                { id: 'A', label: 'Alfa', color: 'red' }
                                            ].map((type) => (
                                                <button
                                                    key={type.id}
                                                    onClick={() => handleStatusChange(student.id, type.id as AttendanceStatus)}
                                                    className={`
                                                        w-10 h-10 rounded-lg text-xs font-bold transition-all border
                                                        ${status === type.id 
                                                            ? `bg-${type.color}-600 text-white border-${type.color}-600 shadow-md transform scale-105` 
                                                            : `bg-white text-slate-400 border-slate-200 hover:border-${type.color}-300 hover:text-${type.color}-500`
                                                        }
                                                    `}
                                                >
                                                    {type.id}
                                                </button>
                                            ))}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <input 
                                            type="text" 
                                            placeholder="Catatan..." 
                                            className="w-full border-b border-slate-200 focus:border-primary border-t-0 border-x-0 bg-transparent text-sm focus:ring-0 px-0"
                                        />
                                    </td>
                                </tr>
                            )
                        })}
                        {filteredStudents.length === 0 && (
                            <tr>
                                <td colSpan={4} className="p-8 text-center text-slate-400 italic">
                                    Tidak ada siswa ditemukan di kelas ini.
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            {/* Footer Action */}
            <div className="p-4 bg-slate-50 border-t border-slate-200 flex justify-end">
                <button className="flex items-center gap-2 px-6 py-2.5 bg-primary text-white rounded-lg font-bold shadow-lg shadow-blue-200 hover:bg-blue-600 transition-all">
                    <span className="material-symbols-outlined">save</span>
                    Simpan Presensi
                </button>
            </div>
          </div>
      ) : (
          <div className="flex flex-col items-center justify-center py-20 bg-slate-50 border-2 border-dashed border-slate-300 rounded-xl text-slate-400">
               <span className="material-symbols-outlined text-5xl mb-3 text-slate-300">fact_check</span>
               <p className="font-medium text-lg">Siap melakukan presensi?</p>
               <p className="text-sm">Silahkan pilih <strong>Kelas</strong> dan <strong>Jadwal</strong> terlebih dahulu di atas.</p>
          </div>
      )}
    </div>
  );
};

