import React, { useState } from 'react';
import { LearningMaterial, LearningObjective, Subject } from '../types';

interface Props {
  subject: Subject;
  tps: LearningObjective[];
  lms: LearningMaterial[];
  onUpdateSubject: (kktp: number) => void;
  onUpdateTPs: (tps: LearningObjective[]) => void;
  onUpdateLMs: (lms: LearningMaterial[]) => void;
  onBack: () => void;
}

export const CurriculumManager: React.FC<Props> = ({ 
  subject, tps, lms, onUpdateSubject, onUpdateTPs, onUpdateLMs, onBack 
}) => {
  const [activeTab, setActiveTab] = useState<'TP' | 'LM'>('TP');

  // State for Inputs
  const [tpForm, setTpForm] = useState({ id: '', code: '', description: '' });
  const [lmForm, setLmForm] = useState({ id: '', code: '', title: '' });

  const [isEditingTp, setIsEditingTp] = useState(false);
  const [isEditingLm, setIsEditingLm] = useState(false);

  // --- TP HANDLERS ---
  const handleSaveTP = () => {
    if (!tpForm.code || !tpForm.description) return;

    if (isEditingTp) {
        // Update existing
        const updatedTPs = tps.map(item => item.id === tpForm.id ? { ...tpForm } : item);
        onUpdateTPs(updatedTPs);
        setIsEditingTp(false);
    } else {
        // Add new
        const newTP: LearningObjective = {
            id: Date.now().toString(),
            code: tpForm.code,
            description: tpForm.description
        };
        onUpdateTPs([...tps, newTP]);
    }
    setTpForm({ id: '', code: '', description: '' });
  };

  const handleEditTP = (tp: LearningObjective) => {
      setTpForm(tp);
      setIsEditingTp(true);
      // Optional: scroll to top or focus input
  };

  const handleDeleteTP = (id: string) => {
    if (confirm('Hapus Tujuan Pembelajaran ini? Data nilai terkait mungkin akan hilang.')) {
      onUpdateTPs(tps.filter(t => t.id !== id));
      if (isEditingTp && tpForm.id === id) {
          setIsEditingTp(false);
          setTpForm({ id: '', code: '', description: '' });
      }
    }
  };

  const handleCancelTpEdit = () => {
      setIsEditingTp(false);
      setTpForm({ id: '', code: '', description: '' });
  }

  // --- LM HANDLERS ---
  const handleSaveLM = () => {
    if (!lmForm.code || !lmForm.title) return;

    if (isEditingLm) {
        // Update existing
        const updatedLMs = lms.map(item => item.id === lmForm.id ? { ...lmForm } : item);
        onUpdateLMs(updatedLMs);
        setIsEditingLm(false);
    } else {
        // Add new
        const newLM: LearningMaterial = {
            id: Date.now().toString(),
            code: lmForm.code,
            title: lmForm.title
        };
        onUpdateLMs([...lms, newLM]);
    }
    setLmForm({ id: '', code: '', title: '' });
  };

  const handleEditLM = (lm: LearningMaterial) => {
      setLmForm(lm);
      setIsEditingLm(true);
  };

  const handleDeleteLM = (id: string) => {
    if (confirm('Hapus Lingkup Materi ini? Data nilai sumatif terkait mungkin akan hilang.')) {
      onUpdateLMs(lms.filter(l => l.id !== id));
      if (isEditingLm && lmForm.id === id) {
          setIsEditingLm(false);
          setLmForm({ id: '', code: '', title: '' });
      }
    }
  };

  const handleCancelLmEdit = () => {
      setIsEditingLm(false);
      setLmForm({ id: '', code: '', title: '' });
  }

  return (
    <div className="h-full flex flex-col bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Header */}
        <div className="bg-gray-50 p-6 border-b flex justify-between items-center">
            <div>
                <h2 className="text-xl font-bold text-gray-800">Manajemen Kurikulum & KKTP</h2>
                <p className="text-sm text-gray-500">Atur Tujuan Pembelajaran dan Batas Ketuntasan</p>
            </div>
             <button onClick={onBack} className="text-gray-500 hover:text-gray-700 font-medium">
                &larr; Kembali
            </button>
        </div>

        {/* KKTP Setting */}
        <div className="p-6 bg-blue-50 border-b flex items-center gap-4">
            <div className="bg-blue-100 p-2 rounded-lg text-blue-600">
                <span className="material-symbols-outlined">tune</span>
            </div>
            <div className="flex-1">
                <label className="text-sm font-bold text-gray-700">KKTP (Kriteria Ketercapaian Tujuan Pembelajaran)</label>
                <p className="text-xs text-gray-500">Nilai minimum agar siswa dianggap tuntas.</p>
            </div>
            <input 
                type="number" 
                value={subject.kktp}
                onChange={(e) => onUpdateSubject(Number(e.target.value))}
                className="w-24 p-2 text-center text-xl font-bold text-blue-700 border-2 border-blue-200 rounded-lg focus:ring-blue-500 focus:border-blue-500 outline-none"
            />
        </div>

        {/* Tabs */}
        <div className="flex border-b">
            <button 
                onClick={() => setActiveTab('TP')}
                className={`flex-1 py-4 text-sm font-bold text-center border-b-2 transition-colors ${activeTab === 'TP' ? 'border-blue-600 text-blue-600 bg-blue-50/50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Tujuan Pembelajaran (TP)
            </button>
            <button 
                 onClick={() => setActiveTab('LM')}
                className={`flex-1 py-4 text-sm font-bold text-center border-b-2 transition-colors ${activeTab === 'LM' ? 'border-purple-600 text-purple-600 bg-purple-50/50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Lingkup Materi (LM)
            </button>
        </div>

        {/* Content */}
        <div className="flex-1 p-6 overflow-y-auto bg-gray-50/50">
            {activeTab === 'TP' ? (
                <div className="space-y-6">
                    {/* Add/Edit TP Form */}
                    <div className={`p-4 rounded-xl shadow-sm border flex gap-4 items-end transition-all ${isEditingTp ? 'bg-orange-50 border-orange-200' : 'bg-white border-blue-100'}`}>
                        <div className="w-1/4">
                            <label className="text-xs font-bold text-gray-500 uppercase">Kode TP</label>
                            <input 
                                type="text" placeholder="Contoh: TP.1" 
                                value={tpForm.code} onChange={e => setTpForm({...tpForm, code: e.target.value})}
                                className="w-full mt-1 p-2 border rounded focus:ring-2 focus:ring-blue-200 outline-none text-sm"
                            />
                        </div>
                        <div className="flex-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Deskripsi Tujuan Pembelajaran</label>
                            <input 
                                type="text" placeholder="Contoh: Menjelaskan konsep algoritma" 
                                value={tpForm.description} onChange={e => setTpForm({...tpForm, description: e.target.value})}
                                className="w-full mt-1 p-2 border rounded focus:ring-2 focus:ring-blue-200 outline-none text-sm"
                            />
                        </div>
                        <div className="flex gap-2">
                             {isEditingTp && (
                                <button onClick={handleCancelTpEdit} className="px-4 py-2 border border-slate-300 text-slate-600 rounded hover:bg-slate-50 font-bold text-sm">
                                    Batal
                                </button>
                            )}
                            <button onClick={handleSaveTP} className={`px-6 py-2 text-white rounded font-bold text-sm shadow-sm ${isEditingTp ? 'bg-orange-500 hover:bg-orange-600' : 'bg-blue-600 hover:bg-blue-700'}`}>
                                {isEditingTp ? 'Update TP' : '+ Tambah TP'}
                            </button>
                        </div>
                    </div>

                    {/* List */}
                    <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
                        <table className="w-full text-sm">
                            <thead className="bg-gray-100 text-gray-600">
                                <tr>
                                    <th className="p-3 text-left w-24 border-b">Kode</th>
                                    <th className="p-3 text-left border-b">Deskripsi</th>
                                    <th className="p-3 text-right w-32 border-b">Aksi</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {tps.map(tp => (
                                    <tr key={tp.id} className="hover:bg-slate-50 transition-colors">
                                        <td className="p-3 font-bold text-blue-700 align-top">{tp.code}</td>
                                        <td className="p-3 text-slate-700 align-top">{tp.description}</td>
                                        <td className="p-3 text-right">
                                            <div className="flex justify-end gap-1">
                                                <button onClick={() => handleEditTP(tp)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded" title="Edit">
                                                    <span className="material-symbols-outlined text-lg">edit</span>
                                                </button>
                                                <button onClick={() => handleDeleteTP(tp.id)} className="p-1.5 text-red-500 hover:bg-red-50 rounded" title="Hapus">
                                                    <span className="material-symbols-outlined text-lg">delete</span>
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                                {tps.length === 0 && (
                                    <tr><td colSpan={3} className="p-8 text-center text-gray-400 italic">Belum ada Tujuan Pembelajaran. Silahkan tambah di atas.</td></tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            ) : (
                <div className="space-y-6">
                    {/* Add/Edit LM Form */}
                     <div className={`p-4 rounded-xl shadow-sm border flex gap-4 items-end transition-all ${isEditingLm ? 'bg-orange-50 border-orange-200' : 'bg-white border-purple-100'}`}>
                        <div className="w-1/4">
                            <label className="text-xs font-bold text-gray-500 uppercase">Kode LM</label>
                            <input 
                                type="text" placeholder="Contoh: LM.1" 
                                value={lmForm.code} onChange={e => setLmForm({...lmForm, code: e.target.value})}
                                className="w-full mt-1 p-2 border rounded focus:ring-2 focus:ring-purple-200 outline-none text-sm"
                            />
                        </div>
                        <div className="flex-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Judul Lingkup Materi</label>
                            <input 
                                type="text" placeholder="Contoh: Berpikir Komputasional" 
                                value={lmForm.title} onChange={e => setLmForm({...lmForm, title: e.target.value})}
                                className="w-full mt-1 p-2 border rounded focus:ring-2 focus:ring-purple-200 outline-none text-sm"
                            />
                        </div>
                        <div className="flex gap-2">
                             {isEditingLm && (
                                <button onClick={handleCancelLmEdit} className="px-4 py-2 border border-slate-300 text-slate-600 rounded hover:bg-slate-50 font-bold text-sm">
                                    Batal
                                </button>
                            )}
                            <button onClick={handleSaveLM} className={`px-6 py-2 text-white rounded font-bold text-sm shadow-sm ${isEditingLm ? 'bg-orange-500 hover:bg-orange-600' : 'bg-purple-600 hover:bg-purple-700'}`}>
                                {isEditingLm ? 'Update LM' : '+ Tambah LM'}
                            </button>
                        </div>
                    </div>

                    {/* List */}
                    <div className="bg-white rounded-xl shadow-sm border overflow-hidden">
                        <table className="w-full text-sm">
                            <thead className="bg-gray-100 text-gray-600">
                                <tr>
                                    <th className="p-3 text-left w-24 border-b">Kode</th>
                                    <th className="p-3 text-left border-b">Judul Materi</th>
                                    <th className="p-3 text-right w-32 border-b">Aksi</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {lms.map(lm => (
                                    <tr key={lm.id} className="hover:bg-slate-50 transition-colors">
                                        <td className="p-3 font-bold text-purple-700 align-top">{lm.code}</td>
                                        <td className="p-3 text-slate-700 align-top">{lm.title}</td>
                                        <td className="p-3 text-right">
                                             <div className="flex justify-end gap-1">
                                                <button onClick={() => handleEditLM(lm)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded" title="Edit">
                                                    <span className="material-symbols-outlined text-lg">edit</span>
                                                </button>
                                                <button onClick={() => handleDeleteLM(lm.id)} className="p-1.5 text-red-500 hover:bg-red-50 rounded" title="Hapus">
                                                    <span className="material-symbols-outlined text-lg">delete</span>
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                                {lms.length === 0 && (
                                    <tr><td colSpan={3} className="p-8 text-center text-gray-400 italic">Belum ada Lingkup Materi. Silahkan tambah di atas.</td></tr>
