            </button>
        </div>

        {/* Content */}
        <div className="flex-1 p-6 overflow-y-auto bg-gray-50/50">
            {activeTab === 'TP' ? (
                <div className="space-y-6">
                    {/* Add/Edit TP Form */}
                    <div className={`p-4 rounded-xl shadow-sm border flex gap-4 items-end transition-all ${isEditingTp ? 'bg-orange-50 border-orange-200' : 'bg-white border-blue-100'}`}>
