import { GradeData, CalculatedGrade } from '../types';

/**
 * FUNGSI PERHITUNGAN NILAI
 * 
 * Logic Updated:
 * Final Score = (Average of all Criteria Scores * 0.9) + (Attitude * 0.1)
 * Note: Logic simplified to accommodate dynamic criteria structure.
 */
export const calculateStudentGrade = (
  studentId: string,
  gradeData: GradeData,
  kktp: number
): CalculatedGrade => {
  const studentGrades = gradeData[studentId];

  if (!studentGrades) {
    return { avgScore: 0, finalScore: 0, isPassed: false };
  }

  // 1. Calculate Average of all Criteria Scores
  const scores = Object.values(studentGrades.scores).filter(v => v !== undefined && v !== null && !isNaN(v));
  const avgScore = scores.length > 0
    ? scores.reduce((a, b) => a + b, 0) / scores.length
    : 0;

  // 2. Get Attitude Score (Default to 0 if missing)
  const attitude = studentGrades.attitude || 0;

  // 3. Apply Formula: 90% Academic, 10% Attitude (Simplified for this version)
  const finalScoreRaw = (avgScore * 0.9) + (attitude * 0.1);
  const finalScore = Math.round(finalScoreRaw * 100) / 100;

  return {
    avgScore,
    finalScore,
    isPassed: finalScore >= kktp
  };
};

import React, { useState } from 'react';
import { LearningMaterial, LearningObjective, Subject, AssessmentCriteria } from '../types';

interface Props {
  subject: Subject;
  tps: LearningObjective[];
  onUpdateSubject: (kktp: number) => void;
  onUpdateTPs: (tps: LearningObjective[]) => void;
  onBack: () => void;
}

export const CurriculumManager: React.FC<Props> = ({ 
  subject, tps, onUpdateSubject, onUpdateTPs, onBack 
}) => {
  const [expandedTpId, setExpandedTpId] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState<string | null>(null);

  // TP Form State
  const [isAddingTp, setIsAddingTp] = useState(false);
  const [newTpForm, setNewTpForm] = useState({ code: '', description: '', semester: '1' });

  // Sub-item Form State (LM & Criteria)
  const [newItemForm, setNewItemForm] = useState<{
      type: 'LM' | 'CRITERIA' | null, 
      parentId: string | null,
      val1: string, // Code
      val2: string // Title/Description
  }>({ type: null, parentId: null, val1: '', val2: '' });

  // --- TP CRUD ---
  const handleAddTP = () => {
    if(!newTpForm.code || !newTpForm.description) return;
    const newTp: LearningObjective = {
        id: Date.now().toString(),
        code: newTpForm.code,
        description: newTpForm.description,
        semester: Number(newTpForm.semester) as 1 | 2,
        lms: [],
        criteria: []
    };
    onUpdateTPs([...tps, newTp]);
    setIsAddingTp(false);
    setNewTpForm({ code: '', description: '', semester: '1' });
  };

  const handleDeleteTP = (id: string) => {
      if(confirm('Hapus TP beserta seluruh LM dan Kriteria di dalamnya?')) {
          onUpdateTPs(tps.filter(t => t.id !== id));
      }
  };

  // --- NESTED ITEMS CRUD ---
  const handleAddItem = () => {
      if(!newItemForm.val1 || !newItemForm.val2 || !newItemForm.parentId || !newItemForm.type) return;

      const updatedTPs = tps.map(tp => {
          if(tp.id === newItemForm.parentId) {
              if(newItemForm.type === 'LM') {
                  return {
                      ...tp,
                      lms: [...tp.lms, { id: Date.now().toString(), code: newItemForm.val1, title: newItemForm.val2 }]
                  };
              } else {
                  return {
                      ...tp,
                      criteria: [...tp.criteria, { id: Date.now().toString(), code: newItemForm.val1, description: newItemForm.val2 }]
                  };
              }
          }
          return tp;
      });

      onUpdateTPs(updatedTPs);
      setNewItemForm({ type: null, parentId: null, val1: '', val2: '' });
  };

  const handleDeleteSubItem = (tpId: string, itemId: string, type: 'LM' | 'CRITERIA') => {
      if(!confirm('Hapus item ini?')) return;
      const updatedTPs = tps.map(tp => {
          if(tp.id === tpId) {
              if(type === 'LM') {
                  return { ...tp, lms: tp.lms.filter(l => l.id !== itemId) };
              } else {
                  return { ...tp, criteria: tp.criteria.filter(c => c.id !== itemId) };
              }
          }
          return tp;
      });
      onUpdateTPs(updatedTPs);
  };

  // --- AI GENERATION LOGIC ---
  const handleGenerateAI = (tp: LearningObjective) => {
      setIsGenerating(tp.id);

      // Simulate AI Processing
      setTimeout(() => {
          let keywords: string[] = [];
          const desc = tp.description.toLowerCase();

          // Simple keyword extraction for "Lingkup Materi"
          if(desc.includes('eksponen')) keywords.push('Sifat Eksponen', 'Grafik Eksponen');
          else if(desc.includes('logaritma')) keywords.push('Sifat Logaritma', 'Persamaan Logaritma');
          else if(desc.includes('biotik')) keywords.push('Komponen Biotik', 'Komponen Abiotik', 'Interaksi Ekosistem');
          else if(desc.includes('algoritma')) keywords.push('Flowchart', 'Pseudocode');
          else keywords.push('Konsep Dasar', 'Penerapan Masalah');

          // Determine Criteria based on Bloom's Verb
          let criteriaDesc = 'Pemahaman Konsep';
          if(desc.startsWith('menganalisis')) criteriaDesc = 'Kemampuan Analisis';
          if(desc.startsWith('menciptakan') || desc.startsWith('membuat')) criteriaDesc = 'Kreativitas Produk';
          if(desc.startsWith('menyelesaikan')) criteriaDesc = 'Pemecahan Masalah';

          const newLMs: LearningMaterial[] = keywords.map((k, i) => ({
              id: `gen-lm-${Date.now()}-${i}`,
              code: `LM.${tp.code.split('.')[1]}.${i+1}`,
              title: k
          }));

          const newCriteria: AssessmentCriteria[] = [
              {
                  id: `gen-cr-${Date.now()}-1`,
                  code: `Kr.${tp.code.split('.')[1]}.1`,
                  description: criteriaDesc
              },
              {
                  id: `gen-cr-${Date.now()}-2`,
                  code: `Kr.${tp.code.split('.')[1]}.2`,
                  description: 'Keterampilan Proses' 
              }
          ];

          const updatedTPs = tps.map(t => {
              if(t.id === tp.id) {
                  return {
                      ...t,
                      lms: [...t.lms, ...newLMs],
                      criteria: [...t.criteria, ...newCriteria]
                  };
              }
              return t;
          });

          onUpdateTPs(updatedTPs);
          setIsGenerating(null);
          setExpandedTpId(tp.id); // Auto expand
      }, 1500);
  };

  return (
    <div className="h-full flex flex-col bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Header */}
        <div className="bg-gray-50 p-6 border-b flex justify-between items-center">
            <div>
                <h2 className="text-xl font-bold text-gray-800">Manajemen Kurikulum & Asesmen</h2>
                <p className="text-sm text-gray-500">Struktur TP, Lingkup Materi, dan Kriteria Penilaian</p>
            </div>
             <button onClick={onBack} className="text-gray-500 hover:text-gray-700 font-medium">
                &larr; Kembali
            </button>
        </div>

        {/* Global Config */}
        <div className="px-6 py-4 bg-white border-b flex items-center justify-between">
             <div className="flex items-center gap-4">
                <div className="bg-blue-100 p-2 rounded-lg text-blue-600">
                    <span className="material-symbols-outlined">tune</span>
                </div>
                <div>
                    <label className="text-xs font-bold text-gray-500 uppercase">KKTP Mapel</label>
                    <div className="flex items-center gap-2">
                         <input 
                            type="number" 
                            value={subject.kktp}
                            onChange={(e) => onUpdateSubject(Number(e.target.value))}
                            className="w-16 p-1 text-center font-bold text-blue-700 border-b-2 border-blue-200 focus:border-blue-500 outline-none"
                        />
                        <span className="text-sm text-gray-400">Poin</span>
                    </div>
                </div>
            </div>
            <button 
                onClick={() => setIsAddingTp(!isAddingTp)}
                className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 transition-colors shadow-sm"
            >
                <span className="material-symbols-outlined text-sm">{isAddingTp ? 'remove' : 'add'}</span>
                Tambah Tujuan Pembelajaran
            </button>
        </div>

        {/* Add TP Form */}
        {isAddingTp && (
            <div className="mx-6 mt-6 p-4 bg-blue-50 border border-blue-100 rounded-xl animate-in fade-in slide-in-from-top-4">
                <h4 className="font-bold text-blue-800 mb-3 text-sm">Tambah TP Baru</h4>
                <div className="flex gap-3 items-start">
                     <div className="w-24">
                        <input 
                            type="text" placeholder="Kode" 
                            value={newTpForm.code} onChange={e => setNewTpForm({...newTpForm, code: e.target.value})}
                            className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300"
                        />
                    </div>
                     <div className="w-24">
                        <select 
                            value={newTpForm.semester} onChange={e => setNewTpForm({...newTpForm, semester: e.target.value})}
                            className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300"
                        >
                            <option value="1">Smt 1</option>
                            <option value="2">Smt 2</option>
                        </select>
                    </div>
                    <div className="flex-1">
                        <input 
                            type="text" placeholder="Deskripsi Tujuan Pembelajaran..." 
                            value={newTpForm.description} onChange={e => setNewTpForm({...newTpForm, description: e.target.value})}
                            className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300"
                        />
                    </div>
                    <button onClick={handleAddTP} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold text-sm hover:bg-blue-700">Simpan</button>
                </div>
            </div>
        )}

        {/* TP List */}
        <div className="flex-1 overflow-y-auto p-6 space-y-4">
            {tps.length === 0 && (
                <div className="text-center py-12 text-gray-400">
                    <span className="material-symbols-outlined text-4xl mb-2">library_books</span>
                    <p>Belum ada Tujuan Pembelajaran.</p>
                </div>
            )}

            {tps.map((tp) => {
                const isExpanded = expandedTpId === tp.id;
                return (
                    <div key={tp.id} className={`border rounded-xl transition-all ${isExpanded ? 'border-primary shadow-md bg-white' : 'border-slate-200 bg-white hover:border-slate-300'}`}>
                        {/* TP Header */}
                        <div 
                            onClick={() => setExpandedTpId(isExpanded ? null : tp.id)}
                            className="p-4 flex items-center gap-4 cursor-pointer"
                        >
                            <div className={`size-10 rounded-lg flex items-center justify-center font-bold text-sm ${isExpanded ? 'bg-primary text-white' : 'bg-slate-100 text-slate-500'}`}>
                                {tp.code}
                            </div>
                            <div className="flex-1">
                                <p className={`text-sm font-bold ${isExpanded ? 'text-primary' : 'text-slate-800'}`}>{tp.description}</p>
                                <div className="flex items-center gap-2 mt-1">
                                    <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500">Semester {tp.semester}</span>
                                    <span className="text-[10px] text-slate-400 flex items-center gap-1">
                                        <span className="material-symbols-outlined text-[10px]">topic</span> {tp.lms.length} LM
                                    </span>
                                    <span className="text-[10px] text-slate-400 flex items-center gap-1">
                                        <span className="material-symbols-outlined text-[10px]">fact_check</span> {tp.criteria.length} Kriteria
                                    </span>
                                </div>
                            </div>
                            <button 
                                onClick={(e) => { e.stopPropagation(); handleDeleteTP(tp.id); }}
                                className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                            >
                                <span className="material-symbols-outlined">delete</span>
                            </button>
                            <span className={`material-symbols-outlined text-slate-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`}>expand_more</span>
                        </div>

                        {/* Expanded Content */}
                        {isExpanded && (
                            <div className="border-t border-slate-100 bg-slate-50/50 p-4 space-y-6 animate-in slide-in-from-top-2">

                                {/* AI Generator Banner */}
                                {(tp.lms.length === 0 && tp.criteria.length === 0) && (
                                    <div className="bg-purple-50 border border-purple-100 rounded-lg p-4 flex items-center justify-between">
                                        <div className="flex items-center gap-3">
                                            <div className="bg-purple-100 p-2 rounded-full text-purple-600">
                                                <span className="material-symbols-outlined">auto_awesome</span>
                                            </div>
                                            <div>
                                                <p className="text-sm font-bold text-purple-900">Generate Otomatis?</p>
                                                <p className="text-xs text-purple-700">AI akan membuatkan Lingkup Materi & Kriteria berdasarkan deskripsi TP.</p>
                                            </div>
                                        </div>
                                        <button 
                                            onClick={() => handleGenerateAI(tp)}
                                            disabled={isGenerating === tp.id}
                                            className="px-4 py-2 bg-purple-600 text-white text-xs font-bold rounded-lg hover:bg-purple-700 flex items-center gap-2 disabled:opacity-70"
                                        >
                                            {isGenerating === tp.id ? 'Memproses...' : 'Generate Sekarang'}
                                            {!isGenerating && <span className="material-symbols-outlined text-sm">arrow_forward</span>}
                                        </button>
                                    </div>
                                )}

                                {/* Lingkup Materi Section */}
                                <div className="space-y-3">
                                    <div className="flex justify-between items-center">
                                        <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
                                            <span className="material-symbols-outlined text-sm">topic</span>
                                            Lingkup Materi (LM)
                                        </h4>
                                    </div>
                                    <div className="bg-white border border-slate-200 rounded-lg overflow-hidden">
                                        <table className="w-full text-sm">
                                            <thead className="bg-slate-50 text-slate-500 font-semibold border-b border-slate-200">
                                                <tr>
                                                    <th className="px-4 py-2 text-left w-24">Kode</th>
                                                    <th className="px-4 py-2 text-left">Judul Materi</th>
                                                    <th className="px-4 py-2 w-16"></th>
