import React, { useState, useCallback, useEffect, useMemo } from 'react';
import { z } from 'zod'; 
import { 
  Student, 
  LearningObjective, 
  GradeData, 
  Subject 
} from '../types';
import { calculateStudentGrade } from '../utils/grading';

interface Props {
  students: Student[];
  tps: LearningObjective[];
  subject: Subject;
}

const scoreSchema = z.number().min(0, "Min 0").max(100, "Max 100").optional();

export const GradingSheet: React.FC<Props> = ({ students, tps, subject }) => {
  const [gradeData, setGradeData] = useState<GradeData>({});
  const [errorMap, setErrorMap] = useState<{[key: string]: string}>({});
  const [currentTime, setCurrentTime] = useState(new Date());

  // Class Filter State
  const [selectedClass, setSelectedClass] = useState<string>('');

  // Derive unique classes from students list
  const availableClasses = useMemo(() => {
      const classes = new Set(students.map(s => s.className).filter(Boolean));
      return Array.from(classes).sort() as string[];
  }, [students]);

  // Filter students based on selection
  const filteredStudents = useMemo(() => {
      if (!selectedClass) return students;
      return students.filter(s => s.className === selectedClass);
  }, [students, selectedClass]);

  useEffect(() => {
    // Update time every minute
    const interval = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(interval);
  }, []);

  const handleScoreChange = useCallback((
    studentId: string, 
    type: 'criteria' | 'attitude', 
    id: string | 'value', 
    value: string
  ) => {
    const numValue = value === '' ? undefined : parseFloat(value);
    const result = scoreSchema.safeParse(numValue);
    const errorKey = `${studentId}-${type}-${id}`;

    if (!result.success && value !== '') {
        setErrorMap(prev => ({...prev, [errorKey]: result.error.errors[0].message}));
    } else {
        setErrorMap(prev => {
            const newMap = {...prev};
            delete newMap[errorKey];
            return newMap;
        });
    }

    setGradeData(prev => {
      const studentData = prev[studentId] || { scores: {}, attitude: 0 };
      if (type === 'criteria') {
        return { ...prev, [studentId]: { ...studentData, scores: { ...studentData.scores, [id]: numValue as number } } };
      } else {
        return { ...prev, [studentId]: { ...studentData, attitude: numValue || 0 } };
      }
    });
  }, []);

  // Stats Calculation (based on filtered students)
  const stats = filteredStudents.reduce((acc, student) => {
      const res = calculateStudentGrade(student.id, gradeData, subject.kktp);
      if (res.finalScore > 0) {
          if (res.isPassed) acc.tuntas++; else acc.remedial++;
      }
      return acc;
  }, { tuntas: 0, remedial: 0 });

  return (
    <div className="max-w-[1440px] mx-auto pb-8">
      {/* Breadcrumbs */}
      <div className="flex items-center gap-2 mb-4 text-sm font-medium text-slate-500">
        <a className="hover:text-primary cursor-pointer">Dashboard</a>
        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <a className="hover:text-primary cursor-pointer">Input Nilai</a>
        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <span className="text-slate-900 font-bold">{subject.name}</span>
      </div>

      {/* Header */}
      <div className="flex flex-wrap justify-between items-end gap-4 mb-6">
        <div className="flex flex-col gap-1">
          <h1 className="text-slate-900 text-3xl font-extrabold tracking-tight">Matrix Grade Input Sheet</h1>
          <p className="text-slate-500">Kurikulum Merdeka • {subject.name} • Semester Ganjil</p>
        </div>
        <div className="flex gap-3">
