          setEditingId(null);
          setFormData({ name: '', level: 'Fase E (10)', homeroomTeacher: '', curriculumStatus: 'Merdeka Mandiri' });
      }
      setIsModalOpen(true);
  };

  const handleSaveClass = (e: React.FormEvent) => {
      e.preventDefault();

      if (editingId) {
          // Update
          const updatedClasses = classes.map(c => c.id === editingId ? { 
              ...c, 
              ...formData,
              curriculumStatus: formData.curriculumStatus as ClassInfo['curriculumStatus']
          } : c);
          setClasses(updatedClasses);
      } else {
          // Add
          const newClass: ClassInfo = {
              id: Date.now().toString(),
              name: formData.name,
              level: formData.level,
              homeroomTeacher: formData.homeroomTeacher || 'Belum ditentukan',
              studentCount: 0,
              curriculumStatus: formData.curriculumStatus as ClassInfo['curriculumStatus']
          };
          setClasses([...classes, newClass]);
      }
      setIsModalOpen(false);
  };

  const handleDeleteClass = (id: string) => {
      if (confirm('Hapus kelas ini? Data siswa terkait mungkin akan hilang.')) {
          setClasses(classes.filter(c => c.id !== id));
