            {activeTab === TabView.CP_GENERATOR && (
                <CPGenerator 
                    onSave={handleSaveGeneratedTPs}
                    onBack={() => setActiveTab(TabView.DASHBOARD)}
                />
            )}

            {activeTab === TabView.CLASS_MASTER && (
                <ClassManager onBack={() => setActiveTab(TabView.DASHBOARD)} />
            )}

            {activeTab === TabView.STUDENT_MASTER && (
                <StudentManager onBack={() => setActiveTab(TabView.DASHBOARD)} />
            )}

            {activeTab === TabView.SCHEDULE_MASTER && (
                <ScheduleManager 
                    schedules={schedules} 
                    onUpdateSchedules={setSchedules}
                    onBack={() => setActiveTab(TabView.DASHBOARD)} 
                />
            )}

            {activeTab === TabView.BLUEPRINT && <SystemBlueprint />}

            {activeTab === TabView.GRADING && (
                <GradingSheet 
                  students={INITIAL_STUDENTS}
                  tps={tps}
                  subject={subject}
                />
            )}

            {activeTab === TabView.ATTENDANCE && (
                <AttendanceSheet 
                  students={INITIAL_STUDENTS}
                  subject={subject}
                  sessions={MOCK_SESSIONS}
                  schedules={schedules}
                />
            )}
          </div>
        </main>
      </div>
    </QueryClientProvider>
  );
}

