export const ClassManager: React.FC<Props> = ({ onBack }) => {
  const [classes, setClasses] = useState<ClassInfo[]>(INITIAL_CLASSES);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
      name: '',
      level: 'Fase E (10)',
      homeroomTeacher: '',
      curriculumStatus: 'Merdeka Mandiri'
  });

  const handleOpenModal = (cls?: ClassInfo) => {
      if (cls) {
          setEditingId(cls.id);
          setFormData({
              name: cls.name,
              level: cls.level,
              homeroomTeacher: cls.homeroomTeacher,
              curriculumStatus: cls.curriculumStatus
          });
      } else {
          setEditingId(null);
          setFormData({ name: '', level: 'Fase E (10)', homeroomTeacher: '', curriculumStatus: 'Merdeka Mandiri' });
      }
      setIsModalOpen(true);
  };

  const handleSaveClass = (e: React.FormEvent) => {
      e.preventDefault();

      if (editingId) {
          // Update
          const updatedClasses = classes.map(c => c.id === editingId ? { 
              ...c, 
              ...formData,
              curriculumStatus: formData.curriculumStatus as ClassInfo['curriculumStatus']
          } : c);
          setClasses(updatedClasses);
      } else {
          // Add
          const newClass: ClassInfo = {
              id: Date.now().toString(),
              name: formData.name,
              level: formData.level,
              homeroomTeacher: formData.homeroomTeacher || 'Belum ditentukan',
              studentCount: 0,
