        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <a className="hover:text-primary cursor-pointer">Input Nilai</a>
        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <span className="text-slate-900 font-bold">{subject.name}</span>
      </div>

      {/* Header */}
      <div className="flex flex-wrap justify-between items-end gap-4 mb-6">
        <div className="flex flex-col gap-1">
          <h1 className="text-slate-900 text-3xl font-extrabold tracking-tight">Matrix Grade Input Sheet</h1>
          <p className="text-slate-500">Kurikulum Merdeka • {subject.name} • Semester Ganjil</p>
        </div>
        <div className="flex gap-3">
          <button className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 rounded-lg text-sm font-medium hover:bg-slate-50 transition-colors text-slate-700 shadow-sm">
            <span className="material-symbols-outlined text-lg text-primary">settings</span>
            Ubah Parameter Nilai
          </button>
        </div>
      </div>

      {/* Toolbar */}
      <div className="bg-white border border-slate-200 rounded-t-xl p-3 flex justify-between items-center">
        <div className="flex gap-4 items-center">
             {/* Class Filter Dropdown */}
             <div className="relative">
                <select 
                    value={selectedClass} 
                    onChange={(e) => setSelectedClass(e.target.value)}
                    className="appearance-none pl-10 pr-8 py-2 border border-slate-200 rounded-lg text-sm font-bold text-slate-700 bg-slate-50 hover:bg-white focus:ring-2 focus:ring-primary focus:border-transparent outline-none cursor-pointer transition-all"
                >
                    <option value="">Semua Kelas</option>
                    {availableClasses.map(cls => (
                        <option key={cls} value={cls}>{cls}</option>
                    ))}
                </select>
                <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-500 pointer-events-none text-lg">filter_alt</span>
                <span className="material-symbols-outlined absolute right-2 top-3 text-slate-400 pointer-events-none text-sm">expand_more</span>
            </div>
        </div>
        <div className="flex items-center gap-4">
           <span className="text-xs font-semibold text-slate-400 uppercase tracking-wider hidden md:block">Format: Excel Spreadsheet</span>
        </div>
      </div>

      {/* Main Matrix Table */}
      <div className="bg-white border border-t-0 border-slate-200 rounded-b-xl overflow-hidden shadow-sm flex flex-col">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left border-collapse table-fixed">
            <thead>
               {/* Group Headers */}
               <tr className="bg-slate-50 border-b border-slate-200">
                  <th className="sticky-col bg-slate-50 w-12 px-4 py-2 border-r border-slate-200"></th>
                  <th className="sticky-col-2 bg-slate-50 w-64 px-4 py-2 border-r border-slate-200"></th>
                  {tps.map(tp => (
