import React, { useState, useCallback, useEffect, useMemo } from 'react';
import { z } from 'zod'; 
import { 
  Student, 
  LearningObjective, 
  GradeData, 
  Subject 
} from '../types';
import { calculateStudentGrade } from '../utils/grading';

interface Props {
  students: Student[];
  tps: LearningObjective[];
  subject: Subject;
  initialClass?: string;
}

const scoreSchema = z.number().min(0, "Min 0").max(100, "Max 100").optional();

// Mock Subjects for the Dropdown (Simulating multiple subjects)
const AVAILABLE_SUBJECTS = [
    { id: 's1', name: 'Matematika - Fase E' },
    { id: 's2', name: 'Fisika - Fase E' },
    { id: 's3', name: 'Kimia - Fase E' },
];

export const GradingSheet: React.FC<Props> = ({ students, tps, subject, initialClass }) => {
  const [gradeData, setGradeData] = useState<GradeData>({});
  const [errorMap, setErrorMap] = useState<{[key: string]: string}>({});
  const [currentTime, setCurrentTime] = useState(new Date());

  // Filters
  const [selectedClass, setSelectedClass] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>(subject.id);

  // Effect to handle navigation from Dashboard
  useEffect(() => {
    if (initialClass) {
        setSelectedClass(initialClass);
    }
  }, [initialClass]);

  // Derive unique classes from students list
  const availableClasses = useMemo(() => {
      const classes = new Set(students.map(s => s.className).filter(Boolean));
      return Array.from(classes).sort() as string[];
  }, [students]);

  // Filter students based on selection
  const filteredStudents = useMemo(() => {
      if (!selectedClass) return [];
      return students.filter(s => s.className === selectedClass);
  }, [students, selectedClass]);

  useEffect(() => {
    // Update time every minute
    const interval = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(interval);
  }, []);

  const handleScoreChange = useCallback((
    studentId: string, 
    type: 'criteria' | 'attitude', 
    id: string | 'value', 
    value: string
  ) => {
    const numValue = value === '' ? undefined : parseFloat(value);
    const result = scoreSchema.safeParse(numValue);
    const errorKey = `${studentId}-${type}-${id}`;

    if (!result.success && value !== '') {
        setErrorMap(prev => ({...prev, [errorKey]: result.error.errors[0].message}));
    } else {
        setErrorMap(prev => {
            const newMap = {...prev};
            delete newMap[errorKey];
            return newMap;
        });
    }

    setGradeData(prev => {
      const studentData = prev[studentId] || { scores: {}, attitude: 0 };
      if (type === 'criteria') {
        return { ...prev, [studentId]: { ...studentData, scores: { ...studentData.scores, [id]: numValue as number } } };
      } else {
        return { ...prev, [studentId]: { ...studentData, attitude: numValue || 0 } };
      }
    });
  }, []);

  // Stats Calculation (based on filtered students)
  const stats = filteredStudents.reduce((acc, student) => {
      const res = calculateStudentGrade(student.id, gradeData, subject.kktp);
      if (res.finalScore > 0) {
          if (res.isPassed) acc.tuntas++; else acc.remedial++;
      }
      return acc;
  }, { tuntas: 0, remedial: 0 });

  return (
    <div className="max-w-[1440px] mx-auto pb-8">
      {/* Breadcrumbs */}
      <div className="flex items-center gap-2 mb-4 text-sm font-medium text-slate-500">
        <a className="hover:text-primary cursor-pointer">Dashboard</a>
        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <a className="hover:text-primary cursor-pointer">Input Nilai</a>
        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <span className="text-slate-900 font-bold">{subject.name}</span>
      </div>

      {/* Header */}
      <div className="flex flex-wrap justify-between items-end gap-4 mb-6">
        <div className="flex flex-col gap-1">
          <h1 className="text-slate-900 text-3xl font-extrabold tracking-tight">Input Nilai Siswa</h1>
          <p className="text-slate-500">Pilih Kelas dan Mata Pelajaran untuk mulai mengisi nilai.</p>
        </div>
      </div>

      {/* Toolbar / Filter Section */}
      <div className="bg-white border border-slate-200 rounded-t-xl p-4 flex flex-col md:flex-row gap-4 justify-between items-start md:items-center shadow-sm z-20 relative">
        <div className="flex flex-col md:flex-row gap-4 items-center w-full md:w-auto">

             {/* Class Filter Dropdown */}
             <div className="relative w-full md:w-56">
                <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Kelas</label>
                <div className="relative">
                    <select 
                        value={selectedClass} 
                        onChange={(e) => setSelectedClass(e.target.value)}
                        className="w-full appearance-none pl-10 pr-8 py-2.5 border border-slate-200 rounded-lg text-sm font-bold text-slate-900 bg-slate-50 hover:bg-white focus:ring-2 focus:ring-primary focus:border-transparent outline-none cursor-pointer transition-all"
                    >
                        <option value="">-- Pilih Kelas --</option>
                        {availableClasses.map(cls => (
                            <option key={cls} value={cls}>{cls}</option>
                        ))}
                    </select>
                    <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-500 pointer-events-none text-lg">school</span>
