                            tp.criteria.map(cr => (
                                <th 
                                    key={cr.id} 
                                    className="w-24 px-2 py-3 text-xs font-bold text-slate-600 text-center border-r border-slate-200 relative group cursor-help bg-slate-50 hover:bg-blue-50 transition-colors"
                                >
                                    {cr.code.toUpperCase()}
                                    {/* Tooltip for Criteria */}
                                    <div className="absolute hidden group-hover:block bg-slate-800 text-white p-2 rounded-lg text-xs w-48 bottom-full mb-2 left-1/2 -translate-x-1/2 z-50 font-normal shadow-xl">
                                        <div className="font-bold text-green-200 mb-0.5 border-b border-white/20 pb-1">{cr.code.toUpperCase()}</div>
                                        {cr.description}
                                        {/* Little triangle arrow */}
                                        <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-slate-800"></div>
                                    </div>
                                </th>
                            ))
                        ) : (
                            <th key={`empty-${tp.id}`} className="w-24 px-2 py-3 text-xs font-bold text-red-300 text-center border-r border-slate-200 italic">No Criteria</th>
                        )
                    ))}
                    <th className="w-24 px-4 py-3 text-xs font-bold text-slate-600 text-center border-r border-slate-200">Sikap</th>
                    <th className="w-24 px-4 py-3 text-xs font-bold text-slate-600 text-center border-r border-slate-200">NA</th>
                    <th className="w-40 px-4 py-3 text-xs font-bold text-slate-600 text-center">Status</th>
                </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {filteredStudents.length > 0 ? (
                        filteredStudents.map((student, index) => {
                            const result = calculateStudentGrade(student.id, gradeData, subject.kktp);
                            return (
                                <tr key={student.id} className="group hover:bg-primary/5 transition-colors">
                                    <td className="sticky-col bg-white group-hover:bg-[#f2f8fe] text-center text-xs text-slate-500 border-r border-slate-100 transition-colors">{index + 1}</td>
                                    <td className="sticky-col-2 bg-white group-hover:bg-[#f2f8fe] px-4 py-0 font-medium text-sm text-slate-700 border-r border-slate-100 transition-colors">
                                        {student.name}
                                        <div className="flex gap-2 items-center mt-0.5">
                                            <span className="text-[10px] text-slate-400 font-normal bg-slate-50 px-1 rounded">{student.nis}</span>
                                            {!selectedClass && <span className="text-[10px] text-blue-500 font-bold bg-blue-50 px-1 rounded">{student.className}</span>}
                                        </div>
                                    </td>

                                    {/* Dynamic Criteria Inputs Nested by TP */}
                                    {tps.map(tp => (
                                        tp.criteria.length > 0 ? (
                                            tp.criteria.map(cr => {
                                                const err = errorMap[`${student.id}-criteria-${cr.id}`];
                                                return (
                                                    <td key={cr.id} className="p-0 border-r border-slate-100 relative">
                                                        <input 
                                                            type="number" 
                                                            className={`w-full h-10 border-none bg-transparent text-center text-sm focus:ring-0 focus:bg-white focus:shadow-inner ${err ? 'text-red-500 bg-red-50' : 'text-slate-800'}`}
                                                            value={gradeData[student.id]?.scores?.[cr.id] ?? ''}
                                                            onChange={(e) => handleScoreChange(student.id, 'criteria', cr.id, e.target.value)}
                                                            placeholder="-"
                                                        />
                                                    </td>
                                                );
                                            })
                                        ) : (
                                            <td key={`empty-cell-${tp.id}`} className="p-0 border-r border-slate-100 bg-slate-50"></td>
                                        )
                                    ))}

                                    {/* Attitude */}
                                    <td className="p-0 border-r border-slate-100">
                                        <input 
                                            type="number"
                                            className="w-full h-10 border-none bg-transparent text-center text-sm focus:ring-0 focus:bg-white focus:shadow-inner text-slate-800"
                                            value={gradeData[student.id]?.attitude ?? ''}
                                            onChange={(e) => handleScoreChange(student.id, 'attitude', 'value', e.target.value)}
                                            placeholder="-"
                                        />
                                    </td>
                                    {/* Final & Status */}
                                    <td className="px-4 text-center font-bold text-sm bg-slate-50 border-r border-slate-200 text-primary">
                                        {result.finalScore || '-'}
                                    </td>
                                    <td className="px-4 text-center">
                                        {result.finalScore > 0 && (
                                            <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider ${result.isPassed ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                {result.isPassed ? 'Tuntas' : 'Remedial'}
                                            </span>
                                        )}
                                    </td>
                                </tr>
                            )
                        })
                    ) : (
                        <tr>
                            <td colSpan={10} className="p-12 text-center text-slate-400 italic bg-slate-50/50">
                                Tidak ada siswa di kelas ini.
                            </td>
                        </tr>
                    )}
                </tbody>
            </table>
            </div>

            {/* Footer Stats */}
            <div className="bg-slate-50 border-t border-slate-200 px-6 py-3 flex justify-between items-center text-xs font-semibold text-slate-500">
                <div className="flex gap-6">
                    <span>TOTAL SISWA: {filteredStudents.length}</span>
                    <span className="text-green-600">TUNTAS: {stats.tuntas}</span>
                    <span className="text-red-600">REMEDIAL: {stats.remedial}</span>
                </div>
            </div>
        </div>
      ) : (
        <div className="bg-white border border-t-0 border-slate-200 rounded-b-xl p-12 flex flex-col items-center justify-center text-slate-400 min-h-[400px]">
             <div className="bg-slate-50 p-6 rounded-full mb-4">
                <span className="material-symbols-outlined text-4xl text-slate-300">fact_check</span>
             </div>
             <p className="text-lg font-bold text-slate-600">Mulai Penilaian</p>
             <p className="text-sm">Silahkan pilih <strong className="text-slate-700">Kelas</strong> dan <strong className="text-slate-700">Mata Pelajaran</strong> terlebih dahulu untuk menampilkan lembar kerja.</p>
        </div>
      )}

      {/* System Status */}
      <div className="mt-4 flex justify-between items-center text-[10px] uppercase tracking-widest text-slate-400">
        <div className="flex items-center gap-2">
            <span className="size-2 rounded-full bg-green-500 animate-pulse"></span>
            System Ready
        </div>
        <div>
          Last Sync: {currentTime.toLocaleTimeString('id-ID', {timeZone: 'Asia/Makassar', hour: '2-digit', minute: '2-digit'})} WITA
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { LearningMaterial, LearningObjective, Subject, AssessmentCriteria } from '../types';

declare const Swal: any;

interface Props {
  subject: Subject;
  tps: LearningObjective[];
  onUpdateSubject: (kktp: number) => void;
  onUpdateTPs: (tps: LearningObjective[]) => void;
  onBack: () => void;
}

export const CurriculumManager: React.FC<Props> = ({ 
  subject, tps, onUpdateSubject, onUpdateTPs, onBack 
}) => {
  const [expandedTpId, setExpandedTpId] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState<string | null>(null);

  // TP Form State
  const [isAddingTp, setIsAddingTp] = useState(false);
  const [newTpForm, setNewTpForm] = useState({ code: '', description: '', semester: '1' });

  // Sub-item Form State (LM & Criteria)
  const [newItemForm, setNewItemForm] = useState<{
      type: 'LM' | 'CRITERIA' | null, 
      parentId: string | null,
      val1: string, // Code
      val2: string // Title/Description
  }>({ type: null, parentId: null, val1: '', val2: '' });

  // --- TP CRUD ---
  const handleAddTP = () => {
    if(!newTpForm.code || !newTpForm.description) return;
    const newTp: LearningObjective = {
        id: Date.now().toString(),
        code: newTpForm.code.toUpperCase(), // Force Uppercase
        description: newTpForm.description,
        semester: Number(newTpForm.semester) as 1 | 2,
        lms: [],
        criteria: []
    };
    onUpdateTPs([...tps, newTp]);
    setIsAddingTp(false);
    setNewTpForm({ code: '', description: '', semester: '1' });
  };

  const handleDeleteTP = (id: string) => {
      Swal.fire({
          title: 'Hapus Tujuan Pembelajaran?',
          text: "Seluruh Lingkup Materi (LM) dan Kriteria yang ada di dalamnya akan ikut terhapus!",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Ya, hapus!',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateTPs(tps.filter(t => t.id !== id));
              Swal.fire(
                  'Terhapus!',
                  'TP berhasil dihapus.',
                  'success'
              )
          }
      });
  };

  // --- NESTED ITEMS CRUD ---
  const handleAddItem = () => {
      if(!newItemForm.val1 || !newItemForm.val2 || !newItemForm.parentId || !newItemForm.type) return;

      const updatedTPs = tps.map(tp => {
          if(tp.id === newItemForm.parentId) {
              if(newItemForm.type === 'LM') {
                  return {
                      ...tp,
                      lms: [...tp.lms, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), // Force Uppercase
                          title: newItemForm.val2 
                      }]
                  };
              } else {
                  return {
                      ...tp,
                      criteria: [...tp.criteria, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), // Force Uppercase
                          description: newItemForm.val2 
                      }]
                  };
              }
          }
          return tp;
      });

      onUpdateTPs(updatedTPs);
      setNewItemForm({ type: null, parentId: null, val1: '', val2: '' });
  };

  const handleDeleteSubItem = (tpId: string, itemId: string, type: 'LM' | 'CRITERIA') => {
      Swal.fire({
          title: 'Hapus Item?',
          text: "Item ini akan dihapus permanen.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Hapus',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              const updatedTPs = tps.map(tp => {
                  if(tp.id === tpId) {
                      if(type === 'LM') {
                          return { ...tp, lms: tp.lms.filter(l => l.id !== itemId) };
                      } else {
                          return { ...tp, criteria: tp.criteria.filter(c => c.id !== itemId) };
                      }
                  }
                  return tp;
              });
              onUpdateTPs(updatedTPs);
          }
      });
  };

  // --- AI GENERATION LOGIC ---
  const handleGenerateAI = (tp: LearningObjective) => {
      setIsGenerating(tp.id);

      // Simulate AI Processing
      setTimeout(() => {
          let keywords: string[] = [];
          const desc = tp.description.toLowerCase();

          if(desc.includes('eksponen')) keywords.push('Sifat Eksponen', 'Grafik Eksponen');
          else if(desc.includes('logaritma')) keywords.push('Sifat Logaritma', 'Persamaan Logaritma');
          else if(desc.includes('biotik')) keywords.push('Komponen Biotik', 'Komponen Abiotik', 'Interaksi Ekosistem');
          else if(desc.includes('algoritma')) keywords.push('Flowchart', 'Pseudocode');
          else keywords.push('Konsep Dasar', 'Penerapan Masalah');

          let criteriaDesc = 'Pemahaman Konsep';
          if(desc.startsWith('menganalisis')) criteriaDesc = 'Kemampuan Analisis';
          if(desc.startsWith('menciptakan') || desc.startsWith('membuat')) criteriaDesc = 'Kreativitas Produk';
          if(desc.startsWith('menyelesaikan')) criteriaDesc = 'Pemecahan Masalah';

          const newLMs: LearningMaterial[] = keywords.map((k, i) => ({
              id: `gen-lm-${Date.now()}-${i}`,
              code: `LM.${tp.code.split('.')[1]}.${i+1}`.toUpperCase(),
              title: k
          }));

          const newCriteria: AssessmentCriteria[] = [
              {
                  id: `gen-cr-${Date.now()}-1`,
                  code: `KR.${tp.code.split('.')[1]}.1`, // Changed to KR
                  description: criteriaDesc
              },
              {
                  id: `gen-cr-${Date.now()}-2`,
                  code: `KR.${tp.code.split('.')[1]}.2`, // Changed to KR
                  description: 'Keterampilan Proses' 
              }
          ];

          const updatedTPs = tps.map(t => {
              if(t.id === tp.id) {
                  return {
                      ...t,
                      lms: [...t.lms, ...newLMs],
                      criteria: [...t.criteria, ...newCriteria]
                  };
              }
              return t;
          });

          onUpdateTPs(updatedTPs);
          setIsGenerating(null);
          setExpandedTpId(tp.id); // Auto expand
      }, 1500);
  };

  return (
    <div className="h-full flex flex-col bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Header */}
        <div className="bg-gray-50 p-6 border-b flex justify-between items-center">
            <div>
                <h2 className="text-xl font-bold text-gray-800">Manajemen Kurikulum & Asesmen</h2>
                <p className="text-sm text-gray-500">Struktur TP, Lingkup Materi, dan Kriteria Penilaian</p>
            </div>
             <button onClick={onBack} className="text-gray-500 hover:text-gray-700 font-medium">
                &larr; Kembali
            </button>
        </div>

        {/* Global Config */}
        <div className="px-6 py-4 bg-white border-b flex items-center justify-between">
             <div className="flex items-center gap-4">
                <div className="bg-blue-100 p-2 rounded-lg text-blue-600">
                    <span className="material-symbols-outlined">tune</span>
                </div>
                <div>
                    <label className="text-xs font-bold text-gray-500 uppercase">KKTP Mapel</label>
                    <div className="flex items-center gap-2">
                         <input 
                            type="number" 
                            value={subject.kktp}
                            onChange={(e) => onUpdateSubject(Number(e.target.value))}
                            className="w-16 p-1 text-center font-bold text-blue-700 border-b-2 border-blue-200 focus:border-blue-500 outline-none bg-transparent"
                        />
                        <span className="text-sm text-gray-400">Poin</span>
                    </div>
                </div>
            </div>
            <button 
                onClick={() => setIsAddingTp(!isAddingTp)}
                className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 transition-colors shadow-sm"
            >
                <span className="material-symbols-outlined text-sm">{isAddingTp ? 'remove' : 'add'}</span>
                Tambah Tujuan Pembelajaran
            </button>
        </div>

        {/* Add TP Form */}
        {isAddingTp && (
            <div className="mx-6 mt-6 p-4 bg-blue-50 border border-blue-100 rounded-xl animate-in fade-in slide-in-from-top-4">
                <h4 className="font-bold text-blue-800 mb-3 text-sm">Tambah TP Baru</h4>
                <div className="flex gap-3 items-start">
                     <div className="w-24">
                        <input 
                            type="text" placeholder="Kode" 
                            value={newTpForm.code} onChange={e => setNewTpForm({...newTpForm, code: e.target.value.toUpperCase()})}
                            className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900 placeholder:text-slate-400"
                        />
                    </div>
                     <div className="w-24">
                        <select 
                            value={newTpForm.semester} onChange={e => setNewTpForm({...newTpForm, semester: e.target.value})}
                            className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900"
                        >
                            <option value="1">Smt 1</option>
                            <option value="2">Smt 2</option>
                        </select>
                    </div>
                    <div className="flex-1">
                        <input 
                            type="text" placeholder="Deskripsi Tujuan Pembelajaran..." 
                            value={newTpForm.description} onChange={e => setNewTpForm({...newTpForm, description: e.target.value})}
                            className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900"
                        />
                    </div>
                    <button onClick={handleAddTP} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold text-sm hover:bg-blue-700">Simpan</button>
                </div>
            </div>
        )}

        {/* TP List */}
        <div className="flex-1 overflow-y-auto p-6 space-y-4">
            {tps.length === 0 && (
                <div className="text-center py-12 text-gray-400">
                    <span className="material-symbols-outlined text-4xl mb-2">library_books</span>
                    <p>Belum ada Tujuan Pembelajaran.</p>
                </div>
            )}

            {tps.map((tp) => {
                const isExpanded = expandedTpId === tp.id;
                return (
                    <div key={tp.id} className={`border rounded-xl transition-all ${isExpanded ? 'border-primary shadow-md bg-white' : 'border-slate-200 bg-white hover:border-slate-300'}`}>
                        {/* TP Header */}
                        <div 
                            onClick={() => setExpandedTpId(isExpanded ? null : tp.id)}
                            className="p-4 flex items-center gap-4 cursor-pointer"
                        >
                            <div className={`size-10 rounded-lg flex items-center justify-center font-bold text-sm ${isExpanded ? 'bg-primary text-white' : 'bg-slate-100 text-slate-500'}`}>
                                {tp.code.toUpperCase()}
                            </div>
                            <div className="flex-1">
                                <p className={`text-sm font-bold ${isExpanded ? 'text-primary' : 'text-slate-800'}`}>{tp.description}</p>
                                <div className="flex items-center gap-2 mt-1">
                                    <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500">Semester {tp.semester}</span>
                                    <span className="text-[10px] text-slate-400 flex items-center gap-1">
                                        <span className="material-symbols-outlined text-[10px]">topic</span> {tp.lms.length} LM
                                    </span>
                                    <span className="text-[10px] text-slate-400 flex items-center gap-1">
                                        <span className="material-symbols-outlined text-[10px]">fact_check</span> {tp.criteria.length} Kriteria
                                    </span>
                                </div>
                            </div>
                            <button 
                                onClick={(e) => { e.stopPropagation(); handleDeleteTP(tp.id); }}
                                className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                            >
                                <span className="material-symbols-outlined">delete</span>
                            </button>
                            <span className={`material-symbols-outlined text-slate-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`}>expand_more</span>
                        </div>

                        {/* Expanded Content */}
                        {isExpanded && (
                            <div className="border-t border-slate-100 bg-slate-50/50 p-4 space-y-6 animate-in slide-in-from-top-2">

                                {/* Lingkup Materi Section */}
                                <div className="space-y-3">
                                    <div className="flex justify-between items-center">
                                        <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
                                            <span className="material-symbols-outlined text-sm">topic</span>
                                            Lingkup Materi (LM)
                                        </h4>
                                    </div>
                                    <div className="bg-white border border-slate-200 rounded-lg overflow-hidden">
                                        <table className="w-full text-sm">
                                            <thead className="bg-slate-50 text-slate-500 font-semibold border-b border-slate-200">
                                                <tr>
                                                    <th className="px-4 py-2 text-left w-24">Kode</th>
                                                    <th className="px-4 py-2 text-left">Judul Materi</th>
                                                    <th className="px-4 py-2 w-16"></th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-slate-100">
                                                {tp.lms.map(lm => (
                                                    <tr key={lm.id} className="group hover:bg-slate-50">
                                                        <td className="px-4 py-2 font-mono text-xs font-bold text-blue-600">{lm.code.toUpperCase()}</td>
                                                        <td className="px-4 py-2 text-slate-800">{lm.title}</td>
                                                        <td className="px-4 py-2 text-right">
                                                            <button 
                                                                onClick={() => handleDeleteSubItem(tp.id, lm.id, 'LM')}
                                                                className="text-slate-300 hover:text-red-500 group-hover:text-slate-400"
                                                            >
                                                                <span className="material-symbols-outlined text-sm">close</span>
                                                            </button>
                                                        </td>
                                                    </tr>
                                                ))}
                                                 {/* Add Row */}
                                                 <tr className="bg-slate-50">
                                                    <td className="px-2 py-2">
                                                        <input 
                                                            type="text" placeholder="LM.x" 
                                                            className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-blue-500 bg-white text-slate-900"
                                                            value={newItemForm.type === 'LM' && newItemForm.parentId === tp.id ? newItemForm.val1 : ''}
                                                            onChange={(e) => setNewItemForm({ type: 'LM', parentId: tp.id, val1: e.target.value.toUpperCase(), val2: newItemForm.val2 })}
                                                            onFocus={() => setNewItemForm(prev => ({ ...prev, type: 'LM', parentId: tp.id }))}
                                                        />
                                                    </td>
                                                    <td className="px-2 py-2">
                                                        <input 
                                                            type="text" placeholder="Tambah Lingkup Materi..." 
                                                            className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-blue-500 bg-white text-slate-900"
                                                            value={newItemForm.type === 'LM' && newItemForm.parentId === tp.id ? newItemForm.val2 : ''}
                                                            onChange={(e) => setNewItemForm({ type: 'LM', parentId: tp.id, val1: newItemForm.val1, val2: e.target.value })}
                                                            onKeyDown={(e) => e.key === 'Enter' && handleAddItem()}
                                                        />
                                                    </td>
                                                    <td className="px-2 py-2 text-center">
                                                         {newItemForm.type === 'LM' && newItemForm.parentId === tp.id && newItemForm.val1 && (
                                                            <button onClick={handleAddItem} className="text-blue-600 hover:text-blue-800">
                                                                <span className="material-symbols-outlined text-lg">check_circle</span>
                                                            </button>
                                                         )}
                                                    </td>
                                                </tr>
                                            </tbody>
                                        </table>
                                    </div>
                                </div>

                                {/* Kriteria Section */}
                                <div className="space-y-3">
                                    <div className="flex justify-between items-center">
                                        <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
                                            <span className="material-symbols-outlined text-sm">fact_check</span>
                                            Kriteria Penilaian (Untuk Matrix Input Nilai)
                                        </h4>
                                    </div>
                                    <div className="bg-white border border-slate-200 rounded-lg overflow-hidden">
                                        <table className="w-full text-sm">
                                            <thead className="bg-slate-50 text-slate-500 font-semibold border-b border-slate-200">
                                                <tr>
                                                    <th className="px-4 py-2 text-left w-24">Kode</th>
                                                    <th className="px-4 py-2 text-left">Deskripsi Kriteria</th>
                                                    <th className="px-4 py-2 w-16"></th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-slate-100">
                                                {tp.criteria.map(cr => (
                                                    <tr key={cr.id} className="group hover:bg-slate-50">
                                                        <td className="px-4 py-2 font-mono text-xs font-bold text-green-600">{cr.code.toUpperCase()}</td>
                                                        <td className="px-4 py-2 text-slate-800">{cr.description}</td>
                                                        <td className="px-4 py-2 text-right">
                                                            <button 
                                                                onClick={() => handleDeleteSubItem(tp.id, cr.id, 'CRITERIA')}
                                                                className="text-slate-300 hover:text-red-500 group-hover:text-slate-400"
                                                            >
                                                                <span className="material-symbols-outlined text-sm">close</span>
                                                            </button>
                                                        </td>
                                                    </tr>
                                                ))}
                                                 {/* Add Row */}
                                                 <tr className="bg-slate-50">
                                                    <td className="px-2 py-2">
                                                        <input 
                                                            type="text" placeholder="KR.x" 
                                                            className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-green-500 bg-white text-slate-900"
                                                            value={newItemForm.type === 'CRITERIA' && newItemForm.parentId === tp.id ? newItemForm.val1 : ''}
                                                            onChange={(e) => setNewItemForm({ type: 'CRITERIA', parentId: tp.id, val1: e.target.value.toUpperCase(), val2: newItemForm.val2 })}
                                                            onFocus={() => setNewItemForm(prev => ({ ...prev, type: 'CRITERIA', parentId: tp.id }))}
                                                        />
                                                    </td>
                                                    <td className="px-2 py-2">
                                                        <input 
                                                            type="text" placeholder="Tambah Kriteria Penilaian..." 
                                                            className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-green-500 bg-white text-slate-900"
                                                            value={newItemForm.type === 'CRITERIA' && newItemForm.parentId === tp.id ? newItemForm.val2 : ''}
                                                            onChange={(e) => setNewItemForm({ type: 'CRITERIA', parentId: tp.id, val1: newItemForm.val1, val2: e.target.value })}
                                                            onKeyDown={(e) => e.key === 'Enter' && handleAddItem()}
                                                        />
                                                    </td>
                                                    <td className="px-2 py-2 text-center">
                                                         {newItemForm.type === 'CRITERIA' && newItemForm.parentId === tp.id && newItemForm.val1 && (
                                                            <button onClick={handleAddItem} className="text-green-600 hover:text-green-800">
                                                                <span className="material-symbols-outlined text-lg">check_circle</span>
                                                            </button>
                                                         )}
                                                    </td>
                                                </tr>
                                            </tbody>
                                        </table>
                                    </div>
                                </div>

                            </div>
                        )}
                    </div>
                );
            })}
        </div>
    </div>
  );
};

// Domain Models

export interface Student {
  id: string;
  name: string;
  nis: string;
  className?: string; // e.g., "10-A IPA"
}

export interface ClassInfo {
  id: string;
  name: string; // e.g. "10-A IPA"
  level: string; // e.g. "Fase E (Kelas 10)"
  studentCount: number;
}

export interface ScheduleItem {
  id: string;
  day: string; // Senin, Selasa, etc
  startTime: string; // "07:30"
  endTime: string; // "09:00"
  className: string;
  subject: string;
  room: string;
}

export interface LearningMaterial { // LM (Lingkup Materi) - Now Child of TP
  id: string;
  code: string; // e.g., LM.1
  title: string;
}

export interface AssessmentCriteria { // Kriteria Penilaian - Child of TP
  id: string;
  code: string; // e.g., Kr.1
  description: string; // e.g., "Pemahaman Konsep"
}

export interface LearningObjective { // TP (Tujuan Pembelajaran)
  id: string;
  code: string; // e.g., TP.1
  description: string;
  semester?: 1 | 2; // Optional, defaulted if missing
  lms: LearningMaterial[]; // Nested LMs
  criteria: AssessmentCriteria[]; // Nested Criteria for Grading
}

export interface Subject {
  id: string;
  name: string;
  kktp: number; // Kriteria Ketercapaian Tujuan Pembelajaran (Passing Grade)
}

export interface GradeData {
  [studentId: string]: {
    scores: { [criteriaId: string]: number }; // Maps Criteria ID -> Score
    attitude: number; // Nilai Sikap
  };
}

export interface CalculatedGrade {
  avgScore: number;
  finalScore: number;
  isPassed: boolean;
}

// Identity Data
export interface IdentityData {
  schoolName: string;
  subjectName: string;
  teacherName: string;
  nip: string;
  semester: string;
  academicYear: string;
  className: string;
  studentCount: number;
}

// Attendance Types
export type AttendanceStatus = 'H' | 'I' | 'S' | 'A'; // Hadir, Izin, Sakit, Alfa

export interface AttendanceSession {
  id: string;
  date: string;
  topic: string;
}

export interface AttendanceData {
  [studentId: string]: {
    [sessionId: string]: AttendanceStatus;
  };
}

