import React, { useState, useMemo } from 'react';
import ExcelJS from 'exceljs';
import { Student, Subject, IdentityData } from '../types';

interface Props {
  students: Student[];
  subject: Subject;
  identity: IdentityData;
}

const AVAILABLE_SUBJECTS = [
    { id: 's1', name: 'Matematika - Fase E' },
    { id: 's2', name: 'Fisika - Fase E' },
    { id: 's3', name: 'Kimia - Fase E' },
];

export const RecapManager: React.FC<Props> = ({ students, subject, identity }) => {
  const [selectedClass, setSelectedClass] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>(subject.id);
  const [activeTab, setActiveTab] = useState<'GRADES' | 'ATTENDANCE'>('GRADES');

  // Derive unique classes
  const availableClasses = useMemo(() => {
    const classes = new Set(students.map(s => s.className).filter(Boolean));
    return Array.from(classes).sort() as string[];
  }, [students]);

  // Filter students
  const filteredStudents = useMemo(() => {
    if (!selectedClass) return [];
    return students.filter(s => s.className === selectedClass);
  }, [students, selectedClass]);

  // Mock Aggregated Data Generation (Since backend is not connected)
  const reportData = useMemo(() => {
    return filteredStudents.map(student => {
        // Randomize Grades
        const formative = Math.floor(Math.random() * (95 - 75) + 75);
        const summative = Math.floor(Math.random() * (90 - 70) + 70);
        const attitude = Math.floor(Math.random() * (100 - 80) + 80);

        // Final Score Calculation (0.4 Formative + 0.5 Summative + 0.1 Attitude)
        const finalScore = Math.round((formative * 0.4) + (summative * 0.5) + (attitude * 0.1));
        const isPassed = finalScore >= subject.kktp;

        // Randomize Attendance
        const totalMeetings = 20;
        const present = Math.floor(Math.random() * (20 - 15) + 15);
        const permit = Math.floor(Math.random() * 3);
        const sick = Math.floor(Math.random() * 2);
        const absent = totalMeetings - (present + permit + sick);
        const percentage = Math.round((present / totalMeetings) * 100);

        return {
            ...student,
            grades: { formative, summative, attitude, finalScore, isPassed },
            attendance: { present, permit, sick, absent, percentage }
        };
    });
  }, [filteredStudents, subject.kktp]);

  // --- EXCEL EXPORT LOGIC ---
  const handleExportExcel = async () => {
    if (reportData.length === 0) return;

    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet(activeTab === 'GRADES' ? 'Rekap Nilai' : 'Rekap Presensi');

    // Add Header Info
    sheet.addRow([identity.schoolName]);
    sheet.addRow([`REKAPITULASI ${activeTab === 'GRADES' ? 'NILAI' : 'PRESENSI'} SISWA`]);
    sheet.addRow([`Kelas: ${selectedClass}`, `Mapel: ${AVAILABLE_SUBJECTS.find(s => s.id === selectedSubject)?.name || subject.name}`]);
    sheet.addRow([`Tahun Ajaran: ${identity.academicYear}`, `Semester: ${identity.semester}`]);
    sheet.addRow([]); // Spacer

    // Define Columns based on Tab
    if (activeTab === 'GRADES') {
        sheet.addRow(['No', 'NIS', 'Nama Siswa', 'Rata-rata Formatif', 'Rata-rata Sumatif', 'Nilai Sikap', 'Nilai Akhir', 'Status']);

        // Style Header Row
        const headerRow = sheet.getRow(6);
        headerRow.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        headerRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } };

        reportData.forEach((d, i) => {
            const row = sheet.addRow([
                i + 1, d.nis, d.name, d.grades.formative, d.grades.summative, d.grades.attitude, d.grades.finalScore, d.grades.isPassed ? 'TUNTAS' : 'REMEDIAL'
            ]);
            // Conditional Formatting for Status
            const statusCell = row.getCell(8);
            statusCell.font = { color: { argb: d.grades.isPassed ? 'FF008000' : 'FFFF0000' }, bold: true };
        });
    } else {
        sheet.addRow(['No', 'NIS', 'Nama Siswa', 'Hadir (H)', 'Izin (I)', 'Sakit (S)', 'Alfa (A)', 'Persentase (%)']);

        // Style Header Row
        const headerRow = sheet.getRow(6);
        headerRow.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        headerRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } };

        reportData.forEach((d, i) => {
            sheet.addRow([
                i + 1, d.nis, d.name, d.attendance.present, d.attendance.permit, d.attendance.sick, d.attendance.absent, `${d.attendance.percentage}%`
            ]);
        });
    }

    // Auto fit columns (Simple approx)
    sheet.columns.forEach(column => {
        column.width = 15;
    });
    sheet.getColumn(3).width = 30; // Name column

    // Trigger Download
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `Rekap_${activeTab}_${selectedClass}_${new Date().toISOString().slice(0,10)}.xlsx`;
    anchor.click();
    window.URL.revokeObjectURL(url);
  };

  return (
    <div className="max-w-7xl mx-auto pb-10">
      {/* Breadcrumbs */}
      <div className="flex items-center gap-2 mb-4 text-sm font-medium text-slate-500">
