      </div>

      {/* Tabs */}
      <div className="flex gap-2 mb-4 border-b border-slate-200">
         <button 
            onClick={() => setActiveTab('GRADES')}
            className={`px-6 py-3 text-sm font-bold border-b-2 transition-colors flex items-center gap-2 ${activeTab === 'GRADES' ? 'border-primary text-primary' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
         >
            <span className="material-symbols-outlined text-lg">grade</span>
            Rekap Nilai
         </button>
         <button 
