                                    <td className="px-4 text-center">
                                        {result.finalScore > 0 && (
                                            <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider ${result.isPassed ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                {result.isPassed ? 'Tuntas' : 'Remedial'}
                                            </span>
                                        )}
                                    </td>
                                </tr>
                            )
                        })
                    ) : (
                        <tr>
                            <td colSpan={10} className="p-12 text-center text-slate-400 italic bg-slate-50/50">
                                Tidak ada siswa di kelas ini.
                            </td>
                        </tr>
                    )}
                </tbody>
            </table>
            </div>

            {/* Footer Stats */}
            <div className="bg-slate-50 border-t border-slate-200 px-6 py-3 flex justify-between items-center text-xs font-semibold text-slate-500">
                <div className="flex gap-6">
                    <span>TOTAL SISWA: {filteredStudents.length}</span>
                    <span className="text-green-600">TUNTAS: {stats.tuntas}</span>
                    <span className="text-red-600">REMEDIAL: {stats.remedial}</span>
                </div>
            </div>
        </div>
      ) : (
        <div className="bg-white border border-t-0 border-slate-200 rounded-b-xl p-12 flex flex-col items-center justify-center text-slate-400 min-h-[400px]">
             <div className="bg-slate-50 p-6 rounded-full mb-4">
                <span className="material-symbols-outlined text-4xl text-slate-300">fact_check</span>
             </div>
             <p className="text-lg font-bold text-slate-600">Mulai Penilaian</p>
             <p className="text-sm">Silahkan pilih <strong className="text-slate-700">Kelas</strong> dan <strong className="text-slate-700">Mata Pelajaran</strong> terlebih dahulu untuk menampilkan lembar kerja.</p>
        </div>
      )}

      {/* System Status */}
      <div className="mt-4 flex justify-between items-center text-[10px] uppercase tracking-widest text-slate-400">
        <div className="flex items-center gap-2">
            <span className="size-2 rounded-full bg-green-500 animate-pulse"></span>
            System Ready
        </div>
        <div>
          Last Sync: {currentTime.toLocaleTimeString('id-ID', {timeZone: 'Asia/Makassar', hour: '2-digit', minute: '2-digit'})} WITA
        </div>
      </div>

       {/* Config Modal */}
       {showConfig && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
            <div className="bg-white rounded-2xl w-full max-w-sm shadow-2xl">
                <div className="p-4 border-b border-slate-100 flex justify-between items-center">
                    <h3 className="font-bold text-slate-900">Parameter Penilaian</h3>
                    <button onClick={() => setShowConfig(false)} className="text-slate-400 hover:text-slate-600">
                        <span className="material-symbols-outlined">close</span>
                    </button>
                </div>
                <div className="p-6 space-y-4">
                     <div>
                        <label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Bobot Nilai Akademik (Formatif/Sumatif)</label>
                        <div className="flex items-center gap-2">
                            <input 
                                type="number" 
                                value={tempWeights.criteria}
                                onChange={(e) => setTempWeights(prev => ({...prev, criteria: Number(e.target.value)}))}
                                className="w-full border-slate-200 rounded-lg text-center font-bold text-slate-900" 
                            />
                            <span className="text-slate-500 font-bold">%</span>
                        </div>
                     </div>
                     <div>
                        <label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Bobot Nilai Sikap</label>
                        <div className="flex items-center gap-2">
                             <input 
                                type="number" 
                                value={tempWeights.attitude}
                                onChange={(e) => setTempWeights(prev => ({...prev, attitude: Number(e.target.value)}))}
                                className="w-full border-slate-200 rounded-lg text-center font-bold text-slate-900" 
                            />
                            <span className="text-slate-500 font-bold">%</span>
                        </div>
                     </div>
                     <div className={`text-xs font-bold text-center ${tempWeights.criteria + tempWeights.attitude === 100 ? 'text-green-600' : 'text-red-500'}`}>
                         Total: {tempWeights.criteria + tempWeights.attitude}%
                     </div>
                     <button 
                        onClick={handleSaveWeights}
                        className="w-full py-2.5 bg-primary text-white rounded-lg font-bold hover:bg-blue-600"
                     >
                         Simpan Parameter
                     </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import ExcelJS from 'exceljs';
import { Student, Subject, IdentityData } from '../types';

interface Props {
  students: Student[];
  subject: Subject;
  identity: IdentityData;
  mode: 'GRADES' | 'ATTENDANCE'; // New prop
}

const AVAILABLE_SUBJECTS = [
    { id: 's1', name: 'Matematika - Fase E' },
    { id: 's2', name: 'Fisika - Fase E' },
    { id: 's3', name: 'Kimia - Fase E' },
];

export const RecapManager: React.FC<Props> = ({ students, subject, identity, mode }) => {
  const [selectedClass, setSelectedClass] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>(subject.id);
  // Removed internal activeTab state

  // Derive unique classes
  const availableClasses = useMemo(() => {
    const classes = new Set(students.map(s => s.className).filter(Boolean));
    return Array.from(classes).sort() as string[];
  }, [students]);

  // Filter students
  const filteredStudents = useMemo(() => {
    if (!selectedClass) return [];
    return students.filter(s => s.className === selectedClass);
  }, [students, selectedClass]);

  // Mock Aggregated Data Generation (Since backend is not connected)
  const reportData = useMemo(() => {
    return filteredStudents.map(student => {
        // Randomize Grades
        const formative = Math.floor(Math.random() * (95 - 75) + 75);
        const summative = Math.floor(Math.random() * (90 - 70) + 70);
        const attitude = Math.floor(Math.random() * (100 - 80) + 80);

        // Final Score Calculation (0.4 Formative + 0.5 Summative + 0.1 Attitude)
        const finalScore = Math.round((formative * 0.4) + (summative * 0.5) + (attitude * 0.1));
        const isPassed = finalScore >= subject.kktp;

        // Randomize Attendance
        const totalMeetings = 20;
        const present = Math.floor(Math.random() * (20 - 15) + 15);
        const permit = Math.floor(Math.random() * 3);
        const sick = Math.floor(Math.random() * 2);
        const absent = totalMeetings - (present + permit + sick);
        const percentage = Math.round((present / totalMeetings) * 100);

        return {
            ...student,
            grades: { formative, summative, attitude, finalScore, isPassed },
            attendance: { present, permit, sick, absent, percentage }
        };
    });
  }, [filteredStudents, subject.kktp]);

  // --- EXCEL EXPORT LOGIC ---
  const handleExportExcel = async () => {
    if (reportData.length === 0) return;

    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet(mode === 'GRADES' ? 'Rekap Nilai' : 'Rekap Presensi');

    // Add Header Info
    sheet.addRow([identity.schoolName]);
    sheet.addRow([`REKAPITULASI ${mode === 'GRADES' ? 'NILAI' : 'PRESENSI'} SISWA`]);
    sheet.addRow([`Kelas: ${selectedClass}`, `Mapel: ${AVAILABLE_SUBJECTS.find(s => s.id === selectedSubject)?.name || subject.name}`]);
    sheet.addRow([`Tahun Ajaran: ${identity.academicYear}`, `Semester: ${identity.semester}`]);
    sheet.addRow([]); // Spacer

    // Define Columns based on Tab
    if (mode === 'GRADES') {
        sheet.addRow(['No', 'NIS', 'Nama Siswa', 'Rata-rata Formatif', 'Rata-rata Sumatif', 'Nilai Sikap', 'Nilai Akhir', 'Status']);

        // Style Header Row
        const headerRow = sheet.getRow(6);
        headerRow.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        headerRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } };

        reportData.forEach((d, i) => {
            const row = sheet.addRow([
                i + 1, d.nis, d.name, d.grades.formative, d.grades.summative, d.grades.attitude, d.grades.finalScore, d.grades.isPassed ? 'TUNTAS' : 'REMEDIAL'
            ]);
            // Conditional Formatting for Status
            const statusCell = row.getCell(8);
            statusCell.font = { color: { argb: d.grades.isPassed ? 'FF008000' : 'FFFF0000' }, bold: true };
        });
    } else {
        sheet.addRow(['No', 'NIS', 'Nama Siswa', 'Hadir (H)', 'Izin (I)', 'Sakit (S)', 'Alfa (A)', 'Persentase (%)']);

        // Style Header Row
        const headerRow = sheet.getRow(6);
        headerRow.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        headerRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } };

        reportData.forEach((d, i) => {
            sheet.addRow([
                i + 1, d.nis, d.name, d.attendance.present, d.attendance.permit, d.attendance.sick, d.attendance.absent, `${d.attendance.percentage}%`
            ]);
        });
    }

    // Auto fit columns (Simple approx)
    sheet.columns.forEach(column => {
        column.width = 15;
    });
    sheet.getColumn(3).width = 30; // Name column

    // Trigger Download
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `Rekap_${mode}_${selectedClass}_${new Date().toISOString().slice(0,10)}.xlsx`;
    anchor.click();
    window.URL.revokeObjectURL(url);
  };

  return (
    <div className="max-w-7xl mx-auto pb-10">
      {/* Breadcrumbs */}
      <div className="flex items-center gap-2 mb-4 text-sm font-medium text-slate-500">
        <a className="hover:text-primary cursor-pointer">Dashboard</a>
        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <span className="text-slate-900 font-bold">Rekapitulasi {mode === 'GRADES' ? 'Nilai' : 'Presensi'}</span>
      </div>

      {/* Header */}
      <div className="flex justify-between items-end mb-8">
        <div className="flex flex-col gap-1">
          <h2 className="text-slate-900 text-3xl font-extrabold tracking-tight">
              {mode === 'GRADES' ? 'Rekap Nilai Siswa' : 'Rekap Kehadiran Siswa'}
          </h2>
          <p className="text-slate-500">
              {mode === 'GRADES' ? 'Laporan nilai akhir semester.' : 'Laporan persentase kehadiran siswa.'}
          </p>
        </div>
        <div className="flex gap-2">
             <button 
                onClick={handleExportExcel}
                disabled={!selectedClass}
                className="flex items-center gap-2 px-6 py-2.5 bg-green-600 text-white rounded-xl text-sm font-bold hover:bg-green-700 transition-colors shadow-lg shadow-green-100 disabled:opacity-50 disabled:cursor-not-allowed"
             >
                <span className="material-symbols-outlined">table_view</span>
                Export Excel (.xlsx)
            </button>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="bg-white border border-slate-200 rounded-xl p-5 shadow-sm mb-6 flex flex-col md:flex-row gap-6 items-end">
         <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-3 gap-4">
             {/* Subject Selector */}
             <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Mata Pelajaran</label>
                <select 
                    value={selectedSubject} 
                    onChange={(e) => setSelectedSubject(e.target.value)}
                    className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary focus:border-primary"
                >
                    {AVAILABLE_SUBJECTS.map(s => (
                        <option key={s.id} value={s.id}>{s.name}</option>
                    ))}
                </select>
             </div>

             {/* Class Selector */}
             <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Kelas <span className="text-red-500">*</span></label>
                <select 
                    value={selectedClass} 
                    onChange={(e) => setSelectedClass(e.target.value)}
                    className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary focus:border-primary"
                >
                    <option value="">-- Pilih Kelas --</option>
                    {availableClasses.map(cls => (
                        <option key={cls} value={cls}>{cls}</option>
                    ))}
                </select>
             </div>

             {/* Semester Filter (Visual Only) */}
             <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Semester</label>
                <select disabled className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-500 bg-slate-50 cursor-not-allowed">
                    <option>{identity.semester} {identity.academicYear}</option>
                </select>
             </div>
         </div>
      </div>

      {/* Data Table */}
      <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden min-h-[400px]">
         {selectedClass ? (
             <div className="overflow-x-auto custom-scrollbar">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-slate-50 border-b border-slate-200">
                        <tr>
                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase w-16 text-center">No</th>
                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Identitas Siswa</th>

                            {mode === 'GRADES' ? (
                                <>
                                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-center">Formatif (40%)</th>
                                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-center">Sumatif (50%)</th>
                                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-center">Sikap (10%)</th>
                                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-center bg-blue-50/50 text-blue-700">Nilai Akhir</th>
                                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-center">Status</th>
                                </>
                            ) : (
                                <>
                                    <th className="px-6 py-4 text-xs font-bold text-green-600 uppercase text-center bg-green-50">Hadir</th>
                                    <th className="px-6 py-4 text-xs font-bold text-blue-600 uppercase text-center bg-blue-50">Izin</th>
                                    <th className="px-6 py-4 text-xs font-bold text-orange-600 uppercase text-center bg-orange-50">Sakit</th>
                                    <th className="px-6 py-4 text-xs font-bold text-red-600 uppercase text-center bg-red-50">Alfa</th>
                                    <th className="px-6 py-4 text-xs font-bold text-slate-600 uppercase text-center">% Kehadiran</th>
                                </>
                            )}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {reportData.map((d, i) => (
                            <tr key={d.id} className="hover:bg-slate-50 transition-colors">
                                <td className="px-6 py-4 text-center text-sm text-slate-500">{i + 1}</td>
                                <td className="px-6 py-4">
                                    <p className="font-bold text-slate-800 text-sm">{d.name}</p>
                                    <p className="text-[10px] text-slate-400">NIS: {d.nis}</p>
                                </td>

                                {mode === 'GRADES' ? (
                                    <>
                                        <td className="px-6 py-4 text-center text-sm text-slate-600">{d.grades.formative}</td>
                                        <td className="px-6 py-4 text-center text-sm text-slate-600">{d.grades.summative}</td>
                                        <td className="px-6 py-4 text-center text-sm text-slate-600">{d.grades.attitude}</td>
                                        <td className="px-6 py-4 text-center font-bold text-blue-600 bg-blue-50/30 text-base">{d.grades.finalScore}</td>
                                        <td className="px-6 py-4 text-center">
                                            <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider ${d.grades.isPassed ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                {d.grades.isPassed ? 'Tuntas' : 'Remedial'}
                                            </span>
                                        </td>
                                    </>
                                ) : (
                                    <>
                                        <td className="px-6 py-4 text-center font-bold text-green-600 bg-green-50/30">{d.attendance.present}</td>
                                        <td className="px-6 py-4 text-center font-bold text-blue-600 bg-blue-50/30">{d.attendance.permit}</td>
                                        <td className="px-6 py-4 text-center font-bold text-orange-600 bg-orange-50/30">{d.attendance.sick}</td>
                                        <td className="px-6 py-4 text-center font-bold text-red-600 bg-red-50/30">{d.attendance.absent}</td>
                                        <td className="px-6 py-4 text-center">
                                            <div className="flex items-center gap-2 justify-center">
                                                <div className="w-16 bg-slate-100 h-1.5 rounded-full overflow-hidden">
                                                    <div className={`h-full rounded-full ${d.attendance.percentage >= 80 ? 'bg-green-500' : d.attendance.percentage >= 50 ? 'bg-orange-500' : 'bg-red-500'}`} style={{width: `${d.attendance.percentage}%`}}></div>
                                                </div>
                                                <span className="text-xs font-bold text-slate-700">{d.attendance.percentage}%</span>
                                            </div>
                                        </td>
                                    </>
                                )}
                            </tr>
                        ))}
                    </tbody>
                </table>
             </div>
         ) : (
             <div className="flex flex-col items-center justify-center h-80 text-slate-400">
                <span className="material-symbols-outlined text-4xl mb-3 text-slate-300">filter_alt_off</span>
                <p className="font-bold text-slate-600">Pilih Kelas Terlebih Dahulu</p>
                <p className="text-sm">Silahkan gunakan filter di atas untuk menampilkan data rekap.</p>
             </div>
         )}
      </div>
    </div>
  );
};

// Domain Models

export type TeacherRole = 'CLASS_TEACHER' | 'SUBJECT_TEACHER';

export interface Student {
  id: string;
  name: string;
  nis: string;
  className?: string; // e.g., "10-A IPA"
}

export interface ClassInfo {
  id: string;
  name: string; // e.g. "10-A IPA"
  level: string; // e.g. "Fase E (Kelas 10)"
  studentCount: number;
}

export interface ScheduleItem {
  id: string;
  day: string; // Senin, Selasa, etc
  startTime: string; // "07:30"
  endTime: string; // "09:00"
  className: string;
  subject: string;
  room: string;
}

export interface LearningMaterial { // LM (Lingkup Materi) - Now Child of TP
  id: string;
  code: string; // e.g., LM.1
  title: string;
}

export interface AssessmentCriteria { // Kriteria Penilaian - Child of TP
  id: string;
  code: string; // e.g., Kr.1
  description: string; // e.g., "Pemahaman Konsep"
}

export interface LearningObjective { // TP (Tujuan Pembelajaran)
  id: string;
  code: string; // e.g., TP.1
  description: string;
  semester?: 1 | 2; // Optional, defaulted if missing
  scopeId?: string; // NEW: Context ID. If Guru Kelas = Subject ID (e.g., 'math'). If Guru Mapel = Level ID (e.g., 'lvl-7')
  lms: LearningMaterial[]; // Nested LMs
  criteria: AssessmentCriteria[]; // Nested Criteria for Grading
}

export interface Subject {
  id: string;
  name: string;
  kktp: number; // Kriteria Ketercapaian Tujuan Pembelajaran (Passing Grade)
}

export interface GradeData {
  [studentId: string]: {
    scores: { [criteriaId: string]: number }; // Maps Criteria ID -> Score
    attitude: number; // Nilai Sikap
  };
}

export interface CalculatedGrade {
  avgScore: number;
  finalScore: number;
  isPassed: boolean;
}

// Identity Data
export interface IdentityData {
  role: TeacherRole; // NEW
  schoolName: string;
  subjectName: string; // Main subject for Subject Teacher, or "Guru Kelas" text
  teacherName: string;
  nip: string;
  semester: string;
  academicYear: string;
  className: string; // Wali Kelas / Main Class
  studentCount: number;
}

// Attendance Types
export type AttendanceStatus = 'H' | 'I' | 'S' | 'A'; // Hadir, Izin, Sakit, Alfa

export interface AttendanceSession {
  id: string;
  date: string;
  topic: string;
}

export interface AttendanceData {
  [studentId: string]: {
    [sessionId: string]: AttendanceStatus;
  };
}

export enum TabView {
  DASHBOARD = 'DASHBOARD',
  CLASS_MASTER = 'CLASS_MASTER', 
  STUDENT_MASTER = 'STUDENT_MASTER',
  SCHEDULE_MASTER = 'SCHEDULE_MASTER',
  IDENTITY = 'IDENTITY', 
  CURRICULUM = 'CURRICULUM', 
  CP_GENERATOR = 'CP_GENERATOR',
  BLUEPRINT = 'BLUEPRINT',
  GRADING = 'GRADING',
  ATTENDANCE = 'ATTENDANCE',
  RECAP_GRADES = 'RECAP_GRADES',      // Split
  RECAP_ATTENDANCE = 'RECAP_ATTENDANCE' // Split
}

import React, { useState, useMemo, useEffect } from 'react';
import { LearningMaterial, LearningObjective, Subject, AssessmentCriteria, IdentityData } from '../types';

declare const Swal: any;

interface Props {
  identity: IdentityData;
  subject: Subject;
  tps: LearningObjective[];
  onUpdateSubject: (kktp: number) => void;
  onUpdateTPs: (tps: LearningObjective[]) => void;
  onBack: () => void;
}

// Mock Data for Scopes
const SD_SUBJECTS = [
    { id: 'math', name: 'Matematika' },
    { id: 'indo', name: 'B. Indonesia' },
    { id: 'ipas', name: 'IPAS' },
    { id: 'ppkn', name: 'PPKn' },
    { id: 'sbura', name: 'Seni Budaya' },
];

const SMP_LEVELS = [
    { id: 'lvl-7', name: 'Kelas 7 (Fase D)' },
    { id: 'lvl-8', name: 'Kelas 8 (Fase D)' },
    { id: 'lvl-9', name: 'Kelas 9 (Fase D)' },
];

const SMA_LEVELS = [
    { id: 'lvl-10', name: 'Kelas 10 (Fase E)' },
    { id: 'lvl-11', name: 'Kelas 11 (Fase F)' },
    { id: 'lvl-12', name: 'Kelas 12 (Fase F)' },
];

export const CurriculumManager: React.FC<Props> = ({ 
  identity, subject, tps, onUpdateSubject, onUpdateTPs, onBack 
}) => {
  const [expandedTpId, setExpandedTpId] = useState<string | null>(null);

  // DETERMINE CONTEXT (Scope)
  // If Class Teacher -> Scope is Subject (Math, IPAS, etc.)
  // If Subject Teacher -> Scope is Level (Grade 7, 8, etc.)

  const scopes = useMemo(() => {
      if (identity.role === 'CLASS_TEACHER') {
          return SD_SUBJECTS;
      } else {
          // Simplistic logic for SMP vs SMA based on School Name (in real app, use Identity.schoolLevel)
          const isSMA = identity.schoolName.toLowerCase().includes('sma') || identity.schoolName.toLowerCase().includes('smk');
          return isSMA ? SMA_LEVELS : SMP_LEVELS;
      }
  }, [identity]);

  const [activeScopeId, setActiveScopeId] = useState<string>(scopes[0].id);

  useEffect(() => {
      // Reset active scope if role changes
      setActiveScopeId(scopes[0].id);
  }, [scopes]);

  // Filter TPs based on Active Scope
  const filteredTPs = useMemo(() => {
      return tps.filter(tp => tp.scopeId === activeScopeId);
  }, [tps, activeScopeId]);

  // TP Form State
  const [isAddingTp, setIsAddingTp] = useState(false);
  const [newTpForm, setNewTpForm] = useState({ code: '', description: '', semester: '1' });

  // Sub-item Form State (LM & Criteria)
  const [newItemForm, setNewItemForm] = useState<{
      type: 'LM' | 'CRITERIA' | null, 
      parentId: string | null,
      val1: string, // Code
      val2: string // Title/Description
  }>({ type: null, parentId: null, val1: '', val2: '' });

  // --- TP CRUD ---
  const handleAddTP = () => {
    if(!newTpForm.code || !newTpForm.description) return;
    const newTp: LearningObjective = {
        id: Date.now().toString(),
        code: newTpForm.code.toUpperCase(), 
        description: newTpForm.description,
        semester: Number(newTpForm.semester) as 1 | 2,
        scopeId: activeScopeId, // ASSIGN CURRENT SCOPE
        lms: [],
        criteria: []
    };
    onUpdateTPs([...tps, newTp]);
    setIsAddingTp(false);
    setNewTpForm({ code: '', description: '', semester: '1' });
  };

  const handleDeleteTP = (id: string) => {
      Swal.fire({
          title: 'Hapus Tujuan Pembelajaran?',
          text: "Seluruh Lingkup Materi (LM) dan Kriteria yang ada di dalamnya akan ikut terhapus!",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Ya, hapus!',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateTPs(tps.filter(t => t.id !== id));
              Swal.fire(
                  'Terhapus!',
                  'TP berhasil dihapus.',
                  'success'
              )
          }
      });
  };

  // --- NESTED ITEMS CRUD ---
  const handleAddItem = () => {
      if(!newItemForm.val1 || !newItemForm.val2 || !newItemForm.parentId || !newItemForm.type) return;

      const updatedTPs = tps.map(tp => {
          if(tp.id === newItemForm.parentId) {
              if(newItemForm.type === 'LM') {
                  return {
                      ...tp,
                      lms: [...tp.lms, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), 
                          title: newItemForm.val2 
                      }]
                  };
              } else {
                  return {
                      ...tp,
                      criteria: [...tp.criteria, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), 
                          description: newItemForm.val2 
                      }]
                  };
              }
          }
          return tp;
      });

      onUpdateTPs(updatedTPs);
      setNewItemForm({ type: null, parentId: null, val1: '', val2: '' });
  };

  const handleDeleteSubItem = (tpId: string, itemId: string, type: 'LM' | 'CRITERIA') => {
      Swal.fire({
          title: 'Hapus Item?',
          text: "Item ini akan dihapus permanen.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Hapus',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              const updatedTPs = tps.map(tp => {
                  if(tp.id === tpId) {
                      if(type === 'LM') {
                          return { ...tp, lms: tp.lms.filter(l => l.id !== itemId) };
                      } else {
                          return { ...tp, criteria: tp.criteria.filter(c => c.id !== itemId) };
                      }
                  }
                  return tp;
              });
              onUpdateTPs(updatedTPs);
          }
      });
  };

  return (
    <div className="h-full flex flex-col bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Header */}
        <div className="bg-gray-50 p-6 border-b flex justify-between items-center">
            <div>
                <h2 className="text-xl font-bold text-gray-800">Manajemen Kurikulum & Asesmen</h2>
                <p className="text-sm text-gray-500">
                    {identity.role === 'CLASS_TEACHER' 
                        ? 'Pengaturan TP per Mata Pelajaran (Guru Kelas)' 
                        : 'Pengaturan TP per Tingkat Kelas (Guru Mapel)'}
                </p>
            </div>
             <button onClick={onBack} className="text-gray-500 hover:text-gray-700 font-medium">
                &larr; Kembali
            </button>
        </div>

        <div className="flex flex-1 overflow-hidden">
            {/* Sidebar Context Switcher */}
            <div className="w-64 bg-slate-50 border-r border-slate-200 flex flex-col">
                <div className="p-4 border-b border-slate-200">
                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider">
                        {identity.role === 'CLASS_TEACHER' ? 'Mata Pelajaran' : 'Tingkat Kelas'}
                    </h3>
                </div>
                <div className="overflow-y-auto flex-1 p-2 space-y-1">
                    {scopes.map(scope => (
                        <button
                            key={scope.id}
                            onClick={() => setActiveScopeId(scope.id)}
                            className={`w-full text-left px-4 py-3 rounded-lg text-sm font-bold transition-colors flex items-center justify-between group ${activeScopeId === scope.id ? 'bg-white text-primary shadow-sm ring-1 ring-slate-200' : 'text-slate-600 hover:bg-slate-200/50'}`}
                        >
                            <span>{scope.name}</span>
                            {activeScopeId === scope.id && <span className="material-symbols-outlined text-sm">chevron_right</span>}
                        </button>
                    ))}
                </div>
            </div>

            {/* Main Content Area */}
            <div className="flex-1 flex flex-col overflow-hidden">
                {/* Global Config for Active Scope */}
                <div className="px-6 py-4 bg-white border-b flex items-center justify-between">
                    <div className="flex items-center gap-4">
                        <div className="bg-blue-100 p-2 rounded-lg text-blue-600">
                            <span className="material-symbols-outlined">tune</span>
                        </div>
                        <div>
                            <label className="text-xs font-bold text-gray-500 uppercase">KKTP ({scopes.find(s => s.id === activeScopeId)?.name})</label>
                            <div className="flex items-center gap-2">
                                <input 
                                    type="number" 
                                    value={subject.kktp} // NOTE: ideally KKTP should also be scoped, keeping simple for now
                                    onChange={(e) => onUpdateSubject(Number(e.target.value))}
                                    className="w-16 p-1 text-center font-bold text-blue-700 border-b-2 border-blue-200 focus:border-blue-500 outline-none bg-transparent"
                                />
                                <span className="text-sm text-gray-400">Poin</span>
                            </div>
                        </div>
                    </div>
                    <button 
                        onClick={() => setIsAddingTp(!isAddingTp)}
                        className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 transition-colors shadow-sm"
                    >
                        <span className="material-symbols-outlined text-sm">{isAddingTp ? 'remove' : 'add'}</span>
                        Tambah TP
                    </button>
                </div>

                {/* Add TP Form */}
                {isAddingTp && (
                    <div className="mx-6 mt-6 p-4 bg-blue-50 border border-blue-100 rounded-xl animate-in fade-in slide-in-from-top-4">
                        <h4 className="font-bold text-blue-800 mb-3 text-sm">
                            Tambah TP Baru di {scopes.find(s => s.id === activeScopeId)?.name}
                        </h4>
                        <div className="flex gap-3 items-start">
                            <div className="w-24">
                                <input 
                                    type="text" placeholder="Kode" 
                                    value={newTpForm.code} onChange={e => setNewTpForm({...newTpForm, code: e.target.value.toUpperCase()})}
                                    className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900 placeholder:text-slate-400"
                                />
                            </div>
                            <div className="w-24">
                                <select 
                                    value={newTpForm.semester} onChange={e => setNewTpForm({...newTpForm, semester: e.target.value})}
                                    className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900"
                                >
                                    <option value="1">Smt 1</option>
                                    <option value="2">Smt 2</option>
                                </select>
                            </div>
                            <div className="flex-1">
                                <input 
                                    type="text" placeholder="Deskripsi Tujuan Pembelajaran..." 
                                    value={newTpForm.description} onChange={e => setNewTpForm({...newTpForm, description: e.target.value})}
                                    className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900"
                                />
                            </div>
                            <button onClick={handleAddTP} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold text-sm hover:bg-blue-700">Simpan</button>
                        </div>
                    </div>
                )}

                {/* TP List */}
                <div className="flex-1 overflow-y-auto p-6 space-y-4">
                    {filteredTPs.length === 0 && (
                        <div className="text-center py-12 text-gray-400">
                            <span className="material-symbols-outlined text-4xl mb-2">library_books</span>
                            <p>Belum ada Tujuan Pembelajaran untuk {scopes.find(s => s.id === activeScopeId)?.name}.</p>
                        </div>
                    )}

                    {filteredTPs.map((tp) => {
                        const isExpanded = expandedTpId === tp.id;
                        return (
                            <div key={tp.id} className={`border rounded-xl transition-all ${isExpanded ? 'border-primary shadow-md bg-white' : 'border-slate-200 bg-white hover:border-slate-300'}`}>
                                {/* TP Header */}
                                <div 
                                    onClick={() => setExpandedTpId(isExpanded ? null : tp.id)}
                                    className="p-4 flex items-center gap-4 cursor-pointer"
                                >
                                    <div className={`size-10 rounded-lg flex items-center justify-center font-bold text-sm ${isExpanded ? 'bg-primary text-white' : 'bg-slate-100 text-slate-500'}`}>
                                        {tp.code.toUpperCase()}
                                    </div>
                                    <div className="flex-1">
                                        <p className={`text-sm font-bold ${isExpanded ? 'text-primary' : 'text-slate-800'}`}>{tp.description}</p>
                                        <div className="flex items-center gap-2 mt-1">
                                            <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500">Semester {tp.semester}</span>
                                            <span className="text-[10px] text-slate-400 flex items-center gap-1">
                                                <span className="material-symbols-outlined text-[10px]">topic</span> {tp.lms.length} LM
                                            </span>
                                            <span className="text-[10px] text-slate-400 flex items-center gap-1">
                                                <span className="material-symbols-outlined text-[10px]">fact_check</span> {tp.criteria.length} Kriteria
                                            </span>
                                        </div>
                                    </div>
                                    <button 
                                        onClick={(e) => { e.stopPropagation(); handleDeleteTP(tp.id); }}
                                        className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                    >
                                        <span className="material-symbols-outlined">delete</span>
                                    </button>
                                    <span className={`material-symbols-outlined text-slate-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`}>expand_more</span>
                                </div>

                                {/* Expanded Content */}
                                {isExpanded && (
                                    <div className="border-t border-slate-100 bg-slate-50/50 p-4 space-y-6 animate-in slide-in-from-top-2">

                                        {/* Lingkup Materi Section */}
                                        <div className="space-y-3">
                                            <div className="flex justify-between items-center">
                                                <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
                                                    <span className="material-symbols-outlined text-sm">topic</span>
                                                    Lingkup Materi (LM)
                                                </h4>
                                            </div>
                                            <div className="bg-white border border-slate-200 rounded-lg overflow-hidden">
                                                <table className="w-full text-sm">
                                                    <thead className="bg-slate-50 text-slate-500 font-semibold border-b border-slate-200">
                                                        <tr>
                                                            <th className="px-4 py-2 text-left w-24">Kode</th>
                                                            <th className="px-4 py-2 text-left">Judul Materi</th>
                                                            <th className="px-4 py-2 w-16"></th>
                                                        </tr>
                                                    </thead>
                                                    <tbody className="divide-y divide-slate-100">
                                                        {tp.lms.map(lm => (
                                                            <tr key={lm.id} className="group hover:bg-slate-50">
                                                                <td className="px-4 py-2 font-mono text-xs font-bold text-blue-600">{lm.code.toUpperCase()}</td>
                                                                <td className="px-4 py-2 text-slate-800">{lm.title}</td>
                                                                <td className="px-4 py-2 text-right">
                                                                    <button 
                                                                        onClick={() => handleDeleteSubItem(tp.id, lm.id, 'LM')}
                                                                        className="text-slate-300 hover:text-red-500 group-hover:text-slate-400"
                                                                    >
                                                                        <span className="material-symbols-outlined text-sm">close</span>
                                                                    </button>
                                                                </td>
                                                            </tr>
                                                        ))}
                                                         {/* Add Row */}
                                                         <tr className="bg-slate-50">
                                                            <td className="px-2 py-2">
                                                                <input 
                                                                    type="text" placeholder="LM.x" 
                                                                    className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-blue-500 bg-white text-slate-900"
                                                                    value={newItemForm.type === 'LM' && newItemForm.parentId === tp.id ? newItemForm.val1 : ''}
                                                                    onChange={(e) => setNewItemForm({ type: 'LM', parentId: tp.id, val1: e.target.value.toUpperCase(), val2: newItemForm.val2 })}
                                                                    onFocus={() => setNewItemForm(prev => ({ ...prev, type: 'LM', parentId: tp.id }))}
                                                                />
                                                            </td>
                                                            <td className="px-2 py-2">
                                                                <input 
                                                                    type="text" placeholder="Tambah Lingkup Materi..." 
                                                                    className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-blue-500 bg-white text-slate-900"
                                                                    value={newItemForm.type === 'LM' && newItemForm.parentId === tp.id ? newItemForm.val2 : ''}
                                                                    onChange={(e) => setNewItemForm({ type: 'LM', parentId: tp.id, val1: newItemForm.val1, val2: e.target.value })}
                                                                    onKeyDown={(e) => e.key === 'Enter' && handleAddItem()}
                                                                />
                                                            </td>
                                                            <td className="px-2 py-2 text-center">
                                                                 {newItemForm.type === 'LM' && newItemForm.parentId === tp.id && newItemForm.val1 && (
                                                                    <button onClick={handleAddItem} className="text-blue-600 hover:text-blue-800">
                                                                        <span className="material-symbols-outlined text-lg">check_circle</span>
                                                                    </button>
                                                                 )}
                                                            </td>
                                                        </tr>
                                                    </tbody>
                                                </table>
                                            </div>
                                        </div>

                                        {/* Kriteria Section */}
                                        <div className="space-y-3">
                                            <div className="flex justify-between items-center">
                                                <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
                                                    <span className="material-symbols-outlined text-sm">fact_check</span>
                                                    Kriteria Penilaian (Untuk Matrix Input Nilai)
                                                </h4>
                                            </div>
                                            <div className="bg-white border border-slate-200 rounded-lg overflow-hidden">
                                                <table className="w-full text-sm">
                                                    <thead className="bg-slate-50 text-slate-500 font-semibold border-b border-slate-200">
                                                        <tr>
                                                            <th className="px-4 py-2 text-left w-24">Kode</th>
                                                            <th className="px-4 py-2 text-left">Deskripsi Kriteria</th>
                                                            <th className="px-4 py-2 w-16"></th>
                                                        </tr>
                                                    </thead>
                                                    <tbody className="divide-y divide-slate-100">
                                                        {tp.criteria.map(cr => (
                                                            <tr key={cr.id} className="group hover:bg-slate-50">
                                                                <td className="px-4 py-2 font-mono text-xs font-bold text-green-600">{cr.code.toUpperCase()}</td>
                                                                <td className="px-4 py-2 text-slate-800">{cr.description}</td>
                                                                <td className="px-4 py-2 text-right">
                                                                    <button 
                                                                        onClick={() => handleDeleteSubItem(tp.id, cr.id, 'CRITERIA')}
                                                                        className="text-slate-300 hover:text-red-500 group-hover:text-slate-400"
                                                                    >
                                                                        <span className="material-symbols-outlined text-sm">close</span>
                                                                    </button>
                                                                </td>
                                                            </tr>
                                                        ))}
                                                         {/* Add Row */}
                                                         <tr className="bg-slate-50">
                                                            <td className="px-2 py-2">
                                                                <input 
                                                                    type="text" placeholder="KR.x" 
                                                                    className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-green-500 bg-white text-slate-900"
                                                                    value={newItemForm.type === 'CRITERIA' && newItemForm.parentId === tp.id ? newItemForm.val1 : ''}
                                                                    onChange={(e) => setNewItemForm({ type: 'CRITERIA', parentId: tp.id, val1: e.target.value.toUpperCase(), val2: newItemForm.val2 })}
                                                                    onFocus={() => setNewItemForm(prev => ({ ...prev, type: 'CRITERIA', parentId: tp.id }))}
                                                                />
                                                            </td>
                                                            <td className="px-2 py-2">
                                                                <input 
                                                                    type="text" placeholder="Tambah Kriteria Penilaian..." 
                                                                    className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-green-500 bg-white text-slate-900"
                                                                    value={newItemForm.type === 'CRITERIA' && newItemForm.parentId === tp.id ? newItemForm.val2 : ''}
                                                                    onChange={(e) => setNewItemForm({ type: 'CRITERIA', parentId: tp.id, val1: newItemForm.val1, val2: e.target.value })}
                                                                    onKeyDown={(e) => e.key === 'Enter' && handleAddItem()}
                                                                />
                                                            </td>
                                                            <td className="px-2 py-2 text-center">
                                                                 {newItemForm.type === 'CRITERIA' && newItemForm.parentId === tp.id && newItemForm.val1 && (
                                                                    <button onClick={handleAddItem} className="text-green-600 hover:text-green-800">
                                                                        <span className="material-symbols-outlined text-lg">check_circle</span>
                                                                    </button>
                                                                 )}
                                                            </td>
                                                        </tr>
                                                    </tbody>
                                                </table>
                                            </div>
                                        </div>

                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    </div>
  );
};

