declare const Swal: any;

interface Props {
  classes: ClassInfo[];
  onUpdateClasses: (classes: ClassInfo[]) => void;
  onBack: () => void;
}

const PHASE_OPTIONS = [
    "Fase A (Kelas 1-2)",
    "Fase B (Kelas 3-4)",
    "Fase C (Kelas 5-6)",
    "Fase D (Kelas 7-9)",
    "Fase E (Kelas 10)",
    "Fase F (Kelas 11-12)"
];

export const ClassManager: React.FC<Props> = ({ classes, onUpdateClasses, onBack }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
      name: '',
      level: 'Fase E (Kelas 10)',
  });

  const handleOpenModal = (cls?: ClassInfo) => {
      if (cls) {
          setEditingId(cls.id);
          setFormData({
              name: cls.name,
              level: cls.level,
          });
      } else {
          setEditingId(null);
          setFormData({ name: '', level: 'Fase E (Kelas 10)' });
      }
      setIsModalOpen(true);
  };

  const handleSaveClass = (e: React.FormEvent) => {
      e.preventDefault();

      if (editingId) {
          // Update
          const updatedClasses = classes.map(c => c.id === editingId ? { 
              ...c, 
              ...formData,
          } : c);
          onUpdateClasses(updatedClasses);
      } else {
          // Add
          const newClass: ClassInfo = {
              id: Date.now().toString(),
              name: formData.name,
              level: formData.level,
              studentCount: 0, // Will be calculated dynamically in App or here based on students list if connected
          };
          onUpdateClasses([...classes, newClass]);
      }
      setIsModalOpen(false);
  };

  const handleDeleteClass = (id: string) => {
      Swal.fire({
          title: 'Hapus Kelas?',
