interface ScheduleCardProps {
    id: string;
    startTime: string;
    endTime: string;
    className: string;
    subject: string;
    room: string;
    currentTime: Date;
    onNavigate: (tab: TabView, context?: { className?: string, scheduleId?: string }) => void;
}

const ScheduleCard: React.FC<ScheduleCardProps> = ({ id, startTime, endTime, className, subject, room, currentTime, onNavigate }) => {
    // Logic to determine if class is live
    const isLive = () => {
        const [startH, startM] = startTime.split(':').map(Number);
        const [endH, endM] = endTime.split(':').map(Number);

        const start = new Date(currentTime);
        start.setHours(startH, startM, 0);

        const end = new Date(currentTime);
        end.setHours(endH, endM, 0);

        return currentTime >= start && currentTime <= end;
    };

    const isFinished = () => {
         const [endH, endM] = endTime.split(':').map(Number);
         const end = new Date(currentTime);
         end.setHours(endH, endM, 0);
         return currentTime > end;
    }

    const liveStatus = isLive();
    const finishedStatus = isFinished();

    return (
        <div className={`border rounded-xl p-5 flex items-center gap-6 shadow-sm relative overflow-hidden transition-all ${liveStatus ? 'bg-white border-primary border-2 ring-4 ring-primary/5' : 'bg-white border-slate-200'}`}>
            {liveStatus && (
                <div className="absolute top-0 right-0 animate-pulse">
                    <div className="bg-primary text-white text-[10px] font-bold px-3 py-1 rounded-bl-lg flex items-center gap-1">
                        <span className="material-symbols-outlined text--[10px]">sensors</span>
                        SEDANG BERLANGSUNG
                    </div>
                </div>
            )}
            <div className={`${liveStatus ? 'bg-primary/10 text-primary' : 'bg-slate-50 text-slate-600'} rounded-lg p-3 text-center min-w-[90px]`}>
                <p className="text-lg font-bold">{startTime}</p>
                <p className="text-xs font-bold opacity-70">{liveStatus ? 'S.D' : 'Hingga'}</p>
                <p className="text-sm font-bold opacity-90">{endTime}</p>
            </div>
            <div className="flex-1">
                <h4 className="font-bold text-lg text-slate-900">{subject}</h4>
                <p className="text-slate-500 text-sm">{className} • {room}</p>
                {finishedStatus && <span className="text-xs font-bold text-green-600 bg-green-50 px-2 py-0.5 rounded mt-1 inline-block">Selesai</span>}
            </div>
            <div className="flex gap-2">
                <button 
                  onClick={() => onNavigate(TabView.ATTENDANCE, { className, scheduleId: id })}
                  className={`px-3 py-1.5 border text-xs font-bold rounded transition-colors ${liveStatus ? 'border-primary text-primary hover:bg-primary/10' : 'border-slate-300 text-slate-500 hover:bg-slate-50'}`}
                >
                  Presensi
                </button>
                <button 
                  onClick={() => onNavigate(TabView.GRADING, { className })}
                  className={`px-3 py-1.5 text-xs font-bold rounded transition-colors ${liveStatus ? 'bg-primary text-white hover:bg-blue-600' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}
                >
                  Input Nilai
                </button>
            </div>
        </div>
    );
}

const DAYS_MAP = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];

export const Dashboard: React.FC<Props> = ({ onNavigate, identity, schedules, classes, students, attendanceData, gradeData, subject }) => {
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => {
        setCurrentTime(new Date());
    }, 1000); 

    return () => clearInterval(timer);
  }, []);

  const currentDayName = DAYS_MAP[currentTime.getDay()];

  // Filter schedules for today
  const todaysSchedules = useMemo(() => {
      return schedules
        .filter(s => s.day === currentDayName)
        .sort((a, b) => a.startTime.localeCompare(b.startTime));
  }, [schedules, currentDayName]);

  const dateString = currentTime.toLocaleDateString('id-ID', { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric',
    timeZone: 'Asia/Makassar' 
  });

  const todayIsoDate = useMemo(() => {
      const d = new Date();
      // Simple ISO Date (YYYY-MM-DD) for local matching
      return d.toISOString().split('T')[0];
  }, []);

  // --- STATS CALCULATION ---

  // 1. Average Grade Calculation
  const averageGrade = useMemo(() => {
      const studentIds = Object.keys(gradeData);
      if (studentIds.length === 0) return 0;

      let totalScore = 0;
      let count = 0;

      studentIds.forEach(sid => {
          // Note: Passing default weights as summary (assuming 90/10 as per default in GradingSheet)
          const result = calculateStudentGrade(sid, gradeData, subject.kktp, { criteria: 90, attitude: 10 });
          if (result.finalScore > 0) {
              totalScore += result.finalScore;
              count++;
          }
      });

      return count > 0 ? (totalScore / count).toFixed(1) : 0;
  }, [gradeData, subject.kktp]);

  // 2. Attendance Stats for TODAY
  const attendanceStats = useMemo(() => {
      let present = 0, izin = 0, sakit = 0, alpa = 0;

      // Look at attendance records for TODAY's schedules
      todaysSchedules.forEach(schedule => {
          const records = attendanceData[schedule.id]?.[todayIsoDate];
          if (records) {
              Object.values(records).forEach(record => {
                  if (record.status === 'H') present++;
                  else if (record.status === 'I') izin++;
                  else if (record.status === 'S') sakit++;
                  else if (record.status === 'A') alpa++;
              });
          }
      });

      const total = present + izin + sakit + alpa;
      const percentage = total > 0 ? Math.round((present / total) * 100) : 0;

      return { present, izin, sakit, alpa, total, percentage };
  }, [todaysSchedules, attendanceData, todayIsoDate]);

  return (
    <div className="w-full max-w-7xl mx-auto space-y-8">

      {/* Hero Header Banner */}
      <div className="bg-white rounded-2xl p-8 border border-slate-200 shadow-sm relative overflow-hidden">
         {/* Decorative Background Elements */}
         <div className="absolute top-0 right-0 w-96 h-96 bg-primary/5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/3 pointer-events-none"></div>
         <div className="absolute bottom-0 left-0 w-64 h-64 bg-purple-500/5 rounded-full blur-3xl translate-y-1/3 -translate-x-1/4 pointer-events-none"></div>
         <div className="absolute right-10 bottom-0 opacity-[0.03] pointer-events-none">
            <span className="material-symbols-outlined text-[120px]">school</span>
         </div>

         <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-end gap-6">

            {/* Left: Profile & Greeting */}
            <div className="flex-1">
                <div className="flex items-center gap-2 mb-2">
                    <span className="px-2.5 py-1 bg-primary/10 text-primary rounded-full text-[10px] font-bold uppercase tracking-wider border border-primary/20">
                        Semester {identity.semester}
                    </span>
                    <span className="px-2.5 py-1 bg-slate-100 text-slate-600 rounded-full text-[10px] font-bold uppercase tracking-wider border border-slate-200">
                        {identity.academicYear}
                    </span>
                </div>
                <h1 className="text-3xl md:text-4xl font-extrabold text-slate-900 tracking-tight leading-tight">
                    {identity.teacherName}
                </h1>

                {/* School Name & Role Integration */}
                <div className="flex flex-wrap items-center gap-3 mt-3 text-sm md:text-base">
                     <div className="flex items-center gap-2 text-slate-500 font-semibold">
                        <span className="material-symbols-outlined text-lg text-primary">domain</span>
                        {identity.schoolName}
                     </div>
                     <span className="text-slate-300">|</span>
                     <div className="flex items-center gap-2 text-slate-700 font-bold bg-slate-50 px-3 py-1 rounded-lg border border-slate-200">
                        <span className="material-symbols-outlined text-sm text-slate-500">
                            {identity.role === 'CLASS_TEACHER' ? 'meeting_room' : 'menu_book'}
                        </span>
                        {identity.role === 'CLASS_TEACHER' 
                            ? 'Guru Kelas' 
                            : `Guru Mapel ${identity.subjectName}`
                        }
                     </div>
                </div>

                <p className="text-slate-400 text-sm mt-3 max-w-lg">
                    Selamat bertugas! Kelola administrasi pembelajaran, presensi, dan penilaian siswa dengan mudah hari ini.
                </p>
            </div>

            {/* Right: Clock & Date */}
            <div className="text-right bg-white/50 backdrop-blur-sm p-4 rounded-xl border border-slate-100 shadow-sm">
                 <div className="text-4xl font-black text-slate-800 leading-none tracking-tight font-mono">
                    {currentTime.toLocaleTimeString('id-ID', { hour: '2-digit', minute:'2-digit', timeZone: 'Asia/Makassar' })} 
                    <span className="text-sm font-bold text-slate-400 ml-1">WITA</span>
                </div>
                <div className="text-sm font-bold text-slate-500 mt-1 capitalize flex items-center justify-end gap-1">
                    <span className="material-symbols-outlined text-sm">calendar_month</span>
                    {dateString}
                </div>
            </div>
         </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="Kelas Aktif" 
          value={classes.length.toString()} 
          subText="Kelas Terdaftar" 
          subColor="text-green-600" 
          bgIcon="bg-blue-50 text-blue-600" 
          icon="school" 
        />
        <StatCard 
          title="Total Siswa" 
          value={students.length.toString()} 
          subText="Siswa Terdaftar" 
          subColor="text-slate-500" 
          bgIcon="bg-orange-50 text-orange-600" 
          icon="groups" 
        />
        <StatCard 
          title="Rata-rata Nilai" 
          value={averageGrade} 
          subText="Seluruh Kelas" 
          subColor="text-green-600" 
          bgIcon="bg-green-50 text-green-600" 
          icon="grade" 
        />
        <StatCard 
          title="Presensi Hari Ini" 
          value={`${attendanceStats.percentage}%`} 
          subText={attendanceStats.total > 0 ? "Kehadiran" : "Belum Ada Data"} 
          subColor={attendanceStats.total > 0 ? "text-slate-700" : "text-slate-400"} 
          bgIcon="bg-red-50 text-red-600" 
          icon="event_available" 
        />
      </div>

      {/* Main Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Left Column: Schedule */}
        <div className="lg:col-span-2 space-y-6">
          <div className="flex items-center justify-between border-b border-slate-200 pb-4">
            <div>
                 <h3 className="text-xl font-bold text-slate-900">Jadwal Mengajar Hari Ini</h3>
                 <p className="text-sm text-slate-500 mt-1 capitalize">{dateString}</p>
            </div>
          </div>

          <div className="flex flex-col gap-4">
            {todaysSchedules.length > 0 ? (
                todaysSchedules.map(schedule => (
                    <ScheduleCard 
                        key={schedule.id}
                        {...schedule}
                        currentTime={currentTime}
                        onNavigate={onNavigate}
                    />
                ))
            ) : (
                <div className="flex flex-col items-center justify-center py-12 bg-slate-50 rounded-xl border border-dashed border-slate-300 text-slate-400">
                    <span className="material-symbols-outlined text-4xl mb-2">event_available</span>
                    <p className="text-sm font-medium">Tidak ada jadwal mengajar hari ini.</p>
                </div>
            )}
          </div>
        </div>

        {/* Right Column: Only Status Presensi remains */}
        <div className="space-y-8">

          {/* Attendance Breakdown */}
          <div className="bg-white border border-slate-200 rounded-xl p-6 shadow-sm sticky top-24">
            <h3 className="font-bold text-slate-900 mb-6">Status Presensi Hari Ini</h3>

            {attendanceStats.total > 0 ? (
                 <div className="flex flex-col gap-5">
                    {[
                        { label: 'Hadir', count: attendanceStats.present, color: 'bg-primary', border: 'border-primary', percent: Math.round((attendanceStats.present / attendanceStats.total) * 100) + '%' },
                        { label: 'Izin', count: attendanceStats.izin, color: 'bg-blue-400', border: 'border-blue-400', percent: Math.round((attendanceStats.izin / attendanceStats.total) * 100) + '%' },
                        { label: 'Sakit', count: attendanceStats.sakit, color: 'bg-orange-400', border: 'border-orange-400', percent: Math.round((attendanceStats.sakit / attendanceStats.total) * 100) + '%' },
                        { label: 'Alpa', count: attendanceStats.alpa, color: 'bg-red-500', border: 'border-red-500', percent: Math.round((attendanceStats.alpa / attendanceStats.total) * 100) + '%' }
                    ].map((item) => (
                        <div key={item.label} className="flex items-center gap-4">
                        <div className={`size-12 rounded-full border-[5px] ${item.border} flex items-center justify-center bg-transparent`}>
                            <span className="text-[10px] font-bold">{item.percent}</span>
                        </div>
                        <div className="flex-1">
                            <div className="flex justify-between text-sm mb-1">
                            <span className="font-medium text-slate-600">{item.label}</span>
                            <span className="font-bold text-slate-900">{item.count} Siswa</span>
                            </div>
                            <div className="w-full bg-slate-100 h-1.5 rounded-full overflow-hidden">
                            <div className={`${item.color} h-full rounded-full`} style={{ width: item.percent }}></div>
                            </div>
                        </div>
                        </div>
                    ))}
                </div>
            ) : (
                <div className="flex flex-col items-center justify-center py-10 text-slate-400 bg-slate-50 rounded-lg">
                    <span className="material-symbols-outlined text-3xl mb-2">data_info_alert</span>
                    <p className="text-xs font-bold text-center">Belum ada data presensi<br/>tersimpan hari ini.</p>
                </div>
            )}
          </div>

        </div>
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect, useMemo } from 'react';
import { z } from 'zod'; 
import { 
  Student, 
  LearningObjective, 
  GradeData, 
  Subject 
} from '../types';
import { calculateStudentGrade } from '../utils/grading';

interface Props {
  students: Student[];
  tps: LearningObjective[];
  subject: Subject;
  initialClass?: string;
  globalGradeData: GradeData;
  setGlobalGradeData: React.Dispatch<React.SetStateAction<GradeData>>;
}

const scoreSchema = z.number().min(0, "Min 0").max(100, "Max 100").optional();

// Mock Subjects for the Dropdown (Simulating multiple subjects)
const AVAILABLE_SUBJECTS = [
    { id: 's1', name: 'Matematika - Fase E' },
    { id: 's2', name: 'Fisika - Fase E' },
    { id: 's3', name: 'Kimia - Fase E' },
];

export const GradingSheet: React.FC<Props> = ({ students, tps, subject, initialClass, globalGradeData, setGlobalGradeData }) => {
  const [errorMap, setErrorMap] = useState<{[key: string]: string}>({});
  const [currentTime, setCurrentTime] = useState(new Date());

  // Weights State
  const [showConfig, setShowConfig] = useState(false);
  const [weights, setWeights] = useState({ criteria: 90, attitude: 10 });
  const [tempWeights, setTempWeights] = useState({ criteria: 90, attitude: 10 });

  // Filters
  const [selectedClass, setSelectedClass] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>(subject.id);

  // Effect to handle navigation from Dashboard
  useEffect(() => {
    if (initialClass) {
        setSelectedClass(initialClass);
    }
  }, [initialClass]);

  // Derive unique classes from students list
  const availableClasses = useMemo(() => {
      const classes = new Set(students.map(s => s.className).filter(Boolean));
      return Array.from(classes).sort() as string[];
  }, [students]);

  // Filter students based on selection
  const filteredStudents = useMemo(() => {
      if (!selectedClass) return [];
      return students.filter(s => s.className === selectedClass);
  }, [students, selectedClass]);

  useEffect(() => {
    // Update time every minute
    const interval = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(interval);
  }, []);

  const handleScoreChange = useCallback((
    studentId: string, 
    type: 'criteria' | 'attitude', 
    id: string | 'value', 
    value: string
  ) => {
    const numValue = value === '' ? undefined : parseFloat(value);
    const result = scoreSchema.safeParse(numValue);
    const errorKey = `${studentId}-${type}-${id}`;

    if (!result.success && value !== '') {
        setErrorMap(prev => ({...prev, [errorKey]: result.error.errors[0].message}));
    } else {
        setErrorMap(prev => {
            const newMap = {...prev};
            delete newMap[errorKey];
            return newMap;
        });
    }

    setGlobalGradeData(prev => {
      const studentData = prev[studentId] || { scores: {}, attitude: 0 };
      if (type === 'criteria') {
        return { ...prev, [studentId]: { ...studentData, scores: { ...studentData.scores, [id]: numValue as number } } };
      } else {
        return { ...prev, [studentId]: { ...studentData, attitude: numValue || 0 } };
      }
    });
  }, [setGlobalGradeData]);

  const handleSaveWeights = () => {
      if (tempWeights.criteria + tempWeights.attitude !== 100) {
          alert("Total bobot harus 100%");
          return;
      }
      setWeights(tempWeights);
      setShowConfig(false);
  }

  // Stats Calculation (based on filtered students)
  const stats = filteredStudents.reduce((acc, student) => {
      const res = calculateStudentGrade(student.id, globalGradeData, subject.kktp, weights);
      if (res.finalScore > 0) {
          if (res.isPassed) acc.tuntas++; else acc.remedial++;
      }
      return acc;
  }, { tuntas: 0, remedial: 0 });

  return (
    <div className="max-w-[1440px] mx-auto pb-8 relative">
      {/* Breadcrumbs */}
      <div className="flex items-center gap-2 mb-4 text-sm font-medium text-slate-500">
        <a className="hover:text-primary cursor-pointer">Dashboard</a>
        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <a className="hover:text-primary cursor-pointer">Input Nilai</a>
        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <span className="text-slate-900 font-bold">{subject.name}</span>
      </div>

      {/* Header */}
      <div className="flex flex-wrap justify-between items-end gap-4 mb-6">
        <div className="flex flex-col gap-1">
          <h1 className="text-slate-900 text-3xl font-extrabold tracking-tight">Input Nilai Siswa</h1>
          <p className="text-slate-500">Pilih Kelas dan Mata Pelajaran untuk mulai mengisi nilai.</p>
        </div>
      </div>

      {/* Toolbar / Filter Section */}
      <div className="bg-white border border-slate-200 rounded-t-xl p-4 flex flex-col md:flex-row gap-4 justify-between items-start md:items-center shadow-sm z-20 relative">
        <div className="flex flex-col md:flex-row gap-4 items-center w-full md:w-auto">

             {/* Class Filter Dropdown */}
             <div className="relative w-full md:w-56">
                <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Kelas</label>
                <div className="relative">
                    <select 
                        value={selectedClass} 
                        onChange={(e) => setSelectedClass(e.target.value)}
                        className="w-full appearance-none pl-10 pr-8 py-2.5 border border-slate-200 rounded-lg text-sm font-bold text-slate-900 bg-slate-50 hover:bg-white focus:ring-2 focus:ring-primary focus:border-transparent outline-none cursor-pointer transition-all"
                    >
                        <option value="">-- Pilih Kelas --</option>
                        {availableClasses.map(cls => (
                            <option key={cls} value={cls}>{cls}</option>
                        ))}
                    </select>
                    <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-500 pointer-events-none text-lg">school</span>
                    <span className="material-symbols-outlined absolute right-2 top-3 text-slate-400 pointer-events-none text-sm">expand_more</span>
                </div>
            </div>

            {/* Subject Filter Dropdown */}
            <div className="relative w-full md:w-64">
                <label className="text-[10px] font-bold text-slate-400 uppercase mb-1 block">Mata Pelajaran</label>
                <div className="relative">
                    <select 
                        value={selectedSubject} 
                        onChange={(e) => setSelectedSubject(e.target.value)}
                        className="w-full appearance-none pl-10 pr-8 py-2.5 border border-slate-200 rounded-lg text-sm font-bold text-slate-900 bg-slate-50 hover:bg-white focus:ring-2 focus:ring-primary focus:border-transparent outline-none cursor-pointer transition-all"
                    >
                        {AVAILABLE_SUBJECTS.map(subj => (
                            <option key={subj.id} value={subj.id}>{subj.name}</option>
                        ))}
                    </select>
                    <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-500 pointer-events-none text-lg">book</span>
                    <span className="material-symbols-outlined absolute right-2 top-3 text-slate-400 pointer-events-none text-sm">expand_more</span>
                </div>
            </div>
        </div>

        <div className="flex items-center gap-3">
             <div className="px-3 py-1 bg-slate-100 rounded border border-slate-200 flex flex-col">
                <span className="text-[10px] font-bold text-slate-400 uppercase">KKTP</span>
                <span className="text-sm font-bold text-slate-900">{subject.kktp}</span>
             </div>
             <button 
                onClick={() => setShowConfig(true)}
                className="flex items-center gap-2 px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold hover:bg-slate-50 transition-colors text-slate-700 shadow-sm"
             >
                <span className="material-symbols-outlined text-sm text-primary">settings</span>
                Parameter
             </button>
        </div>
      </div>

      {/* Main Matrix Table */}
      {selectedClass ? (
        <div className="bg-white border border-t-0 border-slate-200 rounded-b-xl overflow-hidden shadow-sm flex flex-col animate-in fade-in slide-in-from-top-2">
            <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left border-collapse table-fixed">
                <thead>
                {/* Group Headers (TP) */}
                <tr className="bg-slate-50 border-b border-slate-200">
                    <th className="sticky-col bg-slate-50 w-12 px-4 py-2 border-r border-slate-200"></th>
                    <th className="sticky-col-2 bg-slate-50 w-64 px-4 py-2 border-r border-slate-200"></th>
                    {tps.map(tp => (
                        <th 
                            key={tp.id} 
                            className="px-4 py-2 text-center text-[11px] font-bold text-slate-500 uppercase tracking-widest border-r border-slate-200 relative group cursor-help bg-slate-50 hover:bg-slate-100 transition-colors" 
                            colSpan={tp.criteria.length || 1}
                        >
                            {tp.code.toUpperCase()}
                            {/* Tooltip for TP */}
                            <div className="absolute hidden group-hover:block bg-slate-800 text-white p-3 rounded-lg text-xs w-64 top-full mt-1 left-1/2 -translate-x-1/2 z-50 font-normal shadow-xl text-left leading-relaxed">
                                <div className="font-bold text-blue-200 mb-1">{tp.code.toUpperCase()}</div>
                                {tp.description}
                            </div>
                        </th>
                    ))}
                    <th className="w-24 px-4 py-2 border-r border-slate-200"></th>
                    <th className="px-4 py-2 text-center text-[11px] font-bold text-slate-400 uppercase tracking-widest" colSpan={2}>Kalkulasi Akhir</th>
                </tr>
                {/* Column Headers (Criteria/KR) */}
                <tr className="bg-slate-50 border-b border-slate-200">
                    <th className="sticky-col bg-slate-50 w-12 px-4 py-3 text-xs font-bold text-slate-600 border-r border-slate-200 text-center">No</th>
                    <th className="sticky-col-2 bg-slate-50 w-64 px-4 py-3 text-xs font-bold text-slate-600 border-r border-slate-200">Nama Siswa</th>
                    {tps.map(tp => (
                        tp.criteria.length > 0 ? (
                            tp.criteria.map(cr => (
                                <th 
                                    key={cr.id} 
                                    className="w-24 px-2 py-3 text-xs font-bold text-slate-600 text-center border-r border-slate-200 relative group cursor-help bg-slate-50 hover:bg-blue-50 transition-colors"
                                >
                                    {cr.code.toUpperCase()}
                                    {/* Tooltip for Criteria */}
                                    <div className="absolute hidden group-hover:block bg-slate-800 text-white p-2 rounded-lg text-xs w-48 bottom-full mb-2 left-1/2 -translate-x-1/2 z-50 font-normal shadow-xl">
                                        <div className="font-bold text-green-200 mb-0.5 border-b border-white/20 pb-1">{cr.code.toUpperCase()}</div>
                                        {cr.description}
                                        {/* Little triangle arrow */}
                                        <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-slate-800"></div>
                                    </div>
                                </th>
                            ))
                        ) : (
                            <th key={`empty-${tp.id}`} className="w-24 px-2 py-3 text-xs font-bold text-red-300 text-center border-r border-slate-200 italic">No Criteria</th>
                        )
                    ))}
                    <th className="w-24 px-4 py-3 text-xs font-bold text-slate-600 text-center border-r border-slate-200">Sikap</th>
                    <th className="w-24 px-4 py-3 text-xs font-bold text-slate-600 text-center border-r border-slate-200">NA</th>
                    <th className="w-40 px-4 py-3 text-xs font-bold text-slate-600 text-center">Status</th>
                </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {filteredStudents.length > 0 ? (
                        filteredStudents.map((student, index) => {
                            const result = calculateStudentGrade(student.id, globalGradeData, subject.kktp, weights);
                            return (
                                <tr key={student.id} className="group hover:bg-primary/5 transition-colors">
                                    <td className="sticky-col bg-white group-hover:bg-[#f2f8fe] text-center text-xs text-slate-500 border-r border-slate-100 transition-colors">{index + 1}</td>
                                    <td className="sticky-col-2 bg-white group-hover:bg-[#f2f8fe] px-4 py-0 font-medium text-sm text-slate-700 border-r border-slate-100 transition-colors">
                                        {student.name}
                                        <div className="flex gap-2 items-center mt-0.5">
                                            <span className="text-[10px] text-slate-400 font-normal bg-slate-50 px-1 rounded">{student.nis}</span>
                                            {!selectedClass && <span className="text-[10px] text-blue-500 font-bold bg-blue-50 px-1 rounded">{student.className}</span>}
                                        </div>
                                    </td>

                                    {/* Dynamic Criteria Inputs Nested by TP */}
                                    {tps.map(tp => (
                                        tp.criteria.length > 0 ? (
                                            tp.criteria.map(cr => {
                                                const err = errorMap[`${student.id}-criteria-${cr.id}`];
                                                return (
                                                    <td key={cr.id} className="p-0 border-r border-slate-100 relative">
                                                        <input 
                                                            type="number" 
                                                            className={`w-full h-10 border-none bg-transparent text-center text-sm focus:ring-0 focus:bg-white focus:shadow-inner ${err ? 'text-red-500 bg-red-50' : 'text-slate-800'}`}
                                                            value={globalGradeData[student.id]?.scores?.[cr.id] ?? ''}
                                                            onChange={(e) => handleScoreChange(student.id, 'criteria', cr.id, e.target.value)}
                                                            placeholder="-"
                                                        />
                                                    </td>
                                                );
                                            })
                                        ) : (
                                            <td key={`empty-cell-${tp.id}`} className="p-0 border-r border-slate-100 bg-slate-50"></td>
                                        )
                                    ))}

                                    {/* Attitude */}
                                    <td className="p-0 border-r border-slate-100">
                                        <input 
                                            type="number"
                                            className="w-full h-10 border-none bg-transparent text-center text-sm focus:ring-0 focus:bg-white focus:shadow-inner text-slate-800"
                                            value={globalGradeData[student.id]?.attitude ?? ''}
                                            onChange={(e) => handleScoreChange(student.id, 'attitude', 'value', e.target.value)}
                                            placeholder="-"
                                        />
                                    </td>
                                    {/* Final & Status */}
                                    <td className="px-4 text-center font-bold text-sm bg-slate-50 border-r border-slate-200 text-primary">
                                        {result.finalScore || '-'}
                                    </td>
                                    <td className="px-4 text-center">
                                        {result.finalScore > 0 && (
                                            <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider ${result.isPassed ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                {result.isPassed ? 'Tuntas' : 'Remedial'}
                                            </span>
                                        )}
                                    </td>
                                </tr>
                            )
                        })
                    ) : (
                        <tr>
                            <td colSpan={10} className="p-12 text-center text-slate-400 italic bg-slate-50/50">
                                Tidak ada siswa di kelas ini.
                            </td>
                        </tr>
                    )}
                </tbody>
            </table>
            </div>

            {/* Footer Stats */}
            <div className="bg-slate-50 border-t border-slate-200 px-6 py-3 flex justify-between items-center text-xs font-semibold text-slate-500">
                <div className="flex gap-6">
                    <span>TOTAL SISWA: {filteredStudents.length}</span>
                    <span className="text-green-600">TUNTAS: {stats.tuntas}</span>
                    <span className="text-red-600">REMEDIAL: {stats.remedial}</span>
                </div>
            </div>
        </div>
      ) : (
        <div className="bg-white border border-t-0 border-slate-200 rounded-b-xl p-12 flex flex-col items-center justify-center text-slate-400 min-h-[400px]">
             <div className="bg-slate-50 p-6 rounded-full mb-4">
                <span className="material-symbols-outlined text-4xl text-slate-300">fact_check</span>
             </div>
             <p className="text-lg font-bold text-slate-600">Mulai Penilaian</p>
             <p className="text-sm">Silahkan pilih <strong className="text-slate-700">Kelas</strong> dan <strong className="text-slate-700">Mata Pelajaran</strong> terlebih dahulu untuk menampilkan lembar kerja.</p>
        </div>
      )}

      {/* System Status */}
      <div className="mt-4 flex justify-between items-center text-[10px] uppercase tracking-widest text-slate-400">
        <div className="flex items-center gap-2">
            <span className="size-2 rounded-full bg-green-500 animate-pulse"></span>
            System Ready
        </div>
        <div>
          Last Sync: {currentTime.toLocaleTimeString('id-ID', {timeZone: 'Asia/Makassar', hour: '2-digit', minute: '2-digit'})} WITA
        </div>
      </div>

       {/* Config Modal */}
       {showConfig && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
            <div className="bg-white rounded-2xl w-full max-w-sm shadow-2xl">
                <div className="p-4 border-b border-slate-100 flex justify-between items-center">
                    <h3 className="font-bold text-slate-900">Parameter Penilaian</h3>
                    <button onClick={() => setShowConfig(false)} className="text-slate-400 hover:text-slate-600">
                        <span className="material-symbols-outlined">close</span>
                    </button>
                </div>
                <div className="p-6 space-y-4">
                     <div>
                        <label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Bobot Nilai Akademik (Formatif/Sumatif)</label>
                        <div className="flex items-center gap-2">
                            <input 
                                type="number" 
                                value={tempWeights.criteria}
                                onChange={(e) => setTempWeights(prev => ({...prev, criteria: Number(e.target.value)}))}
                                className="w-full border-slate-200 rounded-lg text-center font-bold text-slate-900" 
                            />
                            <span className="text-slate-500 font-bold">%</span>
                        </div>
                     </div>
                     <div>
                        <label className="text-xs font-bold text-slate-500 uppercase mb-1 block">Bobot Nilai Sikap</label>
                        <div className="flex items-center gap-2">
                             <input 
                                type="number" 
                                value={tempWeights.attitude}
                                onChange={(e) => setTempWeights(prev => ({...prev, attitude: Number(e.target.value)}))}
                                className="w-full border-slate-200 rounded-lg text-center font-bold text-slate-900" 
                            />
                            <span className="text-slate-500 font-bold">%</span>
                        </div>
                     </div>
                     <div className={`text-xs font-bold text-center ${tempWeights.criteria + tempWeights.attitude === 100 ? 'text-green-600' : 'text-red-500'}`}>
                         Total: {tempWeights.criteria + tempWeights.attitude}%
                     </div>
                     <button 
                        onClick={handleSaveWeights}
                        className="w-full py-2.5 bg-primary text-white rounded-lg font-bold hover:bg-blue-600"
                     >
                         Simpan Parameter
                     </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { LearningMaterial, LearningObjective, Subject, AssessmentCriteria, IdentityData } from '../types';

declare const Swal: any;

interface Props {
  identity: IdentityData;
  subject: Subject;
  tps: LearningObjective[];
  onUpdateSubject: (kktp: number) => void;
  onUpdateTPs: (tps: LearningObjective[]) => void;
  onBack: () => void;
}

// Mock Data for Scopes
const SD_SUBJECTS = [
    { id: 'math', name: 'Matematika' },
    { id: 'indo', name: 'B. Indonesia' },
    { id: 'ipas', name: 'IPAS' },
    { id: 'ppkn', name: 'PPKn' },
    { id: 'sbura', name: 'Seni Budaya' },
];

const SMP_LEVELS = [
    { id: 'lvl-7', name: 'Kelas 7 (Fase D)' },
    { id: 'lvl-8', name: 'Kelas 8 (Fase D)' },
    { id: 'lvl-9', name: 'Kelas 9 (Fase D)' },
];

const SMA_LEVELS = [
    { id: 'lvl-10', name: 'Kelas 10 (Fase E)' },
    { id: 'lvl-11', name: 'Kelas 11 (Fase F)' },
    { id: 'lvl-12', name: 'Kelas 12 (Fase F)' },
];

export const CurriculumManager: React.FC<Props> = ({ 
  identity, subject, tps, onUpdateSubject, onUpdateTPs, onBack 
}) => {
  const [expandedTpId, setExpandedTpId] = useState<string | null>(null);

  // DETERMINE CONTEXT (Scope)
  // If Class Teacher -> Scope is Subject (Math, IPAS, etc.)
  // If Subject Teacher -> Scope is Level (Grade 7, 8, etc.)

  const scopes = useMemo(() => {
      if (identity.role === 'CLASS_TEACHER') {
          return SD_SUBJECTS;
      } else {
          // Logic: Check school name to determine SMP vs SMA/SMK
          const schoolNameLower = identity.schoolName.toLowerCase();
          const isSMP = schoolNameLower.includes('smp') || schoolNameLower.includes('mts');

          // Default to SMA levels if not explicitly SMP
          return isSMP ? SMP_LEVELS : SMA_LEVELS;
      }
  }, [identity]);

  const [activeScopeId, setActiveScopeId] = useState<string>(scopes[0].id);

  useEffect(() => {
      // Ensure activeScopeId is valid when scopes change
      const exists = scopes.find(s => s.id === activeScopeId);
      if (!exists) {
          setActiveScopeId(scopes[0].id);
      }
  }, [scopes, activeScopeId]);

  // Filter TPs based on Active Scope
  const filteredTPs = useMemo(() => {
      return tps.filter(tp => tp.scopeId === activeScopeId);
  }, [tps, activeScopeId]);

  // TP Form State
  const [isAddingTp, setIsAddingTp] = useState(false);
  const [newTpForm, setNewTpForm] = useState({ code: '', description: '', semester: '1' });

  // Sub-item Form State (LM & Criteria)
  const [newItemForm, setNewItemForm] = useState<{
      type: 'LM' | 'CRITERIA' | null, 
      parentId: string | null,
      val1: string, // Code
      val2: string // Title/Description
  }>({ type: null, parentId: null, val1: '', val2: '' });

  // --- TP CRUD ---
  const handleAddTP = () => {
    if(!newTpForm.code || !newTpForm.description) return;
    const newTp: LearningObjective = {
        id: Date.now().toString(),
        code: newTpForm.code.toUpperCase(), 
        description: newTpForm.description,
        semester: Number(newTpForm.semester) as 1 | 2,
        scopeId: activeScopeId, // ASSIGN CURRENT SCOPE
        lms: [],
        criteria: []
    };
    onUpdateTPs([...tps, newTp]);
    setIsAddingTp(false);
    setNewTpForm({ code: '', description: '', semester: '1' });
  };

  const handleDeleteTP = (id: string) => {
      Swal.fire({
          title: 'Hapus Tujuan Pembelajaran?',
          text: "Seluruh Lingkup Materi (LM) dan Kriteria yang ada di dalamnya akan ikut terhapus!",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Ya, hapus!',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateTPs(tps.filter(t => t.id !== id));
              Swal.fire(
                  'Terhapus!',
                  'TP berhasil dihapus.',
                  'success'
              )
          }
      });
  };

  // --- NESTED ITEMS CRUD ---
  const handleAddItem = () => {
      if(!newItemForm.val1 || !newItemForm.val2 || !newItemForm.parentId || !newItemForm.type) return;

      const updatedTPs = tps.map(tp => {
          if(tp.id === newItemForm.parentId) {
              if(newItemForm.type === 'LM') {
                  return {
                      ...tp,
                      lms: [...tp.lms, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), 
                          title: newItemForm.val2 
                      }]
                  };
              } else {
                  return {
                      ...tp,
                      criteria: [...tp.criteria, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), 
                          description: newItemForm.val2 
                      }]
                  };
              }
          }
          return tp;
      });

      onUpdateTPs(updatedTPs);
      setNewItemForm({ type: null, parentId: null, val1: '', val2: '' });
  };

  const handleDeleteSubItem = (tpId: string, itemId: string, type: 'LM' | 'CRITERIA') => {
      Swal.fire({
          title: 'Hapus Item?',
          text: "Item ini akan dihapus permanen.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Hapus',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              const updatedTPs = tps.map(tp => {
                  if(tp.id === tpId) {
                      if(type === 'LM') {
                          return { ...tp, lms: tp.lms.filter(l => l.id !== itemId) };
                      } else {
                          return { ...tp, criteria: tp.criteria.filter(c => c.id !== itemId) };
                      }
                  }
                  return tp;
              });
              onUpdateTPs(updatedTPs);
          }
      });
  };

  return (
    <div className="h-full flex flex-col bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Header Title */}
        <div className="bg-gray-50 p-6 border-b flex justify-between items-center">
            <div>
                <h2 className="text-xl font-bold text-gray-800">Manajemen Kurikulum & Asesmen</h2>
                <p className="text-sm text-gray-500">
                    {identity.role === 'CLASS_TEACHER' 
                        ? 'Pengaturan TP per Mata Pelajaran (Guru Kelas)' 
                        : 'Pengaturan TP per Tingkat Kelas (Guru Mapel)'}
                </p>
            </div>
             <button onClick={onBack} className="text-gray-500 hover:text-gray-700 font-medium">
                &larr; Kembali
            </button>
        </div>

        {/* Top Control Bar (Dropdown & KKTP) */}
        <div className="px-6 py-4 bg-white border-b flex flex-col md:flex-row gap-4 justify-between items-end md:items-center">
            <div className="flex flex-col md:flex-row gap-6 w-full md:w-auto">

                {/* Scope/Class Selector */}
                <div className="w-full md:w-64">
                    <label className="text-xs font-bold text-gray-500 uppercase block mb-1">
                        {identity.role === 'CLASS_TEACHER' ? 'Mata Pelajaran' : 'Pilih Tingkat Kelas'}
                    </label>
                    <div className="relative">
                        <select 
                            value={activeScopeId} 
                            onChange={(e) => setActiveScopeId(e.target.value)}
                            className="w-full appearance-none pl-10 pr-8 py-2 border border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-2 focus:ring-primary focus:border-transparent outline-none cursor-pointer bg-white"
                        >
                            {scopes.map(scope => (
                                <option key={scope.id} value={scope.id}>{scope.name}</option>
                            ))}
                        </select>
                        <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-500 pointer-events-none text-lg">
                            {identity.role === 'CLASS_TEACHER' ? 'menu_book' : 'school'}
                        </span>
                        <span className="material-symbols-outlined absolute right-2 top-2.5 text-slate-400 pointer-events-none text-sm">expand_more</span>
                    </div>
                </div>

                {/* KKTP Input */}
                <div className="w-full md:w-32">
                    <label className="text-xs font-bold text-gray-500 uppercase block mb-1">KKTP</label>
                    <div className="relative">
                        <input 
                            type="number" 
                            value={subject.kktp} 
                            onChange={(e) => onUpdateSubject(Number(e.target.value))}
                            className="w-full pl-3 pr-8 py-2 border border-slate-300 rounded-lg text-sm font-bold text-blue-700 focus:ring-2 focus:ring-blue-500 outline-none"
                        />
                        <span className="absolute right-3 top-2 text-xs font-bold text-slate-400">Poin</span>
                    </div>
                </div>
            </div>

            <button 
                onClick={() => setIsAddingTp(!isAddingTp)}
                className="flex items-center gap-2 px-4 py-2.5 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 transition-colors shadow-sm"
            >
                <span className="material-symbols-outlined text-sm">{isAddingTp ? 'remove' : 'add'}</span>
                Tambah TP
            </button>
        </div>

        {/* Main Content Area */}
        <div className="flex-1 flex flex-col overflow-hidden bg-white">

            {/* Add TP Form */}
            {isAddingTp && (
                <div className="mx-6 mt-6 p-4 bg-blue-50 border border-blue-100 rounded-xl animate-in fade-in slide-in-from-top-4">
                    <h4 className="font-bold text-blue-800 mb-3 text-sm">
                        Tambah TP Baru di {scopes.find(s => s.id === activeScopeId)?.name}
                    </h4>
                    <div className="flex gap-3 items-start">
                        <div className="w-24">
                            <input 
                                type="text" placeholder="Kode" 
                                value={newTpForm.code} onChange={e => setNewTpForm({...newTpForm, code: e.target.value.toUpperCase()})}
                                className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900 placeholder:text-slate-400"
                            />
                        </div>
                        <div className="w-24">
                            <select 
                                value={newTpForm.semester} onChange={e => setNewTpForm({...newTpForm, semester: e.target.value})}
                                className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900"
                            >
                                <option value="1">Smt 1</option>
                                <option value="2">Smt 2</option>
                            </select>
                        </div>
                        <div className="flex-1">
                            <input 
                                type="text" placeholder="Deskripsi Tujuan Pembelajaran..." 
                                value={newTpForm.description} onChange={e => setNewTpForm({...newTpForm, description: e.target.value})}
                                className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900"
                            />
                        </div>
                        <button onClick={handleAddTP} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold text-sm hover:bg-blue-700">Simpan</button>
                    </div>
                </div>
            )}

            {/* TP List */}
            <div className="flex-1 overflow-y-auto p-6 space-y-4">
                {filteredTPs.length === 0 && (
                    <div className="text-center py-12 text-gray-400">
                        <span className="material-symbols-outlined text-4xl mb-2">library_books</span>
                        <p>Belum ada Tujuan Pembelajaran untuk {scopes.find(s => s.id === activeScopeId)?.name}.</p>
                    </div>
                )}

                {filteredTPs.map((tp) => {
                    const isExpanded = expandedTpId === tp.id;
                    return (
                        <div key={tp.id} className={`border rounded-xl transition-all ${isExpanded ? 'border-primary shadow-md bg-white' : 'border-slate-200 bg-white hover:border-slate-300'}`}>
                            {/* TP Header */}
                            <div 
                                onClick={() => setExpandedTpId(isExpanded ? null : tp.id)}
                                className="p-4 flex items-center gap-4 cursor-pointer"
                            >
                                <div className={`size-10 rounded-lg flex items-center justify-center font-bold text-sm ${isExpanded ? 'bg-primary text-white' : 'bg-slate-100 text-slate-500'}`}>
                                    {tp.code.toUpperCase()}
                                </div>
                                <div className="flex-1">
                                    <p className={`text-sm font-bold ${isExpanded ? 'text-primary' : 'text-slate-800'}`}>{tp.description}</p>
                                    <div className="flex items-center gap-2 mt-1">
                                        <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500">Semester {tp.semester}</span>
                                        <span className="text-[10px] text-slate-400 flex items-center gap-1">
                                            <span className="material-symbols-outlined text-[10px]">topic</span> {tp.lms.length} LM
                                        </span>
                                        <span className="text-[10px] text-slate-400 flex items-center gap-1">
                                            <span className="material-symbols-outlined text-[10px]">fact_check</span> {tp.criteria.length} Kriteria
                                        </span>
                                    </div>
                                </div>
                                <button 
                                    onClick={(e) => { e.stopPropagation(); handleDeleteTP(tp.id); }}
                                    className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                    <span className="material-symbols-outlined">delete</span>
                                </button>
                                <span className={`material-symbols-outlined text-slate-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`}>expand_more</span>
                            </div>

                            {/* Expanded Content */}
                            {isExpanded && (
                                <div className="border-t border-slate-100 bg-slate-50/50 p-4 space-y-6 animate-in slide-in-from-top-2">

                                    {/* Lingkup Materi Section */}
                                    <div className="space-y-3">
                                        <div className="flex justify-between items-center">
                                            <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
                                                <span className="material-symbols-outlined text-sm">topic</span>
                                                Lingkup Materi (LM)
                                            </h4>
                                        </div>
                                        <div className="bg-white border border-slate-200 rounded-lg overflow-hidden">
                                            <table className="w-full text-sm">
                                                <thead className="bg-slate-50 text-slate-500 font-semibold border-b border-slate-200">
                                                    <tr>
                                                        <th className="px-4 py-2 text-left w-24">Kode</th>
                                                        <th className="px-4 py-2 text-left">Judul Materi</th>
                                                        <th className="px-4 py-2 w-16"></th>
                                                    </tr>
                                                </thead>
                                                <tbody className="divide-y divide-slate-100">
                                                    {tp.lms.map(lm => (
                                                        <tr key={lm.id} className="group hover:bg-slate-50">
                                                            <td className="px-4 py-2 font-mono text-xs font-bold text-blue-600">{lm.code.toUpperCase()}</td>
                                                            <td className="px-4 py-2 text-slate-800">{lm.title}</td>
                                                            <td className="px-4 py-2 text-right">
                                                                <button 
                                                                    onClick={() => handleDeleteSubItem(tp.id, lm.id, 'LM')}
                                                                    className="text-slate-300 hover:text-red-500 group-hover:text-slate-400"
                                                                >
                                                                    <span className="material-symbols-outlined text-sm">close</span>
                                                                </button>
                                                            </td>
                                                        </tr>
                                                    ))}
                                                        {/* Add Row */}
                                                        <tr className="bg-slate-50">
                                                        <td className="px-2 py-2">
                                                            <input 
                                                                type="text" placeholder="LM.x" 
                                                                className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-blue-500 bg-white text-slate-900"
                                                                value={newItemForm.type === 'LM' && newItemForm.parentId === tp.id ? newItemForm.val1 : ''}
                                                                onChange={(e) => setNewItemForm({ type: 'LM', parentId: tp.id, val1: e.target.value.toUpperCase(), val2: newItemForm.val2 })}
                                                                onFocus={() => setNewItemForm(prev => ({ ...prev, type: 'LM', parentId: tp.id }))}
                                                            />
                                                        </td>
                                                        <td className="px-2 py-2">
                                                            <input 
                                                                type="text" placeholder="Tambah Lingkup Materi..." 
                                                                className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-blue-500 bg-white text-slate-900"
                                                                value={newItemForm.type === 'LM' && newItemForm.parentId === tp.id ? newItemForm.val2 : ''}
                                                                onChange={(e) => setNewItemForm({ type: 'LM', parentId: tp.id, val1: newItemForm.val1, val2: e.target.value })}
                                                                onKeyDown={(e) => e.key === 'Enter' && handleAddItem()}
                                                            />
                                                        </td>
                                                        <td className="px-2 py-2 text-center">
                                                                {newItemForm.type === 'LM' && newItemForm.parentId === tp.id && newItemForm.val1 && (
                                                                <button onClick={handleAddItem} className="text-blue-600 hover:text-blue-800">
                                                                    <span className="material-symbols-outlined text-lg">check_circle</span>
                                                                </button>
                                                                )}
                                                        </td>
                                                    </tr>
                                                </tbody>
                                            </table>
                                        </div>
                                    </div>

                                    {/* Kriteria Section */}
                                    <div className="space-y-3">
                                        <div className="flex justify-between items-center">
                                            <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
                                                <span className="material-symbols-outlined text-sm">fact_check</span>
                                                Kriteria Penilaian (Untuk Matrix Input Nilai)
                                            </h4>
                                        </div>
                                        <div className="bg-white border border-slate-200 rounded-lg overflow-hidden">
                                            <table className="w-full text-sm">
                                                <thead className="bg-slate-50 text-slate-500 font-semibold border-b border-slate-200">
                                                    <tr>
                                                        <th className="px-4 py-2 text-left w-24">Kode</th>
                                                        <th className="px-4 py-2 text-left">Deskripsi Kriteria</th>
                                                        <th className="px-4 py-2 w-16"></th>
                                                    </tr>
                                                </thead>
                                                <tbody className="divide-y divide-slate-100">
                                                    {tp.criteria.map(cr => (
                                                        <tr key={cr.id} className="group hover:bg-slate-50">
                                                            <td className="px-4 py-2 font-mono text-xs font-bold text-green-600">{cr.code.toUpperCase()}</td>
                                                            <td className="px-4 py-2 text-slate-800">{cr.description}</td>
                                                            <td className="px-4 py-2 text-right">
                                                                <button 
                                                                    onClick={() => handleDeleteSubItem(tp.id, cr.id, 'CRITERIA')}
                                                                    className="text-slate-300 hover:text-red-500 group-hover:text-slate-400"
                                                                >
                                                                    <span className="material-symbols-outlined text-sm">close</span>
                                                                </button>
                                                            </td>
                                                        </tr>
                                                    ))}
                                                        {/* Add Row */}
                                                        <tr className="bg-slate-50">
                                                        <td className="px-2 py-2">
                                                            <input 
                                                                type="text" placeholder="KR.x" 
                                                                className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-green-500 bg-white text-slate-900"
                                                                value={newItemForm.type === 'CRITERIA' && newItemForm.parentId === tp.id ? newItemForm.val1 : ''}
                                                                onChange={(e) => setNewItemForm({ type: 'CRITERIA', parentId: tp.id, val1: e.target.value.toUpperCase(), val2: newItemForm.val2 })}
                                                                onFocus={() => setNewItemForm(prev => ({ ...prev, type: 'CRITERIA', parentId: tp.id }))}
                                                            />
                                                        </td>
                                                        <td className="px-2 py-2">
                                                            <input 
                                                                type="text" placeholder="Tambah Kriteria Penilaian..." 
                                                                className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-green-500 bg-white text-slate-900"
                                                                value={newItemForm.type === 'CRITERIA' && newItemForm.parentId === tp.id ? newItemForm.val2 : ''}
                                                                onChange={(e) => setNewItemForm({ type: 'CRITERIA', parentId: tp.id, val1: newItemForm.val1, val2: e.target.value })}
                                                                onKeyDown={(e) => e.key === 'Enter' && handleAddItem()}
                                                            />
                                                        </td>
                                                        <td className="px-2 py-2 text-center">
                                                                {newItemForm.type === 'CRITERIA' && newItemForm.parentId === tp.id && newItemForm.val1 && (
                                                                <button onClick={handleAddItem} className="text-green-600 hover:text-green-800">
                                                                    <span className="material-symbols-outlined text-lg">check_circle</span>
                                                                </button>
                                                                )}
                                                        </td>
                                                    </tr>
                                                </tbody>
                                            </table>
                                        </div>
                                    </div>

                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </div>
    </div>
  );
};

// Domain Models

export type TeacherRole = 'CLASS_TEACHER' | 'SUBJECT_TEACHER';
export type SchoolLevel = 'SD' | 'SMP' | 'SMA' | 'SMK'; // NEW

export interface Student {
  id: string;
  name: string;
  nis: string;
  className?: string; // e.g., "10-A IPA"
}

export interface ClassInfo {
  id: string;
  name: string; // e.g. "10-A IPA"
  level: string; // e.g. "Fase E (Kelas 10)"
  studentCount: number;
}

export interface ScheduleItem {
  id: string;
  day: string; // Senin, Selasa, etc
  startTime: string; // "07:30"
  endTime: string; // "09:00"
  className: string;
  subject: string;
  room: string;
}

export interface LearningMaterial { // LM (Lingkup Materi) - Now Child of TP
  id: string;
  code: string; // e.g., LM.1
  title: string;
}

export interface AssessmentCriteria { // Kriteria Penilaian - Child of TP
  id: string;
  code: string; // e.g., Kr.1
  description: string; // e.g., "Pemahaman Konsep"
}

export interface LearningObjective { // TP (Tujuan Pembelajaran)
  id: string;
  code: string; // e.g., TP.1
  description: string;
  semester?: 1 | 2; // Optional, defaulted if missing
  scopeId?: string; // NEW: Context ID. If Guru Kelas = Subject ID (e.g., 'math'). If Guru Mapel = Level ID (e.g., 'lvl-7')
  lms: LearningMaterial[]; // Nested LMs
  criteria: AssessmentCriteria[]; // Nested Criteria for Grading
}

export interface Subject {
  id: string;
  name: string;
  kktp: number; // Kriteria Ketercapaian Tujuan Pembelajaran (Passing Grade)
}

export interface GradeData {
  [studentId: string]: {
    scores: { [criteriaId: string]: number }; // Maps Criteria ID -> Score
    attitude: number; // Nilai Sikap
  };
}

export interface CalculatedGrade {
  avgScore: number;
  finalScore: number;
  isPassed: boolean;
}

// Identity Data
export interface IdentityData {
  role: TeacherRole; // NEW
  level: SchoolLevel; // NEW: Jenjang Sekolah (SD/SMP/SMA/SMK)
  schoolName: string;
  subjectName: string; // Main subject for Subject Teacher, or "Guru Kelas" text
  teacherName: string;
  nip: string;
  semester: string;
  academicYear: string;
  className: string; // Wali Kelas / Main Class
  studentCount: number;
}

// Attendance Types
export type AttendanceStatus = 'H' | 'I' | 'S' | 'A'; // Hadir, Izin, Sakit, Alfa

// Removed static AttendanceSession interface as it is now generated dynamically

export interface AttendanceRecord {
   status: AttendanceStatus;
   notes?: string;
}

// New Structure: ScheduleID -> DateString (YYYY-MM-DD) -> StudentID -> Record
export interface AttendanceData {
  [scheduleId: string]: {
      [date: string]: {
          [studentId: string]: AttendanceRecord
      }
  };
}

