  const [editingId, setEditingId] = useState<string | null>(null);

  // Default Form Data
  const [formData, setFormData] = useState({
      name: '',
      nis: '',
      gender: 'L',
      className: '',
      status: 'Aktif'
  });

  const handleOpenModal = (student?: Student) => {
      if (student) {
          setEditingId(student.id);
          setFormData({
              name: student.name,
              nis: student.nis,
              gender: 'L', // Assuming L default if property missing in basic type
              className: student.className || '',
              status: 'Aktif'
          });
      } else {
          setEditingId(null);
          // Set default class if available
          const defaultClass = classes.length > 0 ? classes[0].name : '';
          setFormData({ name: '', nis: '', gender: 'L', className: defaultClass, status: 'Aktif' });
      }
      setIsModalOpen(true);
  };

  const handleSaveStudent = (e: React.FormEvent) => {
      e.preventDefault();

      // VALIDATION: Check for empty fields
      if (!formData.name.trim() || !formData.nis.trim() || !formData.className || !formData.gender) {
          Swal.fire({
              title: 'Gagal Menyimpan',
              text: "Semua kolom (Nama, NIS, Jenis Kelamin, Kelas) wajib diisi!",
              icon: 'error',
              confirmButtonColor: '#d33',
              confirmButtonText: 'OK'
          });
          return;
      }

      if (editingId) {
          // Update
          const updatedStudents = students.map(s => s.id === editingId ? { ...s, ...formData } : s);
          onUpdateStudents(updatedStudents);
      } else {
          // Add
          const newStudent: Student = {
              id: Date.now().toString(),
              name: formData.name,
              nis: formData.nis,
              className: formData.className,
              // status and gender are managed in this form state but Student interface might need extension in real app
              // For now we map to existing simple Student interface
          };
          onUpdateStudents([newStudent, ...students]);
      }
      setIsModalOpen(false);

      // Success Feedback
      Swal.fire({
          title: 'Berhasil!',
          text: 'Data siswa telah disimpan.',
          icon: 'success',
          timer: 1500,
          showConfirmButton: false
      });
  };

  const handleDeleteStudent = (id: string) => {
      Swal.fire({
          title: 'Hapus Siswa?',
          text: "Data ini tidak dapat dikembalikan!",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Ya, hapus!',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateStudents(students.filter(s => s.id !== id));
              Swal.fire(
                  'Terhapus!',
                  'Data siswa berhasil dihapus.',
                  'success'
              )
          }
      });
  };

  return (
    <div className="w-full max-w-7xl mx-auto">
      {/* Breadcrumbs */}
      <div className="flex items-center gap-2 mb-4">
        <button onClick={onBack} className="text-slate-500 text-sm font-medium hover:text-primary">Beranda</button>
        <span className="text-slate-400 text-sm font-medium">/</span>
        <span className="text-primary text-sm font-bold">Master Data Siswa</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <div className="flex flex-col gap-1">
          <h2 className="text-slate-900 text-3xl font-extrabold tracking-tight">Master Data Siswa</h2>
          <p className="text-slate-500 text-base font-normal">Kelola data induk siswa, mutasi, dan status akademik.</p>
        </div>
        <div className="flex gap-2">
           <button className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 rounded-lg text-sm font-bold hover:bg-slate-50 transition-colors text-slate-700">
            <span className="material-symbols-outlined text-sm">upload</span>
            Import Excel
          </button>
          <button 
            onClick={() => handleOpenModal()}
            className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 transition-colors shadow-lg shadow-blue-200"
          >
            <span className="material-symbols-outlined text-sm">person_add</span>
            Tambah Siswa
          </button>
        </div>
      </div>

      {/* Summary Stats - 4 Required Banners */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
        <div className="bg-white border border-slate-200 p-6 rounded-xl shadow-sm flex flex-col gap-1">
            <div className="flex justify-between items-start">
                <span className="text-xs text-slate-500 font-bold uppercase tracking-wider">Total Siswa</span>
                <span className="material-symbols-outlined text-blue-500 bg-blue-50 p-1.5 rounded-lg text-lg">groups</span>
            </div>
            <p className="text-2xl font-bold text-slate-900">{students.length}</p>
        </div>
        {/* Placeholder stats as we don't have full data model for gender/status in the root Student type yet */}
        <div className="bg-white border border-slate-200 p-6 rounded-xl shadow-sm flex flex-col gap-1 opacity-60">
            <div className="flex justify-between items-start">
                <span className="text-xs text-slate-500 font-bold uppercase tracking-wider">Siswa Aktif</span>
                <span className="material-symbols-outlined text-green-500 bg-green-50 p-1.5 rounded-lg text-lg">check_circle</span>
            </div>
            <p className="text-2xl font-bold text-slate-900">-</p>
        </div>
      </div>

      {/* Table Section */}
      <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden">
        {/* Table Toolbar */}
        <div className="p-4 border-b border-slate-200 flex flex-wrap gap-4 justify-between items-center bg-slate-50">
           <div className="flex gap-4 flex-1">
                <div className="relative">
                    <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-400 text-lg">search</span>
                    <input type="text" placeholder="Cari nama, NIS..." className="pl-10 pr-4 py-2 border border-slate-200 rounded-lg text-sm font-bold text-slate-900 w-64 focus:ring-2 focus:ring-primary focus:border-transparent outline-none placeholder:text-slate-400" />
                </div>

                {/* Select with Icon Dropdown */}
                <div className="relative">
                    <select className="appearance-none pl-4 pr-10 py-2 border border-slate-200 rounded-lg text-sm font-bold text-slate-900 bg-white focus:ring-2 focus:ring-primary cursor-pointer w-40">
                        <option value="">Semua Kelas</option>
                        {classes.map(c => (
                            <option key={c.id} value={c.name}>{c.name}</option>
                        ))}
                    </select>
                    <span className="material-symbols-outlined absolute right-3 top-2.5 text-slate-400 pointer-events-none text-sm">expand_more</span>
                </div>
           </div>
        </div>

        <div className="overflow-x-auto min-h-[300px]">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200">
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider w-16 text-center">No</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Identitas Siswa</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Kelas</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Status</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">Aksi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {students.length > 0 ? students.map((student, index) => (
                <tr key={student.id} className="hover:bg-slate-50 transition-colors group">
                  <td className="px-6 py-4 text-center text-sm text-slate-500">{index + 1}</td>
                  <td className="px-6 py-4">
                    <p className="font-bold text-slate-800 text-sm">{student.name}</p>
                    <div className="flex gap-2 text-[10px] text-slate-500 mt-1">
                        <span className="bg-slate-100 px-1.5 py-0.5 rounded">NIS: {student.nis}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-600 font-medium">{student.className || '-'}</td>
                  <td className="px-6 py-4">
                     <span className={`inline-flex items-center gap-1.5 text-xs font-semibold px-2 py-1 rounded-full border bg-green-50 text-green-600 border-green-100`}>
                      <span className={`size-1.5 rounded-full bg-green-500`}></span> 
                      Aktif
                    </span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-2">
                      <button onClick={() => handleOpenModal(student)} className="p-2 bg-blue-50 text-blue-600 hover:bg-blue-100 rounded-lg transition-colors" title="Edit">
                        <span className="material-symbols-outlined text-sm">edit</span>
                      </button>
                      <button onClick={() => handleDeleteStudent(student.id)} className="p-2 bg-red-50 text-red-600 hover:bg-red-100 rounded-lg transition-colors" title="Delete">
                        <span className="material-symbols-outlined text-sm">delete</span>
                      </button>
                    </div>
                  </td>
                </tr>
              )) : (
                  <tr>
                      <td colSpan={5} className="p-12 text-center text-slate-400">
                          <span className="material-symbols-outlined text-4xl mb-2">person_off</span>
                          <p>Belum ada data siswa.</p>
                      </td>
                  </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div className="px-6 py-4 border-t border-slate-200 flex items-center justify-between">
            <p className="text-sm text-slate-500">Menampilkan {students.length} siswa</p>
        </div>
      </div>

       {/* Add/Edit Student Modal */}
       {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
              <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl transform transition-all scale-100">
                  <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                      <h3 className="text-xl font-bold text-slate-900">{editingId ? 'Edit Siswa' : 'Tambah Siswa Baru'}</h3>
                      <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-red-500 transition-colors">
                          <span className="material-symbols-outlined">close</span>
                      </button>
                  </div>
                  <form onSubmit={handleSaveStudent} className="p-6 space-y-4">
                      <div className="space-y-2">
                          <label className="text-sm font-bold text-slate-700">Nama Lengkap <span className="text-red-500">*</span></label>
                          <input 
                              type="text" 
                              required
                              placeholder="Nama Siswa"
                              className="w-full rounded-lg border-slate-200 focus:ring-2 focus:ring-primary focus:border-transparent text-sm font-bold text-slate-900 bg-white"
                              value={formData.name}
                              onChange={(e) => setFormData({...formData, name: e.target.value})}
                          />
                      </div>
                      <div className="space-y-2">
                            <label className="text-sm font-bold text-slate-700">NIS <span className="text-red-500">*</span></label>
                            <input 
                                type="text" 
                                required
                                placeholder="Nomor Induk"
                                className="w-full rounded-lg border-slate-200 focus:ring-2 focus:ring-primary focus:border-transparent text-sm font-bold text-slate-900 bg-white"
                                value={formData.nis}
                                onChange={(e) => setFormData({...formData, nis: e.target.value})}
                            />
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-sm font-bold text-slate-700">Jenis Kelamin <span className="text-red-500">*</span></label>
                            <select 
                                required
                                className="w-full rounded-lg border-slate-200 focus:ring-2 focus:ring-primary focus:border-transparent text-sm font-bold text-slate-900 bg-white"
                                value={formData.gender}
                                onChange={(e) => setFormData({...formData, gender: e.target.value})}
                            >
                                <option value="L">Laki-laki</option>
                                <option value="P">Perempuan</option>
                            </select>
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-bold text-slate-700">Kelas <span className="text-red-500">*</span></label>
                            <select 
                                required
                                className="w-full rounded-lg border-slate-200 focus:ring-2 focus:ring-primary focus:border-transparent text-sm font-bold text-slate-900 bg-white"
                                value={formData.className}
                                onChange={(e) => setFormData({...formData, className: e.target.value})}
                            >
                                <option value="">-- Pilih Kelas --</option>
                                {classes.map(c => (
                                    <option key={c.id} value={c.name}>{c.name}</option>
                                ))}
                            </select>
                        </div>
                      </div>

                      <div className="pt-4 flex gap-3">
                          <button 
                              type="button" 
                              onClick={() => setIsModalOpen(false)}
                              className="flex-1 py-2.5 border border-slate-200 rounded-lg text-sm font-bold text-slate-600 hover:bg-slate-50"
                          >
                              Batal
                          </button>
                          <button 
                              type="submit" 
                              className="flex-1 py-2.5 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 shadow-md shadow-blue-200"
                          >
                              {editingId ? 'Update Siswa' : 'Simpan Siswa'}
                          </button>
                      </div>
                  </form>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { SystemBlueprint } from './components/SystemBlueprint';
import { GradingSheet } from './components/GradingSheet';
import { AttendanceSheet } from './components/AttendanceSheet';
import { Dashboard } from './components/Dashboard';
import { IdentityForm } from './components/IdentityForm';
import { CurriculumManager } from './components/CurriculumManager';
import { ClassManager } from './components/ClassManager';
import { StudentManager } from './components/StudentManager';
import { ScheduleManager } from './components/ScheduleManager';
import { CPGenerator } from './components/CPGenerator';
import { RecapManager } from './components/RecapManager';
import { TabView, Student, LearningObjective, Subject, IdentityData, ScheduleItem, AttendanceData, ClassInfo, GradeData } from './types';

declare const Swal: any;

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 1000 * 60 * 5, 
      refetchOnWindowFocus: false,
    },
  },
});

// INITIAL DATA - RESET TO ZERO (CLEAN SLATE)
const INITIAL_IDENTITY: IdentityData = {
    role: 'SUBJECT_TEACHER', // Default
    level: 'SMA', // Default Level
    schoolName: 'Nama Sekolah',
    teacherName: 'Nama Guru',
    nip: '',
    subjectName: 'Mata Pelajaran',
    semester: 'Genap',
    academicYear: '2025/2026',
    className: '',
    studentCount: 0
};

const NavItem = ({ active, label, icon, onClick }: any) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-3 px-3 py-2.5 rounded-lg transition-colors w-full text-left ${active ? 'bg-primary text-white shadow-md' : 'text-slate-600 hover:bg-slate-100'}`}
  >
    <span className="material-symbols-outlined text-[20px]">{icon}</span>
    <p className="text-sm font-semibold">{label}</p>
  </button>
);

export default function App() {
  const [activeTab, setActiveTab] = useState<TabView>(TabView.DASHBOARD);

  // GLOBAL STATE - MASTER DATA
  const [identity, setIdentity] = useState<IdentityData>(INITIAL_IDENTITY);
  const [students, setStudents] = useState<Student[]>([]); // START EMPTY
  const [classes, setClasses] = useState<ClassInfo[]>([]); // START EMPTY
  const [schedules, setSchedules] = useState<ScheduleItem[]>([]); // START EMPTY
  const [tps, setTps] = useState<LearningObjective[]>([]); // START EMPTY
  const [subject, setSubject] = useState<Subject>({ id: 's1', name: identity.subjectName, kktp: 75 });

  // GLOBAL STATE - TRANSACTIONAL DATA
  const [attendanceData, setAttendanceData] = useState<AttendanceData>({});
  const [gradeData, setGradeData] = useState<GradeData>({}); // Lifted Grade Data

  // Update student count in Identity when student list changes
  useEffect(() => {
    setIdentity(prev => ({ ...prev, studentCount: students.length }));
  }, [students.length]);

  // Context State for Navigation (Passing data from Dashboard to Sheets)
  const [navContext, setNavContext] = useState<{ className?: string, scheduleId?: string }>({});

  const handleIdentitySave = (newData: IdentityData) => {
      setIdentity(newData);
      setSubject(prev => ({...prev, name: newData.subjectName}));
  };

  const handleSaveGeneratedTPs = (newTPs: LearningObjective[]) => {
      const existingCount = tps.length;
      const formattedTPs = newTPs.map((tp, idx) => ({
          ...tp,
          code: `TP.${existingCount + idx + 1}`,
          lms: [],
          criteria: [],
          scopeId: identity.role === 'CLASS_TEACHER' ? 'math' : 'lvl-7' 
      }));
      setTps([...tps, ...formattedTPs]);
      setActiveTab(TabView.CURRICULUM);
  };

  // Enhanced Navigation Handler
  const handleContextNavigate = (tab: TabView, context?: { className?: string, scheduleId?: string }) => {
    if (context) {
      setNavContext(context);
    } else {
      setNavContext({}); // Reset if no context provided
    }
    setActiveTab(tab);
  };

  const handleLogout = () => {
    Swal.fire({
      title: 'Keluar Aplikasi?',
      text: "Sesi anda akan diakhiri.",
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#137fec',
      cancelButtonColor: '#d33',
      confirmButtonText: 'Ya, Keluar',
      cancelButtonText: 'Batal'
    }).then((result: any) => {
      if (result.isConfirmed) {
        window.location.reload(); 
      }
    });
  };

  return (
    <QueryClientProvider client={queryClient}>
      <div className="flex min-h-screen">
        {/* Sidebar */}
        <aside className="w-64 border-r border-slate-200 bg-white flex flex-col h-screen sticky top-0 z-50">
          <div className="p-6">
            <div className="flex items-center gap-3 mb-8">
              <div className="bg-primary size-10 rounded-lg flex items-center justify-center text-white shadow-lg shadow-blue-200">
                <span className="material-symbols-outlined">auto_stories</span>
              </div>
              <div>
                <h1 className="text-slate-900 text-base font-bold leading-tight">SiGuru</h1>
                <p className="text-slate-500 text-[10px] font-normal mt-0.5">Aplikasi Administrasi Guru</p>
              </div>
            </div>

            <div className="flex flex-col gap-1">
              <NavItem active={activeTab === TabView.DASHBOARD} label="Dashboard" icon="dashboard" onClick={() => handleContextNavigate(TabView.DASHBOARD)} />
              <div className="my-2 border-t border-slate-100"></div>

              <p className="px-3 text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2">Master Data</p>
              <NavItem active={activeTab === TabView.CLASS_MASTER} label="Master Kelas" icon="school" onClick={() => handleContextNavigate(TabView.CLASS_MASTER)} />
              <NavItem active={activeTab === TabView.STUDENT_MASTER} label="Master Siswa" icon="group" onClick={() => handleContextNavigate(TabView.STUDENT_MASTER)} />
              <NavItem active={activeTab === TabView.SCHEDULE_MASTER} label="Master Jadwal" icon="calendar_month" onClick={() => handleContextNavigate(TabView.SCHEDULE_MASTER)} />

              {/* SWAPPED ORDER: CP Generator (AI) first, then Curriculum */}
              <NavItem active={activeTab === TabView.CP_GENERATOR} label="Generate TP (AI)" icon="psychology" onClick={() => handleContextNavigate(TabView.CP_GENERATOR)} />
              <NavItem active={activeTab === TabView.CURRICULUM} label="Kurikulum" icon="book" onClick={() => handleContextNavigate(TabView.CURRICULUM)} />

              <div className="my-2 border-t border-slate-100"></div>

              <p className="px-3 text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2">Akademik</p>
              {/* REORDERED: Input Grades -> Recap Grades -> Attendance -> Recap Attendance */}
              <NavItem active={activeTab === TabView.GRADING} label="Input Nilai" icon="assignment_turned_in" onClick={() => handleContextNavigate(TabView.GRADING)} />
              <NavItem active={activeTab === TabView.RECAP_GRADES} label="Rekap Nilai" icon="grade" onClick={() => handleContextNavigate(TabView.RECAP_GRADES)} />
              <NavItem active={activeTab === TabView.ATTENDANCE} label="Presensi" icon="how_to_reg" onClick={() => handleContextNavigate(TabView.ATTENDANCE)} />
              <NavItem active={activeTab === TabView.RECAP_ATTENDANCE} label="Rekap Presensi" icon="fact_check" onClick={() => handleContextNavigate(TabView.RECAP_ATTENDANCE)} />

              <div className="my-2 border-t border-slate-100"></div>
              <p className="px-3 text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2">System</p>
              <NavItem active={activeTab === TabView.BLUEPRINT} label="Dokumentasi" icon="description" onClick={() => handleContextNavigate(TabView.BLUEPRINT)} />
              <NavItem active={activeTab === TabView.IDENTITY} label="Pengaturan" icon="settings" onClick={() => handleContextNavigate(TabView.IDENTITY)} />
            </div>
          </div>

          <div className="mt-auto p-6 flex flex-col gap-1 border-t border-slate-200">
            <div className="flex items-center gap-3 px-3 py-2 bg-slate-50 rounded-xl border border-slate-100">
              <div className="size-10 rounded-full bg-slate-200 flex items-center justify-center text-slate-500 font-bold border-2 border-white shadow-sm">
                {identity.teacherName.charAt(0)}
              </div>
              <div className="flex flex-col overflow-hidden">
                <p className="text-slate-900 text-sm font-bold truncate">{identity.teacherName}</p>
                <p className="text-slate-500 text-[10px] truncate">NIP: {identity.nip || '-'}</p>
              </div>
            </div>
          </div>
        </aside>

        {/* Main Content */}
        <main className="flex-1 flex flex-col h-screen overflow-hidden">
          {/* Top Navbar */}
          <header className="flex items-center justify-end border-b border-slate-200 bg-white px-8 py-3 sticky top-0 z-40 h-[72px]">
             {/* Logout Button */}
             <button 
                onClick={handleLogout}
                className="flex items-center gap-2 px-4 py-2 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors text-sm font-bold"
             >
                <span className="material-symbols-outlined">logout</span>
                Logout
             </button>
          </header>

          {/* Scrollable Content Area */}
          <div className="flex-1 overflow-y-auto bg-background-light p-8">
            {activeTab === TabView.DASHBOARD && (
              <Dashboard 
                onNavigate={handleContextNavigate} 
                identity={identity} 
                schedules={schedules}
                classes={classes}
                students={students}
                attendanceData={attendanceData}
                gradeData={gradeData}
                subject={subject}
              />
            )}

            {activeTab === TabView.IDENTITY && (
                <IdentityForm 
                  data={identity} 
                  onSave={handleIdentitySave} 
                  onBack={() => handleContextNavigate(TabView.DASHBOARD)} 
                />
            )}

            {activeTab === TabView.CURRICULUM && (
                <CurriculumManager 
                  identity={identity}
                  subject={subject}
                  tps={tps}
                  onUpdateSubject={(kktp) => setSubject(prev => ({...prev, kktp}))}
                  onUpdateTPs={setTps}
                  onBack={() => handleContextNavigate(TabView.DASHBOARD)}
                />
            )}

            {activeTab === TabView.CP_GENERATOR && (
                <CPGenerator 
                    onSave={handleSaveGeneratedTPs}
                    onBack={() => handleContextNavigate(TabView.DASHBOARD)}
                />
            )}

            {activeTab === TabView.CLASS_MASTER && (
                <ClassManager 
                    identity={identity}
                    classes={classes}
                    onUpdateClasses={setClasses}
                    onBack={() => handleContextNavigate(TabView.DASHBOARD)} 
                />
            )}

            {activeTab === TabView.STUDENT_MASTER && (
                <StudentManager 
                    students={students}
                    classes={classes}
                    onUpdateStudents={setStudents}
                    onBack={() => handleContextNavigate(TabView.DASHBOARD)} 
                />
            )}

            {activeTab === TabView.SCHEDULE_MASTER && (
                <ScheduleManager 
                    schedules={schedules} 
                    onUpdateSchedules={setSchedules}
                    onBack={() => handleContextNavigate(TabView.DASHBOARD)} 
                />
            )}

            {activeTab === TabView.BLUEPRINT && <SystemBlueprint />}

            {activeTab === TabView.GRADING && (
                <GradingSheet 
                  students={students}
                  tps={tps}
                  subject={subject}
                  initialClass={navContext.className}
                  globalGradeData={gradeData}
                  setGlobalGradeData={setGradeData}
                />
            )}

            {activeTab === TabView.ATTENDANCE && (
                <AttendanceSheet 
                  students={students}
                  subject={subject}
                  schedules={schedules}
                  initialClass={navContext.className}
                  initialScheduleId={navContext.scheduleId}
                  globalAttendance={attendanceData}
                  setGlobalAttendance={setAttendanceData}
                />
            )}

            {(activeTab === TabView.RECAP_GRADES || activeTab === TabView.RECAP_ATTENDANCE) && (
                <RecapManager 
                  students={students}
                  subject={subject}
                  identity={identity}
                  mode={activeTab === TabView.RECAP_GRADES ? 'GRADES' : 'ATTENDANCE'}
                  globalAttendance={attendanceData}
                />
            )}
          </div>
        </main>
      </div>
    </QueryClientProvider>
  );
}

import React, { useState } from 'react';
import { Student, ClassInfo } from '../types';

declare const Swal: any;

interface Props {
  students: Student[];
  classes: ClassInfo[];
  onUpdateStudents: (students: Student[]) => void;
  onBack: () => void;
}

// Helper for Title Case
const toTitleCase = (str: string) => {
    return str.toLowerCase().replace(/\b\w/g, s => s.toUpperCase());
};

export const StudentManager: React.FC<Props> = ({ students, classes, onUpdateStudents, onBack }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Default Form Data
  const [formData, setFormData] = useState({
      name: '',
      nis: '',
      gender: 'L',
      className: '',
      status: 'Aktif'
  });

  const handleOpenModal = (student?: Student) => {
      if (student) {
          setEditingId(student.id);
          setFormData({
              name: student.name,
              nis: student.nis,
              gender: 'L', // Assuming L default if property missing in basic type
              className: student.className || '',
              status: 'Aktif'
          });
      } else {
          setEditingId(null);
          // Set default class if available
          const defaultClass = classes.length > 0 ? classes[0].name : '';
          setFormData({ name: '', nis: '', gender: 'L', className: defaultClass, status: 'Aktif' });
      }
      setIsModalOpen(true);
  };

  const handleSaveStudent = (e: React.FormEvent) => {
      e.preventDefault();

      // VALIDATION: Check for empty fields
      if (!formData.name.trim() || !formData.nis.trim() || !formData.className || !formData.gender) {
          Swal.fire({
              title: 'Gagal Menyimpan',
              text: "Semua kolom (Nama, NIS, Jenis Kelamin, Kelas) wajib diisi!",
              icon: 'error',
              confirmButtonColor: '#d33',
              confirmButtonText: 'OK'
          });
          return;
      }

      // AUTO-CAPITALIZE NAME
      const formattedName = toTitleCase(formData.name);

      if (editingId) {
          // Update
          const updatedStudents = students.map(s => s.id === editingId ? { ...s, ...formData, name: formattedName } : s);
          onUpdateStudents(updatedStudents);
      } else {
          // Add
          const newStudent: Student = {
              id: Date.now().toString(),
              name: formattedName,
              nis: formData.nis,
              className: formData.className,
              // status and gender are managed in this form state but Student interface might need extension in real app
              // For now we map to existing simple Student interface
          };
          onUpdateStudents([newStudent, ...students]);
      }
      setIsModalOpen(false);

      // Success Feedback
      Swal.fire({
          title: 'Berhasil!',
          text: 'Data siswa telah disimpan.',
          icon: 'success',
          timer: 1500,
          showConfirmButton: false
      });
  };

  const handleDeleteStudent = (id: string) => {
      Swal.fire({
          title: 'Hapus Siswa?',
