import React, { useState } from 'react';
import { User } from '../types';

declare const Swal: any;

interface Props {
  users: User[];
  onAddUser: (email: string, name: string) => void;
  onDeleteUser: (id: string) => void;
  onUpdateUser: (id: string, name: string) => void;
  onGoToApp: () => void;
  onLogout: () => void;
}

export const AdminPanel: React.FC<Props> = ({ users, onAddUser, onDeleteUser, onUpdateUser, onGoToApp, onLogout }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);

  const [formData, setFormData] = useState({ email: '', name: '' });

  const handleOpenModal = (user?: User) => {
    if (user) {
      setEditingUser(user);
      setFormData({ email: user.email, name: user.name });
    } else {
      setEditingUser(null);
      setFormData({ email: '', name: '' });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser) {
      onUpdateUser(editingUser.id, formData.name);
    } else {
      onAddUser(formData.email.toLowerCase(), formData.name);
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => {
    Swal.fire({
      title: 'Hapus Pengguna?',
      text: "Data administrasi pengguna ini akan hilang permanen!",
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      confirmButtonText: 'Hapus',
      cancelButtonText: 'Batal'
    }).then((result: any) => {
      if (result.isConfirmed) {
        onDeleteUser(id);
        Swal.fire('Terhapus!', 'Pengguna berhasil dihapus.', 'success');
      }
    });
  };

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col font-sans">
      {/* Navbar */}
      <nav className="bg-slate-900 text-white px-8 py-4 flex justify-between items-center shadow-lg">
        <div className="flex items-center gap-3">
           <div className="bg-blue-600 p-2 rounded-lg">
             <span className="material-symbols-outlined">admin_panel_settings</span>
           </div>
           <div>
             <h1 className="font-bold text-lg leading-tight">Admin Panel</h1>
             <p className="text-xs text-slate-400">Manajemen Pengguna SiGuru</p>
           </div>
        </div>
        <div className="flex items-center gap-4">
           <button 
             onClick={onGoToApp}
             className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-500 rounded-lg text-sm font-bold transition-colors"
           >
             <span className="material-symbols-outlined text-sm">open_in_new</span>
             Buka Aplikasi
           </button>
           <button 
             onClick={onLogout}
             className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-red-600 rounded-lg text-sm font-bold transition-colors"
           >
             <span className="material-symbols-outlined text-sm">logout</span>
             Keluar
           </button>
        </div>
      </nav>

      {/* Content */}
      <div className="flex-1 p-8 max-w-6xl mx-auto w-full">
         <div className="flex justify-between items-end mb-6">
            <div>
              <h2 className="text-2xl font-bold text-slate-800">Daftar Pengguna</h2>
              <p className="text-slate-500">Kelola akses guru ke dalam aplikasi.</p>
            </div>
            <button 
              onClick={() => handleOpenModal()}
              className="flex items-center gap-2 px-5 py-3 bg-slate-900 text-white rounded-xl text-sm font-bold hover:bg-slate-800 shadow-lg"
            >
              <span className="material-symbols-outlined text-sm">person_add</span>
              Tambah Pengguna
            </button>
         </div>

         <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <table className="w-full text-left">
               <thead className="bg-slate-50 border-b border-slate-200">
                  <tr>
                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Nama Guru</th>
                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Email Login</th>
                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Role</th>
                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase">Status</th>
                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-right">Aksi</th>
                  </tr>
               </thead>
               <tbody className="divide-y divide-slate-100">
                  {users.map(user => (
                    <tr key={user.id} className="hover:bg-slate-50 transition-colors">
                       <td className="px-6 py-4 font-bold text-slate-800">{user.name}</td>
                       <td className="px-6 py-4 text-sm text-slate-600">{user.email}</td>
                       <td className="px-6 py-4">
                          <span className={`text-[10px] font-bold px-2 py-1 rounded border ${user.role === 'ADMIN' ? 'bg-purple-50 text-purple-700 border-purple-200' : 'bg-blue-50 text-blue-700 border-blue-200'}`}>
                             {user.role}
                          </span>
                       </td>
                       <td className="px-6 py-4">
                          <span className="flex items-center gap-1.5 text-xs font-bold text-green-600 bg-green-50 px-2 py-1 rounded-full w-fit">
                             <span className="size-1.5 rounded-full bg-green-500"></span> Aktif
                          </span>
                       </td>
                       <td className="px-6 py-4 text-right">
                          {user.role !== 'ADMIN' && (
                            <div className="flex justify-end gap-2">
                                <button onClick={() => handleOpenModal(user)} className="p-2 text-blue-600 hover:bg-blue-50 rounded">
                                  <span className="material-symbols-outlined text-sm">edit</span>
                                </button>
                                <button onClick={() => handleDelete(user.id)} className="p-2 text-red-600 hover:bg-red-50 rounded">
                                  <span className="material-symbols-outlined text-sm">delete</span>
                                </button>
                            </div>
                          )}
                       </td>
                    </tr>
                  ))}
               </tbody>
            </table>
            {users.length === 0 && (
              <div className="p-10 text-center text-slate-400">Belum ada pengguna.</div>
            )}
         </div>
      </div>

      {/* Modal */}
      {isModalOpen && (
         <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-md overflow-hidden">
               <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                  <h3 className="font-bold text-slate-900">{editingUser ? 'Edit Pengguna' : 'Tambah Pengguna Baru'}</h3>
                  <button onClick={() => setIsModalOpen(false)}><span className="material-symbols-outlined text-slate-400">close</span></button>
               </div>
               <form onSubmit={handleSubmit} className="p-6 space-y-4">
                  <div className="space-y-2">
                     <label className="text-sm font-bold text-slate-700">Email Login <span className="text-red-500">*</span></label>
                     <input 
                        type="email" 
                        required 
                        disabled={!!editingUser}
                        className="w-full border-slate-200 rounded-lg text-sm font-medium disabled:bg-slate-100 disabled:text-slate-500"
                        placeholder="email@sekolah.id"
                        value={formData.email}
                        onChange={e => setFormData({...formData, email: e.target.value})}
                     />
                     {editingUser && <p className="text-[10px] text-slate-400">Email tidak dapat diubah.</p>}
                  </div>
                  <div className="space-y-2">
                     <label className="text-sm font-bold text-slate-700">Nama Guru <span className="text-red-500">*</span></label>
                     <input 
                        type="text" 
                        required 
                        className="w-full border-slate-200 rounded-lg text-sm font-medium"
                        placeholder="Nama Lengkap"
                        value={formData.name}
                        onChange={e => setFormData({...formData, name: e.target.value})}
                     />
                  </div>
                  <div className="pt-4 flex gap-3">
                     <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-2.5 border border-slate-200 rounded-lg text-sm font-bold text-slate-600 hover:bg-slate-50">Batal</button>
                     <button type="submit" className="flex-1 py-2.5 bg-slate-900 text-white rounded-lg text-sm font-bold hover:bg-slate-800">Simpan</button>
                  </div>
               </form>
            </div>
         </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { SystemBlueprint } from './components/SystemBlueprint';
import { GradingSheet } from './components/GradingSheet';
import { AttendanceSheet } from './components/AttendanceSheet';
import { Dashboard } from './components/Dashboard';
import { IdentityForm } from './components/IdentityForm';
import { CurriculumManager } from './components/CurriculumManager';
import { ClassManager } from './components/ClassManager';
import { StudentManager } from './components/StudentManager';
import { ScheduleManager } from './components/ScheduleManager';
import { CPGenerator } from './components/CPGenerator';
import { RecapManager } from './components/RecapManager';
import { LoginPage } from './components/LoginPage';
import { AdminPanel } from './components/AdminPanel';
import { 
  TabView, Student, LearningObjective, Subject, IdentityData, 
  ScheduleItem, AttendanceData, ClassInfo, GradeData, User, UserStorageData 
} from './types';

declare const Swal: any;

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 1000 * 60 * 5, 
      refetchOnWindowFocus: false,
    },
  },
});

// INITIAL DATA TEMPLATE (New User gets this)
const INITIAL_IDENTITY: IdentityData = {
    role: 'SUBJECT_TEACHER', 
    level: 'SMA', 
    schoolName: 'Nama Sekolah',
    teacherName: 'Nama Guru',
    nip: '',
    subjectName: 'Mata Pelajaran',
    semester: 'Genap',
    academicYear: '2025/2026',
    className: '',
    studentCount: 0
};

const DEFAULT_USERS: User[] = [
  { id: 'admin', email: 'admin@siguru.com', name: 'Super Admin', role: 'ADMIN', isActive: true },
  { id: 'guru1', email: 'guru@sekolah.id', name: 'Guru Contoh', role: 'USER', isActive: true }
];

const NavItem = ({ active, label, icon, onClick }: any) => (
  <button
    onClick={onClick}
    className={`flex items-center gap-3 px-3 py-2.5 rounded-lg transition-colors w-full text-left ${active ? 'bg-primary text-white shadow-md' : 'text-slate-600 hover:bg-slate-100'}`}
  >
    <span className="material-symbols-outlined text-[20px]">{icon}</span>
    <p className="text-sm font-semibold">{label}</p>
  </button>
);

export default function App() {
  // --- AUTH STATE ---
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [dbUsers, setDbUsers] = useState<User[]>([]);
  const [isLoadingAuth, setIsLoadingAuth] = useState(false);

  // --- VIEW STATE ---
  const [activeTab, setActiveTab] = useState<TabView>(TabView.LOGIN);

  // --- APP DATA STATE (Per User) ---
  const [identity, setIdentity] = useState<IdentityData>(INITIAL_IDENTITY);
  const [students, setStudents] = useState<Student[]>([]); 
  const [classes, setClasses] = useState<ClassInfo[]>([]); 
  const [schedules, setSchedules] = useState<ScheduleItem[]>([]); 
  const [tps, setTps] = useState<LearningObjective[]>([]); 
  const [subject, setSubject] = useState<Subject>({ id: 's1', name: 'Mata Pelajaran', kktp: 75 });
  const [attendanceData, setAttendanceData] = useState<AttendanceData>({});
  const [gradeData, setGradeData] = useState<GradeData>({}); 

  // Context State for Navigation
  const [navContext, setNavContext] = useState<{ className?: string, scheduleId?: string }>({});

  // =================================================================================
  // 1. INITIALIZATION & "DATABASE" (LocalStorage) LOADING
  // =================================================================================
  useEffect(() => {
    // Load User DB
    const savedUsers = localStorage.getItem('siguru_users');
    if (savedUsers) {
      setDbUsers(JSON.parse(savedUsers));
    } else {
      // Initialize Default Users if empty
      localStorage.setItem('siguru_users', JSON.stringify(DEFAULT_USERS));
      setDbUsers(DEFAULT_USERS);
    }
  }, []);

  // Update student count in Identity
  useEffect(() => {
    setIdentity(prev => ({ ...prev, studentCount: students.length }));
  }, [students.length]);

  // =================================================================================
  // 2. PERSISTENCE LAYER (Save Logic)
  // =================================================================================

  // Function to save current state to LocalStorage under the current user's email key
  const saveDataToStorage = useCallback(() => {
    if (!currentUser) return;

    // Admin doesn't necessarily save app data unless they are in "App View" mode acting as themselves
    // But we save it anyway for consistency
    const storageKey = `siguru_data_${currentUser.email}`;

    const payload: UserStorageData = {
      identity,
      students,
      classes,
      schedules,
      tps,
      subject,
      attendanceData,
      gradeData
    };

    localStorage.setItem(storageKey, JSON.stringify(payload));
  }, [currentUser, identity, students, classes, schedules, tps, subject, attendanceData, gradeData]);

  // Auto-save on any data change (Debounced slightly by React batching, but we use Effect here)
  useEffect(() => {
    if (currentUser && activeTab !== TabView.LOGIN && activeTab !== TabView.ADMIN_PANEL) {
      const timeout = setTimeout(saveDataToStorage, 500); // Debounce save
      return () => clearTimeout(timeout);
    }
  }, [saveDataToStorage, currentUser, activeTab]);


  // =================================================================================
  // 3. AUTHENTICATION HANDLERS
  // =================================================================================

  const handleLogin = (email: string) => {
    setIsLoadingAuth(true);

    // Simulate API delay
    setTimeout(() => {
      const user = dbUsers.find(u => u.email === email && u.isActive);

      if (user) {
        setCurrentUser(user);

        // Load Data specific to this user
        const storageKey = `siguru_data_${user.email}`;
        const savedDataStr = localStorage.getItem(storageKey);

        if (savedDataStr) {
          const data: UserStorageData = JSON.parse(savedDataStr);
          setIdentity(data.identity);
          setStudents(data.students);
          setClasses(data.classes);
          setSchedules(data.schedules);
          setTps(data.tps);
          setSubject(data.subject);
          setAttendanceData(data.attendanceData);
          setGradeData(data.gradeData);
        } else {
          // New User? Reset to defaults
          setIdentity({...INITIAL_IDENTITY, teacherName: user.name});
          setStudents([]);
          setClasses([]);
          setSchedules([]);
          setTps([]);
          setSubject({ id: 's1', name: INITIAL_IDENTITY.subjectName, kktp: 75 });
          setAttendanceData({});
          setGradeData({});
        }

        // Redirect based on Role
        if (user.role === 'ADMIN') {
          setActiveTab(TabView.ADMIN_PANEL);
        } else {
          setActiveTab(TabView.DASHBOARD);
        }

      } else {
        Swal.fire({
          title: 'Login Gagal',
          text: 'Email tidak ditemukan atau tidak aktif.',
          icon: 'error'
        });
      }
      setIsLoadingAuth(false);
    }, 800);
  };

  const handleLogout = () => {
    Swal.fire({
      title: 'Keluar Aplikasi?',
      icon: 'question',
      showCancelButton: true,
      confirmButtonText: 'Ya, Keluar',
      cancelButtonText: 'Batal'
    }).then((result: any) => {
      if (result.isConfirmed) {
        saveDataToStorage(); // Ensure save before exit
        setCurrentUser(null);
        setActiveTab(TabView.LOGIN);
      }
    });
  };

  // =================================================================================
  // 4. ADMIN HANDLERS
  // =================================================================================

  const handleAddUser = (email: string, name: string) => {
     if (dbUsers.some(u => u.email === email)) {
       Swal.fire('Error', 'Email sudah terdaftar!', 'error');
       return;
     }
     const newUser: User = {
       id: Date.now().toString(),
       email,
       name,
       role: 'USER',
       isActive: true
     };
     const updatedUsers = [...dbUsers, newUser];
     setDbUsers(updatedUsers);
     localStorage.setItem('siguru_users', JSON.stringify(updatedUsers));
     Swal.fire('Sukses', 'Pengguna berhasil ditambahkan', 'success');
  };

  const handleDeleteUser = (id: string) => {
    const updatedUsers = dbUsers.filter(u => u.id !== id);
    setDbUsers(updatedUsers);
    localStorage.setItem('siguru_users', JSON.stringify(updatedUsers));
  };

  const handleUpdateUser = (id: string, name: string) => {
     const updatedUsers = dbUsers.map(u => u.id === id ? {...u, name} : u);
     setDbUsers(updatedUsers);
     localStorage.setItem('siguru_users', JSON.stringify(updatedUsers));
  };


  // =================================================================================
  // 5. APP LOGIC HANDLERS (Wrappers to update State)
  // =================================================================================

  const handleIdentitySave = (newData: IdentityData) => {
      setIdentity(newData);
      setSubject(prev => ({...prev, name: newData.subjectName}));
  };

  const handleSaveGeneratedTPs = (newTPs: LearningObjective[]) => {
      const existingCount = tps.length;
      const formattedTPs = newTPs.map((tp, idx) => ({
          ...tp,
          code: `TP.${existingCount + idx + 1}`,
          lms: [],
          criteria: [],
          scopeId: identity.role === 'CLASS_TEACHER' ? 'math' : 'lvl-7' 
      }));
      setTps([...tps, ...formattedTPs]);
      setActiveTab(TabView.CURRICULUM);
  };

  const handleContextNavigate = (tab: TabView, context?: { className?: string, scheduleId?: string }) => {
    if (context) setNavContext(context);
    else setNavContext({});
    setActiveTab(tab);
  };

  // =================================================================================
  // RENDER
  // =================================================================================

  if (activeTab === TabView.LOGIN) {
    return <LoginPage onLogin={handleLogin} isLoading={isLoadingAuth} />;
  }

  if (activeTab === TabView.ADMIN_PANEL && currentUser?.role === 'ADMIN') {
    return (
      <AdminPanel 
        users={dbUsers} 
        onAddUser={handleAddUser}
        onDeleteUser={handleDeleteUser}
        onUpdateUser={handleUpdateUser}
        onGoToApp={() => setActiveTab(TabView.DASHBOARD)}
        onLogout={handleLogout}
      />
    );
  }

  return (
    <QueryClientProvider client={queryClient}>
      <div className="flex min-h-screen font-sans">
        {/* Sidebar */}
        <aside className="w-64 border-r border-slate-200 bg-white flex flex-col h-screen sticky top-0 z-50 shadow-sm">
          {/* Sidebar Header (Fixed) */}
          <div className="p-6 pb-2">
            <div className="flex items-center gap-3 mb-6">
              <div className="bg-primary size-10 rounded-lg flex items-center justify-center text-white shadow-lg shadow-blue-200">
                <span className="material-symbols-outlined">auto_stories</span>
              </div>
              <div>
                <h1 className="text-slate-900 text-base font-bold leading-tight">SiGuru</h1>
                <p className="text-slate-500 text-[10px] font-normal mt-0.5">App Admin Guru</p>
              </div>
            </div>
          </div>

          {/* Sidebar Menu (Scrollable) */}
          <div className="flex-1 overflow-y-auto px-6 pb-4 custom-scrollbar">
            <div className="flex flex-col gap-1">
              <NavItem active={activeTab === TabView.DASHBOARD} label="Dashboard" icon="dashboard" onClick={() => handleContextNavigate(TabView.DASHBOARD)} />
              <div className="my-2 border-t border-slate-100"></div>

              <p className="px-3 text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2 mt-2">Master Data</p>
              <NavItem active={activeTab === TabView.CLASS_MASTER} label="Master Kelas" icon="school" onClick={() => handleContextNavigate(TabView.CLASS_MASTER)} />
              <NavItem active={activeTab === TabView.STUDENT_MASTER} label="Master Siswa" icon="group" onClick={() => handleContextNavigate(TabView.STUDENT_MASTER)} />
              <NavItem active={activeTab === TabView.SCHEDULE_MASTER} label="Master Jadwal" icon="calendar_month" onClick={() => handleContextNavigate(TabView.SCHEDULE_MASTER)} />

              <NavItem active={activeTab === TabView.CP_GENERATOR} label="Generate TP (AI)" icon="psychology" onClick={() => handleContextNavigate(TabView.CP_GENERATOR)} />
              <NavItem active={activeTab === TabView.CURRICULUM} label="Kurikulum" icon="book" onClick={() => handleContextNavigate(TabView.CURRICULUM)} />

              <div className="my-2 border-t border-slate-100"></div>

              <p className="px-3 text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2 mt-2">Akademik</p>
              <NavItem active={activeTab === TabView.GRADING} label="Input Nilai" icon="assignment_turned_in" onClick={() => handleContextNavigate(TabView.GRADING)} />
              <NavItem active={activeTab === TabView.RECAP_GRADES} label="Rekap Nilai" icon="grade" onClick={() => handleContextNavigate(TabView.RECAP_GRADES)} />
              <NavItem active={activeTab === TabView.ATTENDANCE} label="Presensi" icon="how_to_reg" onClick={() => handleContextNavigate(TabView.ATTENDANCE)} />
              <NavItem active={activeTab === TabView.RECAP_ATTENDANCE} label="Rekap Presensi" icon="fact_check" onClick={() => handleContextNavigate(TabView.RECAP_ATTENDANCE)} />

              <div className="my-2 border-t border-slate-100"></div>
              <p className="px-3 text-[10px] font-bold text-slate-400 uppercase tracking-wider mb-2 mt-2">System</p>
              <NavItem active={activeTab === TabView.BLUEPRINT} label="Dokumentasi" icon="description" onClick={() => handleContextNavigate(TabView.BLUEPRINT)} />
              <NavItem active={activeTab === TabView.IDENTITY} label="Pengaturan" icon="settings" onClick={() => handleContextNavigate(TabView.IDENTITY)} />
            </div>
          </div>

          {/* Sidebar Footer (Fixed) */}
          <div className="p-6 flex flex-col gap-1 border-t border-slate-200 bg-white z-10">
            <div className="flex items-center gap-3 px-3 py-2 bg-slate-50 rounded-xl border border-slate-100">
              <div className="size-10 rounded-full bg-slate-200 flex items-center justify-center text-slate-500 font-bold border-2 border-white shadow-sm shrink-0">
                {identity.teacherName.charAt(0)}
              </div>
              <div className="flex flex-col overflow-hidden">
                <p className="text-slate-900 text-sm font-bold truncate">{identity.teacherName}</p>
                <p className="text-slate-500 text-[10px] truncate">{currentUser?.email}</p>
              </div>
            </div>
          </div>
        </aside>

        {/* Main Content */}
        <main className="flex-1 flex flex-col h-screen overflow-hidden">
          {/* Top Navbar */}
          <header className="flex items-center justify-between border-b border-slate-200 bg-white px-8 py-3 sticky top-0 z-40 h-[72px] shadow-sm">
             <div className="flex items-center gap-2 text-slate-500 text-sm">
               {currentUser?.role === 'ADMIN' && (
                 <button onClick={() => setActiveTab(TabView.ADMIN_PANEL)} className="flex items-center gap-1 hover:text-primary font-bold bg-slate-100 px-3 py-1 rounded-lg">
                    <span className="material-symbols-outlined text-sm">arrow_back</span>
                    Kembali ke Admin
                 </button>
               )}
             </div>

             {/* Logout Button */}
             <button 
                onClick={handleLogout}
                className="flex items-center gap-2 px-4 py-2 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors text-sm font-bold"
             >
                <span className="material-symbols-outlined">logout</span>
                Logout
             </button>
          </header>

          {/* Scrollable Content Area */}
          <div className="flex-1 overflow-y-auto bg-background-light custom-scrollbar flex flex-col">
            <div className="flex-1 p-8">
                {activeTab === TabView.DASHBOARD && (
                <Dashboard 
                    onNavigate={handleContextNavigate} 
                    identity={identity} 
                    schedules={schedules}
                    classes={classes}
                    students={students}
                    attendanceData={attendanceData}
                    gradeData={gradeData}
                    subject={subject}
                />
                )}

                {activeTab === TabView.IDENTITY && (
                    <IdentityForm 
                    data={identity} 
                    onSave={handleIdentitySave} 
                    onBack={() => handleContextNavigate(TabView.DASHBOARD)} 
                    />
                )}

                {activeTab === TabView.CURRICULUM && (
                    <CurriculumManager 
                    identity={identity}
                    subject={subject}
                    tps={tps}
                    onUpdateSubject={(kktp) => setSubject(prev => ({...prev, kktp}))}
                    onUpdateTPs={setTps}
                    onBack={() => handleContextNavigate(TabView.DASHBOARD)}
                    />
                )}

                {activeTab === TabView.CP_GENERATOR && (
                    <CPGenerator 
                        onSave={handleSaveGeneratedTPs}
                        onBack={() => handleContextNavigate(TabView.DASHBOARD)}
                    />
                )}

                {activeTab === TabView.CLASS_MASTER && (
                    <ClassManager 
                        identity={identity}
                        classes={classes}
                        onUpdateClasses={setClasses}
                        onBack={() => handleContextNavigate(TabView.DASHBOARD)} 
                    />
                )}

                {activeTab === TabView.STUDENT_MASTER && (
                    <StudentManager 
                        students={students}
                        classes={classes}
                        onUpdateStudents={setStudents}
                        onBack={() => handleContextNavigate(TabView.DASHBOARD)} 
                    />
                )}

                {activeTab === TabView.SCHEDULE_MASTER && (
                    <ScheduleManager 
                        schedules={schedules} 
                        onUpdateSchedules={setSchedules}
                        onBack={() => handleContextNavigate(TabView.DASHBOARD)} 
                    />
                )}

                {activeTab === TabView.BLUEPRINT && <SystemBlueprint />}

                {activeTab === TabView.GRADING && (
                    <GradingSheet 
                    students={students}
                    tps={tps}
                    subject={subject}
                    initialClass={navContext.className}
                    globalGradeData={gradeData}
                    setGlobalGradeData={setGradeData}
                    />
                )}

                {activeTab === TabView.ATTENDANCE && (
                    <AttendanceSheet 
                    students={students}
                    subject={subject}
                    schedules={schedules}
                    initialClass={navContext.className}
                    initialScheduleId={navContext.scheduleId}
                    globalAttendance={attendanceData}
                    setGlobalAttendance={setAttendanceData}
                    />
                )}

                {(activeTab === TabView.RECAP_GRADES || activeTab === TabView.RECAP_ATTENDANCE) && (
                    <RecapManager 
                    students={students}
                    subject={subject}
                    identity={identity}
                    mode={activeTab === TabView.RECAP_GRADES ? 'GRADES' : 'ATTENDANCE'}
                    globalAttendance={attendanceData}
                    />
                )}
            </div>

            {/* Application Footer */}
            <footer className="py-6 text-center border-t border-slate-200/60 mt-auto bg-background-light">
                <p className="text-xs font-bold text-slate-400">
                    SiGuru - Aplikasi Administrasi Guru  <span className="mx-1 text-slate-300">|</span>  Copyright 2026
                </p>
            </footer>
          </div>
        </main>
      </div>
    </QueryClientProvider>
  );
}

