<content><![CDATA[
import React, { useState, useEffect, useCallback, Suspense } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { supabase } from './utils/supabase'; // Import Supabase Client
import { GradingSheet } from './components/GradingSheet';
import LoginPage from './components/LoginPage';
import './App.css';
import { createClient } from '@supabase/supabase-js';
import { useNavigate } from 'react-router-dom';
import Swal from 'sweetalert2';
import withReactContent from 'sweetalert2-react-content';
import { useQuery } from '@tanstack/react-query';


const queryClient = new QueryClient();
const MySwal = withReactContent(Swal);

const CPGenerator = React.lazy(() => import('./components/CPGenerator').then(module => ({ default: module.CPGenerator })));

function App() {
  const [session, setSession] = useState(null);
  const [isLoadingAuth, setIsLoadingAuth] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    async function getSession() {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        setSession(session);
      } catch (error) {
        console.error('Error getting session:', error);
        MySwal.fire({
          title: 'Error',
          text: 'There was an error while trying to get your session. Please try again.',
          icon: 'error',
          confirmButtonText: 'OK',
        });
      } finally {
        setIsLoadingAuth(false);
      }
    }

    getSession();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      setIsLoadingAuth(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  const handleSignOut = useCallback(async () => {
    try {
      const { error } = await supabase.auth.signOut();
      if (error) {
        MySwal.fire({
          title: 'Error',
          text: 'There was an error while signing out. Please try again.',
          icon: 'error',
          confirmButtonText: 'OK',
        });
      } else {
        MySwal.fire({
          title: 'Success',
          text: 'You have been signed out.',
          icon: 'success',
          confirmButtonText: 'OK',
        });
        navigate('/');
      }
    } catch (error) {
      console.error('Sign out error:', error);
      MySwal.fire({
        title: 'Error',
        text: 'There was an error while signing out. Please try again.',
        icon: 'error',
        confirmButtonText: 'OK',
      });
    }
  }, [navigate]);

  if (isLoadingAuth) {
    return (
      <div className="App">
        <header className="App-header">
          <p>Loading...</p>
        </header>
      </div>
    );
  }

  return (
    <QueryClientProvider client={queryClient}>
      <div className="App">
        <header className="App-header">
          {session ? (
            <div>
              <p>Signed in!</p>
              <button onClick={handleSignOut}>Sign out</button>
              <Suspense fallback={<p>Loading CPGenerator...</p>}>
                <CPGenerator />
              </Suspense>
            </div>
          ) : (
            <LoginPage />
          )}
        </header>
      </div>
    </QueryClientProvider>
  );
}

export default App;
]]></content>
