    if (error) {
        Swal.fire({
            title: 'Gagal Masuk',
            text: error.message,
            icon: 'error'
        });
        setIsLoadingAuth(false);
    } 
    // Success handled by onAuthStateChange
  };

  const handleRegister = async (data: RegisterData) => {
    setIsLoadingAuth(true);

    if (!isSupabaseConfigured) {
      setTimeout(() => {
          const mockUser = {
              id: 'demo-user-' + Date.now(),
              email: data.email,
              user_metadata: { 
                full_name: data.name, 
                role: data.role, 
                level: data.level 
              }
          };
          handleUserRestored(mockUser);
          Swal.fire({
              title: 'Mode Demo', 
              text: 'Registrasi berhasil (Mode Demo).', 
              icon: 'success',
              timer: 1500,
              showConfirmButton: false
          });
      }, 1000);
      return;
    }

    const { error } = await supabase.auth.signUp({
      email: data.email,
      password: data.password,
      options: {
        data: {
          full_name: data.name,
          role: data.role,
          level: data.level
        }
      }
    });

    if (error) {
      Swal.fire({
        title: 'Registrasi Gagal',
        text: error.message,
        icon: 'error'
      });
      setIsLoadingAuth(false);
    } else {
      Swal.fire({
        title: 'Registrasi Berhasil',
        text: 'Akun Anda telah dibuat. Silahkan login jika tidak diarahkan otomatis.',
        icon: 'success'
      });
      // Auth state change will handle the rest
    }
  };

  const handleLogout = async () => {
    Swal.fire({
      title: 'Keluar Aplikasi?',
      icon: 'question',
      showCancelButton: true,
      confirmButtonText: 'Ya, Keluar',
      cancelButtonText: 'Batal'
    }).then(async (result: any) => {
      if (result.isConfirmed) {
        saveDataToStorage(); // Ensure app data is saved one last time

        if (isSupabaseConfigured) {
            await supabase.auth.signOut(); // Triggers SIGNED_OUT event -> resetAppState()
        } else {
            resetAppState(); // Manual reset for Demo Mode
        }
      }
    });
