                    students={students}
                    subject={subject}
                    schedules={schedules}
                    initialClass={navContext.className}
                    initialScheduleId={navContext.scheduleId}
                    globalAttendance={attendanceData}
                    setGlobalAttendance={setAttendanceData}
                    />
                )}

                {(activeTab === TabView.RECAP_GRADES || activeTab === TabView.RECAP_ATTENDANCE) && (
                    <RecapManager 
                    students={students}
                    subject={subject}
                    identity={identity}
                    mode={activeTab === TabView.RECAP_GRADES ? 'GRADES' : 'ATTENDANCE'}
                    globalAttendance={attendanceData}
                    />
                )}
            </div>

            {/* Application Footer */}
            <footer className="py-6 text-center border-t border-slate-200/60 mt-auto bg-background-light">
                <p className="text-xs font-bold text-slate-400">
                    SiGuru - Aplikasi Administrasi Guru  <span className="mx-1 text-slate-300">|</span>  Copyright 2026
                </p>
            </footer>
          </div>
        </main>
      </div>
    </QueryClientProvider>
  );
}

import React, { useState } from 'react';
import { TeacherRole, SchoolLevel } from '../types';

declare const Swal: any;

// Interfaces for form data
export interface LoginData {
  email: string;
  password: string;
}

export interface RegisterData {
  email: string;
  password: string;
  name: string;
  role: TeacherRole;
  level: SchoolLevel;
}

interface Props {
  onLogin: (data: LoginData) => Promise<void>;
  onRegister: (data: RegisterData) => Promise<void>;
  isLoading?: boolean;
}

type AuthMode = 'LOGIN' | 'REGISTER';

// Helper for Title Case
const toTitleCase = (str: string) => {
    return str.toLowerCase().replace(/\b\w/g, s => s.toUpperCase());
};

export const LoginPage: React.FC<Props> = ({ onLogin, onRegister, isLoading }) => {
  const [mode, setMode] = useState<AuthMode>('LOGIN');
  const [showPassword, setShowPassword] = useState(false);

  // Login State
  const [loginForm, setLoginForm] = useState<LoginData>({ email: '', password: '' });

  // Register State
  const [registerForm, setRegisterForm] = useState<RegisterData>({
      email: '',
      password: '',
      name: '',
      role: 'SUBJECT_TEACHER', // Default
      level: 'SMA' // Default fallback
  });

  const handleLoginSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (loginForm.email && loginForm.password) {
      await onLogin(loginForm);
    }
  };

  const handleRegisterSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (registerForm.email && registerForm.password && registerForm.name) {
      // Validate Password Length
      if (registerForm.password.length < 6) {
          Swal.fire('Error', 'Password minimal 6 karakter.', 'error');
          return;
      }
      await onRegister(registerForm);
    }
  };

  return (
    <div className="min-h-screen bg-background-light flex flex-col justify-center items-center p-4 relative overflow-hidden font-sans">
       {/* Background Decoration */}
       <div className="absolute top-0 left-0 w-full h-full overflow-hidden -z-10">
