import { createClient } from '@supabase/supabase-js';

// PENTING: Akses environment variable harus EKSPLISIT.
// Bundler (Vite/Webpack) mengganti string "import.meta.env.VITE_..." secara statis saat build.
// Akses dinamis seperti process.env[key] seringkali tidak bekerja di sisi client.

const getSupabaseUrl = () => {
  // Cek Vite (import.meta.env)
  // Casting import.meta to any to resolve TS error Property 'env' does not exist on type 'ImportMeta'
  const meta = import.meta as any;
  if (typeof meta !== 'undefined' && meta.env && meta.env.VITE_SUPABASE_URL) {
    return meta.env.VITE_SUPABASE_URL;
  }
  // Cek Standard Process (Node/Webpack)
  if (typeof process !== 'undefined' && process.env && process.env.VITE_SUPABASE_URL) {
    return process.env.VITE_SUPABASE_URL;
  }
  return '';
};

const getSupabaseAnonKey = () => {
  // Cek Vite
  // Casting import.meta to any to resolve TS error Property 'env' does not exist on type 'ImportMeta'
  const meta = import.meta as any;
  if (typeof meta !== 'undefined' && meta.env && meta.env.VITE_SUPABASE_ANON_KEY) {
    return meta.env.VITE_SUPABASE_ANON_KEY;
  }
  // Cek Standard Process
  if (typeof process !== 'undefined' && process.env && process.env.VITE_SUPABASE_ANON_KEY) {
    return process.env.VITE_SUPABASE_ANON_KEY;
  }
  return '';
};

const supabaseUrl = getSupabaseUrl();
const supabaseAnonKey = getSupabaseAnonKey();

// Validasi konfigurasi
export const isSupabaseConfigured = !!supabaseUrl && !!supabaseAnonKey && supabaseUrl !== 'https://placeholder.supabase.co';

if (!isSupabaseConfigured) {
  console.warn("Konfigurasi Supabase Hilang. Pastikan VITE_SUPABASE_URL dan VITE_SUPABASE_ANON_KEY sudah diset di Environment Variables.");
}

// Inisialisasi Client
export const supabase = createClient(
  supabaseUrl || 'https://placeholder.supabase.co', 
  supabaseAnonKey || 'placeholder'
);

import { createClient } from '@supabase/supabase-js';

// ------------------------------------------------------------------
// KONFIGURASI ENVIRONMENT VARIABLES
// ------------------------------------------------------------------
// PENTING: Akses harus ditulis eksplisit (import.meta.env.NAMA_VAR)
// agar Vite dapat melakukan 'static replacement' saat build.
// Jangan membungkusnya dalam objek dinamis atau casting yang kompleks.

let url = '';
let key = '';

// 1. Coba ambil dari Vite (import.meta.env)
try {
  // @ts-ignore - Mengabaikan error TS agar bundler tetap bisa membaca syntax ini
  if (typeof import.meta !== 'undefined' && import.meta.env) {
    // @ts-ignore
    url = import.meta.env.VITE_SUPABASE_URL || '';
    // @ts-ignore
    key = import.meta.env.VITE_SUPABASE_ANON_KEY || '';
  }
} catch (e) {
  // Hiraukan jika import.meta tidak didukung
}

// 2. Fallback ke Process Env (Node.js / Webpack standar) jika Vite kosong
if (!url || !key) {
  try {
    if (typeof process !== 'undefined' && process.env) {
      url = url || process.env.VITE_SUPABASE_URL || '';
      key = key || process.env.VITE_SUPABASE_ANON_KEY || '';
    }
  } catch (e) {
    // Hiraukan error process
  }
}

// ------------------------------------------------------------------
// VALIDASI & INISIALISASI
// ------------------------------------------------------------------

export const isSupabaseConfigured = !!url && !!key && url !== 'https://placeholder.supabase.co';

if (!isSupabaseConfigured) {
  console.error("CRITICAL: Supabase Configuration Missing!");
  console.log("Debug URL:", url ? "Set (Hidden)" : "Empty");
  console.log("Debug Key:", key ? "Set (Hidden)" : "Empty");
  console.warn("Tips: Jika di Vercel, pastikan sudah 'Redeploy' setelah menambah Environment Variables.");
}

export const supabase = createClient(
  url || 'https://placeholder.supabase.co', 
  key || 'placeholder'
);

