  email: string;
  password: string;
  name: string;
  role: TeacherRole;
  level: SchoolLevel;
}

interface Props {
  onLogin: (data: LoginData) => Promise<void>;
  onRegister: (data: RegisterData) => Promise<void>;
  onDemoLogin?: () => void;
  isLoading?: boolean;
  isConfigured?: boolean;
}

type AuthMode = 'LOGIN' | 'REGISTER';

