            text: 'URL Supabase atau Anon Key belum diset di file .env. Sistem tidak dapat menghubungi database.', 
            icon: 'error'
        });
        setIsLoadingAuth(false);
        return;
    }

    try {
        const { error } = await supabase.auth.signInWithPassword({
            email: data.email,
            password: data.password
        });

        if (error) {
            // Tampilkan error jika login gagal.
            let errorMsg = error.message;
            let errorTitle = 'Gagal Masuk';

            if (error.message.includes("Invalid login credentials")) {
                errorTitle = "Akun Tidak Ditemukan / Password Salah";
                errorMsg = "Mohon cek ejaan email dan password Anda. \n\nJika Anda baru mendaftar, pastikan email sudah diverifikasi (Cek Inbox/Spam) atau Admin sudah mematikan fitur 'Confirm Email' di Supabase.";
            } else if (error.message.toLowerCase().includes("email not confirmed")) {
                errorTitle = "Email Belum Dikonfirmasi";
                errorMsg = "Silakan cek inbox email Anda untuk verifikasi, ATAU nonaktifkan fitur 'Confirm Email' di Supabase Dashboard (Auth > Providers > Email).";
            } else if (error.message.toLowerCase().includes("failed to fetch")) {
                errorTitle = "Koneksi Bermasalah";
                errorMsg = "Gagal menghubungi server database. \n\nKemungkinan penyebab:\n1. Project Supabase Sedang 'Paused' (Cek Dashboard)\n2. Koneksi Internet Terputus\n3. Adblocker memblokir akses database.";
            }

            Swal.fire({
                title: errorTitle,
                text: errorMsg,
                icon: 'error'
            });
            setIsLoadingAuth(false);
        }
    } catch (err: any) {
         // Fallback catch for unexpected failures
         console.error("Login Error:", err);
         Swal.fire({
            title: 'Error Sistem',
            text: 'Terjadi kesalahan jaringan yang tidak terduga.',
            icon: 'error'
        });
        setIsLoadingAuth(false);
    }
    // Success handled by onAuthStateChange
  };

  const handleRegister = async (data: RegisterData) => {
    setIsLoadingAuth(true);

    if (!isSupabaseConfigured) {
        Swal.fire({
            title: 'Konfigurasi Hilang', 
            text: 'URL Supabase atau Anon Key belum diset. Tidak dapat mendaftarkan akun.', 
            icon: 'error'
        });
        setIsLoadingAuth(false);
        return;
    }

    try {
        const { error } = await supabase.auth.signUp({
            email: data.email,
            password: data.password,
            options: {
                data: {
                full_name: data.name,
                role: data.role,
                level: data.level
                }
            }
        });

        if (error) {
            Swal.fire({
                title: 'Registrasi Gagal',
                text: error.message.includes("Failed to fetch") 
                    ? "Koneksi ke database gagal. Pastikan project Supabase aktif (tidak paused)." 
                    : error.message,
                icon: 'error'
            });
            setIsLoadingAuth(false);
        } else {
            // SUCCESS REGISTRATION FEEDBACK
            Swal.fire({
                title: 'Registrasi Berhasil!',
                html: `
                <div class="text-left text-sm text-slate-600">
                    <p class="mb-3">Akun Anda telah dibuat. Langkah selanjutnya:</p>
                    <div class="bg-blue-50 p-4 rounded-lg border border-blue-100 text-blue-900">
                    <p class="font-bold flex items-center gap-2 mb-2">
                        <span class="material-symbols-outlined text-sm">mark_email_unread</span>
