```typescript
// src/modules/grading/GradingService.ts
import { GradeRepository } from './GradingRepository';
import { calculateFinalScore } from '../../shared/utils/GradeCalculator';

export class GradingService {
  constructor(private gradeRepo: GradeRepository) {}

  async inputGradesBulk(grades: GradeInput[]) {
    // 1. Validasi input (0-100)
    grades.forEach(g => {
        if (g.score < 0 || g.score > 100) throw new Error("Invalid score");
    });

    // 2. Simpan ke DB via Repository
    return await this.gradeRepo.upsertMany(grades);
  }

  async getClassRecap(classId: string, subjectId: string) {
    const rawGrades = await this.gradeRepo.findByClass(classId, subjectId);

    // Grouping by student
    const recap = rawGrades.map(student => {
      // Panggil fungsi kalkulasi terpisah (Clean Code)
      const calculation = calculateFinalScore({
        formatifScores: student.formatif_scores,
        sumatifScores: student.sumatif_scores,
        attitudeScore: student.attitude_score
      });

      return {
        student: student.name,
        ...calculation
      };
    });

    return recap;
  }
}
```

**Controller (HTTP Handler):**
