### 7. Fungsi Perhitungan Nilai (Core Logic)

Fungsi ini harus **MURNI (Pure Function)**, tidak bergantung pada database atau request, agar mudah di-unit test.

```typescript
// src/shared/utils/GradeCalculator.ts

interface ScoreInput {
  formatifScores: number[]; // Array nilai TP
  sumatifScores: number[];  // Array nilai LM
  attitudeScore: number;    // Nilai Sikap tunggal
}

export const calculateFinalScore = (input: ScoreInput) => {
  const { formatifScores, sumatifScores, attitudeScore } = input;

  // 1. Hitung Rata-rata Formatif (TP)
  const avgFormatif = formatifScores.length > 0 
    ? formatifScores.reduce((a, b) => a + b, 0) / formatifScores.length 
    : 0;

  // 2. Hitung Rata-rata Sumatif (LM)
  const avgSumatif = sumatifScores.length > 0
    ? sumatifScores.reduce((a, b) => a + b, 0) / sumatifScores.length
    : 0;

  // 3. Rumus Baku: (AVG Formatif * 0.4) + (AVG Sumatif * 0.5) + (Sikap * 0.1)
  const finalScore = (avgFormatif * 0.4) + (avgSumatif * 0.5) + (attitudeScore * 0.1);

  // Rounding 2 desimal
  return {
    avgFormatif: parseFloat(avgFormatif.toFixed(2)),
    avgSumatif: parseFloat(avgSumatif.toFixed(2)),
    finalScore: parseFloat(finalScore.toFixed(2)),
    status: finalScore >= 75 ? 'TUNTAS' : 'BELUM TUNTAS' // Asumsi KKTP 75
  };
};

/* 
   Contoh Test:
   formatif: [80, 90] -> Avg 85
   sumatif: [70, 80]  -> Avg 75
   sikap: 90

   Hitung: (85 * 0.4) + (75 * 0.5) + (90 * 0.1)
         = 34 + 37.5 + 9 
         = 80.5 (Tuntas)
*/

