import React, { useState, useEffect, useMemo } from 'react';
import { JournalEntry, LearningObjective, ScheduleItem, ClassInfo } from '../types';

declare const Swal: any;

interface Props {
  journals: JournalEntry[];
  onUpdateJournals: (journals: JournalEntry[]) => void;
  tps: LearningObjective[];
  schedules: ScheduleItem[];
  classes: ClassInfo[];
  initialContext?: { className?: string, scheduleId?: string };
  onBack: () => void;
}

export const JournalManager: React.FC<Props> = ({ 
    journals, onUpdateJournals, tps, schedules, classes, initialContext, onBack 
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Default Form Data
  const [formData, setFormData] = useState<Omit<JournalEntry, 'id' | 'created_at'>>({
      date: new Date().toISOString().split('T')[0],
      className: '',
      scheduleId: '',
      startTime: '',
      endTime: '',
      tpId: '',
      lmId: '',
      activity: '',
      reflection: '',
      followUp: ''
  });

  // Effect to handle navigation from Dashboard (Auto-fill)
  useEffect(() => {
    if (initialContext?.scheduleId && !isModalOpen) {
        const schedule = schedules.find(s => s.id === initialContext.scheduleId);
        if (schedule) {
            setFormData({
                date: new Date().toISOString().split('T')[0],
                className: schedule.className,
                scheduleId: schedule.id,
                startTime: schedule.startTime,
                endTime: schedule.endTime,
                tpId: '',
                lmId: '',
                activity: '',
                reflection: '',
                followUp: ''
            });
            setIsModalOpen(true);
        }
    }
  }, [initialContext, schedules]);

  // Handle Schedule Selection in Form to auto-fill time
  const handleScheduleChange = (scheduleId: string) => {
      const schedule = schedules.find(s => s.id === scheduleId);
      if (schedule) {
          setFormData(prev => ({
              ...prev,
              scheduleId: schedule.id,
              className: schedule.className,
              startTime: schedule.startTime,
              endTime: schedule.endTime
          }));
      } else {
          setFormData(prev => ({ ...prev, scheduleId: '' }));
      }
  };

  // Filtered Journals for Table
  const filteredJournals = useMemo(() => {
      return journals.filter(j => 
          j.activity.toLowerCase().includes(searchQuery.toLowerCase()) ||
          j.className.toLowerCase().includes(searchQuery.toLowerCase())
      ).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [journals, searchQuery]);

  // Derived Options
  const activeTP = useMemo(() => tps.find(tp => tp.id === formData.tpId), [formData.tpId, tps]);
  const availableLMs = activeTP ? activeTP.lms : [];

  const handleSave = (e: React.FormEvent) => {
      e.preventDefault();

      if (!formData.date || !formData.className || !formData.tpId || !formData.activity) {
          Swal.fire('Error', 'Tanggal, Kelas, TP, dan Kegiatan wajib diisi.', 'error');
          return;
      }

      if (editingId) {
          const updated = journals.map(j => j.id === editingId ? { ...j, ...formData } : j);
          onUpdateJournals(updated);
          Swal.fire('Berhasil', 'Jurnal berhasil diperbarui.', 'success');
      } else {
          const newEntry: JournalEntry = {
              id: Date.now().toString(),
              created_at: new Date().toISOString(),
              ...formData
          };
          onUpdateJournals([newEntry, ...journals]);
          Swal.fire('Berhasil', 'Jurnal baru berhasil disimpan.', 'success');
      }
      setIsModalOpen(false);
      setEditingId(null);
  };

  const handleEdit = (journal: JournalEntry) => {
      setEditingId(journal.id);
      setFormData({
          date: journal.date,
          className: journal.className,
          scheduleId: journal.scheduleId,
          startTime: journal.startTime,
          endTime: journal.endTime,
          tpId: journal.tpId,
          lmId: journal.lmId,
          activity: journal.activity,
          reflection: journal.reflection,
          followUp: journal.followUp
      });
      setIsModalOpen(true);
  };

  const handleDelete = (id: string) => {
      Swal.fire({
          title: 'Hapus Jurnal?',
          text: "Data yang dihapus tidak dapat dikembalikan.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          confirmButtonText: 'Ya, Hapus'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateJournals(journals.filter(j => j.id !== id));
              Swal.fire('Terhapus', 'Jurnal berhasil dihapus.', 'success');
          }
      });
  };

  const closeModal = () => {
      setIsModalOpen(false);
      setEditingId(null);
      // Reset form
      setFormData({
          date: new Date().toISOString().split('T')[0],
          className: '',
          scheduleId: '',
          startTime: '',
          endTime: '',
          tpId: '',
          lmId: '',
          activity: '',
          reflection: '',
          followUp: ''
      });
  };

  return (
    <div className="w-full max-w-7xl mx-auto pb-10">
       {/* Breadcrumbs */}
       <div className="flex items-center gap-2 mb-4 text-sm font-medium text-slate-500">
        <a onClick={onBack} className="hover:text-primary cursor-pointer">Dashboard</a>
        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <span className="text-slate-900 font-bold">Jurnal Guru</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <div className="flex flex-col gap-1">
          <h2 className="text-slate-900 text-3xl font-extrabold tracking-tight">Jurnal Mengajar</h2>
          <p className="text-slate-500 text-base font-normal">Catat aktivitas pembelajaran, refleksi, dan tindak lanjut harian.</p>
        </div>
        <button 
            onClick={() => setIsModalOpen(true)}
            className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 transition-colors shadow-lg shadow-blue-200"
        >
            <span className="material-symbols-outlined text-sm">edit_square</span>
            Isi Jurnal Baru
        </button>
      </div>

      {/* Toolbar */}
      <div className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm mb-6 flex justify-between items-center">
         <div className="relative">
             <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-400 text-lg">search</span>
             <input 
                type="text" 
                placeholder="Cari kegiatan atau kelas..." 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10 pr-4 py-2 border border-slate-200 rounded-lg text-sm font-bold text-slate-900 w-72 focus:ring-2 focus:ring-primary outline-none" 
             />
         </div>
         <div className="text-sm text-slate-500 font-bold">
             Total Entry: {journals.length}
         </div>
      </div>

      {/* Journal List */}
      <div className="space-y-4">
          {filteredJournals.length > 0 ? (
              filteredJournals.map(journal => {
                  const tp = tps.find(t => t.id === journal.tpId);
                  const lm = tp?.lms.find(l => l.id === journal.lmId);

                  return (
                      <div key={journal.id} className="bg-white border border-slate-200 rounded-xl p-6 shadow-sm hover:shadow-md transition-all">
                          <div className="flex justify-between items-start mb-4">
                              <div className="flex items-center gap-4">
                                  <div className="bg-blue-50 text-blue-700 px-3 py-2 rounded-lg text-center min-w-[80px]">
                                      <p className="text-xs font-bold uppercase">{new Date(journal.date).toLocaleDateString('id-ID', { month: 'short' })}</p>
                                      <p className="text-2xl font-black">{new Date(journal.date).getDate()}</p>
                                  </div>
                                  <div>
                                      <h3 className="text-lg font-bold text-slate-900">{journal.activity}</h3>
                                      <div className="flex items-center gap-3 text-sm text-slate-500 mt-1">
                                          <span className="flex items-center gap-1"><span className="material-symbols-outlined text-sm">schedule</span> {journal.startTime} - {journal.endTime}</span>
                                          <span className="flex items-center gap-1"><span className="material-symbols-outlined text-sm">school</span> {journal.className}</span>
                                      </div>
                                  </div>
                              </div>
                              <div className="flex gap-2">
                                  <button onClick={() => handleEdit(journal)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg"><span className="material-symbols-outlined">edit</span></button>
                                  <button onClick={() => handleDelete(journal.id)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg"><span className="material-symbols-outlined">delete</span></button>
                              </div>
                          </div>

                          <div className="bg-slate-50 p-4 rounded-lg text-sm space-y-2 mb-4 border border-slate-100">
                              <p className="flex gap-2">
                                  <span className="font-bold text-slate-700 w-24 shrink-0">TP:</span>
                                  <span className="text-slate-600">{tp?.code} - {tp?.description}</span>
                              </p>
                              {lm && (
                                  <p className="flex gap-2">
                                      <span className="font-bold text-slate-700 w-24 shrink-0">Materi (LM):</span>
                                      <span className="text-slate-600">{lm.title}</span>
                                  </p>
                              )}
                          </div>

                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                              <div>
                                  <h4 className="text-xs font-bold text-slate-400 uppercase mb-1">Refleksi</h4>
                                  <p className="text-sm text-slate-700 leading-relaxed">{journal.reflection || '-'}</p>
                              </div>
                              <div>
                                  <h4 className="text-xs font-bold text-slate-400 uppercase mb-1">Tindak Lanjut</h4>
                                  <p className="text-sm text-slate-700 leading-relaxed">{journal.followUp || '-'}</p>
                              </div>
                          </div>
                      </div>
                  );
              })
          ) : (
              <div className="flex flex-col items-center justify-center py-12 bg-slate-50 border border-dashed border-slate-300 rounded-xl text-slate-400">
                  <span className="material-symbols-outlined text-4xl mb-2">auto_stories</span>
                  <p className="text-sm font-medium">Belum ada jurnal yang dicatat.</p>
              </div>
          )}
      </div>

      {/* MODAL FORM */}
      {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 overflow-y-auto">
              <div className="bg-white rounded-2xl w-full max-w-3xl shadow-2xl my-8">
                  <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-2xl sticky top-0">
                      <h3 className="text-xl font-bold text-slate-900">{editingId ? 'Edit Jurnal' : 'Tambah Jurnal Baru'}</h3>
                      <button onClick={closeModal} className="text-slate-400 hover:text-red-500 transition-colors">
                          <span className="material-symbols-outlined">close</span>
                      </button>
                  </div>

                  <form onSubmit={handleSave} className="p-6 space-y-6">

                      {/* Section 1: Waktu & Kelas */}
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Tanggal</label>
                              <input 
                                type="date" required 
                                className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary"
                                value={formData.date}
                                onChange={e => setFormData({...formData, date: e.target.value})}
                              />
                          </div>
                          <div className="space-y-1 md:col-span-2">
                              <label className="text-xs font-bold text-slate-500 uppercase">Jadwal / Jam Mengajar</label>
                              <select 
                                className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary"
                                value={formData.scheduleId}
                                onChange={e => handleScheduleChange(e.target.value)}
                              >
                                  <option value="">-- Pilih Jadwal (Opsional) --</option>
                                  {schedules.map(s => (
                                      <option key={s.id} value={s.id}>{s.day} {s.startTime}-{s.endTime} | {s.className} | {s.subject}</option>
                                  ))}
                              </select>
                          </div>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                          <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Kelas <span className="text-red-500">*</span></label>
                                <select 
                                    required
                                    className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary"
                                    value={formData.className}
                                    onChange={e => setFormData({...formData, className: e.target.value})}
                                >
                                    <option value="">-- Pilih Kelas --</option>
                                    {classes.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                                </select>
                          </div>
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Jam Mulai</label>
                              <input type="time" className="w-full rounded-lg border-slate-200 text-sm font-bold" value={formData.startTime} onChange={e => setFormData({...formData, startTime: e.target.value})} />
                          </div>
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Jam Selesai</label>
                              <input type="time" className="w-full rounded-lg border-slate-200 text-sm font-bold" value={formData.endTime} onChange={e => setFormData({...formData, endTime: e.target.value})} />
                          </div>
                      </div>

                      {/* Section 2: Kurikulum */}
                      <div className="bg-slate-50 p-4 rounded-xl border border-slate-100 space-y-4">
                          <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Tujuan Pembelajaran (TP) <span className="text-red-500">*</span></label>
                                <select 
                                    required
                                    className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary"
                                    value={formData.tpId}
                                    onChange={e => setFormData({...formData, tpId: e.target.value, lmId: ''})}
                                >
                                    <option value="">-- Pilih TP --</option>
                                    {tps.map(tp => (
                                        <option key={tp.id} value={tp.id}>{tp.code} - {tp.description}</option>
                                    ))}
                                </select>
                          </div>
                          <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Lingkup Materi (LM)</label>
                                <select 
                                    className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary"
                                    value={formData.lmId}
                                    onChange={e => setFormData({...formData, lmId: e.target.value})}
                                    disabled={!formData.tpId}
                                >
                                    <option value="">-- Pilih Materi (Opsional) --</option>
                                    {availableLMs.map(lm => (
                                        <option key={lm.id} value={lm.id}>{lm.code} - {lm.title}</option>
                                    ))}
                                </select>
                          </div>
                      </div>

                      {/* Section 3: Refleksi */}
                      <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500 uppercase">Detail Kegiatan Pembelajaran <span className="text-red-500">*</span></label>
                          <textarea 
                             required
                             rows={3}
                             className="w-full rounded-lg border-slate-200 text-sm text-slate-900 focus:ring-primary"
                             placeholder="Deskripsikan aktivitas yang dilakukan..."
                             value={formData.activity}
                             onChange={e => setFormData({...formData, activity: e.target.value})}
                          />
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Refleksi Guru</label>
                              <textarea 
                                rows={3}
                                className="w-full rounded-lg border-slate-200 text-sm text-slate-900 focus:ring-primary"
                                placeholder="Apa yang berhasil? Apa yang perlu diperbaiki?"
                                value={formData.reflection}
                                onChange={e => setFormData({...formData, reflection: e.target.value})}
                                />
                          </div>
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Tindak Lanjut</label>
                              <textarea 
                                rows={3}
                                className="w-full rounded-lg border-slate-200 text-sm text-slate-900 focus:ring-primary"
                                placeholder="Rencana pertemuan selanjutnya..."
                                value={formData.followUp}
                                onChange={e => setFormData({...formData, followUp: e.target.value})}
                                />
                          </div>
                      </div>

                      <div className="pt-4 flex gap-3 border-t border-slate-100">
                          <button type="button" onClick={closeModal} className="flex-1 py-3 border border-slate-200 rounded-xl text-sm font-bold text-slate-600 hover:bg-slate-50">Batal</button>
                          <button type="submit" className="flex-1 py-3 bg-primary text-white rounded-xl text-sm font-bold hover:bg-blue-600 shadow-lg shadow-blue-200">Simpan Jurnal</button>
                      </div>
                  </form>
              </div>
          </div>
      )}

    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { TabView, IdentityData, ScheduleItem, ClassInfo, Student, AttendanceData, GradeData, Subject } from '../types';
import { calculateStudentGrade } from '../utils/grading';

interface Props {
  onNavigate: (tab: TabView, context?: { className?: string, scheduleId?: string }) => void;
  identity: IdentityData;
  schedules: ScheduleItem[];
  classes: ClassInfo[];
  students: Student[];
  attendanceData: AttendanceData;
  gradeData: GradeData;
  subject: Subject;
}

const StatCard = ({ title, value, subText, subColor, icon, bgIcon }: any) => (
  <div className="bg-white rounded-xl p-6 border border-slate-200 shadow-sm flex flex-col gap-2 relative overflow-hidden transition-all hover:shadow-md group">
    <div className="absolute right-0 top-0 opacity-5 transform translate-x-2 -translate-y-2 group-hover:scale-110 transition-transform">
         <span className="material-symbols-outlined text-9xl">{icon}</span>
    </div>
