                {identity.teacherName.charAt(0)}
              </div>
              {!isSidebarCollapsed && (
                <div className="flex flex-col overflow-hidden">
                  <p className="text-slate-900 text-sm font-bold truncate">{identity.teacherName}</p>
                  <p className="text-slate-500 text-sm truncate">{currentUser?.email}</p>
                </div>
              )}
            </div>
          </div>
        </aside>

        {/* Main Content */}
        <main className="flex-1 flex flex-col h-screen overflow-hidden">
          {/* Top Navbar */}
          <header className="flex items-center justify-between border-b border-slate-200 bg-white px-8 py-3 sticky top-0 z-40 h-[72px] shadow-sm">
             <div className="flex items-center gap-2 text-slate-500 text-sm">
               {currentUser?.role === 'ADMIN' && (
                 <button onClick={() => setActiveTab(TabView.ADMIN_PANEL)} className="flex items-center gap-1 hover:text-primary font-bold bg-slate-100 px-3 py-1 rounded-lg">
                    <span className="material-symbols-outlined text-sm">arrow_back</span>
                    Kembali ke Admin
                 </button>
               )}
             </div>

             {/* Logout Button */}
             <button 
                onClick={handleLogout}
                className="flex items-center gap-2 px-4 py-2 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors text-sm font-bold"
             >
                <span className="material-symbols-outlined">logout</span>
                Logout
             </button>
          </header>

          {/* Scrollable Content Area */}
          <div className="flex-1 overflow-y-auto bg-background-light custom-scrollbar flex flex-col">
            <div className="flex-1 p-8">
                {activeTab === TabView.DASHBOARD && (
                <Dashboard 
                    onNavigate={handleContextNavigate} 
                    identity={identity} 
                    schedules={schedules}
                    classes={classes}
                    students={students}
                    attendanceData={attendanceData}
                    gradeData={gradeData}
                    subject={subject}
                />
                )}

                {activeTab === TabView.IDENTITY && (
                    <IdentityForm 
                    data={identity} 
                    onSave={handleIdentitySave} 
                    onBack={() => handleContextNavigate(TabView.DASHBOARD)} 
                    />
                )}

                {activeTab === TabView.CURRICULUM && (
                    <CurriculumManager 
                    identity={identity}
                    subject={subject}
                    tps={tps}
                    onUpdateSubject={(kktp) => setSubject(prev => ({...prev, kktp}))}
                    onUpdateTPs={setTps}
                    onBack={() => handleContextNavigate(TabView.DASHBOARD)}
                    />
                )}

                {activeTab === TabView.CP_GENERATOR && (
                    <Suspense fallback={
                        <div className="flex items-center justify-center h-full p-12 text-slate-400">
                             <div className="flex flex-col items-center gap-2">
                                <span className="size-8 border-4 border-slate-200 border-t-primary rounded-full animate-spin"></span>
                                <span className="text-sm font-bold">Memuat Modul AI...</span>
                             </div>
                        </div>
                    }>
                        <CPGenerator 
                            onSave={handleSaveGeneratedTPs}
                            onBack={() => handleContextNavigate(TabView.DASHBOARD)}
                        />
                    </Suspense>
                )}

                {activeTab === TabView.CLASS_MASTER && (
                    <ClassManager 
                        identity={identity}
                        classes={classes}
                        students={students}
                        onUpdateClasses={setClasses}
                        onBack={() => handleContextNavigate(TabView.DASHBOARD)} 
                    />
                )}

                {activeTab === TabView.STUDENT_MASTER && (
                    <StudentManager 
                        students={students}
                        classes={classes}
                        onUpdateStudents={setStudents}
                        onBack={() => handleContextNavigate(TabView.DASHBOARD)} 
                    />
                )}

                {activeTab === TabView.SCHEDULE_MASTER && (
                    <ScheduleManager 
                        schedules={schedules} 
                        onUpdateSchedules={setSchedules}
                        onBack={() => handleContextNavigate(TabView.DASHBOARD)} 
                    />
                )}

                {activeTab === TabView.JOURNAL && (
                    <JournalManager 
                        journals={journals}
                        onUpdateJournals={setJournals}
                        tps={tps}
                        schedules={schedules}
                        classes={classes}
                        initialContext={navContext}
                        onBack={() => handleContextNavigate(TabView.DASHBOARD)}
                    />
                )}

                {activeTab === TabView.GRADING && (
                    <GradingSheet 
                    students={students}
                    tps={tps}
                    subject={subject}
                    initialClass={navContext.className}
                    globalGradeData={gradeData}
                    setGlobalGradeData={setGradeData}
                    />
                )}

                {activeTab === TabView.ATTENDANCE && (
                    <AttendanceSheet 
                    students={students}
                    subject={subject}
                    schedules={schedules}
                    initialClass={navContext.className}
                    initialScheduleId={navContext.scheduleId}
                    globalAttendance={attendanceData}
                    setGlobalAttendance={setAttendanceData}
                    />
                )}

                {(activeTab === TabView.RECAP_GRADES || activeTab === TabView.RECAP_ATTENDANCE) && (
                    <RecapManager 
                    students={students}
                    subject={subject}
                    identity={identity}
                    mode={activeTab === TabView.RECAP_GRADES ? 'GRADES' : 'ATTENDANCE'}
                    globalAttendance={attendanceData}
                    />
                )}
            </div>

            {/* Application Footer */}
            <footer className="py-6 text-center border-t border-slate-200/60 mt-auto bg-background-light">
                <p className="text-xs font-bold text-slate-400">
                    SiGuru - Aplikasi Administrasi Guru  <span className="mx-1 text-slate-300">|</span>  Copyright 2026
                </p>
            </footer>
          </div>
        </main>
      </div>
    </QueryClientProvider>
  );
}

import React, { useState, useMemo } from 'react';
import { User, SchoolLevel, TeacherRole } from '../types';
import { RegisterData } from './LoginPage'; // Re-use RegisterData type

declare const Swal: any;

interface Props {
  users: User[];
  onAddUser: (data: RegisterData) => void;
  onDeleteUser: (id: string) => void;
  onUpdateUser: (id: string, name: string) => void;
  onApproveUser: (id: string) => void; // New Prop
  onRejectUser: (id: string) => void; // New Prop
  onGoToApp: () => void;
  onLogout: () => void;
  waNumber: string;
  onUpdateWaNumber: (num: string) => void;
}

export const AdminPanel: React.FC<Props> = ({ 
    users, onAddUser, onDeleteUser, onUpdateUser, onApproveUser, onRejectUser,
    onGoToApp, onLogout, 
    waNumber, onUpdateWaNumber 
}) => {
  // User Management State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [userTab, setUserTab] = useState<'ACTIVE' | 'PENDING'>('ACTIVE'); // New Tab State

  // Settings State
  const [tempWaNumber, setTempWaNumber] = useState(waNumber);

  // Form Data for Add User
  const [formData, setFormData] = useState<RegisterData>({ 
      email: '', name: '', password: '', role: 'SUBJECT_TEACHER', level: 'SMA' 
  });

  // Statistics
  const stats = useMemo(() => {
    return {
      total: users.length,
      active: users.filter(u => u.isActive).length,
      pending: users.filter(u => !u.isActive).length,
      admins: users.filter(u => u.role === 'ADMIN').length,
      // Role Stats
      classTeachers: users.filter(u => u.role === 'CLASS_TEACHER' && u.isActive).length,
      subjectTeachers: users.filter(u => u.role === 'SUBJECT_TEACHER' && u.isActive).length,
      // Level Stats
      sd: users.filter(u => u.level === 'SD' && u.isActive).length,
      smp: users.filter(u => u.level === 'SMP' && u.isActive).length,
      sma: users.filter(u => u.level === 'SMA' && u.isActive).length,
      smk: users.filter(u => u.level === 'SMK' && u.isActive).length,
    };
  }, [users]);

  // Filtered Users based on Tab and Search
  const filteredUsers = useMemo(() => {
    const byTab = users.filter(u => userTab === 'ACTIVE' ? u.isActive : !u.isActive);

    return byTab.filter(u => 
      u.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
      u.email.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [users, searchQuery, userTab]);

  const handleOpenModal = (user?: User) => {
    if (user) {
      setEditingUser(user);
      // Untuk edit, kita hanya bisa ubah nama (mocking)
      setFormData({ 
          email: user.email, 
          name: user.name, 
          password: '', 
          role: user.role, 
          level: user.level || 'SMA' 
      });
    } else {
      setEditingUser(null);
      setFormData({ email: '', name: '', password: '', role: 'SUBJECT_TEACHER', level: 'SMA' });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser) {
      onUpdateUser(editingUser.id, formData.name);
    } else {
      // Validasi Basic
      if (!formData.email || !formData.password || !formData.name) {
          Swal.fire('Error', 'Semua kolom wajib diisi.', 'error');
          return;
      }
      onAddUser(formData);
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => {
    Swal.fire({
      title: 'Hapus Pengguna?',
      text: "Data administrasi pengguna ini akan hilang permanen!",
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      confirmButtonText: 'Hapus',
      cancelButtonText: 'Batal'
    }).then((result: any) => {
      if (result.isConfirmed) {
        onDeleteUser(id);
        Swal.fire('Terhapus!', 'Pengguna berhasil dihapus.', 'success');
      }
    });
  };

  const handleSaveSettings = () => {
      onUpdateWaNumber(tempWaNumber);
  };

  return (
    <div className="flex flex-col min-h-screen font-sans bg-slate-50">
      {/* Header Navigation */}
      <header className="bg-slate-900 text-white shadow-lg sticky top-0 z-50">
         <div className="max-w-7xl mx-auto px-6 h-[72px] flex items-center justify-between">
            <div className="flex items-center gap-3">
               <div className="bg-white/10 size-10 rounded-lg flex items-center justify-center text-white border border-white/20">
                  <span className="material-symbols-outlined">admin_panel_settings</span>
               </div>
               <div>
                  <h1 className="text-white text-base font-bold leading-tight">Admin Panel</h1>
                  <p className="text-slate-400 text-[10px] font-normal uppercase tracking-wider">Pusat Kontrol</p>
               </div>
            </div>

            <div className="flex items-center gap-4">
               <button 
                  onClick={onGoToApp}
                  className="flex items-center gap-2 px-4 py-2 rounded-lg text-white hover:bg-white/10 transition-colors text-sm font-bold border border-transparent hover:border-white/20"
               >
                  <span className="material-symbols-outlined text-[18px]">open_in_new</span>
                  Buka Aplikasi
               </button>
               <div className="h-6 w-px bg-white/20"></div>
               <button 
                  onClick={onLogout}
                  className="flex items-center gap-2 px-4 py-2 rounded-lg text-red-300 hover:bg-red-900/30 hover:text-red-200 transition-colors text-sm font-bold"
               >
                  <span className="material-symbols-outlined text-[18px]">logout</span>
                  Keluar
               </button>
            </div>
         </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto custom-scrollbar py-8 px-6">
         <div className="max-w-7xl mx-auto space-y-8">

            <div className="flex flex-col md:flex-row justify-between items-end gap-4">
                <div className="space-y-1">
                <h2 className="text-3xl font-extrabold text-slate-900 tracking-tight">Database Pengguna</h2>
                <p className="text-slate-500">Kelola akses guru dan statistik sistem secara real-time.</p>
                </div>
                <button 
                onClick={() => handleOpenModal()}
                className="flex items-center gap-2 px-5 py-3 bg-primary text-white rounded-xl text-sm font-bold hover:bg-blue-600 shadow-lg shadow-blue-200 transition-all active:scale-95"
                >
                <span className="material-symbols-outlined text-sm">person_add</span>
                Tambah Pengguna Manual
                </button>
            </div>

            {/* SETTINGS SECTION (WA) */}
            <div className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm">
                <h3 className="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2">
                    <span className="material-symbols-outlined text-green-600">chat</span>
                    Konfigurasi Kontak Bantuan (Lupa Password)
                </h3>
                <div className="flex items-end gap-4 max-w-xl">
                    <div className="flex-1 space-y-1">
                        <label className="text-xs font-bold text-slate-500 uppercase">Nomor WhatsApp Admin</label>
                        <div className="relative">
                            <span className="absolute left-3 top-2.5 text-slate-400 font-bold">+</span>
                            <input 
                                type="text"
                                value={tempWaNumber}
                                onChange={(e) => setTempWaNumber(e.target.value.replace(/[^0-9]/g, ''))}
                                className="w-full pl-6 pr-4 py-2 border border-slate-200 rounded-lg text-sm font-bold text-slate-900 focus:ring-2 focus:ring-green-500"
                                placeholder="628xxxxxxxx"
                            />
                        </div>
                        <p className="text-[10px] text-slate-400">Gunakan format internasional tanpa '+'. Contoh: 6282335454864</p>
                    </div>
                    <button 
                        onClick={handleSaveSettings}
                        className="px-4 py-2.5 bg-slate-900 text-white rounded-lg text-sm font-bold hover:bg-slate-700 transition-colors mb-5"
                    >
                        Simpan
                    </button>
                </div>
            </div>

            {/* STATISTICS DASHBOARD */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {/* Total Users */}
                <div className="bg-white border border-slate-200 p-6 rounded-2xl shadow-sm flex flex-col gap-2">
                    <div className="flex justify-between items-start">
                        <span className="text-xs text-slate-500 font-bold uppercase tracking-wider">Total User</span>
                        <div className="bg-blue-50 text-blue-600 p-2 rounded-lg"><span className="material-symbols-outlined">group</span></div>
                    </div>
                    <p className="text-3xl font-extrabold text-slate-900">{stats.total}</p>
                    <p className="text-xs text-slate-400">Semua akun (Aktif & Pending)</p>
                </div>

                {/* Pending Users Alert */}
                <div className={`bg-white border p-6 rounded-2xl shadow-sm flex flex-col gap-2 ${stats.pending > 0 ? 'border-orange-200 ring-2 ring-orange-100' : 'border-slate-200'}`}>
                    <div className="flex justify-between items-start">
                        <span className="text-xs text-slate-500 font-bold uppercase tracking-wider">Menunggu Verifikasi</span>
                        <div className="bg-orange-50 text-orange-600 p-2 rounded-lg"><span className="material-symbols-outlined">person_search</span></div>
                    </div>
                    <p className="text-3xl font-extrabold text-slate-900">{stats.pending}</p>
                    <p className="text-xs text-slate-400">Calon pengguna perlu persetujuan</p>
                </div>

                {/* Role Breakdown */}
                <div className="bg-white border border-slate-200 p-6 rounded-2xl shadow-sm flex flex-col gap-4">
                    <div className="flex justify-between items-start">
                         <span className="text-xs text-slate-500 font-bold uppercase tracking-wider">Guru Aktif</span>
                         <div className="bg-purple-50 text-purple-600 p-2 rounded-lg"><span className="material-symbols-outlined">badge</span></div>
                    </div>
                    <div className="space-y-2">
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-slate-600 font-medium">Guru Kelas</span>
                            <span className="font-bold text-slate-900 bg-slate-100 px-2 py-0.5 rounded">{stats.classTeachers}</span>
                        </div>
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-slate-600 font-medium">Guru Mapel</span>
                            <span className="font-bold text-slate-900 bg-slate-100 px-2 py-0.5 rounded">{stats.subjectTeachers}</span>
                        </div>
                    </div>
                </div>

                {/* Level Breakdown */}
                <div className="bg-white border border-slate-200 p-6 rounded-2xl shadow-sm flex flex-col gap-4">
                    <div className="flex justify-between items-start">
                         <span className="text-xs text-slate-500 font-bold uppercase tracking-wider">Distribusi Jenjang</span>
                         <div className="bg-green-50 text-green-600 p-2 rounded-lg"><span className="material-symbols-outlined">school</span></div>
                    </div>
                    <div className="grid grid-cols-2 gap-2 text-center">
                        <div className="bg-slate-50 rounded p-1">
                             <p className="text-lg font-bold text-slate-900">{stats.sd}</p>
                             <p className="text-[10px] font-bold text-slate-500">SD</p>
                        </div>
                        <div className="bg-slate-50 rounded p-1">
                             <p className="text-lg font-bold text-slate-900">{stats.smp}</p>
                             <p className="text-[10px] font-bold text-slate-500">SMP</p>
                        </div>
                        <div className="bg-slate-50 rounded p-1">
                             <p className="text-lg font-bold text-slate-900">{stats.sma}</p>
                             <p className="text-[10px] font-bold text-slate-500">SMA</p>
                        </div>
                        <div className="bg-slate-50 rounded p-1">
                             <p className="text-lg font-bold text-slate-900">{stats.smk}</p>
                             <p className="text-[10px] font-bold text-slate-500">SMK</p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Table Section */}
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="border-b border-slate-200">
                    <div className="flex px-6 pt-4 gap-6">
                        <button 
                            onClick={() => setUserTab('ACTIVE')}
                            className={`pb-4 text-sm font-bold transition-all border-b-2 ${userTab === 'ACTIVE' ? 'border-primary text-primary' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
                        >
                            Pengguna Aktif
                        </button>
                        <button 
                            onClick={() => setUserTab('PENDING')}
                            className={`pb-4 text-sm font-bold transition-all border-b-2 relative ${userTab === 'PENDING' ? 'border-orange-500 text-orange-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
                        >
                            Calon Pengguna
                            {stats.pending > 0 && <span className="ml-2 bg-orange-500 text-white text-[10px] px-2 py-0.5 rounded-full">{stats.pending}</span>}
                        </button>
                    </div>
                </div>

                <div className="p-4 border-b border-slate-200 bg-slate-50 flex items-center justify-between">
                    <h3 className="font-bold text-slate-700 ml-2">
                        {userTab === 'ACTIVE' ? 'Daftar Guru Terdaftar' : 'Permintaan Akses Baru'}
                    </h3>
                    <div className="relative w-full max-w-sm">
                        <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-400 text-lg">search</span>
                        <input 
                            type="text" 
                            placeholder="Cari nama atau email..." 
                            className="pl-10 pr-4 py-2 border border-slate-200 rounded-lg text-sm font-bold text-slate-900 w-full focus:ring-2 focus:ring-primary focus:border-transparent outline-none placeholder:text-slate-400 bg-white"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                    </div>
                </div>

                <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-white border-b border-slate-200">
                        <tr>
                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Nama Lengkap</th>
                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Email Login</th>
                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Role</th>
                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Jenjang</th>
                            <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">Aksi</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {filteredUsers.length > 0 ? (
                            filteredUsers.map(user => (
                            <tr key={user.id} className="hover:bg-slate-50 transition-colors group">
                                <td className="px-6 py-4 font-bold text-slate-800">{user.name}</td>
                                <td className="px-6 py-4 text-sm text-slate-600 font-medium">{user.email}</td>
                                <td className="px-6 py-4">
                                    <span className={`text-[10px] font-bold px-2.5 py-1 rounded-md border ${user.role === 'ADMIN' ? 'bg-purple-50 text-purple-700 border-purple-200' : 'bg-blue-50 text-blue-700 border-blue-200'}`}>
                                        {user.role}
                                    </span>
                                </td>
                                <td className="px-6 py-4">
                                     {user.role !== 'ADMIN' ? (
                                        <span className="text-xs font-bold bg-orange-50 text-orange-700 px-2 py-1 rounded border border-orange-100">
                                            {user.level || '-'}
                                        </span>
                                     ) : (
                                         <span className="text-xs text-slate-300">-</span>
                                     )}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    {/* Action Buttons Logic */}
                                    {user.role !== 'ADMIN' && (
                                        <div className="flex justify-end gap-2">
                                            {userTab === 'PENDING' ? (
                                                <>
                                                    <button onClick={() => onApproveUser(user.id)} className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white rounded-lg text-xs font-bold hover:bg-green-700 shadow-sm transition-colors" title="Terima User">
                                                        <span className="material-symbols-outlined text-sm">check</span>
                                                        Terima
                                                    </button>
                                                    <button onClick={() => onRejectUser(user.id)} className="flex items-center gap-1 px-3 py-1.5 bg-white border border-red-200 text-red-600 rounded-lg text-xs font-bold hover:bg-red-50 shadow-sm transition-colors" title="Tolak User">
                                                        <span className="material-symbols-outlined text-sm">close</span>
                                                        Tolak
                                                    </button>
                                                </>
                                            ) : (
                                                <div className="opacity-0 group-hover:opacity-100 transition-opacity flex gap-2">
                                                    <button onClick={() => handleOpenModal(user)} className="p-2 bg-white border border-slate-200 text-blue-600 hover:bg-blue-50 hover:border-blue-200 rounded-lg transition-colors shadow-sm" title="Edit">
                                                        <span className="material-symbols-outlined text-sm">edit</span>
                                                    </button>
                                                    <button onClick={() => handleDelete(user.id)} className="p-2 bg-white border border-slate-200 text-red-600 hover:bg-red-50 hover:border-red-200 rounded-lg transition-colors shadow-sm" title="Hapus">
                                                        <span className="material-symbols-outlined text-sm">delete</span>
                                                    </button>
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </td>
                            </tr>
                            ))
                        ) : (
                            <tr>
                            <td colSpan={5} className="p-12 text-center text-slate-400 italic">
                                {userTab === 'ACTIVE' 
                                    ? 'Tidak ada pengguna aktif yang ditemukan.' 
                                    : 'Tidak ada calon pengguna yang menunggu verifikasi.'}
                            </td>
                            </tr>
                        )}
                    </tbody>
                </table>
                </div>
            </div>
         </div>
      </main>

      {/* User Modal */}
      {isModalOpen && (
         <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden transform transition-all scale-100">
               <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                  <h3 className="text-xl font-bold text-slate-900">{editingUser ? 'Edit Pengguna' : 'Tambah Pengguna Baru'}</h3>
                  <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-red-500 transition-colors">
                      <span className="material-symbols-outlined">close</span>
                  </button>
               </div>
               <form onSubmit={handleSubmit} className="p-6 space-y-4">

                  {/* Nama */}
                  <div className="space-y-1">
                     <label className="text-xs font-bold text-slate-500 uppercase">Nama Lengkap <span className="text-red-500">*</span></label>
                     <input 
                        type="text" 
                        required 
                        className="w-full border-slate-200 rounded-lg text-sm font-bold text-slate-900 focus:ring-2 focus:ring-primary focus:border-transparent bg-white"
                        placeholder="Nama Guru"
                        value={formData.name}
                        onChange={e => setFormData({...formData, name: e.target.value})}
                     />
                  </div>

                  {/* Email */}
                  <div className="space-y-1">
                     <label className="text-xs font-bold text-slate-500 uppercase">Email Login <span className="text-red-500">*</span></label>
                     <input 
                        type="email" 
                        required 
                        disabled={!!editingUser}
                        className="w-full border-slate-200 rounded-lg text-sm font-bold text-slate-900 focus:ring-2 focus:ring-primary focus:border-transparent bg-white disabled:bg-slate-100 disabled:text-slate-500"
                        placeholder="contoh: guru@sekolah.id"
                        value={formData.email}
                        onChange={e => setFormData({...formData, email: e.target.value})}
                     />
                     {editingUser && <p className="text-[10px] text-slate-400 flex items-center gap-1"><span className="material-symbols-outlined text-[10px]">lock</span> Email tidak dapat diubah setelah dibuat.</p>}
                  </div>

                  {/* Password (Only for New Users) */}
                  {!editingUser && (
                     <div className="space-y-1">
                        <label className="text-xs font-bold text-slate-500 uppercase">Password <span className="text-red-500">*</span></label>
                        <input 
                           type="password" 
                           required 
                           className="w-full border-slate-200 rounded-lg text-sm font-bold text-slate-900 focus:ring-2 focus:ring-primary focus:border-transparent bg-white"
                           placeholder="••••••••"
                           value={formData.password}
                           onChange={e => setFormData({...formData, password: e.target.value})}
                        />
                     </div>
                  )}

                  {/* Role Selection */}
                  <div className="grid grid-cols-2 gap-3">
                     <div className="space-y-1">
                        <label className="text-xs font-bold text-slate-500 uppercase">Peran</label>
                        <select
                           className="w-full border-slate-200 rounded-lg text-xs font-bold text-slate-900 focus:ring-2 focus:ring-primary focus:border-transparent bg-slate-50"
                           value={formData.role}
                           onChange={(e) => setFormData({...formData, role: e.target.value as TeacherRole})}
                        >
                           <option value="SUBJECT_TEACHER">Guru Mapel</option>
                           <option value="CLASS_TEACHER">Guru Kelas</option>
                           <option value="ADMIN">Admin</option>
                        </select>
                     </div>
                     <div className="space-y-1">
                        <label className="text-xs font-bold text-slate-500 uppercase">Jenjang</label>
                        <select
                           className="w-full border-slate-200 rounded-lg text-xs font-bold text-slate-900 focus:ring-2 focus:ring-primary focus:border-transparent bg-slate-50"
                           value={formData.level}
                           onChange={(e) => setFormData({...formData, level: e.target.value as SchoolLevel})}
                        >
                           <option value="SD">SD</option>
                           <option value="SMP">SMP</option>
                           <option value="SMA">SMA</option>
                           <option value="SMK">SMK</option>
                        </select>
                     </div>
                  </div>

                  <div className="pt-4 flex gap-3">
                     <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-3 border border-slate-200 rounded-xl text-sm font-bold text-slate-600 hover:bg-slate-50 transition-colors">Batal</button>
                     <button type="submit" className="flex-1 py-3 bg-primary text-white rounded-xl text-sm font-bold hover:bg-blue-600 shadow-lg shadow-blue-200 transition-colors">Simpan Data</button>
                  </div>
               </form>
            </div>
         </div>
      )}
    </div>
  );
};

// Domain Models

export type TeacherRole = 'CLASS_TEACHER' | 'SUBJECT_TEACHER' | 'ADMIN'; // Added ADMIN explicitly here
export type SchoolLevel = 'SD' | 'SMP' | 'SMA' | 'SMK'; 

// AUTH TYPES
export interface User {
  id: string;
  email: string;
  name: string;
  role: TeacherRole;
  level?: SchoolLevel; // Added Level specific for User Metadata
  isActive: boolean;
  lastLogin?: string;
}

// STORAGE WRAPPER (To save all app state per user)
export interface UserStorageData {
  identity: IdentityData;
  students: Student[];
  classes: ClassInfo[];
  schedules: ScheduleItem[];
  tps: LearningObjective[];
  subject: Subject;
  attendanceData: AttendanceData;
  gradeData: GradeData;
  journals: JournalEntry[]; // Added Journals
}

export interface Student {
  id: string;
  name: string;
  nis: string;
  className?: string; 
}

export interface ClassInfo {
  id: string;
  name: string; 
  level: string; 
  studentCount: number;
}

export interface ScheduleItem {
  id: string;
  day: string; 
  startTime: string; 
  endTime: string; 
  className: string;
  subject: string;
  room: string;
}

export interface LearningMaterial { 
  id: string;
  code: string; 
  title: string;
}

export interface AssessmentCriteria { 
  id: string;
  code: string; 
  description: string; 
}

export interface LearningObjective { 
  id: string;
  code: string; 
  description: string;
  semester?: 1 | 2; 
  scopeId?: string; 
  lms: LearningMaterial[]; 
  criteria: AssessmentCriteria[]; 
}

export interface Subject {
  id: string;
  name: string;
  kktp: number; 
}

// JOURNAL TYPES
export interface JournalEntry {
  id: string;
  date: string;
  scheduleId?: string; // Link to schedule if available
  subjectName: string; // Added Subject Name
  className: string;
  startTime: string;
  endTime: string;
  tpId: string; // Link to LearningObjective
  lmId?: string; // Link to LearningMaterial (Optional)
  activity: string; // Kegiatan Pembelajaran
  reflection: string; // Refleksi Guru
  followUp: string; // Tindak Lanjut
  created_at: string;
}

export interface GradeData {
  [studentId: string]: {
    scores: { [criteriaId: string]: number }; 
    attitude: number; 
  };
}

export interface CalculatedGrade {
  avgScore: number;
  finalScore: number;
  isPassed: boolean;
}

// Identity Data
export interface IdentityData {
  role: TeacherRole; 
  level: SchoolLevel; 
  schoolName: string;
  subjectName: string; 
  teacherName: string;
  nip: string;
  semester: string;
  academicYear: string;
  className: string; 
  studentCount: number;
}

export type AttendanceStatus = 'H' | 'I' | 'S' | 'A'; 

export interface AttendanceRecord {
   status: AttendanceStatus;
   notes?: string;
}

export interface AttendanceData {
  [scheduleId: string]: {
      [date: string]: {
          [studentId: string]: AttendanceRecord
      }
  };
}

export enum TabView {
  LOGIN = 'LOGIN',
  ADMIN_PANEL = 'ADMIN_PANEL',
  DASHBOARD = 'DASHBOARD',
  CLASS_MASTER = 'CLASS_MASTER', 
  STUDENT_MASTER = 'STUDENT_MASTER',
  SCHEDULE_MASTER = 'SCHEDULE_MASTER',
  IDENTITY = 'IDENTITY', 
  CURRICULUM = 'CURRICULUM', 
  CP_GENERATOR = 'CP_GENERATOR',
  GRADING = 'GRADING',
  ATTENDANCE = 'ATTENDANCE',
  RECAP_GRADES = 'RECAP_GRADES',      
  RECAP_ATTENDANCE = 'RECAP_ATTENDANCE',
  JOURNAL = 'JOURNAL' // Added Journal View
}

import React, { useState, useEffect, useMemo } from 'react';
import { JournalEntry, LearningObjective, ScheduleItem, ClassInfo } from '../types';

declare const Swal: any;

interface Props {
  journals: JournalEntry[];
  onUpdateJournals: (journals: JournalEntry[]) => void;
  tps: LearningObjective[];
  schedules: ScheduleItem[];
  classes: ClassInfo[];
  initialContext?: { className?: string, scheduleId?: string };
  onBack: () => void;
}

export const JournalManager: React.FC<Props> = ({ 
    journals, onUpdateJournals, tps, schedules, classes, initialContext, onBack 
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Default Form Data
  const [formData, setFormData] = useState<Omit<JournalEntry, 'id' | 'created_at'>>({
      date: new Date().toISOString().split('T')[0],
      className: '',
      scheduleId: '',
      subjectName: '', // New field
      startTime: '',
      endTime: '',
      tpId: '',
      lmId: '',
      activity: '',
      reflection: '',
      followUp: ''
  });

  // Effect to handle navigation from Dashboard (Auto-fill)
  useEffect(() => {
    if (initialContext?.scheduleId && !isModalOpen) {
        const schedule = schedules.find(s => s.id === initialContext.scheduleId);
        if (schedule) {
            setFormData({
                date: new Date().toISOString().split('T')[0],
                className: schedule.className,
                scheduleId: schedule.id,
                subjectName: schedule.subject,
                startTime: schedule.startTime,
                endTime: schedule.endTime,
                tpId: '',
                lmId: '',
                activity: '',
                reflection: '',
                followUp: ''
            });
            setIsModalOpen(true);
        }
    }
  }, [initialContext, schedules]);

  // Handle Schedule Selection in Form to auto-fill time, class, and subject
  const handleScheduleChange = (scheduleId: string) => {
      const schedule = schedules.find(s => s.id === scheduleId);
      if (schedule) {
          setFormData(prev => ({
              ...prev,
              scheduleId: schedule.id,
              className: schedule.className,
              subjectName: schedule.subject,
              startTime: schedule.startTime,
              endTime: schedule.endTime
          }));
      } else {
          setFormData(prev => ({ 
              ...prev, 
              scheduleId: '', 
              className: '', 
              subjectName: '',
              startTime: '', 
              endTime: '' 
          }));
      }
  };

  // Filtered Journals for Table
  const filteredJournals = useMemo(() => {
      return journals.filter(j => 
          j.activity.toLowerCase().includes(searchQuery.toLowerCase()) ||
          j.className.toLowerCase().includes(searchQuery.toLowerCase())
      ).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [journals, searchQuery]);

  // Derived Options
  const activeTP = useMemo(() => tps.find(tp => tp.id === formData.tpId), [formData.tpId, tps]);
  const availableLMs = activeTP ? activeTP.lms : [];

  const handleSave = (e: React.FormEvent) => {
      e.preventDefault();

      // VALIDATION: Schedule is now MANDATORY
      if (!formData.scheduleId) {
          Swal.fire('Error', 'Wajib memilih Jadwal Mengajar.', 'error');
          return;
      }

      if (!formData.date || !formData.className || !formData.tpId || !formData.activity) {
          Swal.fire('Error', 'Tanggal, Kelas, TP, dan Kegiatan wajib diisi.', 'error');
          return;
      }

      if (editingId) {
          const updated = journals.map(j => j.id === editingId ? { ...j, ...formData } : j);
          onUpdateJournals(updated);
          Swal.fire('Berhasil', 'Jurnal berhasil diperbarui.', 'success');
      } else {
          const newEntry: JournalEntry = {
              id: Date.now().toString(),
              created_at: new Date().toISOString(),
              ...formData
          };
          onUpdateJournals([newEntry, ...journals]);
          Swal.fire('Berhasil', 'Jurnal baru berhasil disimpan.', 'success');
      }
      setIsModalOpen(false);
      setEditingId(null);
  };

  const handleEdit = (journal: JournalEntry) => {
      setEditingId(journal.id);
      setFormData({
          date: journal.date,
          className: journal.className,
          scheduleId: journal.scheduleId,
          subjectName: journal.subjectName || '', // Handle legacy data
          startTime: journal.startTime,
          endTime: journal.endTime,
          tpId: journal.tpId,
          lmId: journal.lmId,
          activity: journal.activity,
          reflection: journal.reflection,
          followUp: journal.followUp
      });
      setIsModalOpen(true);
  };

  const handleDelete = (id: string) => {
      Swal.fire({
          title: 'Hapus Jurnal?',
          text: "Data yang dihapus tidak dapat dikembalikan.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          confirmButtonText: 'Ya, Hapus'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateJournals(journals.filter(j => j.id !== id));
              Swal.fire('Terhapus', 'Jurnal berhasil dihapus.', 'success');
          }
      });
  };

  const closeModal = () => {
      setIsModalOpen(false);
      setEditingId(null);
      // Reset form
      setFormData({
          date: new Date().toISOString().split('T')[0],
          className: '',
          scheduleId: '',
          subjectName: '',
          startTime: '',
          endTime: '',
          tpId: '',
          lmId: '',
          activity: '',
          reflection: '',
          followUp: ''
      });
  };

  return (
    <div className="w-full max-w-7xl mx-auto pb-10">
       {/* Breadcrumbs */}
       <div className="flex items-center gap-2 mb-4 text-sm font-medium text-slate-500">
        <a onClick={onBack} className="hover:text-primary cursor-pointer">Dashboard</a>
        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <span className="text-slate-900 font-bold">Jurnal Guru</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <div className="flex flex-col gap-1">
          <h2 className="text-slate-900 text-3xl font-extrabold tracking-tight">Jurnal Mengajar</h2>
          <p className="text-slate-500 text-base font-normal">Catat aktivitas pembelajaran, refleksi, dan tindak lanjut harian.</p>
        </div>
        <button 
            onClick={() => setIsModalOpen(true)}
            className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 transition-colors shadow-lg shadow-blue-200"
        >
            <span className="material-symbols-outlined text-sm">edit_square</span>
            Isi Jurnal Baru
        </button>
      </div>

      {/* Toolbar */}
      <div className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm mb-6 flex justify-between items-center">
         <div className="relative">
             <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-400 text-lg">search</span>
             <input 
                type="text" 
                placeholder="Cari kegiatan, kelas, atau mapel..." 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10 pr-4 py-2 border border-slate-200 rounded-lg text-sm font-bold text-slate-900 w-72 focus:ring-2 focus:ring-primary outline-none" 
             />
         </div>
         <div className="text-sm text-slate-500 font-bold">
             Total Entry: {journals.length}
         </div>
      </div>

      {/* Journal List */}
      <div className="space-y-4">
          {filteredJournals.length > 0 ? (
              filteredJournals.map(journal => {
                  const tp = tps.find(t => t.id === journal.tpId);
                  const lm = tp?.lms.find(l => l.id === journal.lmId);

                  return (
                      <div key={journal.id} className="bg-white border border-slate-200 rounded-xl p-6 shadow-sm hover:shadow-md transition-all">
                          <div className="flex justify-between items-start mb-4">
                              <div className="flex items-center gap-4">
                                  <div className="bg-blue-50 text-blue-700 px-3 py-2 rounded-lg text-center min-w-[80px]">
                                      <p className="text-xs font-bold uppercase">{new Date(journal.date).toLocaleDateString('id-ID', { month: 'short' })}</p>
                                      <p className="text-2xl font-black">{new Date(journal.date).getDate()}</p>
                                  </div>
                                  <div>
                                      <h3 className="text-lg font-bold text-slate-900">{journal.activity}</h3>
                                      <div className="flex items-center gap-3 text-sm text-slate-500 mt-1">
                                          <span className="flex items-center gap-1 font-bold text-slate-700">
                                              <span className="material-symbols-outlined text-sm">book</span> {journal.subjectName || 'Mapel Umum'}
                                          </span>
                                          <span className="flex items-center gap-1">
                                              <span className="material-symbols-outlined text-sm">schedule</span> {journal.startTime} - {journal.endTime}
                                          </span>
                                          <span className="flex items-center gap-1">
                                              <span className="material-symbols-outlined text-sm">school</span> {journal.className}
                                          </span>
                                      </div>
                                  </div>
                              </div>
                              <div className="flex gap-2">
                                  <button onClick={() => handleEdit(journal)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg"><span className="material-symbols-outlined">edit</span></button>
                                  <button onClick={() => handleDelete(journal.id)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg"><span className="material-symbols-outlined">delete</span></button>
                              </div>
                          </div>

                          <div className="bg-slate-50 p-4 rounded-lg text-sm space-y-2 mb-4 border border-slate-100">
                              <p className="flex gap-2">
                                  <span className="font-bold text-slate-700 w-24 shrink-0">TP:</span>
                                  <span className="text-slate-600">{tp?.code} - {tp?.description}</span>
                              </p>
                              {lm && (
                                  <p className="flex gap-2">
                                      <span className="font-bold text-slate-700 w-24 shrink-0">Materi (LM):</span>
                                      <span className="text-slate-600">{lm.title}</span>
                                  </p>
                              )}
                          </div>

                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                              <div>
                                  <h4 className="text-xs font-bold text-slate-400 uppercase mb-1">Refleksi</h4>
                                  <p className="text-sm text-slate-700 leading-relaxed">{journal.reflection || '-'}</p>
                              </div>
                              <div>
                                  <h4 className="text-xs font-bold text-slate-400 uppercase mb-1">Tindak Lanjut</h4>
                                  <p className="text-sm text-slate-700 leading-relaxed">{journal.followUp || '-'}</p>
                              </div>
                          </div>
                      </div>
                  );
              })
          ) : (
              <div className="flex flex-col items-center justify-center py-12 bg-slate-50 border border-dashed border-slate-300 rounded-xl text-slate-400">
                  <span className="material-symbols-outlined text-4xl mb-2">auto_stories</span>
                  <p className="text-sm font-medium">Belum ada jurnal yang dicatat.</p>
              </div>
          )}
      </div>

      {/* MODAL FORM */}
      {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 overflow-y-auto">
              <div className="bg-white rounded-2xl w-full max-w-3xl shadow-2xl my-8">
                  <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-2xl sticky top-0">
                      <h3 className="text-xl font-bold text-slate-900">{editingId ? 'Edit Jurnal' : 'Tambah Jurnal Baru'}</h3>
                      <button onClick={closeModal} className="text-slate-400 hover:text-red-500 transition-colors">
                          <span className="material-symbols-outlined">close</span>
                      </button>
                  </div>

                  <form onSubmit={handleSave} className="p-6 space-y-6">

                      {/* Section 1: Waktu & Jadwal */}
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Tanggal</label>
                              <input 
                                type="date" required 
                                className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary"
                                value={formData.date}
                                onChange={e => setFormData({...formData, date: e.target.value})}
                              />
                          </div>
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Jadwal / Jam Mengajar <span className="text-red-500">*</span></label>
                              <select 
                                required
                                className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary"
                                value={formData.scheduleId}
                                onChange={e => handleScheduleChange(e.target.value)}
                              >
                                  <option value="">-- Pilih Jadwal (Wajib) --</option>
                                  {schedules.map(s => (
                                      <option key={s.id} value={s.id}>{s.day} {s.startTime}-{s.endTime} | {s.className} | {s.subject}</option>
                                  ))}
                              </select>
                          </div>
                      </div>

                      {/* Section 2: Detail Kelas (Auto-filled) */}
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-slate-50 p-4 rounded-xl border border-slate-100">
                          <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Mata Pelajaran <span className="text-slate-400">(Otomatis)</span></label>
                                <input 
                                    type="text"
                                    readOnly
                                    className="w-full rounded-lg border-slate-200 bg-slate-100 text-sm font-bold text-slate-700 cursor-not-allowed focus:ring-0"
                                    value={formData.subjectName}
                                    placeholder="Pilih jadwal dulu..."
                                />
                          </div>
                          <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Kelas <span className="text-slate-400">(Otomatis)</span></label>
                                <input 
                                    type="text"
                                    readOnly
                                    className="w-full rounded-lg border-slate-200 bg-slate-100 text-sm font-bold text-slate-700 cursor-not-allowed focus:ring-0"
                                    value={formData.className}
                                    placeholder="Pilih jadwal dulu..."
                                />
                          </div>
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Jam Mulai</label>
                              <input type="time" readOnly className="w-full rounded-lg border-slate-200 bg-slate-100 text-sm font-bold text-slate-700" value={formData.startTime} />
                          </div>
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Jam Selesai</label>
                              <input type="time" readOnly className="w-full rounded-lg border-slate-200 bg-slate-100 text-sm font-bold text-slate-700" value={formData.endTime} />
                          </div>
                      </div>

                      {/* Section 3: Kurikulum */}
                      <div className="bg-white border border-slate-200 p-4 rounded-xl space-y-4">
                          <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Tujuan Pembelajaran (TP) <span className="text-red-500">*</span></label>
                                <select 
                                    required
                                    className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary"
                                    value={formData.tpId}
                                    onChange={e => setFormData({...formData, tpId: e.target.value, lmId: ''})}
                                >
                                    <option value="">-- Pilih TP --</option>
                                    {tps.map(tp => (
                                        <option key={tp.id} value={tp.id}>{tp.code} - {tp.description}</option>
                                    ))}
                                </select>
                          </div>
                          <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Lingkup Materi (LM)</label>
                                <select 
                                    className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary"
                                    value={formData.lmId}
                                    onChange={e => setFormData({...formData, lmId: e.target.value})}
                                    disabled={!formData.tpId}
                                >
                                    <option value="">-- Pilih Materi (Opsional) --</option>
                                    {availableLMs.map(lm => (
                                        <option key={lm.id} value={lm.id}>{lm.code} - {lm.title}</option>
                                    ))}
                                </select>
                          </div>
                      </div>

                      {/* Section 4: Detail Aktivitas */}
                      <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500 uppercase">Detail Kegiatan Pembelajaran <span className="text-red-500">*</span></label>
                          <textarea 
                             required
                             rows={3}
                             className="w-full rounded-lg border-slate-200 text-sm text-slate-900 focus:ring-primary"
                             placeholder="Deskripsikan aktivitas yang dilakukan..."
                             value={formData.activity}
                             onChange={e => setFormData({...formData, activity: e.target.value})}
                          />
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Refleksi Guru</label>
                              <textarea 
                                rows={3}
                                className="w-full rounded-lg border-slate-200 text-sm text-slate-900 focus:ring-primary"
                                placeholder="Apa yang berhasil? Apa yang perlu diperbaiki?"
                                value={formData.reflection}
                                onChange={e => setFormData({...formData, reflection: e.target.value})}
                                />
                          </div>
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Tindak Lanjut</label>
                              <textarea 
                                rows={3}
                                className="w-full rounded-lg border-slate-200 text-sm text-slate-900 focus:ring-primary"
                                placeholder="Rencana pertemuan selanjutnya..."
                                value={formData.followUp}
                                onChange={e => setFormData({...formData, followUp: e.target.value})}
                                />
                          </div>
                      </div>

                      <div className="pt-4 flex gap-3 border-t border-slate-100">
                          <button type="button" onClick={closeModal} className="flex-1 py-3 border border-slate-200 rounded-xl text-sm font-bold text-slate-600 hover:bg-slate-50">Batal</button>
                          <button type="submit" className="flex-1 py-3 bg-primary text-white rounded-xl text-sm font-bold hover:bg-blue-600 shadow-lg shadow-blue-200">Simpan Jurnal</button>
                      </div>
                  </form>
              </div>
          </div>
      )}

    </div>
  );
};

-- =================================================================
-- SIGURU - SUPABASE SCHEMA BLUEPRINT
-- 
-- INSTRUKSI:
-- 1. Buka Dashboard Supabase > SQL Editor
-- 2. Copy isi file ini
-- 3. Paste dan klik Run
-- =================================================================

-- 1. EXTENSIONS & SETUP
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 2. ENUMERATIONS (Tipe Data Khusus)
DO $$ BEGIN
    CREATE TYPE school_level_enum AS ENUM ('SD', 'SMP', 'SMA', 'SMK');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

-- Update: Menambahkan ADMIN ke Enum Role
DO $$ BEGIN
    CREATE TYPE teacher_role_enum AS ENUM ('CLASS_TEACHER', 'SUBJECT_TEACHER', 'ADMIN');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
    CREATE TYPE semester_enum AS ENUM ('1', '2', 'Ganjil', 'Genap');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
    CREATE TYPE day_enum AS ENUM ('Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu', 'Minggu');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
    CREATE TYPE attendance_status_enum AS ENUM ('H', 'I', 'S', 'A');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

-- 3. TABLES STRUCTURE

-- A. ORGANISASI SEKOLAH
CREATE TABLE IF NOT EXISTS schools (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    name VARCHAR(255) NOT NULL,
    address TEXT,
    level school_level_enum NOT NULL DEFAULT 'SMA',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- B. PENGGUNA (GURU)
-- Menghubungkan user public dengan auth.users Supabase
CREATE TABLE IF NOT EXISTS teachers (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, -- Link ke Supabase Auth
    school_id UUID REFERENCES schools(id) ON DELETE CASCADE,
    email VARCHAR(255),
    full_name VARCHAR(150) NOT NULL,
    nip VARCHAR(50),
    role teacher_role_enum DEFAULT 'SUBJECT_TEACHER',
    avatar_url TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- C. MANAJEMEN KELAS & SISWA
CREATE TABLE IF NOT EXISTS classes (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    school_id UUID REFERENCES schools(id) ON DELETE CASCADE,
    teacher_id UUID REFERENCES teachers(id), -- Wali Kelas
    name VARCHAR(50) NOT NULL, -- e.g. "10-A"
    level VARCHAR(50) NOT NULL, -- e.g. "Fase E"
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS students (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    class_id UUID REFERENCES classes(id) ON DELETE SET NULL,
    school_id UUID REFERENCES schools(id) ON DELETE CASCADE,
    name VARCHAR(150) NOT NULL,
    nis VARCHAR(50) NOT NULL,
    gender VARCHAR(1) DEFAULT 'L', -- 'L' or 'P'
    status VARCHAR(20) DEFAULT 'Aktif',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- D. KURIKULUM & MAPEL
CREATE TABLE IF NOT EXISTS subjects (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    school_id UUID REFERENCES schools(id) ON DELETE CASCADE,
    name VARCHAR(100) NOT NULL, -- e.g. "Matematika"
    kktp_default INTEGER DEFAULT 75,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS learning_objectives ( -- TP (Tujuan Pembelajaran)
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    subject_id UUID REFERENCES subjects(id) ON DELETE CASCADE,
    code VARCHAR(20) NOT NULL, -- e.g. "TP.1"
    description TEXT NOT NULL,
    semester semester_enum DEFAULT '1',
    scope_id VARCHAR(50), -- e.g. "lvl-10" or "math" (Context ID)
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS learning_materials ( -- LM (Lingkup Materi)
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tp_id UUID REFERENCES learning_objectives(id) ON DELETE CASCADE,
    code VARCHAR(20) NOT NULL,
    title VARCHAR(255) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS assessment_criteria ( -- Kriteria Penilaian (Columns in Matrix)
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tp_id UUID REFERENCES learning_objectives(id) ON DELETE CASCADE,
    code VARCHAR(20) NOT NULL, -- e.g. "KR.1"
    description TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- E. JADWAL
CREATE TABLE IF NOT EXISTS schedules (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    class_id UUID REFERENCES classes(id) ON DELETE CASCADE,
    subject_id UUID REFERENCES subjects(id) ON DELETE CASCADE,
    teacher_id UUID REFERENCES teachers(id) ON DELETE CASCADE,
    day day_enum NOT NULL,
    start_time TIME NOT NULL,
    end_time TIME NOT NULL,
    room VARCHAR(50),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- F. TRANSAKSI PRESENSI
