    </div>
  );
};

import React, { useState, useMemo } from 'react';
import ExcelJS from 'exceljs';
import { Student, Subject, IdentityData, AttendanceData } from '../types';

interface Props {
  students: Student[];
  subject: Subject;
  identity: IdentityData;
  mode: 'GRADES' | 'ATTENDANCE'; 
  globalAttendance: AttendanceData;
}

const AVAILABLE_SUBJECTS = [
    { id: 's1', name: 'Matematika - Fase E' },
    { id: 's2', name: 'Fisika - Fase E' },
    { id: 's3', name: 'Kimia - Fase E' },
];

const MONTH_NAMES = [
    'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
    'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'
];

export const RecapManager: React.FC<Props> = ({ students, subject, identity, mode, globalAttendance }) => {
  const [selectedClass, setSelectedClass] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>(subject.id);

  // Default to current month
  const [selectedMonth, setSelectedMonth] = useState<string>(new Date().getMonth().toString());

  // Derive unique classes
  const availableClasses = useMemo(() => {
    const classes = new Set(students.map(s => s.className).filter(Boolean));
    return Array.from(classes).sort() as string[];
  }, [students]);

  // Filter students
  const filteredStudents = useMemo(() => {
    if (!selectedClass) return [];
    return students.filter(s => s.className === selectedClass);
  }, [students, selectedClass]);

  // AGGREGATE REAL DATA
  const reportData = useMemo(() => {
    return filteredStudents.map(student => {
        // Init Counters
        let totalStats = { present: 0, permit: 0, sick: 0, absent: 0, meetings: 0 };
        let monthlyStats = { present: 0, permit: 0, sick: 0, absent: 0, meetings: 0 };

        // Iterate through all schedules and dates
        Object.keys(globalAttendance).forEach(schId => {
            const datesObj = globalAttendance[schId];
            Object.keys(datesObj).forEach(dateStr => {
                const record = datesObj[dateStr][student.id];

                // Check if this record belongs to the student
                if (record) {
                    // 1. Total Accumulation
                    totalStats.meetings++;
                    if (record.status === 'H') totalStats.present++;
                    else if (record.status === 'I') totalStats.permit++;
                    else if (record.status === 'S') totalStats.sick++;
                    else if (record.status === 'A') totalStats.absent++;

                    // 2. Monthly Accumulation (Check Month Index)
                    const recordDate = new Date(dateStr);
                    if (recordDate.getMonth() === parseInt(selectedMonth)) {
                        monthlyStats.meetings++;
                        if (record.status === 'H') monthlyStats.present++;
                        else if (record.status === 'I') monthlyStats.permit++;
                        else if (record.status === 'S') monthlyStats.sick++;
                        else if (record.status === 'A') monthlyStats.absent++;
                    }
                }
            });
        });

        const totalPercentage = totalStats.meetings > 0 
            ? Math.round((totalStats.present / totalStats.meetings) * 100) 
            : 0;

        const monthlyPercentage = monthlyStats.meetings > 0
            ? Math.round((monthlyStats.present / monthlyStats.meetings) * 100)
            : 0;

        // --- MOCK GRADES (Existing Logic) ---
        const formative = Math.floor(Math.random() * (95 - 75) + 75);
        const summative = Math.floor(Math.random() * (90 - 70) + 70);
        const attitude = Math.floor(Math.random() * (100 - 80) + 80);
        const finalScore = Math.round((formative * 0.4) + (summative * 0.5) + (attitude * 0.1));
        const isPassed = finalScore >= subject.kktp;

        return {
            ...student,
            grades: { formative, summative, attitude, finalScore, isPassed },
            attendance: { 
                total: { ...totalStats, percentage: totalPercentage },
                monthly: { ...monthlyStats, percentage: monthlyPercentage }
            }
        };
    });
  }, [filteredStudents, subject.kktp, globalAttendance, selectedMonth]);

  // --- EXCEL EXPORT LOGIC ---
  const handleExportExcel = async () => {
    if (reportData.length === 0) return;

    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet(mode === 'GRADES' ? 'Rekap Nilai' : 'Rekap Presensi');
    const monthName = MONTH_NAMES[parseInt(selectedMonth)];

    // 1. Header Information
    sheet.mergeCells('A1:I1');
    sheet.getCell('A1').value = identity.schoolName;
    sheet.getCell('A1').font = { size: 14, bold: true };
    sheet.getCell('A1').alignment = { horizontal: 'center' };

    sheet.mergeCells('A2:I2');
    sheet.getCell('A2').value = `REKAPITULASI ${mode === 'GRADES' ? 'NILAI AKHIR' : 'KEHADIRAN SISWA'}`;
    sheet.getCell('A2').font = { size: 12, bold: true };
    sheet.getCell('A2').alignment = { horizontal: 'center' };

    sheet.addRow([`Kelas: ${selectedClass}`, '', '', '', `Mapel: ${AVAILABLE_SUBJECTS.find(s => s.id === selectedSubject)?.name || subject.name}`]);
    sheet.addRow([`Tahun Ajaran: ${identity.academicYear}`, '', '', '', `Semester: ${identity.semester}`]);
    if (mode === 'ATTENDANCE') {
        sheet.addRow([`Bulan Laporan: ${monthName}`, '', '', '', '']);
    }
    sheet.addRow([]); // Spacer

    // 2. Table Headers
    let headerRowIndex = 0;

    if (mode === 'GRADES') {
        const headerRow = sheet.addRow(['No', 'NIS', 'Nama Siswa', 'Rata-rata Formatif (40%)', 'Rata-rata Sumatif (50%)', 'Nilai Sikap (10%)', 'Nilai Akhir', 'Status', 'Keterangan']);
        headerRowIndex = headerRow.number;
    } else {
        // Attendance Headers (Double Row)
        const row1 = sheet.addRow(['No', 'NIS', 'Nama Siswa', `Rincian Bulan ${monthName}`, '', '', '', 'Total Akumulasi', '']);
        const row2 = sheet.addRow(['', '', '', 'Hadir (H)', 'Izin (I)', 'Sakit (S)', 'Alfa (A)', 'Total Tatap Muka', 'Persentase (%)']);

        headerRowIndex = row1.number;

        // Merging Header Cells
        sheet.mergeCells(`A${headerRowIndex}:A${headerRowIndex+1}`); // No
        sheet.mergeCells(`B${headerRowIndex}:B${headerRowIndex+1}`); // NIS
        sheet.mergeCells(`C${headerRowIndex}:C${headerRowIndex+1}`); // Nama
        sheet.mergeCells(`D${headerRowIndex}:G${headerRowIndex}`);   // Month Group
        sheet.mergeCells(`H${headerRowIndex}:I${headerRowIndex}`);   // Total Group
    }

    // 3. Styling Headers
    const headerRow = sheet.getRow(headerRowIndex);
    const subHeaderRow = mode === 'ATTENDANCE' ? sheet.getRow(headerRowIndex + 1) : null;

    [headerRow, subHeaderRow].forEach(row => {
        if(!row) return;
        row.eachCell((cell) => {
            cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
            cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } }; // Primary Blue
            cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
            cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
        });
    });

    // 4. Data Rows
    reportData.forEach((d, i) => {
        let rowValues = [];
        if (mode === 'GRADES') {
            rowValues = [
                i + 1, d.nis, d.name, 
                d.grades.formative, d.grades.summative, d.grades.attitude, 
                d.grades.finalScore, 
                d.grades.isPassed ? 'TUNTAS' : 'REMEDIAL',
                d.grades.isPassed ? 'Lulus KKTP' : 'Perlu Bimbingan'
            ];
        } else {
            rowValues = [
                i + 1, d.nis, d.name, 
                d.attendance.monthly.present, d.attendance.monthly.permit, d.attendance.monthly.sick, d.attendance.monthly.absent,
                d.attendance.total.meetings, `${d.attendance.total.percentage}%`
            ];
        }

        const row = sheet.addRow(rowValues);

        // Data Borders & Alignment
        row.eachCell((cell, colNumber) => {
            cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
            if (colNumber === 1 || colNumber > 3) {
                cell.alignment = { horizontal: 'center' };
            }
        });

        // Conditional Formatting for Status
        if (mode === 'GRADES') {
            const statusCell = row.getCell(8);
            statusCell.font = { bold: true, color: { argb: d.grades.isPassed ? 'FF008000' : 'FFFF0000' } };
        }
        // Conditional Formatting for Percentage
        if (mode === 'ATTENDANCE') {
            const percentCell = row.getCell(9);
             if (d.attendance.total.percentage < 50) {
                 percentCell.font = { color: { argb: 'FFFF0000' }, bold: true }; // Red text for low attendance
             }
        }
    });

    // 5. Column Widths
    sheet.columns.forEach((col, index) => {
        if (index === 2) col.width = 35; // Name
        else col.width = 15;
    });

    // 6. Download Trigger
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `Rekap_${mode}_${selectedClass}_${monthName}.xlsx`;
    anchor.click();
    window.URL.revokeObjectURL(url);
  };

  return (
    <div className="max-w-7xl mx-auto pb-10">
      {/* Breadcrumbs */}
      <div className="flex items-center gap-2 mb-4 text-sm font-medium text-slate-500">
        <a className="hover:text-primary cursor-pointer">Dashboard</a>
        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <span className="text-slate-900 font-bold">Rekapitulasi {mode === 'GRADES' ? 'Nilai' : 'Presensi'}</span>
      </div>

      {/* Header */}
      <div className="flex justify-between items-end mb-8">
        <div className="flex flex-col gap-1">
          <h2 className="text-slate-900 text-3xl font-extrabold tracking-tight">
              {mode === 'GRADES' ? 'Rekap Nilai Siswa' : 'Rekap Kehadiran Siswa'}
          </h2>
          <p className="text-slate-500">
              {mode === 'GRADES' ? 'Laporan nilai akhir semester.' : 'Pantau progres kehadiran bulanan dan akumulasi total.'}
          </p>
        </div>
        <div className="flex gap-2">
             <button 
                onClick={handleExportExcel}
                disabled={!selectedClass}
                className="flex items-center gap-2 px-6 py-2.5 bg-green-600 text-white rounded-xl text-sm font-bold hover:bg-green-700 transition-colors shadow-lg shadow-green-100 disabled:opacity-50 disabled:cursor-not-allowed"
             >
                <span className="material-symbols-outlined">table_view</span>
                Export Excel
            </button>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="bg-white border border-slate-200 rounded-xl p-5 shadow-sm mb-6 flex flex-col md:flex-row gap-6 items-end">
         <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-4 gap-4">
             {/* Subject Selector */}
             <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Mata Pelajaran</label>
                <select 
                    value={selectedSubject} 
                    onChange={(e) => setSelectedSubject(e.target.value)}
                    className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary focus:border-primary"
                >
                    {AVAILABLE_SUBJECTS.map(s => (
                        <option key={s.id} value={s.id}>{s.name}</option>
                    ))}
                </select>
             </div>

             {/* Class Selector */}
             <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Kelas <span className="text-red-500">*</span></label>
                <select 
                    value={selectedClass} 
                    onChange={(e) => setSelectedClass(e.target.value)}
                    className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary focus:border-primary"
                >
                    <option value="">-- Pilih Kelas --</option>
                    {availableClasses.map(cls => (
                        <option key={cls} value={cls}>{cls}</option>
                    ))}
                </select>
             </div>

             {/* Month Filter (Only for Attendance) */}
             {mode === 'ATTENDANCE' && (
                 <div className="space-y-1">
                    <label className="text-xs font-bold text-slate-500 uppercase">Bulan Laporan</label>
                    <select 
                        value={selectedMonth}
                        onChange={(e) => setSelectedMonth(e.target.value)}
                        className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary focus:border-primary"
                    >
                        {MONTH_NAMES.map((m, i) => (
                            <option key={m} value={i}>{m}</option>
                        ))}
                    </select>
                 </div>
             )}

             {/* Semester Filter (Visual Only) */}
             <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Semester</label>
                <select disabled className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-500 bg-slate-50 cursor-not-allowed">
                    <option>{identity.semester} {identity.academicYear}</option>
                </select>
             </div>
         </div>
      </div>

      {/* Data Table */}
      <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden min-h-[400px]">
         {selectedClass ? (
             <div className="overflow-x-auto custom-scrollbar">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-slate-50 border-b border-slate-200">
                        <tr>
                            <th rowSpan={2} className="px-6 py-4 text-xs font-bold text-slate-500 uppercase w-16 text-center border-r border-slate-200">No</th>
                            <th rowSpan={2} className="px-6 py-4 text-xs font-bold text-slate-500 uppercase border-r border-slate-200 min-w-[200px]">Identitas Siswa</th>

                            {mode === 'GRADES' ? (
                                <>
                                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-center">Formatif (40%)</th>
                                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-center">Sumatif (50%)</th>
                                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-center">Sikap (10%)</th>
                                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-center bg-blue-50/50 text-blue-700">Nilai Akhir</th>
                                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase text-center">Status</th>
                                </>
                            ) : (
                                <>
                                    <th colSpan={4} className="px-6 py-3 text-xs font-extrabold text-slate-700 uppercase text-center bg-slate-100 border-r border-slate-200 border-b">
                                        Rincian Bulan {MONTH_NAMES[parseInt(selectedMonth)]}
                                    </th>
                                    <th colSpan={2} className="px-6 py-3 text-xs font-extrabold text-blue-700 uppercase text-center bg-blue-50 border-b">
                                        Total Akumulasi
                                    </th>
                                </>
                            )}
                        </tr>
                        {mode === 'ATTENDANCE' && (
                            <tr className="bg-slate-50 border-b border-slate-200">
                                <th className="px-4 py-2 text-[10px] font-bold text-green-600 uppercase text-center border-r border-slate-200">Hadir</th>
                                <th className="px-4 py-2 text-[10px] font-bold text-blue-600 uppercase text-center border-r border-slate-200">Izin</th>
                                <th className="px-4 py-2 text-[10px] font-bold text-orange-600 uppercase text-center border-r border-slate-200">Sakit</th>
                                <th className="px-4 py-2 text-[10px] font-bold text-red-600 uppercase text-center border-r border-slate-200">Alfa</th>
                                <th className="px-4 py-2 text-[10px] font-bold text-slate-600 uppercase text-center bg-blue-50/30 border-r border-blue-100">Total Pertemuan</th>
                                <th className="px-4 py-2 text-[10px] font-bold text-slate-600 uppercase text-center bg-blue-50/30">Persentase</th>
                            </tr>
                        )}
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {reportData.map((d, i) => (
                            <tr key={d.id} className="hover:bg-slate-50 transition-colors">
                                <td className="px-6 py-4 text-center text-sm text-slate-500 border-r border-slate-100">{i + 1}</td>
                                <td className="px-6 py-4 border-r border-slate-100">
                                    <p className="font-bold text-slate-800 text-sm">{d.name}</p>
                                    <p className="text-[10px] text-slate-400">NIS: {d.nis}</p>
                                </td>

                                {mode === 'GRADES' ? (
                                    <>
                                        <td className="px-6 py-4 text-center text-sm text-slate-600">{d.grades.formative}</td>
                                        <td className="px-6 py-4 text-center text-sm text-slate-600">{d.grades.summative}</td>
                                        <td className="px-6 py-4 text-center text-sm text-slate-600">{d.grades.attitude}</td>
                                        <td className="px-6 py-4 text-center font-bold text-blue-600 bg-blue-50/30 text-base">{d.grades.finalScore}</td>
                                        <td className="px-6 py-4 text-center">
                                            <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider ${d.grades.isPassed ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                {d.grades.isPassed ? 'Tuntas' : 'Remedial'}
                                            </span>
                                        </td>
                                    </>
                                ) : (
                                    <>
                                        <td className="px-4 py-4 text-center text-sm font-bold text-green-600 bg-slate-50/30 border-r border-slate-100">{d.attendance.monthly.present}</td>
                                        <td className="px-4 py-4 text-center text-sm font-bold text-blue-600 bg-slate-50/30 border-r border-slate-100">{d.attendance.monthly.permit}</td>
                                        <td className="px-4 py-4 text-center text-sm font-bold text-orange-600 bg-slate-50/30 border-r border-slate-100">{d.attendance.monthly.sick}</td>
                                        <td className="px-4 py-4 text-center text-sm font-bold text-red-600 bg-slate-50/30 border-r border-slate-100">{d.attendance.monthly.absent}</td>

                                        <td className="px-4 py-4 text-center text-sm font-bold text-slate-700 bg-blue-50/20 border-r border-blue-50">{d.attendance.total.meetings}</td>
                                        <td className="px-4 py-4 text-center bg-blue-50/20">
                                            <div className="flex items-center gap-2 justify-center">
                                                <div className="w-12 bg-slate-200 h-1.5 rounded-full overflow-hidden">
                                                    <div className={`h-full rounded-full ${d.attendance.total.percentage >= 80 ? 'bg-green-500' : d.attendance.total.percentage >= 50 ? 'bg-orange-500' : 'bg-red-500'}`} style={{width: `${d.attendance.total.percentage}%`}}></div>
                                                </div>
                                                <span className="text-xs font-bold text-slate-700">{d.attendance.total.percentage}%</span>
                                            </div>
                                        </td>
                                    </>
                                )}
                            </tr>
                        ))}
                    </tbody>
                </table>
             </div>
         ) : (
             <div className="flex flex-col items-center justify-center h-80 text-slate-400">
                <span className="material-symbols-outlined text-4xl mb-3 text-slate-300">filter_alt_off</span>
                <p className="font-bold text-slate-600">Pilih Kelas Terlebih Dahulu</p>
                <p className="text-sm">Silahkan gunakan filter di atas untuk menampilkan data rekap.</p>
             </div>
         )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import ExcelJS from 'exceljs';
import { JournalEntry, LearningObjective, ScheduleItem, ClassInfo } from '../types';

declare const Swal: any;

interface Props {
  journals: JournalEntry[];
  onUpdateJournals: (journals: JournalEntry[]) => void;
  tps: LearningObjective[];
  schedules: ScheduleItem[];
  classes: ClassInfo[];
  initialContext?: { className?: string, scheduleId?: string };
  onBack: () => void;
}

export const JournalManager: React.FC<Props> = ({ 
    journals, onUpdateJournals, tps, schedules, classes, initialContext, onBack 
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // FILTER STATES (Main View)
  const [filterClass, setFilterClass] = useState<string>('');
  const [filterSubject, setFilterSubject] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');

  // Default Form Data
  const [formData, setFormData] = useState<Omit<JournalEntry, 'id' | 'created_at'>>({
      date: new Date().toISOString().split('T')[0],
      className: '',
      scheduleId: '',
      subjectName: '', 
      startTime: '',
      endTime: '',
      tpId: '',
      lmId: '',
      activity: '',
      reflection: '',
      followUp: ''
  });

  // --- DERIVED LISTS FOR FILTERS ---
  const availableClasses = useMemo(() => {
      return [...new Set(schedules.map(s => s.className))].sort();
  }, [schedules]);

  const availableSubjects = useMemo(() => {
      return [...new Set(schedules.map(s => s.subject))].sort();
  }, [schedules]);

  // --- EFFECT: HANDLE CONTEXT NAVIGATION ---
  useEffect(() => {
    if (initialContext?.scheduleId && !isModalOpen) {
        // Auto-open modal logic (existing)
        const schedule = schedules.find(s => s.id === initialContext.scheduleId);
        if (schedule) {
            setFormData({
                date: new Date().toISOString().split('T')[0],
                className: schedule.className,
                scheduleId: schedule.id,
                subjectName: schedule.subject,
                startTime: schedule.startTime,
                endTime: schedule.endTime,
                tpId: '',
                lmId: '',
                activity: '',
                reflection: '',
                followUp: ''
            });
            setIsModalOpen(true);
        }
    }

    // Auto-set filters if navigating from Dashboard
    if (initialContext?.className) {
        setFilterClass(initialContext.className);
    }
    if (initialContext?.scheduleId) {
        const schedule = schedules.find(s => s.id === initialContext.scheduleId);
        if(schedule) setFilterSubject(schedule.subject);
    }

  }, [initialContext, schedules]);

  // Handle Schedule Selection in Form
  const handleScheduleChange = (scheduleId: string) => {
      const schedule = schedules.find(s => s.id === scheduleId);
      if (schedule) {
          setFormData(prev => ({
              ...prev,
              scheduleId: schedule.id,
              className: schedule.className,
              subjectName: schedule.subject,
              startTime: schedule.startTime,
              endTime: schedule.endTime
          }));
      } else {
          setFormData(prev => ({ 
              ...prev, 
              scheduleId: '', 
              className: '', 
              subjectName: '',
              startTime: '', 
              endTime: '' 
          }));
      }
  };

  // --- MAIN FILTER LOGIC ---
  const filteredJournals = useMemo(() => {
      return journals.filter(j => {
          const matchClass = filterClass ? j.className === filterClass : false;
          const matchSubject = filterSubject ? j.subjectName === filterSubject : false;

          const query = searchQuery.toLowerCase();
          const matchSearch = j.activity.toLowerCase().includes(query) || 
                              j.reflection.toLowerCase().includes(query);

          return matchClass && matchSubject && matchSearch;
      }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [journals, filterClass, filterSubject, searchQuery]);

  // Derived Options for Form
  const activeTP = useMemo(() => tps.find(tp => tp.id === formData.tpId), [formData.tpId, tps]);
  const availableLMs = activeTP ? activeTP.lms : [];

  const handleExportExcel = async () => {
    if (filteredJournals.length === 0) return;

    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet('Jurnal Guru');

    // Headers
    const headerRow = sheet.addRow([
        'No', 'Tanggal', 'Jam', 'Kelas', 'Mata Pelajaran', 
        'Kode TP', 'Deskripsi Kegiatan', 'Refleksi Guru', 'Tindak Lanjut'
    ]);

    // Style Header
    headerRow.eachCell((cell) => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } };
        cell.alignment = { horizontal: 'center', vertical: 'middle' };
        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
    });

    // Data Rows
    filteredJournals.forEach((j, index) => {
        const tp = tps.find(t => t.id === j.tpId);

        const row = sheet.addRow([
            index + 1,
            new Date(j.date).toLocaleDateString('id-ID'),
            `${j.startTime} - ${j.endTime}`,
            j.className,
            j.subjectName,
            tp ? tp.code : '-',
            j.activity,
            j.reflection,
            j.followUp
        ]);

        row.eachCell((cell) => {
             cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
             cell.alignment = { vertical: 'top', wrapText: true };
        });
    });

    // Column Widths
    sheet.getColumn(2).width = 15; // Tanggal
    sheet.getColumn(7).width = 40; // Aktivitas
    sheet.getColumn(8).width = 30; // Refleksi
    sheet.getColumn(9).width = 30; // Tindak Lanjut

    // Download
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `Jurnal_${filterClass || 'Semua'}_${filterSubject || 'Semua'}.xlsx`;
    anchor.click();
    window.URL.revokeObjectURL(url);
  };

  const handleSave = (e: React.FormEvent) => {
      e.preventDefault();

      if (!formData.scheduleId) {
          Swal.fire('Error', 'Wajib memilih Jadwal Mengajar.', 'error');
          return;
      }
      if (!formData.date || !formData.className || !formData.tpId || !formData.activity) {
          Swal.fire('Error', 'Tanggal, Kelas, TP, dan Kegiatan wajib diisi.', 'error');
          return;
      }

      if (editingId) {
          const updated = journals.map(j => j.id === editingId ? { ...j, ...formData } : j);
          onUpdateJournals(updated);
          Swal.fire('Berhasil', 'Jurnal berhasil diperbarui.', 'success');
      } else {
          const newEntry: JournalEntry = {
              id: Date.now().toString(),
              created_at: new Date().toISOString(),
              ...formData
          };
          onUpdateJournals([newEntry, ...journals]);
          Swal.fire('Berhasil', 'Jurnal baru berhasil disimpan.', 'success');
      }
      setIsModalOpen(false);
      setEditingId(null);
  };

  const handleEdit = (journal: JournalEntry) => {
      setEditingId(journal.id);
      setFormData({ ...journal }); // Simplified spread since types match mostly
      setIsModalOpen(true);
  };

  const handleDelete = (id: string) => {
      Swal.fire({
          title: 'Hapus Jurnal?',
          text: "Data yang dihapus tidak dapat dikembalikan.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          confirmButtonText: 'Ya, Hapus'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateJournals(journals.filter(j => j.id !== id));
              Swal.fire('Terhapus', 'Jurnal berhasil dihapus.', 'success');
          }
      });
  };

  const closeModal = () => {
      setIsModalOpen(false);
      setEditingId(null);
      setFormData({
          date: new Date().toISOString().split('T')[0],
          className: '',
          scheduleId: '',
          subjectName: '',
          startTime: '',
          endTime: '',
          tpId: '',
          lmId: '',
          activity: '',
          reflection: '',
          followUp: ''
      });
  };

  return (
    <div className="w-full max-w-7xl mx-auto pb-10">
       {/* Breadcrumbs */}
       <div className="flex items-center gap-2 mb-4 text-sm font-medium text-slate-500">
        <a onClick={onBack} className="hover:text-primary cursor-pointer">Dashboard</a>
        <span className="material-symbols-outlined text-sm">chevron_right</span>
        <span className="text-slate-900 font-bold">Jurnal Guru</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <div className="flex flex-col gap-1">
          <h2 className="text-slate-900 text-3xl font-extrabold tracking-tight">Jurnal Mengajar</h2>
          <p className="text-slate-500 text-base font-normal">Catat aktivitas pembelajaran, refleksi, dan tindak lanjut harian.</p>
        </div>
        <div className="flex gap-3">
             <button 
                onClick={handleExportExcel}
                disabled={filteredJournals.length === 0}
                className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg text-sm font-bold hover:bg-green-700 transition-colors shadow-lg shadow-green-200 disabled:opacity-50 disabled:cursor-not-allowed"
            >
                <span className="material-symbols-outlined text-sm">table_view</span>
                Export Excel
            </button>
            <button 
                onClick={() => setIsModalOpen(true)}
                className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 transition-colors shadow-lg shadow-blue-200"
            >
                <span className="material-symbols-outlined text-sm">edit_square</span>
                Isi Jurnal Baru
            </button>
        </div>
      </div>

      {/* FILTER BAR (REQUIRED) */}
      <div className="bg-white border border-slate-200 rounded-xl p-5 shadow-sm mb-6 flex flex-col md:flex-row gap-6 items-end">
         <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 gap-4">
             {/* Class Filter */}
             <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Pilih Kelas</label>
                <div className="relative">
                    <select 
                        value={filterClass} 
                        onChange={(e) => setFilterClass(e.target.value)}
                        className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary focus:border-primary pl-10 appearance-none bg-slate-50"
                    >
                        <option value="">-- Semua Kelas --</option>
                        {availableClasses.map(cls => (
                            <option key={cls} value={cls}>{cls}</option>
                        ))}
                    </select>
                    <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-500 pointer-events-none text-lg">school</span>
                    <span className="material-symbols-outlined absolute right-3 top-3 text-slate-400 pointer-events-none text-sm">expand_more</span>
                </div>
             </div>

             {/* Subject Filter */}
             <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase">Pilih Mata Pelajaran</label>
                <div className="relative">
                    <select 
                        value={filterSubject} 
                        onChange={(e) => setFilterSubject(e.target.value)}
                        className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary focus:border-primary pl-10 appearance-none bg-slate-50"
                    >
                        <option value="">-- Semua Mapel --</option>
                        {availableSubjects.map(subj => (
                            <option key={subj} value={subj}>{subj}</option>
                        ))}
                    </select>
                    <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-500 pointer-events-none text-lg">book</span>
                    <span className="material-symbols-outlined absolute right-3 top-3 text-slate-400 pointer-events-none text-sm">expand_more</span>
                </div>
             </div>
         </div>

         {/* Search Filter (Auxiliary) */}
         <div className="w-full md:w-auto">
             <div className="relative">
                 <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-400 text-lg">search</span>
                 <input 
                    type="text" 
                    placeholder="Cari topik kegiatan..." 
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="pl-10 pr-4 py-2.5 border border-slate-200 rounded-lg text-sm font-bold text-slate-900 w-full md:w-64 focus:ring-2 focus:ring-primary outline-none" 
                 />
             </div>
         </div>
      </div>

      {/* Main Content: List or Empty State */}
      <div className="space-y-4">
          {/* Validation: Check if filters are selected */}
          {!filterClass || !filterSubject ? (
              <div className="flex flex-col items-center justify-center py-16 bg-slate-50 border-2 border-dashed border-slate-300 rounded-xl text-slate-400">
                  <span className="material-symbols-outlined text-5xl mb-3 text-slate-300">filter_alt</span>
                  <h3 className="text-lg font-bold text-slate-600">Filter Diperlukan</h3>
                  <p className="text-sm text-center max-w-md mt-1">
                      Silahkan pilih <strong>Kelas</strong> dan <strong>Mata Pelajaran</strong> di atas untuk menampilkan riwayat jurnal.
                  </p>
              </div>
          ) : (
              <>
                {/* Stats Bar if filtered */}
                <div className="flex justify-between items-center px-2">
                    <p className="text-sm font-bold text-slate-500">
                        Menampilkan riwayat untuk <span className="text-primary">{filterSubject}</span> di <span className="text-primary">{filterClass}</span>
                    </p>
                    <span className="bg-slate-100 text-slate-600 px-3 py-1 rounded-full text-xs font-bold">
                        {filteredJournals.length} Catatan
                    </span>
                </div>

                {filteredJournals.length > 0 ? (
                    filteredJournals.map(journal => {
                        const tp = tps.find(t => t.id === journal.tpId);
                        const lm = tp?.lms.find(l => l.id === journal.lmId);

                        return (
                            <div key={journal.id} className="bg-white border border-slate-200 rounded-xl p-6 shadow-sm hover:shadow-md transition-all animate-in fade-in slide-in-from-bottom-2">
                                <div className="flex justify-between items-start mb-4">
                                    <div className="flex items-center gap-4">
                                        <div className="bg-blue-50 text-blue-700 px-3 py-2 rounded-lg text-center min-w-[80px]">
                                            <p className="text-xs font-bold uppercase">{new Date(journal.date).toLocaleDateString('id-ID', { month: 'short' })}</p>
                                            <p className="text-2xl font-black">{new Date(journal.date).getDate()}</p>
                                        </div>
                                        <div>
                                            <h3 className="text-lg font-bold text-slate-900">{journal.activity}</h3>
                                            <div className="flex items-center gap-3 text-sm text-slate-500 mt-1">
                                                <span className="flex items-center gap-1 font-bold text-slate-700">
                                                    <span className="material-symbols-outlined text-sm">book</span> {journal.subjectName || 'Mapel Umum'}
                                                </span>
                                                <span className="flex items-center gap-1">
                                                    <span className="material-symbols-outlined text-sm">schedule</span> {journal.startTime} - {journal.endTime}
                                                </span>
                                                <span className="flex items-center gap-1">
                                                    <span className="material-symbols-outlined text-sm">school</span> {journal.className}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="flex gap-2">
                                        <button onClick={() => handleEdit(journal)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg"><span className="material-symbols-outlined">edit</span></button>
                                        <button onClick={() => handleDelete(journal.id)} className="p-2 text-red-600 hover:bg-red-50 rounded-lg"><span className="material-symbols-outlined">delete</span></button>
                                    </div>
                                </div>

                                <div className="bg-slate-50 p-4 rounded-lg text-sm space-y-2 mb-4 border border-slate-100">
                                    <p className="flex gap-2">
                                        <span className="font-bold text-slate-700 w-24 shrink-0">TP:</span>
                                        <span className="text-slate-600">{tp?.code} - {tp?.description}</span>
                                    </p>
                                    {lm && (
                                        <p className="flex gap-2">
                                            <span className="font-bold text-slate-700 w-24 shrink-0">Materi (LM):</span>
                                            <span className="text-slate-600">{lm.title}</span>
                                        </p>
                                    )}
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div>
                                        <h4 className="text-xs font-bold text-slate-400 uppercase mb-1">Refleksi</h4>
                                        <p className="text-sm text-slate-700 leading-relaxed">{journal.reflection || '-'}</p>
                                    </div>
                                    <div>
                                        <h4 className="text-xs font-bold text-slate-400 uppercase mb-1">Tindak Lanjut</h4>
                                        <p className="text-sm text-slate-700 leading-relaxed">{journal.followUp || '-'}</p>
                                    </div>
                                </div>
                            </div>
                        );
                    })
                ) : (
                    <div className="flex flex-col items-center justify-center py-12 bg-slate-50 border border-dashed border-slate-300 rounded-xl text-slate-400">
                        <span className="material-symbols-outlined text-4xl mb-2">auto_stories</span>
                        <p className="text-sm font-medium">Belum ada jurnal untuk filter ini.</p>
                        <button onClick={() => setIsModalOpen(true)} className="mt-2 text-primary font-bold hover:underline text-sm">Buat Jurnal Baru</button>
                    </div>
                )}
              </>
          )}
      </div>

      {/* MODAL FORM (REUSED FROM PREVIOUS STEP) */}
      {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 overflow-y-auto">
              <div className="bg-white rounded-2xl w-full max-w-3xl shadow-2xl my-8">
                  <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-2xl sticky top-0">
                      <h3 className="text-xl font-bold text-slate-900">{editingId ? 'Edit Jurnal' : 'Tambah Jurnal Baru'}</h3>
                      <button onClick={closeModal} className="text-slate-400 hover:text-red-500 transition-colors">
                          <span className="material-symbols-outlined">close</span>
                      </button>
                  </div>

                  <form onSubmit={handleSave} className="p-6 space-y-6">
                       {/* Form Fields (Same as previous turn) */}
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Tanggal</label>
                              <input 
                                type="date" required 
                                className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary"
                                value={formData.date}
                                onChange={e => setFormData({...formData, date: e.target.value})}
                              />
                          </div>
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Jadwal / Jam Mengajar <span className="text-red-500">*</span></label>
                              <select 
                                required
                                className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary"
                                value={formData.scheduleId}
                                onChange={e => handleScheduleChange(e.target.value)}
                              >
                                  <option value="">-- Pilih Jadwal (Wajib) --</option>
                                  {schedules.map(s => (
                                      <option key={s.id} value={s.id}>{s.day} {s.startTime}-{s.endTime} | {s.className} | {s.subject}</option>
                                  ))}
                              </select>
                          </div>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-slate-50 p-4 rounded-xl border border-slate-100">
                          <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Mata Pelajaran <span className="text-slate-400">(Otomatis)</span></label>
                                <input 
                                    type="text" readOnly
                                    className="w-full rounded-lg border-slate-200 bg-slate-100 text-sm font-bold text-slate-700 cursor-not-allowed focus:ring-0"
                                    value={formData.subjectName}
                                    placeholder="Pilih jadwal dulu..."
                                />
                          </div>
                          <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Kelas <span className="text-slate-400">(Otomatis)</span></label>
                                <input 
                                    type="text" readOnly
                                    className="w-full rounded-lg border-slate-200 bg-slate-100 text-sm font-bold text-slate-700 cursor-not-allowed focus:ring-0"
                                    value={formData.className}
                                    placeholder="Pilih jadwal dulu..."
                                />
                          </div>
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Jam Mulai</label>
                              <input type="time" readOnly className="w-full rounded-lg border-slate-200 bg-slate-100 text-sm font-bold text-slate-700" value={formData.startTime} />
                          </div>
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Jam Selesai</label>
                              <input type="time" readOnly className="w-full rounded-lg border-slate-200 bg-slate-100 text-sm font-bold text-slate-700" value={formData.endTime} />
                          </div>
                      </div>

                      <div className="bg-white border border-slate-200 p-4 rounded-xl space-y-4">
                          <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Tujuan Pembelajaran (TP) <span className="text-red-500">*</span></label>
                                <select 
                                    required
                                    className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary"
                                    value={formData.tpId}
                                    onChange={e => setFormData({...formData, tpId: e.target.value, lmId: ''})}
                                >
                                    <option value="">-- Pilih TP --</option>
                                    {tps.map(tp => (
                                        <option key={tp.id} value={tp.id}>{tp.code} - {tp.description}</option>
                                    ))}
                                </select>
                          </div>
                          <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Lingkup Materi (LM)</label>
                                <select 
                                    className="w-full rounded-lg border-slate-200 text-sm font-bold text-slate-900 focus:ring-primary"
                                    value={formData.lmId}
                                    onChange={e => setFormData({...formData, lmId: e.target.value})}
                                    disabled={!formData.tpId}
                                >
                                    <option value="">-- Pilih Materi (Opsional) --</option>
                                    {availableLMs.map(lm => (
                                        <option key={lm.id} value={lm.id}>{lm.code} - {lm.title}</option>
                                    ))}
                                </select>
                          </div>
                      </div>

                      <div className="space-y-1">
                          <label className="text-xs font-bold text-slate-500 uppercase">Detail Kegiatan Pembelajaran <span className="text-red-500">*</span></label>
                          <textarea 
                             required rows={3}
                             className="w-full rounded-lg border-slate-200 text-sm text-slate-900 focus:ring-primary"
                             placeholder="Deskripsikan aktivitas yang dilakukan..."
                             value={formData.activity}
                             onChange={e => setFormData({...formData, activity: e.target.value})}
                          />
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Refleksi Guru</label>
                              <textarea 
                                rows={3}
                                className="w-full rounded-lg border-slate-200 text-sm text-slate-900 focus:ring-primary"
                                placeholder="Apa yang berhasil? Apa yang perlu diperbaiki?"
                                value={formData.reflection}
                                onChange={e => setFormData({...formData, reflection: e.target.value})}
                                />
                          </div>
                          <div className="space-y-1">
                              <label className="text-xs font-bold text-slate-500 uppercase">Tindak Lanjut</label>
                              <textarea 
                                rows={3}
                                className="w-full rounded-lg border-slate-200 text-sm text-slate-900 focus:ring-primary"
                                placeholder="Rencana pertemuan selanjutnya..."
                                value={formData.followUp}
                                onChange={e => setFormData({...formData, followUp: e.target.value})}
                                />
                          </div>
                      </div>

                      <div className="pt-4 flex gap-3 border-t border-slate-100">
                          <button type="button" onClick={closeModal} className="flex-1 py-3 border border-slate-200 rounded-xl text-sm font-bold text-slate-600 hover:bg-slate-50">Batal</button>
                          <button type="submit" className="flex-1 py-3 bg-primary text-white rounded-xl text-sm font-bold hover:bg-blue-600 shadow-lg shadow-blue-200">Simpan Jurnal</button>
                      </div>
                  </form>
              </div>
          </div>
      )}

    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import ExcelJS from 'exceljs';
import { LearningMaterial, LearningObjective, Subject, AssessmentCriteria, IdentityData } from '../types';

declare const Swal: any;

interface Props {
  identity: IdentityData;
  subject: Subject;
  tps: LearningObjective[];
  onUpdateSubject: (kktp: number) => void;
  onUpdateTPs: (tps: LearningObjective[]) => void;
  onBack: () => void;
}

// Mock Data for Scopes
const SD_SUBJECTS = [
    { id: 'math', name: 'Matematika' },
    { id: 'indo', name: 'B. Indonesia' },
    { id: 'ipas', name: 'IPAS' },
    { id: 'ppkn', name: 'PPKn' },
    { id: 'sbura', name: 'Seni Budaya' },
];

const SMP_LEVELS = [
    { id: 'lvl-7', name: 'Kelas 7 (Fase D)' },
    { id: 'lvl-8', name: 'Kelas 8 (Fase D)' },
    { id: 'lvl-9', name: 'Kelas 9 (Fase D)' },
];

const SMA_LEVELS = [
    { id: 'lvl-10', name: 'Kelas 10 (Fase E)' },
    { id: 'lvl-11', name: 'Kelas 11 (Fase F)' },
    { id: 'lvl-12', name: 'Kelas 12 (Fase F)' },
];

export const CurriculumManager: React.FC<Props> = ({ 
  identity, subject, tps, onUpdateSubject, onUpdateTPs, onBack 
}) => {
  const [expandedTpId, setExpandedTpId] = useState<string | null>(null);

  // DETERMINE CONTEXT (Scope)
  const scopes = useMemo(() => {
      if (identity.level === 'SD') return SD_SUBJECTS;
      else if (identity.level === 'SMP') return SMP_LEVELS;
      else return SMA_LEVELS;
  }, [identity.level]);

  const [activeScopeId, setActiveScopeId] = useState<string>(scopes[0].id);

  useEffect(() => {
      const exists = scopes.find(s => s.id === activeScopeId);
      if (!exists) setActiveScopeId(scopes[0].id);
  }, [scopes, activeScopeId]);

  // Filter TPs based on Active Scope
  const filteredTPs = useMemo(() => {
      return tps.filter(tp => tp.scopeId === activeScopeId);
  }, [tps, activeScopeId]);

  // TP Form State
  const [isAddingTp, setIsAddingTp] = useState(false);
  const [newTpForm, setNewTpForm] = useState({ code: '', description: '', semester: '1' });

  // Sub-item Form State (LM & Criteria)
  const [newItemForm, setNewItemForm] = useState<{
      type: 'LM' | 'CRITERIA' | null, 
      parentId: string | null,
      val1: string, // Code
      val2: string // Title/Description
  }>({ type: null, parentId: null, val1: '', val2: '' });

  // --- EXPORT FUNCTION ---
  const handleExportCurriculum = async () => {
    if (filteredTPs.length === 0) return;

    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet('Kurikulum');

    // Headers
    const headerRow = sheet.addRow([
        'No', 
        'Semester', 
        'Mata Pelajaran', 
        'Lingkup Materi (Scope/Fase)', 
        'Kelas', 
        'Tujuan Pembelajaran (TP)', 
        'Lingkup Materi (LM) Detail'
    ]);

    // Style Headers
    headerRow.eachCell((cell) => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } };
        cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
    });

    const activeScopeName = scopes.find(s => s.id === activeScopeId)?.name || activeScopeId;
    const mapelName = identity.level === 'SD' ? activeScopeName : identity.subjectName; // Logic: di SD scope adalah Mapel, di SMA scope adalah Fase/Kelas

    let rowIndex = 1;

    filteredTPs.forEach((tp) => {
        // Jika ada LM, buat baris untuk setiap LM. Jika tidak, buat 1 baris untuk TP saja.
        if (tp.lms.length > 0) {
            tp.lms.forEach(lm => {
                const row = sheet.addRow([
                    rowIndex,
                    `Semester ${tp.semester}`,
                    mapelName,
                    activeScopeName, // Scope/Phase context
                    identity.level,
                    `${tp.code} - ${tp.description}`,
                    `${lm.code} - ${lm.title}`
                ]);
                // Styling per cell
                row.eachCell((cell) => {
                    cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                    cell.alignment = { vertical: 'top', wrapText: true };
                });
            });
        } else {
             const row = sheet.addRow([
                    rowIndex,
                    `Semester ${tp.semester}`,
                    mapelName,
                    activeScopeName,
                    identity.level,
                    `${tp.code} - ${tp.description}`,
                    '-'
            ]);
            row.eachCell((cell) => {
                cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                cell.alignment = { vertical: 'top', wrapText: true };
            });
        }
        rowIndex++;
    });

    // Column Widths
    sheet.getColumn(6).width = 50; // TP Description
    sheet.getColumn(7).width = 40; // LM Detail
    sheet.getColumn(3).width = 20; // Mapel
    sheet.getColumn(4).width = 25; // Scope

    // Download
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `Kurikulum_${activeScopeName.replace(/\s/g, '_')}.xlsx`;
    anchor.click();
    window.URL.revokeObjectURL(url);
  };

  // --- TP CRUD ---
  const handleAddTP = () => {
    if(!newTpForm.code || !newTpForm.description) return;
    const newTp: LearningObjective = {
        id: Date.now().toString(),
        code: newTpForm.code.toUpperCase(), 
        description: newTpForm.description,
        semester: Number(newTpForm.semester) as 1 | 2,
        scopeId: activeScopeId, 
        lms: [],
        criteria: []
    };
    onUpdateTPs([...tps, newTp]);
    setIsAddingTp(false);
    setNewTpForm({ code: '', description: '', semester: '1' });
  };

  const handleDeleteTP = (id: string) => {
      Swal.fire({
          title: 'Hapus Tujuan Pembelajaran?',
          text: "Seluruh Lingkup Materi (LM) dan Kriteria yang ada di dalamnya akan ikut terhapus!",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Ya, hapus!',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateTPs(tps.filter(t => t.id !== id));
              Swal.fire('Terhapus!', 'TP berhasil dihapus.', 'success')
          }
      });
  };

  // --- NESTED ITEMS CRUD ---
  const handleAddItem = () => {
      if(!newItemForm.val1 || !newItemForm.val2 || !newItemForm.parentId || !newItemForm.type) return;

      const updatedTPs = tps.map(tp => {
          if(tp.id === newItemForm.parentId) {
              if(newItemForm.type === 'LM') {
                  return {
                      ...tp,
                      lms: [...tp.lms, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), 
                          title: newItemForm.val2 
                      }]
                  };
              } else {
                  return {
                      ...tp,
                      criteria: [...tp.criteria, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), 
                          description: newItemForm.val2 
                      }]
                  };
              }
          }
          return tp;
      });

      onUpdateTPs(updatedTPs);
      setNewItemForm({ type: null, parentId: null, val1: '', val2: '' });
  };

  const handleDeleteSubItem = (tpId: string, itemId: string, type: 'LM' | 'CRITERIA') => {
      Swal.fire({
          title: 'Hapus Item?',
          text: "Item ini akan dihapus permanen.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Hapus',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              const updatedTPs = tps.map(tp => {
                  if(tp.id === tpId) {
                      if(type === 'LM') {
                          return { ...tp, lms: tp.lms.filter(l => l.id !== itemId) };
                      } else {
                          return { ...tp, criteria: tp.criteria.filter(c => c.id !== itemId) };
                      }
                  }
                  return tp;
              });
              onUpdateTPs(updatedTPs);
          }
      });
  };

  return (
    <div className="h-full flex flex-col bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Header Title */}
        <div className="bg-gray-50 p-6 border-b flex justify-between items-center">
            <div>
                <h2 className="text-xl font-bold text-gray-800">Manajemen Kurikulum & Asesmen</h2>
                <p className="text-sm text-gray-500">
                    {identity.level === 'SD' 
                        ? 'Pengaturan TP per Mata Pelajaran (Jenjang SD)' 
                        : 'Pengaturan TP per Tingkat Kelas (Jenjang SMP/SMA/SMK)'}
                </p>
            </div>
             <button onClick={onBack} className="text-gray-500 hover:text-gray-700 font-medium">
                &larr; Kembali
            </button>
        </div>

        {/* Top Control Bar (Dropdown & KKTP) */}
        <div className="px-6 py-4 bg-white border-b flex flex-col md:flex-row gap-4 justify-between items-end md:items-center">
            <div className="flex flex-col md:flex-row gap-6 w-full md:w-auto">

                {/* Scope/Class Selector */}
                <div className="w-full md:w-64">
                    <label className="text-xs font-bold text-gray-500 uppercase block mb-1">
                        {identity.level === 'SD' ? 'Mata Pelajaran' : 'Pilih Tingkat Kelas'}
                    </label>
                    <div className="relative">
                        <select 
                            value={activeScopeId} 
                            onChange={(e) => setActiveScopeId(e.target.value)}
                            className="w-full appearance-none pl-10 pr-8 py-2 border border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-2 focus:ring-primary focus:border-transparent outline-none cursor-pointer bg-white"
                        >
                            {scopes.map(scope => (
                                <option key={scope.id} value={scope.id}>{scope.name}</option>
                            ))}
                        </select>
                        <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-500 pointer-events-none text-lg">
                            {identity.level === 'SD' ? 'menu_book' : 'school'}
                        </span>
                        <span className="material-symbols-outlined absolute right-2 top-2.5 text-slate-400 pointer-events-none text-sm">expand_more</span>
                    </div>
                </div>

                {/* KKTP Input */}
                <div className="w-full md:w-32">
                    <label className="text-xs font-bold text-gray-500 uppercase block mb-1">KKTP</label>
                    <div className="relative">
                        <input 
                            type="number" 
                            value={subject.kktp} 
                            onChange={(e) => onUpdateSubject(Number(e.target.value))}
                            className="w-full pl-3 pr-8 py-2 border border-slate-300 rounded-lg text-sm font-bold text-blue-700 focus:ring-2 focus:ring-blue-500 outline-none"
                        />
                        <span className="absolute right-3 top-2 text-xs font-bold text-slate-400">Poin</span>
                    </div>
                </div>
            </div>

            <div className="flex gap-3">
                 <button 
                    onClick={handleExportCurriculum}
                    disabled={filteredTPs.length === 0}
                    className="flex items-center gap-2 px-4 py-2.5 bg-green-600 text-white rounded-lg text-sm font-bold hover:bg-green-700 transition-colors shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    <span className="material-symbols-outlined text-sm">table_view</span>
                    Export Excel
                </button>
                <button 
                    onClick={() => setIsAddingTp(!isAddingTp)}
                    className="flex items-center gap-2 px-4 py-2.5 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 transition-colors shadow-sm"
                >
                    <span className="material-symbols-outlined text-sm">{isAddingTp ? 'remove' : 'add'}</span>
                    Tambah TP
                </button>
            </div>
        </div>

        {/* Main Content Area */}
        <div className="flex-1 flex flex-col overflow-hidden bg-white">

            {/* Add TP Form */}
            {isAddingTp && (
                <div className="mx-6 mt-6 p-4 bg-blue-50 border border-blue-100 rounded-xl animate-in fade-in slide-in-from-top-4">
                    <h4 className="font-bold text-blue-800 mb-3 text-sm">
                        Tambah TP Baru di {scopes.find(s => s.id === activeScopeId)?.name}
                    </h4>
                    <div className="flex gap-3 items-start">
                        <div className="w-24">
                            <input 
                                type="text" placeholder="Kode" 
                                value={newTpForm.code} onChange={e => setNewTpForm({...newTpForm, code: e.target.value.toUpperCase()})}
                                className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900 placeholder:text-slate-400"
                            />
                        </div>
                        <div className="w-24">
                            <select 
                                value={newTpForm.semester} onChange={e => setNewTpForm({...newTpForm, semester: e.target.value})}
                                className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900"
                            >
                                <option value="1">Smt 1</option>
                                <option value="2">Smt 2</option>
                            </select>
                        </div>
                        <div className="flex-1">
                            <input 
                                type="text" placeholder="Deskripsi Tujuan Pembelajaran..." 
                                value={newTpForm.description} onChange={e => setNewTpForm({...newTpForm, description: e.target.value})}
                                className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900"
                            />
                        </div>
                        <button onClick={handleAddTP} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold text-sm hover:bg-blue-700">Simpan</button>
                    </div>
                </div>
            )}

            {/* TP List */}
            <div className="flex-1 overflow-y-auto p-6 space-y-4">
                {filteredTPs.length === 0 && (
                    <div className="text-center py-12 text-gray-400">
                        <span className="material-symbols-outlined text-4xl mb-2">library_books</span>
                        <p>Belum ada Tujuan Pembelajaran untuk {scopes.find(s => s.id === activeScopeId)?.name}.</p>
                    </div>
                )}

                {filteredTPs.map((tp) => {
                    const isExpanded = expandedTpId === tp.id;
                    return (
                        <div key={tp.id} className={`border rounded-xl transition-all ${isExpanded ? 'border-primary shadow-md bg-white' : 'border-slate-200 bg-white hover:border-slate-300'}`}>
                            {/* TP Header */}
                            <div 
                                onClick={() => setExpandedTpId(isExpanded ? null : tp.id)}
                                className="p-4 flex items-center gap-4 cursor-pointer"
                            >
                                <div className={`size-10 rounded-lg flex items-center justify-center font-bold text-sm ${isExpanded ? 'bg-primary text-white' : 'bg-slate-100 text-slate-500'}`}>
                                    {tp.code.toUpperCase()}
                                </div>
                                <div className="flex-1">
                                    <p className={`text-sm font-bold ${isExpanded ? 'text-primary' : 'text-slate-800'}`}>{tp.description}</p>
                                    <div className="flex items-center gap-2 mt-1">
                                        <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500">Semester {tp.semester}</span>
                                        <span className="text-[10px] text-slate-400 flex items-center gap-1">
                                            <span className="material-symbols-outlined text-[10px]">topic</span> {tp.lms.length} LM
