                    {dateString}
                </div>
            </div>
         </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="Kelas Aktif" 
          value={classes.length.toString()} 
          subText="Kelas Terdaftar" 
          subColor="text-green-600" 
          bgIcon="bg-blue-50 text-blue-600" 
          icon="school" 
        />
        <StatCard 
          title="Total Siswa" 
