          </div>

          <div className="flex flex-col gap-4">
            {todaysSchedules.length > 0 ? (
                todaysSchedules.map(schedule => (
                    <ScheduleCard 
                        key={schedule.id}
                        {...schedule}
                        currentTime={currentTime}
                        onNavigate={onNavigate}
