                {activeTab === TabView.JOURNAL && (
                    <JournalManager 
                        journals={journals}
                        onUpdateJournals={setJournals}
                        tps={tps}
                        schedules={schedules}
                        classes={classes}
                        initialContext={navContext}
                        onBack={() => handleContextNavigate(TabView.DASHBOARD)}
