      } catch (e: any) {
          Swal.fire('Error', e.message, 'error');
      }
  };

  const handleUpdateUser = async (id: string, data: RegisterData) => {
     try {
         const { error } = await supabase.from('teachers').update({
             full_name: data.name,
             email: data.email,
             role: data.role,
             level: data.level
