                                <span className="text-sm font-bold">Memuat Modul AI...</span>
                             </div>
                        </div>
                    }>
                        <CPGenerator 
                            onSave={handleSaveGeneratedTPs}
                            onBack={() => handleContextNavigate(TabView.DASHBOARD)}
                        />
                    </Suspense>
                )}

                {activeTab === TabView.CLASS_MASTER && (
                    <ClassManager 
                        identity={identity}
                        classes={classes}
                        students={students}
                        onUpdateClasses={setClasses}
                        onBack={() => handleContextNavigate(TabView.DASHBOARD)} 
