  // =================================================================================
  // 7. NAVIGATION HANDLERS (Missing in previous context)
  // =================================================================================

  const handleContextNavigate = useCallback((tab: TabView, context: { className?: string, scheduleId?: string } = {}) => {
    if (context.className || context.scheduleId) {
