  // --- VIEW STATE ---
  const [activeTab, setActiveTab] = useState<TabView>(TabView.LOGIN);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false); // Sidebar State

  // --- APP DATA STATE (Per User) ---
