import React, { useState } from 'react';
import { ScheduleItem, ClassInfo } from '../types';

declare const Swal: any;

interface Props {
  schedules: ScheduleItem[];
  classes: ClassInfo[]; // Recieve classes for dropdown
  onUpdateSchedules: (schedules: ScheduleItem[]) => void;
  onBack: () => void;
}

const DAYS = ['Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];

// Helper for Title Case
const toTitleCase = (str: string) => {
    return str.toLowerCase().replace(/\b\w/g, s => s.toUpperCase());
};

export const ScheduleManager: React.FC<Props> = ({ schedules, classes, onUpdateSchedules, onBack }) => {
  const [activeDay, setActiveDay] = useState<string>('Senin');
  const [searchQuery, setSearchQuery] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState<Omit<ScheduleItem, 'id'>>({
    day: 'Senin',
    startTime: '07:30',
    endTime: '09:00',
    className: '',
    subject: '',
    room: ''
  });

  const filteredSchedules = schedules
    .filter(s => {
        const matchesDay = s.day === activeDay;
        const query = searchQuery.toLowerCase();
        const matchesSearch = s.subject.toLowerCase().includes(query) || 
                              s.className.toLowerCase().includes(query) ||
                              s.room.toLowerCase().includes(query);
        return matchesDay && matchesSearch;
    })
    .sort((a, b) => a.startTime.localeCompare(b.startTime));

  const handleOpenModal = (schedule?: ScheduleItem) => {
    // VALIDATION: Prevent adding schedule if no classes exist
    if (!schedule && classes.length === 0) {
        Swal.fire({
            title: 'Data Kelas Kosong',
            text: 'Anda belum memiliki data Kelas. Silahkan buat Kelas terlebih dahulu di menu "Master Kelas" sebelum membuat jadwal.',
            icon: 'warning',
            confirmButtonText: 'Oke, Mengerti',
            confirmButtonColor: '#137fec'
        });
        return;
    }

    if (schedule) {
        setEditingId(schedule.id);
        setFormData({
            day: schedule.day,
            startTime: schedule.startTime,
            endTime: schedule.endTime,
            className: schedule.className,
            subject: schedule.subject,
            room: schedule.room
        });
    } else {
        setEditingId(null);
        // Default to first class if available
        const defaultClass = classes.length > 0 ? classes[0].name : '';
        setFormData({
            day: activeDay,
            startTime: '07:30',
            endTime: '09:00',
            className: defaultClass,
            subject: '',
            room: ''
        });
    }
    setIsModalOpen(true);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    // 1. VALIDATION: Check for empty fields
    if (!formData.day || !formData.startTime || !formData.endTime || !formData.className || !formData.subject.trim() || !formData.room.trim()) {
         Swal.fire({
              title: 'Gagal Menyimpan',
              text: "Semua kolom (Hari, Jam, Kelas, Mapel, Ruangan) wajib diisi!",
              icon: 'error',
              confirmButtonColor: '#d33',
              confirmButtonText: 'OK'
          });
          return;
    }

    // 2. AUTO-CAPITALIZE FIELDS
    const formattedData = {
        ...formData,
        className: formData.className, // Already selected from dropdown (exact value)
        subject: toTitleCase(formData.subject),
        room: toTitleCase(formData.room)
    };

    if (editingId) {
        // Update
        const updated = schedules.map(s => s.id === editingId ? { ...formattedData, id: editingId } : s);
        onUpdateSchedules(updated);
    } else {
        // Add
        const newItem: ScheduleItem = {
            id: Date.now().toString(),
            ...formattedData
        };
        onUpdateSchedules([...schedules, newItem]);
    }
    setIsModalOpen(false);

    Swal.fire({
          title: 'Berhasil!',
          text: 'Jadwal telah disimpan.',
          icon: 'success',
          timer: 1500,
          showConfirmButton: false
    });
  };

  const handleDelete = (id: string) => {
      Swal.fire({
          title: 'Hapus Jadwal?',
          text: "Jadwal yang dihapus tidak dapat dikembalikan!",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Ya, hapus!',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateSchedules(schedules.filter(s => s.id !== id));
              Swal.fire(
                  'Terhapus!',
                  'Jadwal berhasil dihapus.',
                  'success'
              )
          }
      });
  };

  return (
    <div className="w-full max-w-7xl mx-auto">
      {/* Breadcrumbs */}
      <div className="flex items-center gap-2 mb-4">
        <button onClick={onBack} className="text-slate-500 text-sm font-medium hover:text-primary">Beranda</button>
        <span className="text-slate-400 text-sm font-medium">/</span>
        <span className="text-primary text-sm font-bold">Master Jadwal Pelajaran</span>
      </div>

      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <div className="flex flex-col gap-1">
          <h2 className="text-slate-900 text-3xl font-extrabold tracking-tight">Master Jadwal Mengajar</h2>
          <p className="text-slate-500 text-base font-normal">Atur jadwal pertemuan tatap muka per kelas dan hari.</p>
        </div>
        <button 
            onClick={() => handleOpenModal()}
            className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 transition-colors shadow-lg shadow-blue-200"
        >
            <span className="material-symbols-outlined text-sm">add_circle</span>
            Tambah Jadwal
        </button>
      </div>

      {/* Day Tabs */}
      <div className="flex gap-2 mb-6 overflow-x-auto pb-2">
        {DAYS.map(day => (
            <button
                key={day}
                onClick={() => setActiveDay(day)}
                className={`px-6 py-2 rounded-full text-sm font-bold transition-all whitespace-nowrap ${
                    activeDay === day 
                    ? 'bg-primary text-white shadow-md ring-2 ring-primary/20' 
                    : 'bg-white text-slate-500 border border-slate-200 hover:bg-slate-50'
                }`}
            >
                {day}
            </button>
        ))}
      </div>

      {/* Schedule Table */}
      <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden min-h-[400px]">

        {/* Toolbar - Consistent with other managers */}
        <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
           <div className="relative">
             <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-400 text-lg">search</span>
             <input 
                type="text" 
                placeholder="Cari mapel, kelas, ruang..." 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10 pr-4 py-2 border border-slate-200 rounded-lg text-sm font-bold text-slate-900 w-72 focus:ring-2 focus:ring-primary focus:border-transparent outline-none placeholder:text-slate-400 bg-white" 
             />
           </div>
           <div className="flex gap-2">
             <button className="p-2 text-slate-500 hover:text-primary hover:bg-white rounded border border-transparent hover:border-slate-200 transition-all"><span className="material-symbols-outlined">filter_list</span></button>
           </div>
        </div>

        {filteredSchedules.length > 0 ? (
            <>
            <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
                <thead>
                <tr className="bg-slate-50 border-b border-slate-200">
                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider w-32">Jam Mulai</th>
                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider w-32">Jam Selesai</th>
                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Kelas</th>
                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Mata Pelajaran</th>
                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Ruangan</th>
                    <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">Aksi</th>
                </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                {filteredSchedules.map((item) => (
                    <tr key={item.id} className="hover:bg-slate-50 transition-colors group cursor-pointer">
                    <td className="px-6 py-4 font-mono text-sm font-bold text-slate-600">{item.startTime}</td>
                    <td className="px-6 py-4 font-mono text-sm font-bold text-slate-400">{item.endTime}</td>
                    <td className="px-6 py-4">
                        <span className="px-2.5 py-1 rounded text-xs font-bold bg-blue-100 text-blue-700">
                            {item.className}
                        </span>
                    </td>
                    <td className="px-6 py-4 font-bold text-slate-800">{item.subject}</td>
                    <td className="px-6 py-4 text-sm text-slate-500 flex items-center gap-2">
                        <span className="material-symbols-outlined text-lg text-slate-400">meeting_room</span>
                        {item.room}
                    </td>
                    <td className="px-6 py-4 text-right">
                        <div className="flex justify-end gap-2">
                        <button onClick={() => handleOpenModal(item)} className="p-2 bg-blue-50 text-blue-600 hover:bg-blue-100 rounded-lg transition-colors" title="Edit">
                            <span className="material-symbols-outlined text-sm">edit</span>
                        </button>
                        <button onClick={() => handleDelete(item.id)} className="p-2 bg-red-50 text-red-600 hover:bg-red-100 rounded-lg transition-colors" title="Delete">
                            <span className="material-symbols-outlined text-sm">delete</span>
                        </button>
                        </div>
                    </td>
                    </tr>
                ))}
                </tbody>
            </table>
            </div>

            {/* Footer */}
            <div className="px-6 py-4 border-t border-slate-200 flex items-center justify-between bg-slate-50/50">
                <p className="text-sm text-slate-500">Menampilkan {filteredSchedules.length} jadwal hari {activeDay}</p>
                <div className="flex gap-2">
                    <button className="p-2 border border-slate-200 rounded-lg text-slate-400 hover:bg-slate-50 disabled:opacity-50" disabled>
                        <span className="material-symbols-outlined text-sm">chevron_left</span>
                    </button>
                    <button className="px-3 py-1 bg-primary text-white rounded-lg text-sm font-bold">1</button>
                    <button className="p-2 border border-slate-200 rounded-lg text-slate-600 hover:bg-slate-50">
                        <span className="material-symbols-outlined text-sm">chevron_right</span>
                    </button>
                </div>
            </div>
            </>
        ) : (
            <div className="flex flex-col items-center justify-center h-80 text-slate-400">
                <span className="material-symbols-outlined text-4xl mb-2 text-slate-300">event_busy</span>
                <p>Tidak ada jadwal untuk hari {activeDay} {searchQuery && 'yang cocok'}</p>
                {!searchQuery && (
                    <button onClick={() => handleOpenModal()} className="mt-4 text-primary text-sm font-bold hover:underline">Tambah Jadwal Hari Ini</button>
                )}
            </div>
        )}
      </div>

       {/* Modal Form */}
       {isModalOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
              <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl transform transition-all scale-100">
                  <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                      <h3 className="text-xl font-bold text-slate-900">{editingId ? 'Edit Jadwal' : 'Tambah Jadwal Baru'}</h3>
                      <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-red-500 transition-colors">
                          <span className="material-symbols-outlined">close</span>
                      </button>
                  </div>
                  <form onSubmit={handleSave} className="p-6 space-y-4">
                      <div className="space-y-2">
                          <label className="text-sm font-bold text-slate-700">Hari <span className="text-red-500">*</span></label>
                          <select 
                             required
                             className="w-full rounded-lg border-slate-200 focus:ring-2 focus:ring-primary focus:border-transparent text-sm font-bold text-slate-900 bg-white"
                             value={formData.day}
                             onChange={(e) => setFormData({...formData, day: e.target.value})}
                          >
                              {DAYS.map(d => <option key={d} value={d}>{d}</option>)}
                          </select>
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-sm font-bold text-slate-700">Jam Mulai <span className="text-red-500">*</span></label>
                            <input 
                                type="time" 
                                required
                                className="w-full rounded-lg border-slate-200 focus:ring-2 focus:ring-primary focus:border-transparent text-sm font-bold text-slate-900 bg-white"
                                value={formData.startTime}
                                onChange={(e) => setFormData({...formData, startTime: e.target.value})}
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-bold text-slate-700">Jam Selesai <span className="text-red-500">*</span></label>
                            <input 
                                type="time" 
                                required
                                className="w-full rounded-lg border-slate-200 focus:ring-2 focus:ring-primary focus:border-transparent text-sm font-bold text-slate-900 bg-white"
                                value={formData.endTime}
                                onChange={(e) => setFormData({...formData, endTime: e.target.value})}
                            />
                        </div>
                      </div>

                      {/* Class Dropdown Selection */}
                      <div className="space-y-2">
                          <label className="text-sm font-bold text-slate-700">Kelas <span className="text-red-500">*</span></label>
                          <select 
                              required
                              className="w-full rounded-lg border-slate-200 focus:ring-2 focus:ring-primary focus:border-transparent text-sm font-bold text-slate-900 bg-white cursor-pointer"
                              value={formData.className}
                              onChange={(e) => setFormData({...formData, className: e.target.value})}
                          >
                              <option value="">-- Pilih Kelas --</option>
                              {classes.map(cls => (
                                  <option key={cls.id} value={cls.name}>{cls.name}</option>
                              ))}
                          </select>
                      </div>

                      <div className="space-y-2">
                          <label className="text-sm font-bold text-slate-700">Mata Pelajaran <span className="text-red-500">*</span></label>
                          <input 
                              type="text" 
                              required
                              placeholder="Nama Mapel"
                              className="w-full rounded-lg border-slate-200 focus:ring-2 focus:ring-primary focus:border-transparent text-sm font-bold text-slate-900 bg-white"
                              value={formData.subject}
                              onChange={(e) => setFormData({...formData, subject: e.target.value})}
                          />
                      </div>
                       <div className="space-y-2">
                          <label className="text-sm font-bold text-slate-700">Ruangan <span className="text-red-500">*</span></label>
                          <input 
                              type="text" 
                              required
                              placeholder="Contoh: Lab Komputer"
                              className="w-full rounded-lg border-slate-200 focus:ring-2 focus:ring-primary focus:border-transparent text-sm font-bold text-slate-900 bg-white"
                              value={formData.room}
                              onChange={(e) => setFormData({...formData, room: e.target.value})}
                          />
                      </div>

                      <div className="pt-4 flex gap-3">
                          <button 
                              type="button" 
                              onClick={() => setIsModalOpen(false)}
                              className="flex-1 py-2.5 border border-slate-200 rounded-lg text-sm font-bold text-slate-600 hover:bg-slate-50"
                          >
                              Batal
                          </button>
                          <button 
                              type="submit" 
                              className="flex-1 py-2.5 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 shadow-md shadow-blue-200"
                          >
                              Simpan
                          </button>
                      </div>
                  </form>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import ExcelJS from 'exceljs';
import { LearningMaterial, LearningObjective, Subject, AssessmentCriteria, IdentityData, AssessmentType } from '../types';
import { GoogleGenAI, Type } from "@google/genai";

declare const Swal: any;

interface Props {
  identity: IdentityData;
  subject: Subject;
  tps: LearningObjective[];
  onUpdateSubject: (kktp: number) => void;
  onUpdateTPs: (tps: LearningObjective[]) => void;
  onBack: () => void;
}

// Mock Data for Scopes
const SD_SUBJECTS = [
    { id: 'math', name: 'Matematika' },
    { id: 'indo', name: 'B. Indonesia' },
    { id: 'ipas', name: 'IPAS' },
    { id: 'ppkn', name: 'PPKn' },
    { id: 'sbura', name: 'Seni Budaya' },
];

const SMP_LEVELS = [
    { id: 'lvl-7', name: 'Kelas 7 (Fase D)' },
    { id: 'lvl-8', name: 'Kelas 8 (Fase D)' },
    { id: 'lvl-9', name: 'Kelas 9 (Fase D)' },
];

const SMA_LEVELS = [
    { id: 'lvl-10', name: 'Kelas 10 (Fase E)' },
    { id: 'lvl-11', name: 'Kelas 11 (Fase F)' },
    { id: 'lvl-12', name: 'Kelas 12 (Fase F)' },
];

export const CurriculumManager: React.FC<Props> = ({ 
  identity, subject, tps, onUpdateSubject, onUpdateTPs, onBack 
}) => {
  const [expandedTpId, setExpandedTpId] = useState<string | null>(null);
  const [generatingTpId, setGeneratingTpId] = useState<string | null>(null);

  // DETERMINE CONTEXT (Scope)
  const scopes = useMemo(() => {
      if (identity.level === 'SD') return SD_SUBJECTS;
      else if (identity.level === 'SMP') return SMP_LEVELS;
      else return SMA_LEVELS;
  }, [identity.level]);

  const [activeScopeId, setActiveScopeId] = useState<string>(scopes[0].id);

  useEffect(() => {
      const exists = scopes.find(s => s.id === activeScopeId);
      if (!exists) setActiveScopeId(scopes[0].id);
  }, [scopes, activeScopeId]);

  // Filter TPs based on Active Scope
  const filteredTPs = useMemo(() => {
      return tps.filter(tp => tp.scopeId === activeScopeId);
  }, [tps, activeScopeId]);

  // TP Form State
  const [isAddingTp, setIsAddingTp] = useState(false);
  const [newTpForm, setNewTpForm] = useState({ code: '', description: '', semester: '1' });

  // Sub-item Form State (LM & Criteria)
  const [newItemForm, setNewItemForm] = useState<{
      type: 'LM' | 'CRITERIA' | null, 
      parentId: string | null,
      val1: string, // Code
      val2: string // Title/Description
  }>({ type: null, parentId: null, val1: '', val2: '' });

  // Add state for Item Type (Formative/Summative)
  const [newItemType, setNewItemType] = useState<AssessmentType>('FORMATIVE');

  // --- AI GENERATION LOGIC FOR TP DETAILS ---
  const generateTpDetails = async (tp: LearningObjective) => {
      setGeneratingTpId(tp.id);

      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
          const prompt = `
            Role: Expert Curriculum Developer for Indonesian School (Kurikulum Merdeka).
            Context: Subject '${identity.subjectName}' for Grade '${identity.level}'.
            Task: Based on the Learning Objective (TP) below, generate strictly:
            1. 3 specific 'Lingkup Materi' (Learning Materials/Scope) titles.
            2. 3 specific 'Assessment Criteria' (Kriteria Ketercapaian TP). Ensure mixed types (Formatif/Sumatif).

            TP Description: "${tp.description}" (Code: ${tp.code})

            Output must be valid JSON object with arrays 'lms' and 'criteria'.
          `;

          const response = await ai.models.generateContent({
              model: "gemini-3-flash-preview",
              contents: prompt,
              config: {
                  responseMimeType: "application/json",
                  responseSchema: {
                      type: Type.OBJECT,
                      properties: {
                          lms: {
                              type: Type.ARRAY,
                              items: {
                                  type: Type.OBJECT,
                                  properties: {
                                      code: { type: Type.STRING, description: "Example: LM.1" },
                                      title: { type: Type.STRING, description: "Material title" }
                                  }
                              }
                          },
                          criteria: {
                              type: Type.ARRAY,
                              items: {
                                  type: Type.OBJECT,
                                  properties: {
                                      code: { type: Type.STRING, description: "Example: KR.1" },
                                      description: { type: Type.STRING, description: "Assessment criteria description" },
                                      type: { type: Type.STRING, enum: ["FORMATIVE", "SUMMATIVE"], description: "Assessment type" }
                                  }
                              }
                          }
                      }
                  }
              }
          });

          const json = JSON.parse(response.text || '{}');

          if (json.lms && json.criteria) {
              // Map output to internal types
              const newLms: LearningMaterial[] = json.lms.map((lm: any, idx: number) => ({
                  id: `gen-lm-${Date.now()}-${idx}`,
                  code: lm.code || `LM.${idx+1}`,
                  title: lm.title
              }));

              const newCriteria: AssessmentCriteria[] = json.criteria.map((cr: any, idx: number) => ({
                  id: `gen-cr-${Date.now()}-${idx}`,
                  code: cr.code || `KR.${idx+1}`,
                  description: cr.description,
                  type: (cr.type === 'SUMMATIVE' ? 'SUMMATIVE' : 'FORMATIVE') as AssessmentType
              }));

              // Update TP
              const updatedTPs = tps.map(t => {
                  if (t.id === tp.id) {
                      return {
                          ...t,
                          lms: [...t.lms, ...newLms],
                          criteria: [...t.criteria, ...newCriteria]
                      };
                  }
                  return t;
              });

              onUpdateTPs(updatedTPs);
              setExpandedTpId(tp.id); // Auto expand to show results
              Swal.fire({
                  title: 'Generate Berhasil',
                  text: `Ditambahkan ${newLms.length} Materi dan ${newCriteria.length} Kriteria.`,
                  icon: 'success',
                  timer: 2000
              });
          }

      } catch (error: any) {
          console.error(error);
          Swal.fire('Gagal Generate', error.message, 'error');
      } finally {
          setGeneratingTpId(null);
      }
  };

  // --- EXPORT FUNCTION ---
  const handleExportCurriculum = async () => {
    if (filteredTPs.length === 0) return;

    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet('Kurikulum');

    // Headers
    const headerRow = sheet.addRow([
        'No', 
        'Semester', 
        'Mata Pelajaran', 
        'Lingkup Materi (Scope/Fase)', 
        'Kelas', 
        'Tujuan Pembelajaran (TP)', 
        'Lingkup Materi (LM) Detail'
    ]);

    // Style Headers
    headerRow.eachCell((cell) => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } };
        cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
    });

    const activeScopeName = scopes.find(s => s.id === activeScopeId)?.name || activeScopeId;
    const mapelName = identity.level === 'SD' ? activeScopeName : identity.subjectName; // Logic: di SD scope adalah Mapel, di SMA scope adalah Fase/Kelas

    let rowIndex = 1;

    filteredTPs.forEach((tp) => {
        // Jika ada LM, buat baris untuk setiap LM. Jika tidak, buat 1 baris untuk TP saja.
        if (tp.lms.length > 0) {
            tp.lms.forEach(lm => {
                const row = sheet.addRow([
                    rowIndex,
                    `Semester ${tp.semester}`,
                    mapelName,
                    activeScopeName, // Scope/Phase context
                    identity.level,
                    `${tp.code} - ${tp.description}`,
                    `${lm.code} - ${lm.title}`
                ]);
                // Styling per cell
                row.eachCell((cell) => {
                    cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                    cell.alignment = { vertical: 'top', wrapText: true };
                });
            });
        } else {
             const row = sheet.addRow([
                    rowIndex,
                    `Semester ${tp.semester}`,
                    mapelName,
                    activeScopeName,
                    identity.level,
                    `${tp.code} - ${tp.description}`,
                    '-'
            ]);
            row.eachCell((cell) => {
                cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                cell.alignment = { vertical: 'top', wrapText: true };
            });
        }
        rowIndex++;
    });

    // Column Widths
    sheet.getColumn(6).width = 50; // TP Description
    sheet.getColumn(7).width = 40; // LM Detail
    sheet.getColumn(3).width = 20; // Mapel
    sheet.getColumn(4).width = 25; // Scope

    // Download
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `Kurikulum_${activeScopeName.replace(/\s/g, '_')}.xlsx`;
    anchor.click();
    window.URL.revokeObjectURL(url);
  };

  // --- TP CRUD ---
  const handleAddTP = () => {
    if(!newTpForm.code || !newTpForm.description) return;
    const newTp: LearningObjective = {
        id: Date.now().toString(),
        code: newTpForm.code.toUpperCase(), 
        description: newTpForm.description,
        semester: Number(newTpForm.semester) as 1 | 2,
        scopeId: activeScopeId, 
        lms: [],
        criteria: []
    };
    onUpdateTPs([...tps, newTp]);
    setIsAddingTp(false);
    setNewTpForm({ code: '', description: '', semester: '1' });
  };

  const handleDeleteTP = (id: string) => {
      Swal.fire({
          title: 'Hapus Tujuan Pembelajaran?',
          text: "Seluruh Lingkup Materi (LM) dan Kriteria yang ada di dalamnya akan ikut terhapus!",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Ya, hapus!',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateTPs(tps.filter(t => t.id !== id));
              Swal.fire('Terhapus!', 'TP berhasil dihapus.', 'success')
          }
      });
  };

  // --- NESTED ITEMS CRUD ---
  const handleAddItem = () => {
      if(!newItemForm.val1 || !newItemForm.val2 || !newItemForm.parentId || !newItemForm.type) return;

      const updatedTPs = tps.map(tp => {
          if(tp.id === newItemForm.parentId) {
              if(newItemForm.type === 'LM') {
                  return {
                      ...tp,
                      lms: [...tp.lms, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), 
                          title: newItemForm.val2 
                      }]
                  };
              } else {
                  return {
                      ...tp,
                      criteria: [...tp.criteria, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), 
                          description: newItemForm.val2,
                          type: newItemType // Use the selected state
                      }]
                  };
              }
          }
          return tp;
      });

      onUpdateTPs(updatedTPs);
      setNewItemForm({ type: null, parentId: null, val1: '', val2: '' });
      setNewItemType('FORMATIVE'); // Reset default
  };

  const handleDeleteSubItem = (tpId: string, itemId: string, type: 'LM' | 'CRITERIA') => {
      Swal.fire({
          title: 'Hapus Item?',
          text: "Item ini akan dihapus permanen.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Hapus',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              const updatedTPs = tps.map(tp => {
                  if(tp.id === tpId) {
                      if(type === 'LM') {
                          return { ...tp, lms: tp.lms.filter(l => l.id !== itemId) };
                      } else {
                          return { ...tp, criteria: tp.criteria.filter(c => c.id !== itemId) };
                      }
                  }
                  return tp;
              });
              onUpdateTPs(updatedTPs);
          }
      });
  };

  return (
    <div className="h-full flex flex-col bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Header Title */}
        <div className="bg-gray-50 p-6 border-b flex justify-between items-center">
            <div>
                <h2 className="text-xl font-bold text-gray-800">Manajemen Kurikulum & Asesmen</h2>
                <p className="text-sm text-gray-500">
                    {identity.level === 'SD' 
                        ? 'Pengaturan TP per Mata Pelajaran (Jenjang SD)' 
                        : 'Pengaturan TP per Tingkat Kelas (Jenjang SMP/SMA/SMK)'}
                </p>
            </div>
             <button onClick={onBack} className="text-gray-500 hover:text-gray-700 font-medium">
                &larr; Kembali
            </button>
        </div>

        {/* Top Control Bar (Dropdown & KKTP) */}
        <div className="px-6 py-4 bg-white border-b flex flex-col md:flex-row gap-4 justify-between items-end md:items-center">
            <div className="flex flex-col md:flex-row gap-6 w-full md:w-auto">

                {/* Scope/Class Selector */}
                <div className="w-full md:w-64">
                    <label className="text-xs font-bold text-gray-500 uppercase block mb-1">
                        {identity.level === 'SD' ? 'Mata Pelajaran' : 'Pilih Tingkat Kelas'}
                    </label>
                    <div className="relative">
                        <select 
                            value={activeScopeId} 
                            onChange={(e) => setActiveScopeId(e.target.value)}
                            className="w-full appearance-none pl-10 pr-8 py-2 border border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-2 focus:ring-primary focus:border-transparent outline-none cursor-pointer bg-white"
                        >
                            {scopes.map(scope => (
                                <option key={scope.id} value={scope.id}>{scope.name}</option>
                            ))}
                        </select>
                        <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-500 pointer-events-none text-lg">
                            {identity.level === 'SD' ? 'menu_book' : 'school'}
                        </span>
                        <span className="material-symbols-outlined absolute right-2 top-2.5 text-slate-400 pointer-events-none text-sm">expand_more</span>
                    </div>
                </div>

                {/* KKTP Input */}
                <div className="w-full md:w-32">
                    <label className="text-xs font-bold text-gray-500 uppercase block mb-1">KKTP</label>
                    <div className="relative">
                        <input 
                            type="number" 
                            value={subject.kktp} 
                            onChange={(e) => onUpdateSubject(Number(e.target.value))}
                            className="w-full pl-3 pr-8 py-2 border border-slate-300 rounded-lg text-sm font-bold text-blue-700 focus:ring-2 focus:ring-blue-500 outline-none"
                        />
                        <span className="absolute right-3 top-2 text-xs font-bold text-slate-400">Poin</span>
                    </div>
                </div>
            </div>

            <div className="flex gap-3">
                 <button 
                    onClick={handleExportCurriculum}
                    disabled={filteredTPs.length === 0}
                    className="flex items-center gap-2 px-4 py-2.5 bg-green-600 text-white rounded-lg text-sm font-bold hover:bg-green-700 transition-colors shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    <span className="material-symbols-outlined text-sm">table_view</span>
                    Export Excel
                </button>
                <button 
                    onClick={() => setIsAddingTp(!isAddingTp)}
                    className="flex items-center gap-2 px-4 py-2.5 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 transition-colors shadow-sm"
                >
                    <span className="material-symbols-outlined text-sm">{isAddingTp ? 'remove' : 'add'}</span>
                    Tambah TP
                </button>
            </div>
        </div>

        {/* Main Content Area */}
        <div className="flex-1 flex flex-col overflow-hidden bg-white">

            {/* Add TP Form */}
            {isAddingTp && (
                <div className="mx-6 mt-6 p-4 bg-blue-50 border border-blue-100 rounded-xl animate-in fade-in slide-in-from-top-4">
                    <h4 className="font-bold text-blue-800 mb-3 text-sm">
                        Tambah TP Baru di {scopes.find(s => s.id === activeScopeId)?.name}
                    </h4>
                    <div className="flex gap-3 items-start">
                        <div className="w-24">
                            <input 
                                type="text" placeholder="Kode" 
                                value={newTpForm.code} onChange={e => setNewTpForm({...newTpForm, code: e.target.value.toUpperCase()})}
                                className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900 placeholder:text-slate-400"
                            />
                        </div>
                        <div className="w-24">
                            <select 
                                value={newTpForm.semester} onChange={e => setNewTpForm({...newTpForm, semester: e.target.value})}
                                className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900"
                            >
                                <option value="1">Smt 1</option>
                                <option value="2">Smt 2</option>
                            </select>
                        </div>
                        <div className="flex-1">
                            <input 
                                type="text" placeholder="Deskripsi Tujuan Pembelajaran..." 
                                value={newTpForm.description} onChange={e => setNewTpForm({...newTpForm, description: e.target.value})}
                                className="w-full p-2 text-sm border border-blue-200 rounded-lg outline-none focus:ring-2 focus:ring-blue-300 bg-white text-slate-900"
                            />
                        </div>
                        <button onClick={handleAddTP} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold text-sm hover:bg-blue-700">Simpan</button>
                    </div>
                </div>
            )}

            {/* TP List */}
            <div className="flex-1 overflow-y-auto p-6 space-y-4">
                {filteredTPs.length === 0 && (
                    <div className="text-center py-12 text-gray-400">
                        <span className="material-symbols-outlined text-4xl mb-2">library_books</span>
                        <p>Belum ada Tujuan Pembelajaran untuk {scopes.find(s => s.id === activeScopeId)?.name}.</p>
                    </div>
                )}

                {filteredTPs.map((tp) => {
                    const isExpanded = expandedTpId === tp.id;
                    const isGeneratingThis = generatingTpId === tp.id;

                    return (
                        <div key={tp.id} className={`border rounded-xl transition-all ${isExpanded ? 'border-primary shadow-md bg-white' : 'border-slate-200 bg-white hover:border-slate-300'}`}>
                            {/* TP Header */}
                            <div 
                                onClick={() => setExpandedTpId(isExpanded ? null : tp.id)}
                                className="p-4 flex items-center gap-4 cursor-pointer"
                            >
                                <div className={`size-10 rounded-lg flex items-center justify-center font-bold text-sm ${isExpanded ? 'bg-primary text-white' : 'bg-slate-100 text-slate-500'}`}>
                                    {tp.code.toUpperCase()}
                                </div>
                                <div className="flex-1">
                                    <p className={`text-sm font-bold ${isExpanded ? 'text-primary' : 'text-slate-800'}`}>{tp.description}</p>
                                    <div className="flex items-center gap-2 mt-1">
                                        <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded text-slate-500">Semester {tp.semester}</span>
                                        <span className="text-[10px] text-slate-400 flex items-center gap-1">
                                            <span className="material-symbols-outlined text-[10px]">topic</span> {tp.lms.length} LM
                                        </span>
                                        <span className="text-[10px] text-slate-400 flex items-center gap-1">
                                            <span className="material-symbols-outlined text-[10px]">fact_check</span> {tp.criteria.length} Kriteria
                                        </span>
                                    </div>
                                </div>

                                {/* AI Generate Detail Button */}
                                {tp.lms.length === 0 && tp.criteria.length === 0 && (
                                    <button 
                                        onClick={(e) => { e.stopPropagation(); generateTpDetails(tp); }}
                                        disabled={isGeneratingThis || generatingTpId !== null}
                                        className={`px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 transition-all
                                            ${isGeneratingThis 
                                                ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                                                : 'bg-purple-50 text-purple-600 border border-purple-200 hover:bg-purple-100'
                                            }
                                        `}
                                    >
                                        {isGeneratingThis ? (
                                            <>
                                                <span className="size-3 border-2 border-slate-300 border-t-purple-600 rounded-full animate-spin"></span>
                                                Generating...
                                            </>
                                        ) : (
                                            <>
                                                <span className="material-symbols-outlined text-sm">auto_awesome</span>
                                                Generate Detail AI
                                            </>
                                        )}
                                    </button>
                                )}

                                <button 
                                    onClick={(e) => { e.stopPropagation(); handleDeleteTP(tp.id); }}
                                    className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                    <span className="material-symbols-outlined">delete</span>
                                </button>
                                <span className={`material-symbols-outlined text-slate-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`}>expand_more</span>
                            </div>

                            {/* Expanded Content */}
                            {isExpanded && (
                                <div className="border-t border-slate-100 bg-slate-50/50 p-4 space-y-6 animate-in slide-in-from-top-2">

                                    {/* Lingkup Materi Section */}
                                    <div className="space-y-3">
                                        <div className="flex justify-between items-center">
                                            <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
                                                <span className="material-symbols-outlined text-sm">topic</span>
                                                Lingkup Materi (LM)
                                            </h4>
                                        </div>
                                        <div className="bg-white border border-slate-200 rounded-lg overflow-hidden">
                                            <table className="w-full text-sm">
                                                <thead className="bg-slate-50 text-slate-500 font-semibold border-b border-slate-200">
                                                    <tr>
                                                        <th className="px-4 py-2 text-left w-24">Kode</th>
                                                        <th className="px-4 py-2 text-left">Judul Materi</th>
                                                        <th className="px-4 py-2 w-16"></th>
                                                    </tr>
                                                </thead>
                                                <tbody className="divide-y divide-slate-100">
                                                    {tp.lms.map(lm => (
                                                        <tr key={lm.id} className="group hover:bg-slate-50">
                                                            <td className="px-4 py-2 font-mono text-xs font-bold text-blue-600">{lm.code.toUpperCase()}</td>
                                                            <td className="px-4 py-2 text-slate-800">{lm.title}</td>
                                                            <td className="px-4 py-2 text-right">
                                                                <button 
                                                                    onClick={() => handleDeleteSubItem(tp.id, lm.id, 'LM')}
                                                                    className="text-slate-300 hover:text-red-500 group-hover:text-slate-400"
                                                                >
                                                                    <span className="material-symbols-outlined text-sm">close</span>
                                                                </button>
                                                            </td>
                                                        </tr>
                                                    ))}
                                                        {/* Add Row */}
                                                        <tr className="bg-slate-50">
                                                        <td className="px-2 py-2">
                                                            <input 
                                                                type="text" placeholder="LM.x" 
                                                                className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-blue-500 bg-white text-slate-900"
                                                                value={newItemForm.type === 'LM' && newItemForm.parentId === tp.id ? newItemForm.val1 : ''}
                                                                onChange={(e) => setNewItemForm({ type: 'LM', parentId: tp.id, val1: e.target.value.toUpperCase(), val2: newItemForm.val2 })}
                                                                onFocus={() => setNewItemForm(prev => ({ ...prev, type: 'LM', parentId: tp.id }))}
                                                            />
                                                        </td>
                                                        <td className="px-2 py-2">
                                                            <input 
                                                                type="text" placeholder="Tambah Lingkup Materi..." 
                                                                className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-blue-500 bg-white text-slate-900"
                                                                value={newItemForm.type === 'LM' && newItemForm.parentId === tp.id ? newItemForm.val2 : ''}
                                                                onChange={(e) => setNewItemForm({ type: 'LM', parentId: tp.id, val1: newItemForm.val1, val2: e.target.value })}
                                                                onKeyDown={(e) => e.key === 'Enter' && handleAddItem()}
                                                            />
                                                        </td>
                                                        <td className="px-2 py-2 text-center">
                                                                {newItemForm.type === 'LM' && newItemForm.parentId === tp.id && newItemForm.val1 && (
                                                                <button onClick={handleAddItem} className="text-blue-600 hover:text-blue-800">
                                                                    <span className="material-symbols-outlined text-lg">check_circle</span>
                                                                </button>
                                                                )}
                                                        </td>
                                                    </tr>
                                                </tbody>
                                            </table>
                                        </div>
                                    </div>

                                    {/* Kriteria Section */}
                                    <div className="space-y-3">
                                        <div className="flex justify-between items-center">
                                            <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider flex items-center gap-2">
                                                <span className="material-symbols-outlined text-sm">fact_check</span>
                                                Kriteria Penilaian (Untuk Matrix Input Nilai)
                                            </h4>
                                        </div>
                                        <div className="bg-white border border-slate-200 rounded-lg overflow-hidden">
                                            <table className="w-full text-sm">
                                                <thead className="bg-slate-50 text-slate-500 font-semibold border-b border-slate-200">
                                                    <tr>
                                                        <th className="px-4 py-2 text-left w-24">Kode</th>
                                                        <th className="px-4 py-2 text-left">Deskripsi Kriteria</th>
                                                        <th className="px-4 py-2 w-32 text-center">Jenis</th>
                                                        <th className="px-4 py-2 w-16"></th>
                                                    </tr>
                                                </thead>
                                                <tbody className="divide-y divide-slate-100">
                                                    {tp.criteria.map(cr => (
                                                        <tr key={cr.id} className="group hover:bg-slate-50">
                                                            <td className="px-4 py-2 font-mono text-xs font-bold text-green-600">{cr.code.toUpperCase()}</td>
                                                            <td className="px-4 py-2 text-slate-800">{cr.description}</td>
                                                            <td className="px-4 py-2 text-center">
                                                                <span className={`text-[10px] px-2 py-0.5 rounded font-bold uppercase ${cr.type === 'SUMMATIVE' ? 'bg-orange-100 text-orange-700' : 'bg-blue-100 text-blue-700'}`}>
                                                                    {cr.type === 'SUMMATIVE' ? 'Sumatif' : 'Formatif'}
                                                                </span>
                                                            </td>
                                                            <td className="px-4 py-2 text-right">
                                                                <button 
                                                                    onClick={() => handleDeleteSubItem(tp.id, cr.id, 'CRITERIA')}
                                                                    className="text-slate-300 hover:text-red-500 group-hover:text-slate-400"
                                                                >
                                                                    <span className="material-symbols-outlined text-sm">close</span>
                                                                </button>
                                                            </td>
                                                        </tr>
                                                    ))}
                                                        {/* Add Row */}
                                                        <tr className="bg-slate-50">
                                                        <td className="px-2 py-2">
                                                            <input 
                                                                type="text" placeholder="KR.x" 
                                                                className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-green-500 bg-white text-slate-900"
                                                                value={newItemForm.type === 'CRITERIA' && newItemForm.parentId === tp.id ? newItemForm.val1 : ''}
                                                                onChange={(e) => setNewItemForm({ type: 'CRITERIA', parentId: tp.id, val1: e.target.value.toUpperCase(), val2: newItemForm.val2 })}
                                                                onFocus={() => setNewItemForm(prev => ({ ...prev, type: 'CRITERIA', parentId: tp.id }))}
                                                            />
                                                        </td>
                                                        <td className="px-2 py-2">
                                                            <input 
                                                                type="text" placeholder="Tambah Kriteria Penilaian..." 
                                                                className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-green-500 bg-white text-slate-900"
                                                                value={newItemForm.type === 'CRITERIA' && newItemForm.parentId === tp.id ? newItemForm.val2 : ''}
                                                                onChange={(e) => setNewItemForm({ type: 'CRITERIA', parentId: tp.id, val1: newItemForm.val1, val2: e.target.value })}
                                                                onKeyDown={(e) => e.key === 'Enter' && handleAddItem()}
                                                            />
                                                        </td>
                                                        <td className="px-2 py-2">
                                                            <select 
                                                                value={newItemType}
                                                                onChange={(e) => setNewItemType(e.target.value as AssessmentType)}
                                                                className="w-full text-xs border-slate-200 rounded p-1.5 focus:ring-1 focus:ring-green-500 bg-white text-slate-900"
                                                                onFocus={() => setNewItemForm(prev => ({ ...prev, type: 'CRITERIA', parentId: tp.id }))}
                                                            >
                                                                <option value="FORMATIVE">Formatif</option>
                                                                <option value="SUMMATIVE">Sumatif</option>
                                                            </select>
                                                        </td>
                                                        <td className="px-2 py-2 text-center">
                                                                {newItemForm.type === 'CRITERIA' && newItemForm.parentId === tp.id && newItemForm.val1 && (
                                                                <button onClick={handleAddItem} className="text-green-600 hover:text-green-800">
                                                                    <span className="material-symbols-outlined text-lg">check_circle</span>
                                                                </button>
                                                                )}
                                                        </td>
                                                    </tr>
                                                </tbody>
                                            </table>
                                        </div>
                                    </div>

                                </div>
                            )}
                        </div>
                    );
                })}
            </div>
        </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import ExcelJS from 'exceljs';
import { LearningMaterial, LearningObjective, Subject, AssessmentCriteria, IdentityData, AssessmentType } from '../types';
import { GoogleGenAI, Type } from "@google/genai";

declare const Swal: any;

interface Props {
  identity: IdentityData;
  subject: Subject;
  tps: LearningObjective[];
  onUpdateSubject: (kktp: number) => void;
  onUpdateTPs: (tps: LearningObjective[]) => void;
  onBack: () => void;
}

// Mock Data for Scopes
const SD_SUBJECTS = [
    { id: 'math', name: 'Matematika' },
    { id: 'indo', name: 'B. Indonesia' },
    { id: 'ipas', name: 'IPAS' },
    { id: 'ppkn', name: 'PPKn' },
    { id: 'sbura', name: 'Seni Budaya' },
];

const SMP_LEVELS = [
    { id: 'lvl-7', name: 'Kelas 7 (Fase D)' },
    { id: 'lvl-8', name: 'Kelas 8 (Fase D)' },
    { id: 'lvl-9', name: 'Kelas 9 (Fase D)' },
];

const SMA_LEVELS = [
    { id: 'lvl-10', name: 'Kelas 10 (Fase E)' },
    { id: 'lvl-11', name: 'Kelas 11 (Fase F)' },
    { id: 'lvl-12', name: 'Kelas 12 (Fase F)' },
];

export const CurriculumManager: React.FC<Props> = ({ 
  identity, subject, tps, onUpdateSubject, onUpdateTPs, onBack 
}) => {
  const [expandedTpId, setExpandedTpId] = useState<string | null>(null);
  const [generatingTpId, setGeneratingTpId] = useState<string | null>(null);

  // DETERMINE CONTEXT (Scope)
  const scopes = useMemo(() => {
      if (identity.level === 'SD') return SD_SUBJECTS;
      else if (identity.level === 'SMP') return SMP_LEVELS;
      else return SMA_LEVELS;
  }, [identity.level]);

  const [activeScopeId, setActiveScopeId] = useState<string>(scopes[0].id);

  useEffect(() => {
      const exists = scopes.find(s => s.id === activeScopeId);
      if (!exists) setActiveScopeId(scopes[0].id);
  }, [scopes, activeScopeId]);

  // Filter TPs based on Active Scope
  const filteredTPs = useMemo(() => {
      return tps.filter(tp => tp.scopeId === activeScopeId);
  }, [tps, activeScopeId]);

  // TP Form State
  const [isAddingTp, setIsAddingTp] = useState(false);
  const [newTpForm, setNewTpForm] = useState({ code: '', description: '', semester: '1' });

  // Sub-item Form State (LM & Criteria)
  const [newItemForm, setNewItemForm] = useState<{
      type: 'LM' | 'CRITERIA' | null, 
      parentId: string | null,
      val1: string, // Code
      val2: string // Title/Description
  }>({ type: null, parentId: null, val1: '', val2: '' });

  // Add state for Item Type (Formative/Summative)
  const [newItemType, setNewItemType] = useState<AssessmentType>('FORMATIVE');

  // --- AI GENERATION LOGIC FOR TP DETAILS ---
  const generateTpDetails = async (tp: LearningObjective) => {
      if (tp.lms.length > 0 || tp.criteria.length > 0) {
          const result = await Swal.fire({
              title: 'TP Sudah Memiliki Detail',
              text: "Data Lingkup Materi dan Kriteria yang sudah ada mungkin akan terduplikasi. Lanjutkan generate?",
              icon: 'warning',
              showCancelButton: true,
              confirmButtonText: 'Ya, Tambahkan',
              cancelButtonText: 'Batal'
          });
          if (!result.isConfirmed) return;
      }

      setGeneratingTpId(tp.id);

      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
          const prompt = `
            Role: Expert Curriculum Developer for Indonesian School (Kurikulum Merdeka).
            Context: Subject '${identity.subjectName}' for Grade '${identity.level}'.
            Task: Based on the Learning Objective (TP) below, generate strictly:
            1. 3 specific 'Lingkup Materi' (Learning Materials/Scope) titles.
            2. 3 specific 'Assessment Criteria' (Kriteria Ketercapaian TP). Ensure mixed types (Formatif/Sumatif).

            TP Description: "${tp.description}" (Code: ${tp.code})

            Output must be valid JSON object with arrays 'lms' and 'criteria'.
          `;

          const response = await ai.models.generateContent({
              model: "gemini-3-flash-preview",
              contents: prompt,
              config: {
                  responseMimeType: "application/json",
                  responseSchema: {
                      type: Type.OBJECT,
                      properties: {
                          lms: {
                              type: Type.ARRAY,
                              items: {
                                  type: Type.OBJECT,
                                  properties: {
                                      code: { type: Type.STRING, description: "Example: LM.1" },
                                      title: { type: Type.STRING, description: "Material title" }
                                  }
                              }
                          },
                          criteria: {
                              type: Type.ARRAY,
                              items: {
                                  type: Type.OBJECT,
                                  properties: {
                                      code: { type: Type.STRING, description: "Example: KR.1" },
                                      description: { type: Type.STRING, description: "Assessment criteria description" },
                                      type: { type: Type.STRING, enum: ["FORMATIVE", "SUMMATIVE"], description: "Assessment type" }
                                  }
                              }
                          }
                      }
                  }
              }
          });

          const json = JSON.parse(response.text || '{}');

          if (json.lms && json.criteria) {
              // Map output to internal types
              const newLms: LearningMaterial[] = json.lms.map((lm: any, idx: number) => ({
                  id: `gen-lm-${Date.now()}-${idx}`,
                  code: lm.code || `LM.${tp.lms.length + idx + 1}`,
                  title: lm.title
              }));

              const newCriteria: AssessmentCriteria[] = json.criteria.map((cr: any, idx: number) => ({
                  id: `gen-cr-${Date.now()}-${idx}`,
                  code: cr.code || `KR.${tp.criteria.length + idx + 1}`,
                  description: cr.description,
                  type: (cr.type === 'SUMMATIVE' ? 'SUMMATIVE' : 'FORMATIVE') as AssessmentType
              }));

              // Update TP
              const updatedTPs = tps.map(t => {
                  if (t.id === tp.id) {
                      return {
                          ...t,
                          lms: [...t.lms, ...newLms],
                          criteria: [...t.criteria, ...newCriteria]
                      };
                  }
                  return t;
              });

              onUpdateTPs(updatedTPs);
              setExpandedTpId(tp.id); // Auto expand to show results
              Swal.fire({
                  title: 'Generate Berhasil',
                  text: `Ditambahkan ${newLms.length} Materi dan ${newCriteria.length} Kriteria.`,
                  icon: 'success',
                  timer: 2000
              });
          }

      } catch (error: any) {
          console.error(error);
          Swal.fire('Gagal Generate', error.message, 'error');
      } finally {
          setGeneratingTpId(null);
      }
  };

  // --- EXPORT FUNCTION ---
  const handleExportCurriculum = async () => {
    if (filteredTPs.length === 0) return;

    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet('Kurikulum');

    // Headers
    const headerRow = sheet.addRow([
        'No', 
        'Semester', 
        'Mata Pelajaran', 
        'Lingkup Materi (Scope/Fase)', 
        'Kelas', 
        'Tujuan Pembelajaran (TP)', 
        'Lingkup Materi (LM) Detail'
    ]);

    // Style Headers
    headerRow.eachCell((cell) => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } };
        cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
    });

    const activeScopeName = scopes.find(s => s.id === activeScopeId)?.name || activeScopeId;
    const mapelName = identity.level === 'SD' ? activeScopeName : identity.subjectName; // Logic: di SD scope adalah Mapel, di SMA scope adalah Fase/Kelas

    let rowIndex = 1;

    filteredTPs.forEach((tp) => {
        // Jika ada LM, buat baris untuk setiap LM. Jika tidak, buat 1 baris untuk TP saja.
        if (tp.lms.length > 0) {
            tp.lms.forEach(lm => {
                const row = sheet.addRow([
                    rowIndex,
                    `Semester ${tp.semester}`,
                    mapelName,
                    activeScopeName, // Scope/Phase context
                    identity.level,
                    `${tp.code} - ${tp.description}`,
                    `${lm.code} - ${lm.title}`
                ]);
                // Styling per cell
                row.eachCell((cell) => {
                    cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                    cell.alignment = { vertical: 'top', wrapText: true };
                });
            });
        } else {
             const row = sheet.addRow([
                    rowIndex,
                    `Semester ${tp.semester}`,
                    mapelName,
                    activeScopeName,
                    identity.level,
                    `${tp.code} - ${tp.description}`,
                    '-'
            ]);
            row.eachCell((cell) => {
                cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                cell.alignment = { vertical: 'top', wrapText: true };
            });
        }
        rowIndex++;
    });

    // Column Widths
    sheet.getColumn(6).width = 50; // TP Description
    sheet.getColumn(7).width = 40; // LM Detail
    sheet.getColumn(3).width = 20; // Mapel
    sheet.getColumn(4).width = 25; // Scope

    // Download
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `Kurikulum_${activeScopeName.replace(/\s/g, '_')}.xlsx`;
    anchor.click();
    window.URL.revokeObjectURL(url);
  };

  // --- TP CRUD ---
  const handleAddTP = () => {
    if(!newTpForm.code || !newTpForm.description) return;
    const newTp: LearningObjective = {
        id: Date.now().toString(),
        code: newTpForm.code.toUpperCase(), 
        description: newTpForm.description,
        semester: Number(newTpForm.semester) as 1 | 2,
        scopeId: activeScopeId, 
        lms: [],
        criteria: []
    };
    onUpdateTPs([...tps, newTp]);
    setIsAddingTp(false);
    setNewTpForm({ code: '', description: '', semester: '1' });
  };

  const handleDeleteTP = (id: string) => {
      Swal.fire({
          title: 'Hapus Tujuan Pembelajaran?',
          text: "Seluruh Lingkup Materi (LM) dan Kriteria yang ada di dalamnya akan ikut terhapus!",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Ya, hapus!',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateTPs(tps.filter(t => t.id !== id));
              Swal.fire('Terhapus!', 'TP berhasil dihapus.', 'success')
          }
      });
  };

  // --- NESTED ITEMS CRUD ---
  const handleAddItem = () => {
      if(!newItemForm.val1 || !newItemForm.val2 || !newItemForm.parentId || !newItemForm.type) return;

      const updatedTPs = tps.map(tp => {
          if(tp.id === newItemForm.parentId) {
              if(newItemForm.type === 'LM') {
                  return {
                      ...tp,
                      lms: [...tp.lms, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), 
                          title: newItemForm.val2 
                      }]
                  };
              } else {
                  return {
                      ...tp,
                      criteria: [...tp.criteria, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), 
                          description: newItemForm.val2,
                          type: newItemType // Use the selected state
                      }]
                  };
              }
          }
          return tp;
      });

      onUpdateTPs(updatedTPs);
      setNewItemForm({ type: null, parentId: null, val1: '', val2: '' });
      setNewItemType('FORMATIVE'); // Reset default
  };

  const handleDeleteSubItem = (tpId: string, itemId: string, type: 'LM' | 'CRITERIA') => {
      Swal.fire({
          title: 'Hapus Item?',
          text: "Item ini akan dihapus permanen.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Hapus',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              const updatedTPs = tps.map(tp => {
                  if(tp.id === tpId) {
                      if(type === 'LM') {
                          return { ...tp, lms: tp.lms.filter(l => l.id !== itemId) };
                      } else {
                          return { ...tp, criteria: tp.criteria.filter(c => c.id !== itemId) };
                      }
                  }
                  return tp;
              });
              onUpdateTPs(updatedTPs);
          }
      });
  };

  return (
    <div className="h-full flex flex-col bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Header Title */}
        <div className="bg-gray-50 p-6 border-b flex justify-between items-center">
            <div>
                <h2 className="text-xl font-bold text-gray-800">Manajemen Kurikulum & Asesmen</h2>
                <p className="text-sm text-gray-500">
                    {identity.level === 'SD' 
                        ? 'Pengaturan TP per Mata Pelajaran (Jenjang SD)' 
                        : 'Pengaturan TP per Tingkat Kelas (Jenjang SMP/SMA/SMK)'}
                </p>
            </div>
             <button onClick={onBack} className="text-gray-500 hover:text-gray-700 font-medium">
                &larr; Kembali
            </button>
        </div>

        {/* Top Control Bar (Dropdown & KKTP) */}
        <div className="px-6 py-4 bg-white border-b flex flex-col md:flex-row gap-4 justify-between items-end md:items-center">
            <div className="flex flex-col md:flex-row gap-6 w-full md:w-auto">

                {/* Scope/Class Selector */}
                <div className="w-full md:w-64">
                    <label className="text-xs font-bold text-gray-500 uppercase block mb-1">
                        {identity.level === 'SD' ? 'Mata Pelajaran' : 'Pilih Tingkat Kelas'}
                    </label>
                    <div className="relative">
                        <select 
                            value={activeScopeId} 
                            onChange={(e) => setActiveScopeId(e.target.value)}
                            className="w-full appearance-none pl-10 pr-8 py-2 border border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-2 focus:ring-primary focus:border-transparent outline-none cursor-pointer bg-white"
                        >
                            {scopes.map(scope => (
                                <option key={scope.id} value={scope.id}>{scope.name}</option>
                            ))}
                        </select>
                        <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-500 pointer-events-none text-lg">
                            {identity.level === 'SD' ? 'menu_book' : 'school'}
                        </span>
                        <span className="material-symbols-outlined absolute right-2 top-2.5 text-slate-400 pointer-events-none text-sm">expand_more</span>
                    </div>
                </div>

                {/* KKTP Input */}
                <div className="w-full md:w-32">
                    <label className="text-xs font-bold text-gray-500 uppercase block mb-1">KKTP</label>
                    <div className="relative">
                        <input 
                            type="number" 
                            value={subject.kktp} 
                            onChange={(e) => onUpdateSubject(Number(e.target.value))}
                            className="w-full pl-3 pr-8 py-2 border border-slate-300 rounded-lg text-sm font-bold text-blue-700 focus:ring-2 focus:ring-blue-500 outline-none"
                        />
                        <span className="absolute right-3 top-2 text-xs font-bold text-slate-400">Poin</span>
                    </div>
                </div>
            </div>

            <div className="flex gap-3">
                 <button 
                    onClick={handleExportCurriculum}
                    disabled={filteredTPs.length === 0}
                    className="flex items-center gap-2 px-4 py-2.5 bg-green-600 text-white rounded-lg text-sm font-bold hover:bg-green-700 transition-colors shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    <span className="material-symbols-outlined text-sm">table_view</span>
                    Export Excel
                </button>
                <button 
                    onClick={() => setIsAddingTp(!isAddingTp)}
                    className="flex items-center gap-2 px-4 py-2.5 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 transition-colors shadow-sm"
                >
                    <span className="material-symbols-outlined text-sm">{isAddingTp ? 'remove' : 'add'}</span>
                    Tambah TP
                </button>
            </div>
        </div>

        {/* Main Content Area */}
        <div className="flex-1 flex flex-col overflow-hidden bg-white">

            {/* Add TP Form */}
            {isAddingTp && (
                <div className="mx-6 mt-6 p-4 bg-blue-50 border border-blue-100 rounded-xl animate-in fade-in slide-in-from-top-4">
                    <h4 className="font-bold text-blue-800 mb-3 text-sm">
                        Tambah TP Baru di {scopes.find(s => s.id === activeScopeId)?.name}
                    </h4>
                    <div className="flex gap-3 items-start">
                        <div className="w-24">
                            <input 
                                type="text" placeholder="Kode" 
