  id: string;
  email: string;
  name: string;
  role: TeacherRole;
  level?: SchoolLevel; 
  isActive: boolean;
  lastLogin?: string;
  password?: string; // Added: Plain Text Password for Admin View
}

// STORAGE WRAPPER 
export interface UserStorageData {
  identity: IdentityData;
  students: Student[];
  classes: ClassInfo[];
  schedules: ScheduleItem[];
