import { useState, useMemo } from 'react';
import { User, TeacherRole, SchoolLevel } from '../types';
import { RegisterData } from '../components/LoginPage';

declare const Swal: any;

interface UseAdminLogicProps {
  users: User[];
  waNumber: string;
  onAddUser: (data: RegisterData) => void;
  onUpdateUser: (id: string, data: RegisterData) => void;
  onDeleteUser: (id: string) => void;
  onUpdateWaNumber: (num: string) => void;
}

export const useAdminLogic = ({
  users,
  waNumber,
  onAddUser,
  onUpdateUser,
  onDeleteUser,
  onUpdateWaNumber
}: UseAdminLogicProps) => {
  // --- STATE ---
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [userTab, setUserTab] = useState<'ACTIVE' | 'PENDING'>('ACTIVE');
  const [tempWaNumber, setTempWaNumber] = useState(waNumber);

  // Form Data State
  const [formData, setFormData] = useState<RegisterData>({ 
      email: '', name: '', password: '', role: 'SUBJECT_TEACHER', level: 'SMA' 
  });

  // --- DERIVED STATE (MEMOS) ---
  const stats = useMemo(() => {
    return {
      total: users.length,
      active: users.filter(u => u.isActive).length,
      pending: users.filter(u => !u.isActive).length,
      admins: users.filter(u => u.role === 'ADMIN').length,
      classTeachers: users.filter(u => u.role === 'CLASS_TEACHER' && u.isActive).length,
      subjectTeachers: users.filter(u => u.role === 'SUBJECT_TEACHER' && u.isActive).length,
      sd: users.filter(u => u.level === 'SD' && u.isActive).length,
      smp: users.filter(u => u.level === 'SMP' && u.isActive).length,
      sma: users.filter(u => u.level === 'SMA' && u.isActive).length,
      smk: users.filter(u => u.level === 'SMK' && u.isActive).length,
    };
  }, [users]);

  const filteredUsers = useMemo(() => {
    const byTab = users.filter(u => userTab === 'ACTIVE' ? u.isActive : !u.isActive);
    return byTab.filter(u => 
      u.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
      u.email.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [users, searchQuery, userTab]);

  // --- HANDLERS ---

  const handleOpenModal = (user?: User) => {
    if (user) {
      setEditingUser(user);
      setFormData({ 
          email: user.email, 
          name: user.name, 
          password: '', 
          role: user.role, 
          level: user.level || 'SMA' 
      });
    } else {
      setEditingUser(null);
      setFormData({ email: '', name: '', password: '', role: 'SUBJECT_TEACHER', level: 'SMA' });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser) {
      onUpdateUser(editingUser.id, formData);
    } else {
      if (!formData.email || !formData.name || !formData.password) {
          Swal.fire('Error', 'Nama, Email, dan Password wajib diisi.', 'error');
          return;
      }
      if (formData.password.length < 6) {
          Swal.fire('Error', 'Password minimal 6 karakter.', 'error');
          return;
      }
      onAddUser(formData);
    }
    setIsModalOpen(false);
  };

  const handleDelete = (id: string) => {
    Swal.fire({
      title: 'Hapus Pengguna?',
      text: "Data administrasi pengguna ini akan hilang permanen!",
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      confirmButtonText: 'Hapus',
      cancelButtonText: 'Batal'
    }).then((result: any) => {
      if (result.isConfirmed) {
        onDeleteUser(id);
      }
    });
  };

  const handleSaveSettings = () => {
      onUpdateWaNumber(tempWaNumber);
  };

  return {
    state: {
      isModalOpen,
      editingUser,
      searchQuery,
      userTab,
      tempWaNumber,
      formData
    },
    setters: {
      setIsModalOpen,
      setSearchQuery,
      setUserTab,
      setTempWaNumber,
      setFormData
    },
    computed: {
      stats,
      filteredUsers
    },
    handlers: {
      handleOpenModal,
      handleSubmit,
      handleDelete,
      handleSaveSettings
    }
  };
};

import { useState, useMemo, useRef } from 'react';
import ExcelJS from 'exceljs';
import { Student, ClassInfo, IdentityData } from '../types';

declare const Swal: any;

// Helper
const toTitleCase = (str: string) => {
    return str.toLowerCase().replace(/\b\w/g, s => s.toUpperCase());
};

interface UseStudentLogicProps {
  identity: IdentityData;
  students: Student[];
  classes: ClassInfo[];
  onUpdateStudents: (students: Student[]) => void;
  onUpdateClasses: (classes: ClassInfo[]) => void;
}

export const useStudentLogic = ({
  identity,
  students,
  classes,
  onUpdateStudents,
  onUpdateClasses
}: UseStudentLogicProps) => {
  // --- STATE ---
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // FILTER STATE
  const [filterClass, setFilterClass] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState<string>('');

  // Default Form Data
  const [formData, setFormData] = useState({
      name: '',
      nis: '',
      gender: 'L',
      className: '',
      status: 'Aktif'
  });

  // --- COMPUTED ---
  const filteredStudents = useMemo(() => {
    return students.filter(student => {
        const matchesClass = filterClass ? student.className === filterClass : true;
        const matchesSearch = student.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                              student.nis.includes(searchQuery);
        return matchesClass && matchesSearch;
    });
  }, [students, filterClass, searchQuery]);

  // --- HANDLERS ---

  const handleOpenModal = (student?: Student) => {
      if (student) {
          setEditingId(student.id);
          setFormData({
              name: student.name,
              nis: student.nis,
              gender: 'L',
              className: student.className || '',
              status: 'Aktif'
          });
          setIsModalOpen(true);
      } else {
          // VALIDATION
          if (classes.length === 0) {
              Swal.fire({
                  title: 'Data Kelas Kosong',
                  text: 'Anda belum memiliki data Kelas. Silahkan buat Kelas terlebih dahulu di menu "Master Kelas" sebelum menambahkan siswa.',
                  icon: 'warning',
                  confirmButtonText: 'Oke, Mengerti',
                  confirmButtonColor: '#137fec'
              });
              return;
          }

          setEditingId(null);
          const defaultClass = classes.length > 0 ? classes[0].name : '';
          setFormData({ name: '', nis: '', gender: 'L', className: defaultClass, status: 'Aktif' });
          setIsModalOpen(true);
      }
  };

  const handleSaveStudent = (e: React.FormEvent) => {
      e.preventDefault();

      if (!formData.name.trim() || !formData.nis.trim() || !formData.className || !formData.gender) {
          Swal.fire({
              title: 'Gagal Menyimpan',
              text: "Semua kolom (Nama, NIS, Jenis Kelamin, Kelas) wajib diisi!",
              icon: 'error',
              confirmButtonColor: '#d33',
              confirmButtonText: 'OK'
          });
          return;
      }

      const formattedName = toTitleCase(formData.name);

      if (editingId) {
          const updatedStudents = students.map(s => s.id === editingId ? { ...s, ...formData, name: formattedName } : s);
          onUpdateStudents(updatedStudents);
      } else {
          const newStudent: Student = {
              id: Date.now().toString(),
              name: formattedName,
              nis: formData.nis,
              className: formData.className,
          };
          onUpdateStudents([newStudent, ...students]);
      }
      setIsModalOpen(false);

      Swal.fire({
          title: 'Berhasil!',
          text: 'Data siswa telah disimpan.',
          icon: 'success',
          timer: 1500,
          showConfirmButton: false
      });
  };

  const handleDeleteStudent = (id: string) => {
      Swal.fire({
          title: 'Hapus Siswa?',
          text: "Data ini tidak dapat dikembalikan!",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonColor: '#3085d6',
          confirmButtonText: 'Ya, hapus!',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateStudents(students.filter(s => s.id !== id));
              Swal.fire('Terhapus!', 'Data siswa berhasil dihapus.', 'success')
          }
      });
  };

  // --- IMPORT LOGIC ---

  const handleImportMenuClick = () => {
      Swal.fire({
          title: 'Import Data Siswa',
          text: 'Silahkan unduh template terlebih dahulu, isi data, lalu upload kembali. Jika nama kelas di Excel belum ada di sistem, kelas baru akan otomatis dibuat.',
          icon: 'info',
          showDenyButton: true,
          showCancelButton: true,
          confirmButtonText: 'Upload Data Excel',
          denyButtonText: 'Unduh Template',
          cancelButtonText: 'Batal',
          confirmButtonColor: '#137fec',
          denyButtonColor: '#28a745'
      }).then((result: any) => {
          if (result.isConfirmed) {
              if (fileInputRef.current) {
                  fileInputRef.current.value = ''; 
                  fileInputRef.current.click();
              }
          } else if (result.isDenied) {
              handleDownloadTemplate();
          }
      });
  };

  const handleDownloadTemplate = async () => {
      const workbook = new ExcelJS.Workbook();
      const sheet = workbook.addWorksheet('Template Siswa');

      sheet.columns = [
          { header: 'No', key: 'no', width: 5 },
          { header: 'Nama Lengkap', key: 'name', width: 30 },
          { header: 'NIS', key: 'nis', width: 15 },
          { header: 'Kelas', key: 'className', width: 15 },
          { header: 'L/P', key: 'gender', width: 10 },
      ];

      const headerRow = sheet.getRow(1);
      headerRow.font = { bold: true, color: { argb: 'FFFFFFFF' } };
      headerRow.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } };

      sheet.addRow([1, 'Contoh: Ahmad Dahlan', '12345', '10-A', 'L']);

      const buffer = await workbook.xlsx.writeBuffer();
      const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      const url = window.URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = 'Template_Import_Siswa_SiGuru.xlsx';
      anchor.click();
      window.URL.revokeObjectURL(url);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const workbook = new ExcelJS.Workbook();
      const reader = new FileReader();

      reader.onload = async (evt) => {
          const buffer = evt.target?.result as ArrayBuffer;
          if (!buffer) return;

          try {
              await workbook.xlsx.load(buffer);
              const worksheet = workbook.getWorksheet(1); 

              if (!worksheet) {
                  Swal.fire('Error', 'File Excel tidak valid atau kosong.', 'error');
                  return;
              }

              const newStudents: Student[] = [];
              const importedClassNames = new Set<string>();
              let successCount = 0;
              let failCount = 0;

              worksheet.eachRow((row, rowNumber) => {
                  if (rowNumber === 1) return;

                  const name = row.getCell(2).text?.trim(); 
                  const nis = row.getCell(3).text?.trim();  
                  let className = row.getCell(4).text?.trim(); 

                  if (name && nis && className) {
                      const student: Student = {
                          id: `imp-${Date.now()}-${rowNumber}`,
                          name: toTitleCase(name),
                          nis: nis,
                          className: className,
                      };
                      newStudents.push(student);
                      importedClassNames.add(className);
                      successCount++;
                  } else {
                      if (name || nis || className) failCount++;
                  }
              });

              if (newStudents.length > 0) {
                  const classesToCreate: ClassInfo[] = [];
                  const existingClassNames = new Set(classes.map(c => c.name.toLowerCase()));
                  const defaultLevel = classes.length > 0 ? classes[0].level : 'Fase E';

                  importedClassNames.forEach(clsName => {
                      if (!existingClassNames.has(clsName.toLowerCase())) {
                          const newClass: ClassInfo = {
                              id: `auto-cls-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
                              name: clsName,
                              level: defaultLevel,
                              studentCount: 0
                          };
                          classesToCreate.push(newClass);
                          existingClassNames.add(clsName.toLowerCase());
                      }
                  });

                  if (classesToCreate.length > 0) {
                      onUpdateClasses([...classes, ...classesToCreate]);
                  }

                  onUpdateStudents([...newStudents, ...students]); 

                  let message = `<p>Berhasil menyimpan <b>${successCount}</b> data siswa.</p>`;
                  if (classesToCreate.length > 0) {
                      message += `<p class="text-blue-600 mt-2 text-sm bg-blue-50 p-2 rounded"><span class="font-bold">Info:</span> ${classesToCreate.length} Kelas baru otomatis dibuat.</p>`;
                  }
                  if (failCount > 0) {
                      message += `<p class="text-red-500 mt-2 text-sm">Gagal: <b>${failCount}</b> baris dilewati.</p>`;
                  }

                  Swal.fire({
                      title: 'Import Selesai',
                      html: message,
                      icon: failCount > 0 ? 'warning' : 'success'
                  });
              } else {
                  Swal.fire('Info', 'Tidak ada data valid yang ditemukan.', 'info');
              }

          } catch (error) {
              console.error(error);
              Swal.fire('Error', 'Gagal membaca file. Pastikan format Excel (.xlsx) benar.', 'error');
          }
      };

      reader.readAsArrayBuffer(file);
  };

  return {
    state: { isModalOpen, editingId, filterClass, searchQuery, formData },
    setters: { setIsModalOpen, setFilterClass, setSearchQuery, setFormData },
    computed: { filteredStudents },
    handlers: { 
        handleOpenModal, 
        handleSaveStudent, 
        handleDeleteStudent, 
        handleImportMenuClick, 
        handleFileUpload 
    },
    refs: { fileInputRef }
  };
};

import { useState, useEffect, useMemo } from 'react';
import ExcelJS from 'exceljs';
import { JournalEntry, LearningObjective, ScheduleItem, ClassInfo } from '../types';

declare const Swal: any;

interface UseJournalLogicProps {
  journals: JournalEntry[];
  onUpdateJournals: (journals: JournalEntry[]) => void;
  tps: LearningObjective[];
  schedules: ScheduleItem[];
  classes: ClassInfo[];
  initialContext?: { className?: string, scheduleId?: string };
}

export const useJournalLogic = ({
  journals,
  onUpdateJournals,
  tps,
  schedules,
  classes,
  initialContext
}: UseJournalLogicProps) => {
  // --- STATE ---
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // FILTER STATES
  const [filterClass, setFilterClass] = useState<string>('');
  const [filterSubject, setFilterSubject] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');

  // Default Form Data
  const [formData, setFormData] = useState<Omit<JournalEntry, 'id' | 'created_at'>>({
      date: new Date().toISOString().split('T')[0],
      className: '',
      scheduleId: '',
      subjectName: '', 
      startTime: '',
      endTime: '',
      tpId: '',
      lmId: '',
      activity: '',
      reflection: '',
      followUp: ''
  });

  // --- DERIVED LISTS ---
  const availableClasses = useMemo(() => {
      return [...new Set(schedules.map(s => s.className))].sort();
  }, [schedules]);

  const availableSubjects = useMemo(() => {
      return [...new Set(schedules.map(s => s.subject))].sort();
  }, [schedules]);

  const filteredJournals = useMemo(() => {
      return journals.filter(j => {
          const matchClass = filterClass ? j.className === filterClass : false;
          const matchSubject = filterSubject ? j.subjectName === filterSubject : false;
          const query = searchQuery.toLowerCase();
          const matchSearch = j.activity.toLowerCase().includes(query) || 
                              j.reflection.toLowerCase().includes(query);
          return matchClass && matchSubject && matchSearch;
      }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [journals, filterClass, filterSubject, searchQuery]);

  const activeTP = useMemo(() => tps.find(tp => tp.id === formData.tpId), [formData.tpId, tps]);
  const availableLMs = activeTP ? activeTP.lms : [];

  // --- EFFECTS ---
  useEffect(() => {
    if (initialContext?.scheduleId && !isModalOpen) {
        const schedule = schedules.find(s => s.id === initialContext.scheduleId);
        if (schedule) {
            setFormData({
                date: new Date().toISOString().split('T')[0],
                className: schedule.className,
                scheduleId: schedule.id,
                subjectName: schedule.subject,
                startTime: schedule.startTime,
                endTime: schedule.endTime,
                tpId: '',
                lmId: '',
                activity: '',
                reflection: '',
                followUp: ''
            });
            setIsModalOpen(true);
        }
    }
    if (initialContext?.className) setFilterClass(initialContext.className);
    if (initialContext?.scheduleId) {
        const schedule = schedules.find(s => s.id === initialContext.scheduleId);
        if(schedule) setFilterSubject(schedule.subject);
    }
  }, [initialContext, schedules]);

  // --- HANDLERS ---

  const handleScheduleChange = (scheduleId: string) => {
      const schedule = schedules.find(s => s.id === scheduleId);
      if (schedule) {
          setFormData(prev => ({
              ...prev,
              scheduleId: schedule.id,
              className: schedule.className,
              subjectName: schedule.subject,
              startTime: schedule.startTime,
              endTime: schedule.endTime
          }));
      } else {
          setFormData(prev => ({ 
              ...prev, scheduleId: '', className: '', subjectName: '', startTime: '', endTime: '' 
          }));
      }
  };

  const handleSave = (e: React.FormEvent) => {
      e.preventDefault();

      if (!formData.scheduleId) {
          Swal.fire('Error', 'Wajib memilih Jadwal Mengajar.', 'error');
          return;
      }
      if (!formData.date || !formData.className || !formData.tpId || !formData.activity) {
          Swal.fire('Error', 'Tanggal, Kelas, TP, dan Kegiatan wajib diisi.', 'error');
          return;
      }

      if (editingId) {
          const updated = journals.map(j => j.id === editingId ? { ...j, ...formData } : j);
          onUpdateJournals(updated);
          Swal.fire('Berhasil', 'Jurnal berhasil diperbarui.', 'success');
      } else {
          const newEntry: JournalEntry = {
              id: Date.now().toString(),
              created_at: new Date().toISOString(),
              ...formData
          };
          onUpdateJournals([newEntry, ...journals]);
          Swal.fire('Berhasil', 'Jurnal baru berhasil disimpan.', 'success');
      }
      setIsModalOpen(false);
      setEditingId(null);
  };

  const handleEdit = (journal: JournalEntry) => {
      setEditingId(journal.id);
      setFormData({ ...journal });
      setIsModalOpen(true);
  };

  const handleDelete = (id: string) => {
      Swal.fire({
          title: 'Hapus Jurnal?',
          text: "Data yang dihapus tidak dapat dikembalikan.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          confirmButtonText: 'Ya, Hapus'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateJournals(journals.filter(j => j.id !== id));
              Swal.fire('Terhapus', 'Jurnal berhasil dihapus.', 'success');
          }
      });
  };

  const handleExportExcel = async () => {
    if (filteredJournals.length === 0) return;

    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet('Jurnal Guru');

    const headerRow = sheet.addRow([
        'No', 'Tanggal', 'Jam', 'Kelas', 'Mata Pelajaran', 
        'Kode TP', 'Deskripsi Kegiatan', 'Refleksi Guru', 'Tindak Lanjut'
    ]);

    headerRow.eachCell((cell) => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } };
        cell.alignment = { horizontal: 'center', vertical: 'middle' };
        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
    });

    filteredJournals.forEach((j, index) => {
        const tp = tps.find(t => t.id === j.tpId);
        const row = sheet.addRow([
            index + 1,
            new Date(j.date).toLocaleDateString('id-ID'),
            `${j.startTime} - ${j.endTime}`,
            j.className,
            j.subjectName,
            tp ? tp.code : '-',
            j.activity,
            j.reflection,
            j.followUp
        ]);
        row.eachCell((cell) => {
             cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
             cell.alignment = { vertical: 'top', wrapText: true };
        });
    });

    sheet.getColumn(2).width = 15;
    sheet.getColumn(7).width = 40;
    sheet.getColumn(8).width = 30;
    sheet.getColumn(9).width = 30;

    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `Jurnal_${filterClass || 'Semua'}_${filterSubject || 'Semua'}.xlsx`;
    anchor.click();
    window.URL.revokeObjectURL(url);
  };

  const closeModal = () => {
      setIsModalOpen(false);
      setEditingId(null);
      setFormData({
          date: new Date().toISOString().split('T')[0],
          className: '',
          scheduleId: '',
          subjectName: '',
          startTime: '',
          endTime: '',
          tpId: '',
          lmId: '',
          activity: '',
          reflection: '',
          followUp: ''
      });
  };

  return {
    state: { isModalOpen, editingId, filterClass, filterSubject, searchQuery, formData },
    setters: { setIsModalOpen, setFilterClass, setFilterSubject, setSearchQuery, setFormData },
    computed: { availableClasses, availableSubjects, filteredJournals, activeTP, availableLMs },
    handlers: { 
        handleScheduleChange, 
        handleSave, 
        handleEdit, 
        handleDelete, 
        handleExportExcel,
        closeModal
    }
  };
};

import { useState, useEffect, useCallback, useMemo } from 'react';
import { z } from 'zod'; 
import { Student, LearningObjective, GradeData, Subject } from '../types';
import { calculateStudentGrade } from '../utils/grading';

const scoreSchema = z.number().min(0, "Min 0").max(100, "Max 100").optional();

interface UseGradingLogicProps {
  students: Student[];
  tps: LearningObjective[];
  subject: Subject;
  initialClass?: string;
  globalGradeData: GradeData;
  setGlobalGradeData: React.Dispatch<React.SetStateAction<GradeData>>;
}

export const useGradingLogic = ({
  students,
  tps,
  subject,
  initialClass,
  globalGradeData,
  setGlobalGradeData
}: UseGradingLogicProps) => {
  // --- STATE ---
  const [errorMap, setErrorMap] = useState<{[key: string]: string}>({});
  const [currentTime, setCurrentTime] = useState(new Date());

  // Weights State
  const [showConfig, setShowConfig] = useState(false);
  const [weights, setWeights] = useState({ criteria: 90, attitude: 10 });
  const [tempWeights, setTempWeights] = useState({ criteria: 90, attitude: 10 });

  // Filters
  const [selectedClass, setSelectedClass] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>(subject.id);

  // --- EFFECTS ---

  // Handle navigation from Dashboard
  useEffect(() => {
    if (initialClass) {
        setSelectedClass(initialClass);
    }
  }, [initialClass]);

  // Update time every minute
  useEffect(() => {
    const interval = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(interval);
  }, []);

  // --- COMPUTED ---

  const availableClasses = useMemo(() => {
      const classes = new Set(students.map(s => s.className).filter(Boolean));
      return Array.from(classes).sort() as string[];
  }, [students]);

  const filteredStudents = useMemo(() => {
      if (!selectedClass) return [];
      return students.filter(s => s.className === selectedClass);
  }, [students, selectedClass]);

  // Stats Calculation
  const stats = useMemo(() => {
      return filteredStudents.reduce((acc, student) => {
          const res = calculateStudentGrade(student.id, globalGradeData, tps, subject.kktp);
          if (res.finalScore > 0) {
              if (res.isPassed) acc.tuntas++; else acc.remedial++;
          }
          return acc;
      }, { tuntas: 0, remedial: 0 });
  }, [filteredStudents, globalGradeData, tps, subject.kktp]);

  // --- HANDLERS ---

  const handleScoreChange = useCallback((
    studentId: string, 
    type: 'criteria' | 'attitude', 
    id: string | 'value', 
    value: string
  ) => {
    const numValue = value === '' ? undefined : parseFloat(value);
    const result = scoreSchema.safeParse(numValue);
    const errorKey = `${studentId}-${type}-${id}`;

    if (!result.success && value !== '') {
        setErrorMap(prev => ({...prev, [errorKey]: result.error.issues[0].message}));
    } else {
        setErrorMap(prev => {
            const newMap = {...prev};
            delete newMap[errorKey];
            return newMap;
        });
    }

    setGlobalGradeData(prev => {
      const studentData = prev[studentId] || { scores: {}, attitude: 0 };
      if (type === 'criteria') {
        return { ...prev, [studentId]: { ...studentData, scores: { ...studentData.scores, [id]: numValue as number } } };
      } else {
        return { ...prev, [studentId]: { ...studentData, attitude: numValue || 0 } };
      }
    });
  }, [setGlobalGradeData]);

  const handleSaveWeights = () => {
      if (tempWeights.criteria + tempWeights.attitude !== 100) {
          alert("Total bobot harus 100%");
          return;
      }
      setWeights(tempWeights);
      setShowConfig(false);
  };

  return {
    state: {
      errorMap,
      currentTime,
      showConfig,
      weights,
      tempWeights,
      selectedClass,
      selectedSubject
    },
    setters: {
      setShowConfig,
      setTempWeights,
      setSelectedClass,
      setSelectedSubject
    },
    computed: {
      availableClasses,
      filteredStudents,
      stats
    },
    handlers: {
      handleScoreChange,
      handleSaveWeights
    }
  };
};

