  const handleSaveGeneratedTPs = useCallback((newTps: LearningObjective[]) => {
      setTps(prev => [...prev, ...newTps]);
      Swal.fire('Tersimpan!', `${newTps.length} TP berhasil ditambahkan.`, 'success');
      navigate('/curriculum');
  }, [navigate]);

  // Context Navigation Wrapper
  const handleContextNavigate = (tab: TabView, context: { className?: string, scheduleId?: string } = {}) => {
      // Logic to map legacy TabView to Routes (mostly for Dashboard widgets)
      if (tab === TabView.ATTENDANCE) {
          navigate('/akademik/attendance', { state: context });
      } else if (tab === TabView.JOURNAL) {
          navigate('/akademik/journal', { state: context });
      } else if (tab === TabView.GRADING) {
          navigate('/akademik/grading', { state: context });
      } else {
          // Default fallbacks handled by Sidebar links mostly
          console.log("Navigating to:", tab, context);
      }
  };

  // Helper for admin actions (simplified for brevity as they are passed to AdminPanel)
  const adminActions = {
      onAddUser: async (d: RegisterData) => { /* logic */ }, 
      onDeleteUser: async (id: string) => { /* logic */ },
      onUpdateUser: async (id: string, d: RegisterData) => { /* logic */ },
      onApproveUser: async (id: string) => { /* logic */ },
      onRejectUser: async (id: string) => { /* logic */ },
      onUpdateWaNumber: (num: string) => { 
          setAdminWaNumber(num); 
          localStorage.setItem('siguru_admin_wa', num);
          Swal.fire('Sukses', 'WA diperbarui', 'success');
      }
  };

  // Loading Screen
  if (isLoadingAuth) {
      return (
          <div className="flex h-screen w-full items-center justify-center bg-background-light">
              <div className="flex flex-col items-center gap-4">
                  <div className="size-12 border-4 border-slate-200 border-t-primary rounded-full animate-spin"></div>
                  <p className="text-slate-500 font-bold text-sm animate-pulse">Memuat Data...</p>
              </div>
          </div>
      );
  }

  return (
    <Suspense fallback={<PageLoader />}>
      <Routes>
        {/* PUBLIC ROUTE */}
        <Route 
            path="/login" 
            element={
                currentUser ? <Navigate to="/dashboard" replace /> : 
                <LoginPage onLogin={handleLogin} onRegister={handleRegister} isLoading={isLoadingAuth} adminWaNumber={adminWaNumber} />
            } 
        />

        {/* ADMIN ROUTE */}
        <Route 
            path="/admin" 
            element={
                <ProtectedRoute user={currentUser} allowedRoles={['ADMIN']}>
                    <AdminPanel 
                        users={allUsers} 
                        {...adminActions}
                        onGoToApp={() => navigate('/dashboard')}
                        onLogout={handleLogout}
                        waNumber={adminWaNumber}
                    />
                </ProtectedRoute>
            } 
        />

        {/* PROTECTED APP ROUTES */}
        <Route element={<ProtectedRoute user={currentUser}><MainLayout identity={identity} currentUser={currentUser} onLogout={handleLogout} /></ProtectedRoute>}>
            <Route path="/" element={<Navigate to="/dashboard" replace />} />

            <Route path="dashboard" element={
                <Dashboard 
                    onNavigate={handleContextNavigate} identity={identity} schedules={schedules}
                    classes={classes} students={students} attendanceData={attendanceData}
                    gradeData={gradeData} subject={subject} tps={tps}
                />
            } />

            <Route path="identity" element={
                <IdentityForm data={identity} onSave={handleIdentitySave} onBack={() => navigate('/dashboard')} />
            } />

            {/* MASTER DATA */}
            <Route path="master">
                <Route path="classes" element={
                    <ClassManager identity={identity} classes={classes} students={students} onUpdateClasses={setClasses} onBack={() => navigate('/dashboard')} />
                } />
                <Route path="students" element={
                    <StudentManager identity={identity} students={students} classes={classes} onUpdateStudents={setStudents} onUpdateClasses={setClasses} onBack={() => navigate('/dashboard')} />
                } />
                <Route path="schedules" element={
                    <ScheduleManager schedules={schedules} classes={classes} onUpdateSchedules={setSchedules} onBack={() => navigate('/dashboard')} />
                } />
            </Route>

            {/* CURRICULUM */}
            <Route path="curriculum">
                <Route index element={
                    <CurriculumManager identity={identity} subject={subject} tps={tps} onUpdateSubject={(kktp) => setSubject(prev => ({...prev, kktp}))} onUpdateTPs={setTps} onBack={() => navigate('/dashboard')} />
                } />
                <Route path="cp-generator" element={
                    <CPGenerator onSave={handleSaveGeneratedTPs} onBack={() => navigate('/dashboard')} />
                } />
            </Route>

            {/* AKADEMIK */}
            <Route path="akademik">
                <Route path="journal" element={
                    <JournalManager journals={journals} onUpdateJournals={setJournals} tps={tps} schedules={schedules} classes={classes} onBack={() => navigate('/dashboard')} />
                } />
                <Route path="grading" element={
                    <GradingSheet students={students} tps={tps} subject={subject} globalGradeData={gradeData} setGlobalGradeData={setGradeData} />
                } />
                <Route path="attendance" element={
                    <AttendanceSheet students={students} subject={subject} schedules={schedules} globalAttendance={attendanceData} setGlobalAttendance={setAttendanceData} />
                } />
            </Route>

            {/* RECAP */}
            <Route path="recap">
                <Route path="grades" element={
                    <RecapManager students={students} subject={subject} identity={identity} mode='GRADES' globalAttendance={attendanceData} gradeData={gradeData} tps={tps} />
                } />
                <Route path="attendance" element={
                    <RecapManager students={students} subject={subject} identity={identity} mode='ATTENDANCE' globalAttendance={attendanceData} gradeData={gradeData} tps={tps} />
                } />
            </Route>
        </Route>

        {/* 404 CATCH ALL */}
        <Route path="*" element={<NotFound />} />
      </Routes>
    </Suspense>
  );
};

export default function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <HashRouter>
        <AppContent />
      </HashRouter>
    </QueryClientProvider>
  );
}

import React, { useState, useMemo } from 'react';
import { LearningObjective } from '../types';
import { GoogleGenAI, Type } from "@google/genai";

declare const Swal: any;

interface Props {
  onSave: (tps: LearningObjective[]) => void;
  onBack: () => void;
}

// Data Mapping Fase ke Kelas
const PHASE_MAP: { [key: string]: string[] } = {
    'Fase A': ['Kelas 1', 'Kelas 2'],
    'Fase B': ['Kelas 3', 'Kelas 4'],
    'Fase C': ['Kelas 5', 'Kelas 6'],
    'Fase D': ['Kelas 7', 'Kelas 8', 'Kelas 9'],
    'Fase E': ['Kelas 10'],
    'Fase F': ['Kelas 11', 'Kelas 12'],
};

// Mock Subjects
const SUBJECT_OPTIONS = [
    { id: 'Matematika', name: 'Matematika' },
    { id: 'Bahasa Indonesia', name: 'Bahasa Indonesia' },
    { id: 'Bahasa Inggris', name: 'Bahasa Inggris' },
    { id: 'IPA', name: 'Ilmu Pengetahuan Alam (IPA)' },
    { id: 'IPS', name: 'Ilmu Pengetahuan Sosial (IPS)' },
    { id: 'PPKn', name: 'Pendidikan Pancasila' },
    { id: 'PJOK', name: 'PJOK' },
    { id: 'Seni Budaya', name: 'Seni Budaya' },
    { id: 'Informatika', name: 'Informatika' },
    { id: 'PAI', name: 'Pendidikan Agama Islam' },
    { id: 'PAK', name: 'Pendidikan Agama Kristen' },
    { id: 'Sejarah', name: 'Sejarah' },
    { id: 'Geografi', name: 'Geografi' },
    { id: 'Ekonomi', name: 'Ekonomi' },
    { id: 'Sosiologi', name: 'Sosiologi' },
    { id: 'Fisika', name: 'Fisika' },
    { id: 'Kimia', name: 'Kimia' },
    { id: 'Biologi', name: 'Biologi' }
];

// Helper Interfaces for AI Generator State
interface AI_TP {
    id: string;
    code: string;
    description: string;
    level: string; // Cognitive Level (C1-C6)
}

interface AI_Topic {
    id: string;
    title: string; // Lingkup Materi
    tps: AI_TP[];
}

interface AllocationItem extends AI_TP {
    topicTitle: string; // Carry over topic for context
    targetClass: string;
    semester: 1 | 2;
}

export const CPGenerator: React.FC<Props> = ({ onSave, onBack }) => {
  // Input State
  const [phase, setPhase] = useState('Fase E'); 
  const [selectedSubject, setSelectedSubject] = useState('Matematika'); 
  const [cpText, setCpText] = useState('');

  // Processing State
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedTopics, setGeneratedTopics] = useState<AI_Topic[]>([]);
  const [allocatedItems, setAllocatedItems] = useState<AllocationItem[]>([]);

  // Drag State
  const [draggedItem, setDraggedItem] = useState<{ tp: AI_TP, topicTitle: string } | null>(null);

  // --- COMPUTED ---
  const targetClasses = useMemo(() => PHASE_MAP[phase] || [], [phase]);

  // --- LOGIC ---

  const handleGenerate = async () => {
    if (!cpText.trim()) {
        Swal.fire('Error', 'Teks CP tidak boleh kosong.', 'error');
        return;
    }

    setIsGenerating(true);
    setGeneratedTopics([]);
    setAllocatedItems([]);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const prompt = `
        Role: Expert Curriculum Developer (Kurikulum Merdeka).
        Task: Analyze the Capaian Pembelajaran (CP) for Subject '${selectedSubject}' in '${phase}'.

        Instructions:
        1. Break down the CP into "Lingkup Materi" (Topics).
        2. For each Topic, generate a scaffolding list of "Tujuan Pembelajaran" (TP).
        3. Assign a cognitive level (Bloom's Taxonomy: C1-C6) to each TP.
        4. Output strictly as JSON.

        CP Text: "${cpText}"
        `;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            lingkup_materi: { type: Type.STRING, description: "Judul Lingkup Materi" },
                            tps: {
                                type: Type.ARRAY,
                                items: {
                                    type: Type.OBJECT,
                                    properties: {
                                        deskripsi: { type: Type.STRING, description: "Kalimat Tujuan Pembelajaran" },
                                        level_kognitif: { type: Type.STRING, description: "C1, C2, C3, C4, C5, atau C6" }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        });

        const rawData = JSON.parse(response.text || '[]');

        // Transform to internal state
        const processed: AI_Topic[] = rawData.map((topic: any, tIdx: number) => ({
            id: `topic-${tIdx}`,
            title: topic.lingkup_materi,
            tps: topic.tps.map((tp: any, tpIdx: number) => ({
                id: `gen-tp-${tIdx}-${tpIdx}`,
                code: `TP.${tIdx + 1}.${tpIdx + 1}`,
                description: tp.deskripsi,
                level: tp.level_kognitif
            }))
        }));

        setGeneratedTopics(processed);
        Swal.fire('Generate Berhasil', `Ditemukan ${processed.length} Lingkup Materi.`, 'success');

    } catch (error: any) {
        console.error("AI Error:", error);
        Swal.fire('Gagal', error.message, 'error');
    } finally {
        setIsGenerating(false);
    }
  };

  // --- DRAG & DROP HANDLERS ---

  const onDragStart = (e: React.DragEvent, tp: AI_TP, topicTitle: string) => {
      setDraggedItem({ tp, topicTitle });
      e.dataTransfer.setData('text/plain', tp.id); // Required for Firefox
      e.dataTransfer.effectAllowed = 'copyMove';
  };

  const onDragOver = (e: React.DragEvent) => {
      e.preventDefault(); // Allow drop
      e.dataTransfer.dropEffect = 'move';
  };

  const onDrop = (e: React.DragEvent, targetClass: string, semester: 1 | 2) => {
      e.preventDefault();
      if (!draggedItem) return;

      // Check if already allocated
      const isExists = allocatedItems.some(i => i.id === draggedItem.tp.id);
      if (isExists) {
          // Move logic (Update existing)
          setAllocatedItems(prev => prev.map(item => 
              item.id === draggedItem.tp.id 
                  ? { ...item, targetClass, semester } 
                  : item
          ));
      } else {
          // Add new allocation
          setAllocatedItems(prev => [...prev, {
              ...draggedItem.tp,
              topicTitle: draggedItem.topicTitle,
              targetClass,
              semester
          }]);

          // Remove from source list (visual cleanup)
          setGeneratedTopics(prev => prev.map(topic => ({
              ...topic,
              tps: topic.tps.filter(t => t.id !== draggedItem.tp.id)
          })).filter(t => t.tps.length > 0)); // Remove empty topics
      }
      setDraggedItem(null);
  };

  const onReturnToPool = (item: AllocationItem) => {
      // Remove from allocation
      setAllocatedItems(prev => prev.filter(i => i.id !== item.id));

      // Add back to pool (Simplified: Find topic or create temp topic)
      setGeneratedTopics(prev => {
          const existingTopicIndex = prev.findIndex(t => t.title === item.topicTitle);
          if (existingTopicIndex >= 0) {
              const updated = [...prev];
              updated[existingTopicIndex].tps.push({
                  id: item.id,
                  code: item.code,
                  description: item.description,
                  level: item.level
              });
              // Sort TPs by code to keep order roughly
              updated[existingTopicIndex].tps.sort((a,b) => a.code.localeCompare(b.code));
              return updated;
          } else {
              // Re-create topic if it was removed
              return [...prev, {
                  id: `restored-${Date.now()}`,
                  title: item.topicTitle,
                  tps: [{
                      id: item.id,
                      code: item.code,
                      description: item.description,
                      level: item.level
                  }]
              }];
          }
      });
  };

  // --- SAVE & RESET ---

  const handleReset = () => {
      Swal.fire({
          title: 'Reset Generator?',
          text: "Semua hasil generate dan alokasi akan dihapus.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          confirmButtonText: 'Ya, Reset'
      }).then((result: any) => {
          if (result.isConfirmed) {
              setGeneratedTopics([]);
              setAllocatedItems([]);
              setCpText('');
          }
      });
  };

  const handleSaveAll = () => {
      if (allocatedItems.length === 0) {
          Swal.fire('Belum Ada Alokasi', 'Silahkan drag & drop TP ke dalam Kelas/Semester terlebih dahulu.', 'warning');
          return;
      }

      // Convert to LearningObjective type
      const finalTPs: LearningObjective[] = allocatedItems.map(item => ({
          id: item.id,
          code: item.code,
          description: item.description,
          semester: item.semester,
          scopeId: item.targetClass, // IMPORTANT: Save CLASS as SCOPE
          subjectId: selectedSubject,
          lms: [
              // Auto-create 1 LM based on the Topic Title
              {
                  id: `auto-lm-${item.id}`,
                  code: 'LM.1',
                  title: item.topicTitle
              }
          ],
          criteria: []
      }));

      onSave(finalTPs);
  };

  // Helper for Bloom Colors
  const getBloomColor = (level: string) => {
      if (['C1', 'C2'].some(l => level.includes(l))) return 'bg-green-100 text-green-700 border-green-200';
      if (['C3', 'C4'].some(l => level.includes(l))) return 'bg-blue-100 text-blue-700 border-blue-200';
      return 'bg-purple-100 text-purple-700 border-purple-200';
  };

  return (
    <div className="max-w-[1600px] mx-auto pb-24">
        {/* Header */}
        <div className="flex items-center gap-2 mb-6">
            <button onClick={onBack} className="text-slate-500 text-sm font-medium hover:text-primary">Beranda</button>
            <span className="text-slate-400 text-sm font-medium">/</span>
            <span className="text-primary text-sm font-bold">AI Kurikulum Generator</span>
        </div>

        <div className="grid grid-cols-12 gap-6 h-[calc(100vh-140px)]">

            {/* LEFT PANEL: CONFIG & SOURCE (3 Columns) */}
            <div className="col-span-12 md:col-span-3 flex flex-col gap-4 h-full overflow-hidden">
                {/* 1. Input Box */}
                <div className="bg-white border border-slate-200 rounded-xl p-5 shadow-sm shrink-0">
                    <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2 text-sm">
                        <span className="material-symbols-outlined text-primary text-lg">settings</span>
                        Konfigurasi Input
                    </h3>
                    <div className="space-y-3">
                        <div>
                            <label className="text-[10px] font-bold text-slate-500 uppercase block mb-1">Fase (Tingkat)</label>
                            <select 
                                value={phase} 
                                onChange={e => setPhase(e.target.value)} 
                                className="w-full border-slate-200 rounded-lg text-sm font-bold text-slate-800 focus:ring-primary py-2"
                            >
                                {Object.keys(PHASE_MAP).map(p => <option key={p} value={p}>{p}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="text-[10px] font-bold text-slate-500 uppercase block mb-1">Mata Pelajaran</label>
                            <select 
                                value={selectedSubject} 
                                onChange={e => setSelectedSubject(e.target.value)} 
                                className="w-full border-slate-200 rounded-lg text-sm font-bold text-slate-800 focus:ring-primary py-2"
                            >
                                {SUBJECT_OPTIONS.map(subj => (
                                    <option key={subj.id} value={subj.id}>{subj.name}</option>
                                ))}
                            </select>
                        </div>
                        <div>
                            <label className="text-[10px] font-bold text-slate-500 uppercase block mb-1">Teks CP</label>
                            <textarea 
                                value={cpText}
                                onChange={e => setCpText(e.target.value)}
                                rows={4}
                                placeholder="Paste naskah CP di sini..."
                                className="w-full border-slate-200 rounded-lg text-xs text-slate-700 p-2 focus:ring-primary resize-none"
                            ></textarea>
                        </div>
                        <button 
                            onClick={handleGenerate}
                            disabled={isGenerating}
                            className={`w-full py-2.5 rounded-lg font-bold text-white text-sm shadow-md transition-all flex justify-center items-center gap-2
                                ${isGenerating ? 'bg-slate-400 cursor-not-allowed' : 'bg-primary hover:bg-blue-600'}
                            `}
                        >
                            {isGenerating ? <span className="size-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></span> : <span className="material-symbols-outlined text-lg">auto_awesome</span>}
                            {isGenerating ? 'Processing...' : 'Generate TP'}
                        </button>
                    </div>
                </div>

                {/* 2. Generated Pool (Scrollable) */}
                <div className="flex-1 bg-slate-50 border border-slate-200 rounded-xl overflow-hidden flex flex-col">
                    <div className="p-3 border-b border-slate-200 bg-white flex justify-between items-center">
                        <span className="text-xs font-bold text-slate-600 uppercase flex items-center gap-1">
                            <span className="material-symbols-outlined text-sm">psychology</span> Hasil AI
                        </span>
                        <span className="bg-slate-100 text-slate-500 text-[10px] px-2 py-0.5 rounded-full font-bold">
                            {generatedTopics.reduce((acc, t) => acc + t.tps.length, 0)} TP
                        </span>
                    </div>
                    <div className="flex-1 overflow-y-auto p-3 custom-scrollbar space-y-4">
                        {generatedTopics.length === 0 ? (
                            <div className="h-full flex flex-col items-center justify-center text-slate-400 text-center px-4">
                                <span className="material-symbols-outlined text-3xl mb-2 opacity-50">output</span>
                                <p className="text-xs">Belum ada hasil generate.<br/>Masukkan CP dan klik tombol di atas.</p>
                            </div>
                        ) : (
                            generatedTopics.map(topic => (
                                <div key={topic.id} className="space-y-2">
                                    <div className="sticky top-0 bg-slate-100/95 backdrop-blur-sm z-10 px-2 py-1.5 rounded border border-slate-200">
                                        <p className="text-[11px] font-bold text-slate-700 leading-tight flex items-center gap-1">
                                            <span className="material-symbols-outlined text-sm text-primary">topic</span>
                                            {topic.title}
                                        </p>
                                    </div>
                                    <div className="grid gap-2">
                                        {topic.tps.map(tp => (
                                            <div 
                                                key={tp.id}
                                                draggable
                                                onDragStart={(e) => onDragStart(e, tp, topic.title)}
                                                className="bg-white p-2.5 rounded-lg border border-slate-200 shadow-sm cursor-grab active:cursor-grabbing hover:border-primary hover:shadow-md transition-all group relative"
                                            >
                                                <div className="flex justify-between items-start mb-1">
                                                    <span className="text-[10px] font-bold text-slate-400">{tp.code}</span>
                                                    <span className={`text-[9px] px-1.5 py-0.5 rounded font-bold border ${getBloomColor(tp.level)}`}>
                                                        {tp.level}
                                                    </span>
                                                </div>
                                                <p className="text-xs text-slate-700 leading-snug">{tp.description}</p>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            </div>

            {/* RIGHT PANEL: ALLOCATION GRID (9 Columns) */}
            <div className="col-span-12 md:col-span-9 bg-white border border-slate-200 rounded-xl overflow-hidden flex flex-col shadow-sm">
                <div className="p-4 border-b border-slate-200 bg-slate-50 flex justify-between items-center">
                    <div>
                        <h3 className="font-bold text-slate-800 flex items-center gap-2">
                            <span className="material-symbols-outlined text-primary">view_column</span>
                            Alur Tujuan Pembelajaran (ATP) - {phase}
                        </h3>
                        <p className="text-xs text-slate-500 mt-0.5">Drag TP dari panel kiri ke kotak semester kelas yang sesuai.</p>
                    </div>
                    <div className="flex items-center gap-4 text-xs font-bold text-slate-500">
                        <div className="flex items-center gap-1"><span className="size-3 bg-blue-50 border border-blue-200 rounded"></span> Semester 1</div>
                        <div className="flex items-center gap-1"><span className="size-3 bg-purple-50 border border-purple-200 rounded"></span> Semester 2</div>
                    </div>
                </div>

                <div className="flex-1 overflow-x-auto overflow-y-hidden p-6 bg-slate-100/50">
                    <div className="flex gap-6 h-full min-w-max">
                        {targetClasses.map((clsName) => (
                            <div key={clsName} className="w-80 flex flex-col gap-0 bg-white border border-slate-300 rounded-xl shadow-sm overflow-hidden h-full">
                                {/* Class Header */}
                                <div className="bg-slate-800 text-white py-2 px-4 text-center font-bold text-sm tracking-wide">
                                    {clsName}
                                </div>

                                {/* Semester 1 Zone */}
                                <div 
                                    onDrop={(e) => onDrop(e, clsName, 1)}
                                    onDragOver={onDragOver}
                                    className="flex-1 bg-blue-50/30 p-3 border-b border-dashed border-slate-300 overflow-y-auto custom-scrollbar flex flex-col gap-2 relative transition-colors hover:bg-blue-100/50"
                                >
                                    <div className="sticky top-0 z-10 flex justify-center mb-2 pointer-events-none">
                                        <span className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-[10px] font-bold shadow-sm border border-blue-200">
                                            Semester 1 (Ganjil)
                                        </span>
                                    </div>
                                    {allocatedItems.filter(i => i.targetClass === clsName && i.semester === 1).map(item => (
                                        <div key={item.id} className="bg-white p-2.5 rounded-lg border border-slate-200 shadow-sm text-xs relative group hover:border-red-300 transition-all">
                                            <div className="flex justify-between mb-1">
                                                <span className="font-bold text-blue-600">{item.code}</span>
                                                <button onClick={() => onReturnToPool(item)} className="text-slate-300 hover:text-red-500"><span className="material-symbols-outlined text-sm">close</span></button>
                                            </div>
                                            <p className="text-slate-700 line-clamp-3">{item.description}</p>
                                            <div className="mt-1 pt-1 border-t border-slate-100 text-[9px] text-slate-400 truncate">
                                                {item.topicTitle}
                                            </div>
                                        </div>
                                    ))}
