  const [newItemType, setNewItemType] = useState<AssessmentType>('FORMATIVE');

  // --- DERIVED SCOPES (Flexible based on Level) ---
  const scopes = useMemo(() => {
      // Default Scopes (Classes)
      if (identity.level === 'SD') {
          return [
              { id: 'Kelas 1', name: 'Kelas 1 (Fase A)' },
              { id: 'Kelas 2', name: 'Kelas 2 (Fase A)' },
              { id: 'Kelas 3', name: 'Kelas 3 (Fase B)' },
              { id: 'Kelas 4', name: 'Kelas 4 (Fase B)' },
              { id: 'Kelas 5', name: 'Kelas 5 (Fase C)' },
              { id: 'Kelas 6', name: 'Kelas 6 (Fase C)' },
          ];
      } else if (identity.level === 'SMP') {
          return [
              { id: 'Kelas 7', name: 'Kelas 7 (Fase D)' },
              { id: 'Kelas 8', name: 'Kelas 8 (Fase D)' },
              { id: 'Kelas 9', name: 'Kelas 9 (Fase D)' },
          ];
      } else { // SMA / SMK
          return [
              { id: 'Kelas 10', name: 'Kelas 10 (Fase E)' },
              { id: 'Kelas 11', name: 'Kelas 11 (Fase F)' },
              { id: 'Kelas 12', name: 'Kelas 12 (Fase F)' },
          ];
      }
  }, [identity.level]);

  // Filter States
  const [activeScopeId, setActiveScopeId] = useState<string>(scopes[0].id);
  const [activeSubjectId, setActiveSubjectId] = useState<string>(
      identity.role === 'SUBJECT_TEACHER' ? identity.subjectName : 'Matematika'
  );

  useEffect(() => {
      // Ensure activeScopeId is valid when scopes change (e.g. login level change)
      const exists = scopes.find(s => s.id === activeScopeId);
      if (!exists && scopes.length > 0) setActiveScopeId(scopes[0].id);
  }, [scopes, activeScopeId]);

  const filteredTPs = useMemo(() => {
      return tps.filter(tp => {
          // Strict filtering: scopeId must match exactly (e.g., "Kelas 10")
          const scopeMatch = tp.scopeId === activeScopeId;
          const subjectMatch = tp.subjectId ? tp.subjectId === activeSubjectId : true; 
          return scopeMatch && subjectMatch;
      });
  }, [tps, activeScopeId, activeSubjectId]);

  // --- HANDLERS (CRUD) ---

  const handleAddTP = () => {
    if(!newTpForm.code || !newTpForm.description) return;
    const newTp: LearningObjective = {
        id: Date.now().toString(),
        code: newTpForm.code.toUpperCase(), 
        description: newTpForm.description,
        semester: Number(newTpForm.semester) as 1 | 2,
        scopeId: activeScopeId,
        subjectId: activeSubjectId, 
        lms: [],
        criteria: []
    };
    onUpdateTPs([...tps, newTp]);
    setIsAddingTp(false);
    setNewTpForm({ code: '', description: '', semester: '1' });
  };

  const handleDeleteTP = (id: string) => {
      Swal.fire({
          title: 'Hapus Tujuan Pembelajaran?',
          text: "Seluruh Lingkup Materi (LM) dan Kriteria yang ada di dalamnya akan ikut terhapus!",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateTPs(tps.filter(t => t.id !== id));
              Swal.fire('Terhapus!', 'TP berhasil dihapus.', 'success')
          }
      });
  };

  const handleAddItem = () => {
      if(!newItemForm.val1 || !newItemForm.val2 || !newItemForm.parentId || !newItemForm.type) return;

      const updatedTPs = tps.map(tp => {
          if(tp.id === newItemForm.parentId) {
              if(newItemForm.type === 'LM') {
                  return {
                      ...tp,
                      lms: [...tp.lms, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), 
                          title: newItemForm.val2 
                      }]
                  };
              } else {
                  return {
                      ...tp,
                      criteria: [...tp.criteria, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), 
                          description: newItemForm.val2,
                          type: newItemType 
                      }]
                  };
              }
          }
          return tp;
      });

      onUpdateTPs(updatedTPs);
      setNewItemForm({ type: null, parentId: null, val1: '', val2: '' });
      setNewItemType('FORMATIVE');
  };

  const handleDeleteSubItem = (tpId: string, itemId: string, type: 'LM' | 'CRITERIA') => {
      Swal.fire({
          title: 'Hapus Item?',
          text: "Item ini akan dihapus permanen.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              const updatedTPs = tps.map(tp => {
                  if(tp.id === tpId) {
                      if(type === 'LM') {
                          return { ...tp, lms: tp.lms.filter(l => l.id !== itemId) };
                      } else {
                          return { ...tp, criteria: tp.criteria.filter(c => c.id !== itemId) };
                      }
                  }
                  return tp;
              });
              onUpdateTPs(updatedTPs);
          }
      });
  };

  // --- AI GENERATION ---
  const generateTpDetails = async (tp: LearningObjective) => {
      if (tp.lms.length > 0 || tp.criteria.length > 0) {
          const result = await Swal.fire({
              title: 'TP Sudah Memiliki Detail',
              text: "Data Lingkup Materi dan Kriteria yang sudah ada mungkin akan terduplikasi. Lanjutkan generate?",
              icon: 'warning',
              showCancelButton: true,
              confirmButtonText: 'Ya, Tambahkan',
              cancelButtonText: 'Batal'
          });
          if (!result.isConfirmed) return;
      }

      setGeneratingTpId(tp.id);

      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
          const prompt = `
            Role: Expert Curriculum Developer for Indonesian School (Kurikulum Merdeka).
            Context: Subject '${activeSubjectId}' for Grade '${activeScopeId}'.
            Task: Based on the Learning Objective (TP) below, generate strictly:
            1. 3 specific 'Lingkup Materi' (Learning Materials/Scope) titles.
            2. 3 specific 'Assessment Criteria' (Kriteria Ketercapaian TP). Ensure mixed types (Formatif/Sumatif).

            TP Description: "${tp.description}" (Code: ${tp.code})

            Output must be valid JSON object with arrays 'lms' and 'criteria'.
          `;

          const response = await ai.models.generateContent({
              model: "gemini-3-flash-preview",
              contents: prompt,
              config: {
                  responseMimeType: "application/json",
                  responseSchema: {
                      type: Type.OBJECT,
                      properties: {
                          lms: {
                              type: Type.ARRAY,
                              items: {
                                  type: Type.OBJECT,
                                  properties: {
                                      code: { type: Type.STRING },
                                      title: { type: Type.STRING }
                                  }
                              }
                          },
                          criteria: {
                              type: Type.ARRAY,
                              items: {
                                  type: Type.OBJECT,
                                  properties: {
                                      code: { type: Type.STRING },
                                      description: { type: Type.STRING },
                                      type: { type: Type.STRING, enum: ["FORMATIVE", "SUMMATIVE"] }
                                  }
                              }
                          }
                      }
                  }
              }
          });

          const json = JSON.parse(response.text || '{}');

          if (json.lms && json.criteria) {
              const newLms: LearningMaterial[] = json.lms.map((lm: any, idx: number) => ({
                  id: `gen-lm-${Date.now()}-${idx}`,
                  code: lm.code || `LM.${tp.lms.length + idx + 1}`,
                  title: lm.title
              }));

              const newCriteria: AssessmentCriteria[] = json.criteria.map((cr: any, idx: number) => ({
                  id: `gen-cr-${Date.now()}-${idx}`,
                  code: cr.code || `KR.${tp.criteria.length + idx + 1}`,
                  description: cr.description,
                  type: (cr.type === 'SUMMATIVE' ? 'SUMMATIVE' : 'FORMATIVE') as AssessmentType
              }));

              const updatedTPs = tps.map(t => {
                  if (t.id === tp.id) {
                      return {
                          ...t,
                          lms: [...t.lms, ...newLms],
                          criteria: [...t.criteria, ...newCriteria]
                      };
                  }
                  return t;
              });

              onUpdateTPs(updatedTPs);
              setExpandedTpId(tp.id);
              Swal.fire({
                  title: 'Generate Berhasil',
                  text: `Ditambahkan ${newLms.length} Materi dan ${newCriteria.length} Kriteria.`,
                  icon: 'success',
                  timer: 2000
              });
          }

      } catch (error: any) {
          console.error(error);
          Swal.fire('Gagal Generate', error.message, 'error');
      } finally {
          setGeneratingTpId(null);
      }
  };

  // --- EXPORT ---
  const handleExportCurriculum = async () => {
    if (filteredTPs.length === 0) return;

    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet('Kurikulum');

    const headerRow = sheet.addRow([
        'No', 'Semester', 'Mata Pelajaran', 'Lingkup Materi (Scope/Fase)', 'Kelas', 'Tujuan Pembelajaran (TP)', 'Lingkup Materi (LM) Detail'
    ]);

    headerRow.eachCell((cell) => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } };
        cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
    });

    const activeScopeName = scopes.find(s => s.id === activeScopeId)?.name || activeScopeId;
    let rowIndex = 1;

    filteredTPs.forEach((tp) => {
        if (tp.lms.length > 0) {
            tp.lms.forEach(lm => {
                const row = sheet.addRow([
                    rowIndex, `Semester ${tp.semester}`, activeSubjectId, activeScopeName, identity.level,
                    `${tp.code} - ${tp.description}`, `${lm.code} - ${lm.title}`
                ]);
                row.eachCell((cell) => {
                    cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                    cell.alignment = { vertical: 'top', wrapText: true };
                });
            });
        } else {
             const row = sheet.addRow([
                    rowIndex, `Semester ${tp.semester}`, activeSubjectId, activeScopeName, identity.level,
                    `${tp.code} - ${tp.description}`, '-'
            ]);
            row.eachCell((cell) => {
                cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                cell.alignment = { vertical: 'top', wrapText: true };
            });
        }
        rowIndex++;
    });

    sheet.getColumn(6).width = 50;
    sheet.getColumn(7).width = 40;
    sheet.getColumn(3).width = 20;
    sheet.getColumn(4).width = 25;

    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `Kurikulum_${activeScopeName.replace(/\s/g, '_')}_${activeSubjectId}.xlsx`;
    anchor.click();
    window.URL.revokeObjectURL(url);
  };

  return {
    state: {
        expandedTpId,
        generatingTpId,
        isAddingTp,
        newTpForm,
        newItemForm,
        newItemType,
        activeScopeId,
        activeSubjectId,
        scopes,
        subjectOptions: SUBJECT_OPTIONS
    },
    setters: {
        setExpandedTpId,
        setIsAddingTp,
        setNewTpForm,
        setNewItemForm,
        setNewItemType,
        setActiveScopeId,
        setActiveSubjectId
    },
    computed: {
        filteredTPs
    },
    handlers: {
        handleAddTP,
        handleDeleteTP,
        handleAddItem,
        handleDeleteSubItem,
        generateTpDetails,
        handleExportCurriculum
    }
  };
};

import { useState, useMemo, useEffect } from 'react';
import ExcelJS from 'exceljs';
import { GoogleGenAI, Type } from "@google/genai";
import { LearningMaterial, LearningObjective, Subject, AssessmentCriteria, IdentityData, AssessmentType } from '../types';

declare const Swal: any;

const SUBJECT_OPTIONS = [
    { id: 'Matematika', name: 'Matematika' },
    { id: 'Bahasa Indonesia', name: 'Bahasa Indonesia' },
    { id: 'Bahasa Inggris', name: 'Bahasa Inggris' },
    { id: 'IPA', name: 'Ilmu Pengetahuan Alam (IPA)' },
    { id: 'IPS', name: 'Ilmu Pengetahuan Sosial (IPS)' },
    { id: 'PPKn', name: 'Pendidikan Pancasila' },
    { id: 'PJOK', name: 'PJOK' },
    { id: 'Seni Budaya', name: 'Seni Budaya' },
    { id: 'Informatika', name: 'Informatika' },
    { id: 'PAI', name: 'Pendidikan Agama Islam' },
    { id: 'PAK', name: 'Pendidikan Agama Kristen' },
    { id: 'Sejarah', name: 'Sejarah' },
    { id: 'Geografi', name: 'Geografi' },
    { id: 'Ekonomi', name: 'Ekonomi' },
    { id: 'Sosiologi', name: 'Sosiologi' },
    { id: 'Fisika', name: 'Fisika' },
    { id: 'Kimia', name: 'Kimia' },
    { id: 'Biologi', name: 'Biologi' }
];

interface UseCurriculumLogicProps {
  identity: IdentityData;
  tps: LearningObjective[];
  onUpdateTPs: (tps: LearningObjective[]) => void;
}

export const useCurriculumLogic = ({ identity, tps, onUpdateTPs }: UseCurriculumLogicProps) => {
  // --- STATE ---
  const [expandedTpId, setExpandedTpId] = useState<string | null>(null);
  const [generatingTpId, setGeneratingTpId] = useState<string | null>(null);
  const [isAddingTp, setIsAddingTp] = useState(false);

  // Forms
  const [newTpForm, setNewTpForm] = useState({ code: '', description: '', semester: '1' });
  const [newItemForm, setNewItemForm] = useState<{
      type: 'LM' | 'CRITERIA' | null, 
      parentId: string | null,
      val1: string, 
      val2: string 
  }>({ type: null, parentId: null, val1: '', val2: '' });
  const [newItemType, setNewItemType] = useState<AssessmentType>('FORMATIVE');

  // --- DERIVED SCOPES (Flexible based on Level) ---
  const scopes = useMemo(() => {
      // Default Scopes (Classes)
      if (identity.level === 'SD') {
          return [
              { id: 'Kelas 1', name: 'Kelas 1 (Fase A)' },
              { id: 'Kelas 2', name: 'Kelas 2 (Fase A)' },
              { id: 'Kelas 3', name: 'Kelas 3 (Fase B)' },
              { id: 'Kelas 4', name: 'Kelas 4 (Fase B)' },
              { id: 'Kelas 5', name: 'Kelas 5 (Fase C)' },
              { id: 'Kelas 6', name: 'Kelas 6 (Fase C)' },
          ];
      } else if (identity.level === 'SMP') {
          return [
              { id: 'Kelas 7', name: 'Kelas 7 (Fase D)' },
              { id: 'Kelas 8', name: 'Kelas 8 (Fase D)' },
              { id: 'Kelas 9', name: 'Kelas 9 (Fase D)' },
          ];
      } else { // SMA / SMK
          return [
              { id: 'Kelas 10', name: 'Kelas 10 (Fase E)' },
              { id: 'Kelas 11', name: 'Kelas 11 (Fase F)' },
              { id: 'Kelas 12', name: 'Kelas 12 (Fase F)' },
          ];
      }
  }, [identity.level]);

  // Filter States
  const [activeScopeId, setActiveScopeId] = useState<string>(scopes[0].id);
  const [activeSubjectId, setActiveSubjectId] = useState<string>(
      identity.role === 'SUBJECT_TEACHER' ? identity.subjectName : 'Matematika'
  );

  useEffect(() => {
      // Ensure activeScopeId is valid when scopes change (e.g. login level change)
      const exists = scopes.find(s => s.id === activeScopeId);
      if (!exists && scopes.length > 0) setActiveScopeId(scopes[0].id);
  }, [scopes, activeScopeId]);

  const filteredTPs = useMemo(() => {
      return tps.filter(tp => {
          // Strict filtering: scopeId must match exactly (e.g., "Kelas 10")
          const scopeMatch = tp.scopeId === activeScopeId;
          const subjectMatch = tp.subjectId ? tp.subjectId === activeSubjectId : true; 
          return scopeMatch && subjectMatch;
      });
  }, [tps, activeScopeId, activeSubjectId]);

  // --- HANDLERS (CRUD) ---

  const handleAddTP = () => {
    if(!newTpForm.code || !newTpForm.description) return;
    const newTp: LearningObjective = {
        id: Date.now().toString(),
        code: newTpForm.code.toUpperCase(), 
        description: newTpForm.description,
        semester: Number(newTpForm.semester) as 1 | 2,
        scopeId: activeScopeId,
        subjectId: activeSubjectId, 
        lms: [],
        criteria: []
    };
    onUpdateTPs([...tps, newTp]);
    setIsAddingTp(false);
    setNewTpForm({ code: '', description: '', semester: '1' });
  };

  const handleDeleteTP = (id: string) => {
      Swal.fire({
          title: 'Hapus Tujuan Pembelajaran?',
          text: "Seluruh Lingkup Materi (LM) dan Kriteria yang ada di dalamnya akan ikut terhapus!",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateTPs(tps.filter(t => t.id !== id));
              Swal.fire('Terhapus!', 'TP berhasil dihapus.', 'success')
          }
      });
  };

  const handleAddItem = () => {
      if(!newItemForm.val1 || !newItemForm.val2 || !newItemForm.parentId || !newItemForm.type) return;

      const updatedTPs = tps.map(tp => {
          if(tp.id === newItemForm.parentId) {
              if(newItemForm.type === 'LM') {
                  return {
                      ...tp,
                      lms: [...tp.lms, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), 
                          title: newItemForm.val2 
                      }]
                  };
              } else {
                  return {
                      ...tp,
                      criteria: [...tp.criteria, { 
                          id: Date.now().toString(), 
                          code: newItemForm.val1.toUpperCase(), 
                          description: newItemForm.val2,
                          type: newItemType 
                      }]
                  };
              }
          }
          return tp;
      });

      onUpdateTPs(updatedTPs);
      setNewItemForm({ type: null, parentId: null, val1: '', val2: '' });
      setNewItemType('FORMATIVE');
  };

  const handleDeleteSubItem = (tpId: string, itemId: string, type: 'LM' | 'CRITERIA') => {
      Swal.fire({
          title: 'Hapus Item?',
          text: "Item ini akan dihapus permanen.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              const updatedTPs = tps.map(tp => {
                  if(tp.id === tpId) {
                      if(type === 'LM') {
                          return { ...tp, lms: tp.lms.filter(l => l.id !== itemId) };
                      } else {
                          return { ...tp, criteria: tp.criteria.filter(c => c.id !== itemId) };
                      }
                  }
                  return tp;
              });
              onUpdateTPs(updatedTPs);
          }
      });
  };

  // --- AI GENERATION (KRITERIA ONLY) ---
  const generateTpDetails = async (tp: LearningObjective) => {
      if (tp.criteria.length > 0) {
          const result = await Swal.fire({
              title: 'TP Sudah Memiliki Kriteria',
              text: "Melanjutkan akan menambahkan kriteria baru (duplikasi mungkin terjadi). Lanjutkan?",
              icon: 'warning',
              showCancelButton: true,
              confirmButtonText: 'Ya, Tambahkan',
              cancelButtonText: 'Batal'
          });
          if (!result.isConfirmed) return;
      }

      setGeneratingTpId(tp.id);

      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
          const prompt = `
            Role: Expert Curriculum Developer for Indonesian School (Kurikulum Merdeka).
            Context: Subject '${activeSubjectId}' for Grade '${activeScopeId}'.
            Task: Based on the Learning Objective (TP) below, generate strictly:

            5 specific 'Assessment Criteria' (Kriteria Ketercapaian Tujuan Pembelajaran / KKTP). 
            - Ensure a mix of types: FORMATIVE (Observasi/Proses) and SUMMATIVE (Tes/Produk).
            - Do NOT generate Learning Materials (Lingkup Materi), focus only on assessment criteria.

            TP Description: "${tp.description}" (Code: ${tp.code})

            Output must be valid JSON object with array 'criteria'.
          `;

          const response = await ai.models.generateContent({
              model: "gemini-3-flash-preview",
              contents: prompt,
              config: {
                  responseMimeType: "application/json",
                  responseSchema: {
                      type: Type.OBJECT,
                      properties: {
                          criteria: {
                              type: Type.ARRAY,
                              items: {
                                  type: Type.OBJECT,
                                  properties: {
                                      code: { type: Type.STRING },
                                      description: { type: Type.STRING },
                                      type: { type: Type.STRING, enum: ["FORMATIVE", "SUMMATIVE"] }
                                  }
                              }
                          }
                      }
                  }
              }
          });

          const json = JSON.parse(response.text || '{}');

          if (json.criteria) {
              // We only update criteria now, LMs are untouched
              const newCriteria: AssessmentCriteria[] = json.criteria.map((cr: any, idx: number) => ({
                  id: `gen-cr-${Date.now()}-${idx}`,
                  code: cr.code || `KR.${tp.criteria.length + idx + 1}`,
                  description: cr.description,
                  type: (cr.type === 'SUMMATIVE' ? 'SUMMATIVE' : 'FORMATIVE') as AssessmentType
              }));

              const updatedTPs = tps.map(t => {
                  if (t.id === tp.id) {
                      return {
                          ...t,
                          // lms stay the same
                          criteria: [...t.criteria, ...newCriteria]
                      };
                  }
                  return t;
              });

              onUpdateTPs(updatedTPs);
              setExpandedTpId(tp.id);
              Swal.fire({
                  title: 'Generate Berhasil',
                  text: `Ditambahkan ${newCriteria.length} Kriteria Penilaian (KKTP).`,
                  icon: 'success',
                  timer: 2000
              });
          }

      } catch (error: any) {
          console.error(error);
          Swal.fire('Gagal Generate', error.message, 'error');
      } finally {
          setGeneratingTpId(null);
      }
  };

  // --- EXPORT ---
  const handleExportCurriculum = async () => {
    if (filteredTPs.length === 0) return;

    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet('Kurikulum');

    const headerRow = sheet.addRow([
        'No', 'Semester', 'Mata Pelajaran', 'Lingkup Materi (Scope/Fase)', 'Kelas', 'Tujuan Pembelajaran (TP)', 'Kriteria Ketercapaian (KKTP)'
    ]);

    headerRow.eachCell((cell) => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } };
        cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
    });

    const activeScopeName = scopes.find(s => s.id === activeScopeId)?.name || activeScopeId;
    let rowIndex = 1;

    filteredTPs.forEach((tp) => {
        if (tp.criteria.length > 0) {
            tp.criteria.forEach(cr => {
                const row = sheet.addRow([
                    rowIndex, `Semester ${tp.semester}`, activeSubjectId, activeScopeName, identity.level,
                    `${tp.code} - ${tp.description}`, `[${cr.type}] ${cr.description}`
                ]);
                row.eachCell((cell) => {
                    cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                    cell.alignment = { vertical: 'top', wrapText: true };
                });
            });
        } else {
             const row = sheet.addRow([
                    rowIndex, `Semester ${tp.semester}`, activeSubjectId, activeScopeName, identity.level,
                    `${tp.code} - ${tp.description}`, '-'
            ]);
            row.eachCell((cell) => {
                cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                cell.alignment = { vertical: 'top', wrapText: true };
            });
        }
        rowIndex++;
    });

    sheet.getColumn(6).width = 50;
    sheet.getColumn(7).width = 40;
    sheet.getColumn(3).width = 20;
    sheet.getColumn(4).width = 25;

    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `Kurikulum_Kriteria_${activeScopeName.replace(/\s/g, '_')}_${activeSubjectId}.xlsx`;
    anchor.click();
    window.URL.revokeObjectURL(url);
  };

  return {
    state: {
        expandedTpId,
        generatingTpId,
        isAddingTp,
        newTpForm,
        newItemForm,
        newItemType,
        activeScopeId,
        activeSubjectId,
        scopes,
        subjectOptions: SUBJECT_OPTIONS
    },
    setters: {
        setExpandedTpId,
        setIsAddingTp,
        setNewTpForm,
        setNewItemForm,
        setNewItemType,
        setActiveScopeId,
        setActiveSubjectId
    },
    computed: {
        filteredTPs
    },
    handlers: {
        handleAddTP,
        handleDeleteTP,
        handleAddItem,
        handleDeleteSubItem,
        generateTpDetails,
        handleExportCurriculum
    }
  };
};

import React, { useState, useMemo } from 'react';
import { LearningObjective } from '../types';
import { GoogleGenAI, Type } from "@google/genai";

declare const Swal: any;

interface Props {
  onSave: (tps: LearningObjective[]) => void;
  onBack: () => void;
}

// Data Mapping Fase ke Kelas
const PHASE_MAP: { [key: string]: string[] } = {
    'Fase A': ['Kelas 1', 'Kelas 2'],
    'Fase B': ['Kelas 3', 'Kelas 4'],
    'Fase C': ['Kelas 5', 'Kelas 6'],
    'Fase D': ['Kelas 7', 'Kelas 8', 'Kelas 9'],
    'Fase E': ['Kelas 10'],
    'Fase F': ['Kelas 11', 'Kelas 12'],
};

// Mock Subjects
const SUBJECT_OPTIONS = [
    { id: 'Matematika', name: 'Matematika' },
    { id: 'Bahasa Indonesia', name: 'Bahasa Indonesia' },
    { id: 'Bahasa Inggris', name: 'Bahasa Inggris' },
    { id: 'IPA', name: 'Ilmu Pengetahuan Alam (IPA)' },
    { id: 'IPS', name: 'Ilmu Pengetahuan Sosial (IPS)' },
    { id: 'PPKn', name: 'Pendidikan Pancasila' },
    { id: 'PJOK', name: 'PJOK' },
    { id: 'Seni Budaya', name: 'Seni Budaya' },
    { id: 'Informatika', name: 'Informatika' },
    { id: 'PAI', name: 'Pendidikan Agama Islam' },
    { id: 'PAK', name: 'Pendidikan Agama Kristen' },
    { id: 'Sejarah', name: 'Sejarah' },
    { id: 'Geografi', name: 'Geografi' },
    { id: 'Ekonomi', name: 'Ekonomi' },
    { id: 'Sosiologi', name: 'Sosiologi' },
    { id: 'Fisika', name: 'Fisika' },
    { id: 'Kimia', name: 'Kimia' },
    { id: 'Biologi', name: 'Biologi' }
];

interface AllocationItem {
    id: string;
    code: string;
    description: string;
    level: string; // Cognitive Level
    topicTitle: string; 
    targetClass: string;
    semester: 1 | 2;
}

export const CPGenerator: React.FC<Props> = ({ onSave, onBack }) => {
  // Input State
  const [phase, setPhase] = useState('Fase E'); 
  const [selectedSubject, setSelectedSubject] = useState('Matematika'); 
  const [cpText, setCpText] = useState('');

  // Data State
  const [isGenerating, setIsGenerating] = useState(false);
  const [allocatedItems, setAllocatedItems] = useState<AllocationItem[]>([]);

  // Drag State
  const [draggedItemId, setDraggedItemId] = useState<string | null>(null);

  // --- COMPUTED ---
  const targetClasses = useMemo(() => PHASE_MAP[phase] || [], [phase]);

  // --- AI GENERATION LOGIC ---
  const handleGenerate = async () => {
    if (!cpText.trim()) {
        Swal.fire('Error', 'Teks CP tidak boleh kosong.', 'error');
        return;
    }

    setIsGenerating(true);
    setAllocatedItems([]); // Clear previous

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // Dynamic Class Context for Prompt
        const classListString = targetClasses.join(', ');

        const prompt = `
        Role: Expert Curriculum Developer (Kurikulum Merdeka).
        Task: Analyze the Capaian Pembelajaran (CP) for Subject '${selectedSubject}' in '${phase}' (Covering: ${classListString}).

        Instructions:
        1. Break down the CP into "Lingkup Materi" (Topics).
        2. Create a scaffolding sequence of "Tujuan Pembelajaran" (TP).
        3. AUTOMATICALLY DISTRIBUTE these TPs into the available classes (${classListString}) and Semesters (1 or 2).
           - Easier/Foundational TPs -> First Class, Semester 1.
           - Advanced/Complex TPs -> Last Class, Semester 2.
        4. Assign cognitive level (C1-C6).

        Output JSON Schema:
        Array of Objects:
        {
            "lingkup_materi": string,
            "tps": Array of {
                "deskripsi": string,
                "level_kognitif": string,
                "target_kelas_index": number (0 for the first class in ${phase}, 1 for the second, etc.),
                "target_semester": number (1 or 2)
            }
        }

        CP Text: "${cpText}"
        `;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            lingkup_materi: { type: Type.STRING },
                            tps: {
                                type: Type.ARRAY,
                                items: {
                                    type: Type.OBJECT,
                                    properties: {
                                        deskripsi: { type: Type.STRING },
                                        level_kognitif: { type: Type.STRING },
                                        target_kelas_index: { type: Type.INTEGER, description: "Index of the class array (0-based)" },
                                        target_semester: { type: Type.INTEGER, description: "1 or 2" }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        });

        const rawData = JSON.parse(response.text || '[]');

        // Transform to internal state directly
        const newAllocations: AllocationItem[] = [];

        rawData.forEach((topic: any, tIdx: number) => {
            topic.tps.forEach((tp: any, tpIdx: number) => {
                // Safety check for class index
                const safeClassIndex = Math.min(Math.max(0, tp.target_kelas_index), targetClasses.length - 1);
                const targetClassName = targetClasses[safeClassIndex];

                newAllocations.push({
                    id: `gen-tp-${tIdx}-${tpIdx}-${Date.now()}`,
                    code: `TP.${tIdx + 1}.${tpIdx + 1}`, // Temporary Code
                    description: tp.deskripsi,
                    level: tp.level_kognitif,
                    topicTitle: topic.lingkup_materi,
                    targetClass: targetClassName,
                    semester: tp.target_semester as 1 | 2
                });
            });
        });

        setAllocatedItems(newAllocations);
        Swal.fire('Generate Berhasil', `Berhasil menyusun ${newAllocations.length} TP ke dalam Alur.`, 'success');

    } catch (error: any) {
        console.error("AI Error:", error);
        Swal.fire('Gagal', error.message, 'error');
    } finally {
        setIsGenerating(false);
    }
  };

  // --- DRAG & DROP LOGIC ---

  const onDragStart = (e: React.DragEvent, itemId: string) => {
      setDraggedItemId(itemId);
      e.dataTransfer.setData('text/plain', itemId);
      e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
  };

  const onDrop = (e: React.DragEvent, targetClass: string, semester: 1 | 2) => {
      e.preventDefault();
      if (!draggedItemId) return;

      setAllocatedItems(prev => prev.map(item => {
          if (item.id === draggedItemId) {
              return { ...item, targetClass, semester };
          }
          return item;
      }));

      setDraggedItemId(null);
  };

  const handleDeleteItem = (id: string) => {
      setAllocatedItems(prev => prev.filter(i => i.id !== id));
  };

  // --- SAVE & RESET ---

  const handleReset = () => {
      Swal.fire({
          title: 'Reset Generator?',
          text: "Semua hasil generate akan dihapus.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          confirmButtonText: 'Ya, Reset'
      }).then((result: any) => {
          if (result.isConfirmed) {
              setAllocatedItems([]);
              setCpText('');
          }
      });
  };

  const handleSaveAll = () => {
      if (allocatedItems.length === 0) {
          Swal.fire('Data Kosong', 'Belum ada TP yang di-generate.', 'warning');
          return;
      }

      // Final transformation for Global State
      const finalTPs: LearningObjective[] = allocatedItems.map(item => ({
          id: item.id,
          code: item.code,
          description: item.description,
          semester: item.semester,
          scopeId: item.targetClass, // IMPORTANT: Linking to Class Name
          subjectId: selectedSubject,
          lms: [
              {
                  id: `auto-lm-${item.id}`,
                  code: 'LM.1',
                  title: item.topicTitle
              }
          ],
          criteria: []
      }));

      onSave(finalTPs);
  };

  // Helper Styles
  const getBloomColor = (level: string) => {
      if (['C1', 'C2'].some(l => level.includes(l))) return 'bg-green-100 text-green-700 border-green-200';
      if (['C3', 'C4'].some(l => level.includes(l))) return 'bg-blue-100 text-blue-700 border-blue-200';
      return 'bg-purple-100 text-purple-700 border-purple-200';
  };

  return (
    <div className="h-full flex flex-col bg-slate-50">
        {/* TOP CONFIGURATION BAR */}
        <div className="bg-white border-b border-slate-200 p-6 shadow-sm z-20">
            <div className="max-w-[1600px] mx-auto">
                <div className="flex items-start justify-between gap-6">

                    {/* INPUT SECTION - STACKED LAYOUT */}
                    <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-6">

                        {/* LEFT: SETTINGS */}
                        <div className="space-y-4">
                            <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Fase</label>
                                <select 
                                    value={phase} 
                                    onChange={e => setPhase(e.target.value)} 
                                    className="w-full border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-primary py-2.5"
                                >
                                    {Object.keys(PHASE_MAP).map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                            <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Mata Pelajaran</label>
                                <select 
                                    value={selectedSubject} 
                                    onChange={e => setSelectedSubject(e.target.value)} 
                                    className="w-full border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-primary py-2.5"
                                >
                                    {SUBJECT_OPTIONS.map(subj => (
                                        <option key={subj.id} value={subj.id}>{subj.name}</option>
                                    ))}
                                </select>
                            </div>
                        </div>

                        {/* RIGHT: CP TEXT AREA */}
                        <div className="space-y-1 flex flex-col">
                            <label className="text-xs font-bold text-slate-500 uppercase">Capaian Pembelajaran (CP)</label>
                            <textarea 
                                value={cpText}
                                onChange={e => setCpText(e.target.value)}
                                rows={5} // Increased size
                                placeholder="Paste naskah CP di sini..."
                                className="w-full border-slate-300 rounded-lg text-xs text-slate-700 p-3 focus:ring-primary resize-none flex-1"
                            ></textarea>
                        </div>
                    </div>

                    {/* ACTION BUTTONS */}
                    <div className="flex flex-col gap-3 w-48 self-stretch justify-end">
                        <button 
                            onClick={handleGenerate}
                            disabled={isGenerating}
                            className={`w-full py-3 rounded-xl font-bold text-white text-sm shadow-md transition-all flex justify-center items-center gap-2
                                ${isGenerating ? 'bg-slate-400 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-200'}
                            `}
                        >
                            {isGenerating ? (
                                <>
                                    <span className="size-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
                                    Proses...
                                </>
                            ) : (
                                <>
                                    <span className="material-symbols-outlined text-lg">auto_awesome</span>
                                    Generate AI
                                </>
                            )}
                        </button>
                        <button onClick={onBack} className="w-full py-2 text-slate-400 hover:text-slate-600 font-bold text-xs border border-transparent hover:border-slate-200 rounded-lg transition-all">
                            Batal / Kembali
                        </button>
                    </div>
                </div>
            </div>
        </div>

        {/* MAIN BOARD (SCROLLABLE) */}
        <div className="flex-1 overflow-x-auto overflow-y-hidden p-6 relative">
            <div className="flex gap-6 h-full min-w-max mx-auto">
                {targetClasses.map((clsName) => (
                    <div key={clsName} className="w-[400px] flex flex-col bg-white border border-slate-300 rounded-xl shadow-sm overflow-hidden h-full">
                        {/* Class Header */}
                        <div className="bg-slate-800 text-white py-3 px-4 flex justify-between items-center">
                            <span className="font-bold text-sm tracking-wide">{clsName}</span>
                            <span className="text-[10px] bg-white/20 px-2 py-0.5 rounded text-white/80">
                                {allocatedItems.filter(i => i.targetClass === clsName).length} TP
                            </span>
                        </div>

                        <div className="flex-1 flex flex-col overflow-hidden">
                            {/* Semester 1 */}
                            <div 
                                onDrop={(e) => onDrop(e, clsName, 1)}
                                onDragOver={onDragOver}
                                className="flex-1 bg-blue-50/30 p-3 border-b border-dashed border-slate-300 overflow-y-auto custom-scrollbar flex flex-col gap-3 relative transition-colors hover:bg-blue-100/50"
                            >
                                <div className="sticky top-0 z-10 flex justify-center mb-1 pointer-events-none">
                                    <span className="bg-blue-100 text-blue-700 px-3 py-0.5 rounded-full text-[10px] font-bold shadow-sm border border-blue-200 uppercase tracking-wider">
                                        Semester 1
                                    </span>
                                </div>
                                {allocatedItems.filter(i => i.targetClass === clsName && i.semester === 1).map(item => (
                                    <div 
                                        key={item.id} 
                                        draggable
                                        onDragStart={(e) => onDragStart(e, item.id)}
                                        className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm text-xs relative group cursor-grab active:cursor-grabbing hover:border-blue-400 transition-all"
                                    >
