interface UseCurriculumLogicProps {
  identity: IdentityData;
  tps: LearningObjective[];
  onUpdateTPs: (tps: LearningObjective[]) => void;
}

export const useCurriculumLogic = ({ identity, tps, onUpdateTPs }: UseCurriculumLogicProps) => {
  // --- STATE ---
  const [expandedTpId, setExpandedTpId] = useState<string | null>(null);
  const [generatingTpId, setGeneratingTpId] = useState<string | null>(null);
  const [isAddingTp, setIsAddingTp] = useState(false);

  // Forms
  const [newTpForm, setNewTpForm] = useState({ code: '', description: '', semester: '1' });
  const [newItemForm, setNewItemForm] = useState<{
      type: 'CRITERIA' | null, 
      parentId: string | null,
      val1: string, 
      val2: string 
  }>({ type: null, parentId: null, val1: '', val2: '' });
  const [newItemType, setNewItemType] = useState<AssessmentType>('FORMATIVE');

  // --- DERIVED SCOPES (Flexible based on Level) ---
  const scopes = useMemo(() => {
      // Default Scopes (Classes)
      if (identity.level === 'SD') {
          return [
              { id: 'Kelas 1', name: 'Kelas 1 (Fase A)' },
              { id: 'Kelas 2', name: 'Kelas 2 (Fase A)' },
              { id: 'Kelas 3', name: 'Kelas 3 (Fase B)' },
              { id: 'Kelas 4', name: 'Kelas 4 (Fase B)' },
              { id: 'Kelas 5', name: 'Kelas 5 (Fase C)' },
              { id: 'Kelas 6', name: 'Kelas 6 (Fase C)' },
          ];
      } else if (identity.level === 'SMP') {
          return [
              { id: 'Kelas 7', name: 'Kelas 7 (Fase D)' },
              { id: 'Kelas 8', name: 'Kelas 8 (Fase D)' },
              { id: 'Kelas 9', name: 'Kelas 9 (Fase D)' },
          ];
      } else { // SMA / SMK
          return [
              { id: 'Kelas 10', name: 'Kelas 10 (Fase E)' },
              { id: 'Kelas 11', name: 'Kelas 11 (Fase F)' },
              { id: 'Kelas 12', name: 'Kelas 12 (Fase F)' },
          ];
      }
  }, [identity.level]);

  // Subject Logic
  const subjectOptions = useMemo(() => {
      return identity.level === 'SD' ? SD_SUBJECTS : SECONDARY_SUBJECTS;
  }, [identity.level]);

  // Filter States
  const [activeScopeId, setActiveScopeId] = useState<string>(scopes[0].id);

  // Active Subject State
  // If Subject Teacher -> Default to their subject (identity.subjectName)
  // If Class Teacher -> Default to first SD subject or Math
  const [activeSubjectId, setActiveSubjectId] = useState<string>('');

  // Check if active subject is in the predefined list (for "Lainnya" logic)
  const isManualSubject = useMemo(() => {
      return !subjectOptions.some(s => s.id === activeSubjectId) && activeSubjectId !== '' && activeSubjectId !== 'Lainnya';
  }, [activeSubjectId, subjectOptions]);

  useEffect(() => {
      // Initialize active subject on load
      if (!activeSubjectId) {
          if (identity.role === 'SUBJECT_TEACHER' && identity.subjectName) {
              setActiveSubjectId(identity.subjectName);
          } else {
              setActiveSubjectId(subjectOptions[0].id);
          }
      }
  }, [identity, subjectOptions, activeSubjectId]);

  useEffect(() => {
      // Ensure activeScopeId is valid when scopes change (e.g. login level change)
      const exists = scopes.find(s => s.id === activeScopeId);
      if (!exists && scopes.length > 0) setActiveScopeId(scopes[0].id);
  }, [scopes, activeScopeId]);

  const filteredTPs = useMemo(() => {
      return tps.filter(tp => {
          // Strict filtering: scopeId must match exactly (e.g., "Kelas 10")
          const scopeMatch = tp.scopeId === activeScopeId;
          const subjectMatch = tp.subjectId ? tp.subjectId === activeSubjectId : true; 
          return scopeMatch && subjectMatch;
      });
  }, [tps, activeScopeId, activeSubjectId]);

  // --- HANDLERS (CRUD) ---

  const handleAddTP = () => {
    if(!newTpForm.code || !newTpForm.description) return;
    const newTp: LearningObjective = {
        id: Date.now().toString(),
        code: newTpForm.code.toUpperCase(), 
        description: newTpForm.description,
        semester: Number(newTpForm.semester) as 1 | 2,
        scopeId: activeScopeId,
        subjectId: activeSubjectId, 
        lms: [],
        criteria: []
    };
    onUpdateTPs([...tps, newTp]);
    setIsAddingTp(false);
    setNewTpForm({ code: '', description: '', semester: '1' });
  };

  const handleDeleteTP = (id: string) => {
      Swal.fire({
          title: 'Hapus Tujuan Pembelajaran?',
          text: "Seluruh Kriteria yang ada di dalamnya akan ikut terhapus!",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateTPs(tps.filter(t => t.id !== id));
              Swal.fire('Terhapus!', 'TP berhasil dihapus.', 'success')
          }
      });
  };

  const handleAddItem = () => {
      if(!newItemForm.val1 || !newItemForm.val2 || !newItemForm.parentId || !newItemForm.type) return;

      const updatedTPs = tps.map(tp => {
          if(tp.id === newItemForm.parentId) {
              // Only Criteria now
              return {
                  ...tp,
                  criteria: [...tp.criteria, { 
                      id: Date.now().toString(), 
                      code: newItemForm.val1.toUpperCase(), 
                      description: newItemForm.val2,
                      type: newItemType 
                  }]
              };
          }
          return tp;
      });

      onUpdateTPs(updatedTPs);
      setNewItemForm({ type: null, parentId: null, val1: '', val2: '' });
      setNewItemType('FORMATIVE');
  };

  const handleDeleteSubItem = (tpId: string, itemId: string, type: 'CRITERIA') => {
      Swal.fire({
          title: 'Hapus Item?',
          text: "Item ini akan dihapus permanen.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              const updatedTPs = tps.map(tp => {
                  if(tp.id === tpId) {
                      return { ...tp, criteria: tp.criteria.filter(c => c.id !== itemId) };
                  }
                  return tp;
              });
              onUpdateTPs(updatedTPs);
          }
      });
  };

  // --- AI GENERATION (KRITERIA ONLY - OPTIMIZED) ---
  const generateTpDetails = async (tp: LearningObjective) => {
      if (tp.criteria.length > 0) {
          const result = await Swal.fire({
              title: 'TP Sudah Memiliki Kriteria',
              text: "Melanjutkan akan menambahkan kriteria baru. Lanjutkan?",
              icon: 'warning',
              showCancelButton: true,
              confirmButtonText: 'Ya, Tambahkan',
              cancelButtonText: 'Batal'
          });
          if (!result.isConfirmed) return;
      }

      setGeneratingTpId(tp.id);

      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
          const prompt = `
            Role: Expert Curriculum Developer for Indonesian School (Kurikulum Merdeka).
            Context: Subject '${activeSubjectId}' for Grade '${activeScopeId}'.
            Task: Based on the Learning Objective (TP) below, generate strictly:

            2 to 3 specific 'Assessment Criteria' (Kriteria Ketercapaian Tujuan Pembelajaran / KKTP). 
            - IMPORTANT: Do not generate too many. Keep it concise (maximum 3).
            - The criteria must be directly observable and measurable based on the TP competency.
            - Ensure a mix of types if possible (FORMATIVE for process, SUMMATIVE for result).

            TP Description: "${tp.description}" (Code: ${tp.code})

            Output must be valid JSON object with array 'criteria'.
          `;

          const response = await ai.models.generateContent({
              model: "gemini-3-flash-preview",
              contents: prompt,
              config: {
                  responseMimeType: "application/json",
                  responseSchema: {
                      type: Type.OBJECT,
                      properties: {
                          criteria: {
                              type: Type.ARRAY,
                              items: {
                                  type: Type.OBJECT,
                                  properties: {
                                      code: { type: Type.STRING },
                                      description: { type: Type.STRING },
                                      type: { type: Type.STRING, enum: ["FORMATIVE", "SUMMATIVE"] }
                                  }
                              }
                          }
                      }
                  }
              }
          });

          const json = JSON.parse(response.text || '{}');

          if (json.criteria) {
              const newCriteria: AssessmentCriteria[] = json.criteria.map((cr: any, idx: number) => ({
                  id: `gen-cr-${Date.now()}-${idx}`,
                  code: cr.code || `KR.${tp.criteria.length + idx + 1}`,
                  description: cr.description,
                  type: (cr.type === 'SUMMATIVE' ? 'SUMMATIVE' : 'FORMATIVE') as AssessmentType
              }));

              const updatedTPs = tps.map(t => {
                  if (t.id === tp.id) {
                      return {
                          ...t,
                          criteria: [...t.criteria, ...newCriteria]
                      };
                  }
                  return t;
              });

              onUpdateTPs(updatedTPs);
              setExpandedTpId(tp.id);
              Swal.fire({
                  title: 'Generate Berhasil',
                  text: `Ditambahkan ${newCriteria.length} Kriteria Penilaian.`,
                  icon: 'success',
                  timer: 2000
              });
          }

      } catch (error: any) {
          console.error(error);
          Swal.fire('Gagal Generate', error.message, 'error');
      } finally {
          setGeneratingTpId(null);
      }
  };

  // --- EXPORT ---
  const handleExportCurriculum = async () => {
    if (filteredTPs.length === 0) return;

    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet('Kurikulum');

    const headerRow = sheet.addRow([
        'No', 'Semester', 'Mata Pelajaran', 'Lingkup Materi (Scope/Fase)', 'Kelas', 'Tujuan Pembelajaran (TP)', 'Kriteria Ketercapaian (KKTP)'
    ]);

    headerRow.eachCell((cell) => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } };
        cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
    });

    const activeScopeName = scopes.find(s => s.id === activeScopeId)?.name || activeScopeId;
    let rowIndex = 1;

    filteredTPs.forEach((tp) => {
        if (tp.criteria.length > 0) {
            tp.criteria.forEach(cr => {
                const row = sheet.addRow([
                    rowIndex, `Semester ${tp.semester}`, activeSubjectId, activeScopeName, identity.level,
                    `${tp.code} - ${tp.description}`, `[${cr.type}] ${cr.description}`
                ]);
                row.eachCell((cell) => {
                    cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                    cell.alignment = { vertical: 'top', wrapText: true };
                });
            });
        } else {
             const row = sheet.addRow([
                    rowIndex, `Semester ${tp.semester}`, activeSubjectId, activeScopeName, identity.level,
                    `${tp.code} - ${tp.description}`, '-'
            ]);
            row.eachCell((cell) => {
                cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                cell.alignment = { vertical: 'top', wrapText: true };
            });
        }
        rowIndex++;
    });

    sheet.getColumn(6).width = 50;
    sheet.getColumn(7).width = 40;
    sheet.getColumn(3).width = 20;
    sheet.getColumn(4).width = 25;

    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `Kurikulum_Kriteria_${activeScopeName.replace(/\s/g, '_')}_${activeSubjectId}.xlsx`;
    anchor.click();
    window.URL.revokeObjectURL(url);
  };

  return {
    state: {
        expandedTpId,
        generatingTpId,
        isAddingTp,
        newTpForm,
        newItemForm,
        newItemType,
        activeScopeId,
        activeSubjectId,
        isManualSubject,
        scopes,
        subjectOptions
    },
    setters: {
        setExpandedTpId,
        setIsAddingTp,
        setNewTpForm,
        setNewItemForm,
        setNewItemType,
        setActiveScopeId,
        setActiveSubjectId
    },
    computed: {
        filteredTPs
    },
    handlers: {
        handleAddTP,
        handleDeleteTP,
        handleAddItem,
        handleDeleteSubItem,
        generateTpDetails,
        handleExportCurriculum
    }
  };
};

import React from 'react';
import { LearningObjective, Subject, IdentityData, AssessmentType } from '../types';
import { useCurriculumLogic } from '../hooks/useCurriculumLogic';

interface Props {
  identity: IdentityData;
  subject: Subject;
  tps: LearningObjective[];
  onUpdateSubject: (kktp: number) => void;
  onUpdateTPs: (tps: LearningObjective[]) => void;
  onBack: () => void;
}

export const CurriculumManager: React.FC<Props> = (props) => {
  const { 
    state, 
    setters, 
    computed, 
    handlers 
  } = useCurriculumLogic(props);

  const { filteredTPs } = computed;
  const { 
      expandedTpId, generatingTpId, isAddingTp, newTpForm, 
      newItemForm, newItemType, activeScopeId, activeSubjectId, isManualSubject,
      scopes, subjectOptions 
  } = state;

  return (
    <div className="h-full flex flex-col bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
        {/* Header Title */}
        <div className="bg-gray-50 p-6 border-b flex justify-between items-center">
            <div>
                <h2 className="text-xl font-bold text-gray-800">Manajemen Kurikulum & Asesmen</h2>
                <p className="text-sm text-gray-500">
                    {props.identity.level === 'SD' 
                        ? 'Pengaturan TP per Mata Pelajaran (Jenjang SD)' 
                        : 'Pengaturan TP per Tingkat Kelas (Jenjang SMP/SMA/SMK)'}
                </p>
            </div>
             <button onClick={props.onBack} className="text-gray-500 hover:text-gray-700 font-medium">
                &larr; Kembali
            </button>
        </div>

        {/* Top Control Bar (Dropdown) */}
        <div className="px-6 py-4 bg-white border-b flex flex-col md:flex-row gap-4 justify-between items-end md:items-center">
            <div className="flex flex-col md:flex-row gap-4 w-full md:w-auto items-end md:items-center">

                {/* Scope/Class Selector */}
                <div className="w-full md:w-56">
                    <label className="text-xs font-bold text-gray-500 uppercase block mb-1">
                        {props.identity.level === 'SD' ? 'Pilih Kelas' : 'Pilih Tingkat / Fase'}
                    </label>
                    <div className="relative">
                        <select 
                            value={activeScopeId} 
                            onChange={(e) => setters.setActiveScopeId(e.target.value)}
                            className="w-full appearance-none pl-10 pr-8 py-2 border border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-2 focus:ring-primary focus:border-transparent outline-none cursor-pointer bg-white"
                        >
                            {scopes.map(scope => (
                                <option key={scope.id} value={scope.id}>{scope.name}</option>
                            ))}
                        </select>
                        <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-500 pointer-events-none text-lg">
                            {props.identity.level === 'SD' ? 'menu_book' : 'school'}
                        </span>
                        <span className="material-symbols-outlined absolute right-2 top-2.5 text-slate-400 pointer-events-none text-sm">expand_more</span>
                    </div>
                </div>

                {/* Subject Selector (Smart Logic) */}
                <div className="w-full md:w-64">
                    <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Mata Pelajaran</label>
                    <div className="relative flex gap-2">
                        {isManualSubject ? (
                            <div className="relative w-full">
                                <input 
                                    type="text" 
                                    value={activeSubjectId}
                                    onChange={(e) => setters.setActiveSubjectId(e.target.value)}
                                    placeholder="Ketik Mata Pelajaran..."
                                    className="w-full pl-10 pr-8 py-2 border border-blue-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-2 focus:ring-primary outline-none bg-blue-50"
                                    autoFocus
                                />
                                <span className="material-symbols-outlined absolute left-3 top-2.5 text-blue-500 text-lg">edit</span>
                                <button 
                                    onClick={() => setters.setActiveSubjectId(subjectOptions[0].id)} 
                                    className="absolute right-2 top-2 text-slate-400 hover:text-red-500"
                                    title="Kembali ke Daftar"
                                >
                                    <span className="material-symbols-outlined text-sm">close</span>
                                </button>
                            </div>
                        ) : (
                            <div className="relative w-full">
                                <select 
                                    value={activeSubjectId} 
                                    onChange={(e) => {
                                        if(e.target.value === 'Lainnya') {
                                            setters.setActiveSubjectId(''); // Trigger manual mode
                                        } else {
                                            setters.setActiveSubjectId(e.target.value);
                                        }
                                    }}
                                    className="w-full appearance-none pl-10 pr-8 py-2 border border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-2 focus:ring-primary focus:border-transparent outline-none cursor-pointer bg-white"
                                >
                                    {subjectOptions.map(subj => (
                                        <option key={subj.id} value={subj.id}>{subj.name}</option>
                                    ))}
                                    <option value="Lainnya">+ Tambah Manual / Lainnya</option>
                                </select>
                                <span className="material-symbols-outlined absolute left-3 top-2.5 text-slate-500 pointer-events-none text-lg">book</span>
                                <span className="material-symbols-outlined absolute right-2 top-2.5 text-slate-400 pointer-events-none text-sm">expand_more</span>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            <div className="flex gap-3">
                 <button 
                    onClick={handlers.handleExportCurriculum}
                    disabled={filteredTPs.length === 0}
                    className="flex items-center gap-2 px-4 py-2.5 bg-green-600 text-white rounded-lg text-sm font-bold hover:bg-green-700 transition-colors shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    <span className="material-symbols-outlined text-sm">table_view</span>
                    Export Excel
                </button>
                <button 
                    onClick={() => setters.setIsAddingTp(!isAddingTp)}
                    className="flex items-center gap-2 px-4 py-2.5 bg-primary text-white rounded-lg text-sm font-bold hover:bg-blue-600 transition-colors shadow-sm"
                >
                    <span className="material-symbols-outlined text-sm">{isAddingTp ? 'remove' : 'add'}</span>
                    Tambah TP
                </button>
            </div>
        </div>

        {/* Main Content Area */}
        <div className="flex-1 flex flex-col overflow-hidden bg-white">

            {/* Add TP Form */}
            {isAddingTp && (
                <div className="mx-6 mt-6 p-4 bg-blue-50 border border-blue-100 rounded-xl animate-in fade-in slide-in-from-top-4">
