import React, { useState, useMemo } from 'react';
import { LearningObjective, AssessmentCriteria } from '../types';
import { GoogleGenAI, Type } from "@google/genai";

declare const Swal: any;

interface Props {
  onSave: (tps: LearningObjective[]) => void;
  onBack: () => void;
}

// Data Mapping Fase ke Kelas
const PHASE_MAP: { [key: string]: string[] } = {
    'Fase A': ['Kelas 1', 'Kelas 2'],
    'Fase B': ['Kelas 3', 'Kelas 4'],
    'Fase C': ['Kelas 5', 'Kelas 6'],
    'Fase D': ['Kelas 7', 'Kelas 8', 'Kelas 9'],
    'Fase E': ['Kelas 10'],
    'Fase F': ['Kelas 11', 'Kelas 12'],
};

// Mock Subjects
const SUBJECT_OPTIONS = [
    { id: 'Matematika', name: 'Matematika' },
    { id: 'Bahasa Indonesia', name: 'Bahasa Indonesia' },
    { id: 'Bahasa Inggris', name: 'Bahasa Inggris' },
    { id: 'IPA', name: 'Ilmu Pengetahuan Alam (IPA)' },
    { id: 'IPS', name: 'Ilmu Pengetahuan Sosial (IPS)' },
    { id: 'PPKn', name: 'Pendidikan Pancasila' },
    { id: 'PJOK', name: 'PJOK' },
    { id: 'Seni Budaya', name: 'Seni Budaya' },
    { id: 'Informatika', name: 'Informatika' },
    { id: 'PAI', name: 'Pendidikan Agama Islam' },
    { id: 'PAK', name: 'Pendidikan Agama Kristen' },
    { id: 'Sejarah', name: 'Sejarah' },
    { id: 'Geografi', name: 'Geografi' },
    { id: 'Ekonomi', name: 'Ekonomi' },
    { id: 'Sosiologi', name: 'Sosiologi' },
    { id: 'Fisika', name: 'Fisika' },
    { id: 'Kimia', name: 'Kimia' },
    { id: 'Biologi', name: 'Biologi' }
];

interface AllocationItem {
    id: string;
    code: string;
    description: string;
    level: string; // Cognitive Level
    topicTitle: string; 
    targetClass: string;
    semester: 1 | 2;
    criteria: { description: string }[]; // New: Holds generated KKTP
}

export const CPGenerator: React.FC<Props> = ({ onSave, onBack }) => {
  // Input State
  const [phase, setPhase] = useState('Fase E'); 
  const [selectedSubject, setSelectedSubject] = useState('Matematika'); 
  const [cpText, setCpText] = useState('');

  // Data State
  const [isGenerating, setIsGenerating] = useState(false);
  const [allocatedItems, setAllocatedItems] = useState<AllocationItem[]>([]);

  // Drag State
  const [draggedItemId, setDraggedItemId] = useState<string | null>(null);

  // --- COMPUTED ---
  const targetClasses = useMemo(() => PHASE_MAP[phase] || [], [phase]);

  // --- AI GENERATION LOGIC ---
  const handleGenerate = async () => {
    if (!cpText.trim()) {
        Swal.fire('Error', 'Teks CP tidak boleh kosong.', 'error');
        return;
    }

    setIsGenerating(true);
    setAllocatedItems([]); // Clear previous

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const classListString = targetClasses.join(', ');

        const prompt = `
        Role: Expert Curriculum Developer (Kurikulum Merdeka).
        Task: Analyze the Capaian Pembelajaran (CP) for Subject '${selectedSubject}' in '${phase}' (Covering: ${classListString}).

        Instructions (HIERARCHY DOWN STRATEGY):
        1. First, identify the "Lingkup Materi" (Scope/Topics) from the CP.
        2. For each Scope, break it down into "Tujuan Pembelajaran" (TP).
        3. CRITICAL: For each TP, immediately generate 2-3 specific "Kriteria Ketercapaian Tujuan Pembelajaran" (KKTP/Indicators). These must be concrete and observable.
        4. Distribute TPs into classes (${classListString}) and Semesters (1 or 2) based on complexity.

        Output JSON Schema:
        Array of Objects:
        {
            "lingkup_materi": string,
            "tps": Array of {
                "deskripsi": string,
                "level_kognitif": string,
                "kktp": Array of string (List 2-3 indicators),
                "target_kelas_index": number (0 for the first class, etc.),
                "target_semester": number (1 or 2)
            }
        }

        CP Text: "${cpText}"
        `;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            lingkup_materi: { type: Type.STRING },
                            tps: {
                                type: Type.ARRAY,
                                items: {
                                    type: Type.OBJECT,
                                    properties: {
                                        deskripsi: { type: Type.STRING },
                                        level_kognitif: { type: Type.STRING },
                                        kktp: { 
                                            type: Type.ARRAY, 
                                            items: { type: Type.STRING } 
                                        },
                                        target_kelas_index: { type: Type.INTEGER },
                                        target_semester: { type: Type.INTEGER }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        });

        const rawData = JSON.parse(response.text || '[]');

        // Transform to internal state
        const newAllocations: AllocationItem[] = [];

        rawData.forEach((topic: any, tIdx: number) => {
            topic.tps.forEach((tp: any, tpIdx: number) => {
                const safeClassIndex = Math.min(Math.max(0, tp.target_kelas_index), targetClasses.length - 1);
                const targetClassName = targetClasses[safeClassIndex];

                newAllocations.push({
                    id: `gen-tp-${tIdx}-${tpIdx}-${Date.now()}`,
                    code: `TP.${tIdx + 1}.${tpIdx + 1}`,
                    description: tp.deskripsi,
                    level: tp.level_kognitif,
                    topicTitle: topic.lingkup_materi,
                    targetClass: targetClassName,
                    semester: tp.target_semester as 1 | 2,
                    criteria: (tp.kktp || []).map((k: string) => ({ description: k }))
                });
            });
        });

        setAllocatedItems(newAllocations);
        Swal.fire('Generate Berhasil', `Berhasil menyusun Kurikulum: ${rawData.length} Lingkup Materi, ${newAllocations.length} TP, dan Indikator KKTP.`, 'success');

    } catch (error: any) {
        console.error("AI Error:", error);
        Swal.fire('Gagal', error.message, 'error');
    } finally {
        setIsGenerating(false);
    }
  };

  // --- DRAG & DROP LOGIC ---

  const onDragStart = (e: React.DragEvent, itemId: string) => {
      setDraggedItemId(itemId);
      e.dataTransfer.setData('text/plain', itemId);
      e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
  };

  const onDrop = (e: React.DragEvent, targetClass: string, semester: 1 | 2) => {
      e.preventDefault();
      if (!draggedItemId) return;

      setAllocatedItems(prev => prev.map(item => {
          if (item.id === draggedItemId) {
              return { ...item, targetClass, semester };
          }
          return item;
      }));

      setDraggedItemId(null);
  };

  const handleDeleteItem = (id: string) => {
      setAllocatedItems(prev => prev.filter(i => i.id !== id));
  };

  // --- SAVE & RESET ---

  const handleReset = () => {
      Swal.fire({
          title: 'Reset Generator?',
          text: "Semua hasil generate akan dihapus.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          confirmButtonText: 'Ya, Reset'
      }).then((result: any) => {
          if (result.isConfirmed) {
              setAllocatedItems([]);
              setCpText('');
          }
      });
  };

  const handleSaveAll = () => {
      if (allocatedItems.length === 0) {
          Swal.fire('Data Kosong', 'Belum ada TP yang di-generate.', 'warning');
          return;
      }

      // Final transformation
      const finalTPs: LearningObjective[] = allocatedItems.map(item => {
          // Convert generic criteria string to AssessmentCriteria object
          const criteriaObjects: AssessmentCriteria[] = item.criteria.map((c, idx) => ({
              id: `auto-crit-${item.id}-${idx}`,
              code: `KKTP.${idx + 1}`,
              description: c.description,
              type: 'FORMATIVE' // Default type, can be used for checking
          }));

          return {
              id: item.id,
              code: item.code,
              description: item.description,
              semester: item.semester,
              scopeId: item.targetClass,
              subjectId: selectedSubject,
              scope: item.topicTitle, // SAVE LINGKUP MATERI HERE
              lms: [], // No longer needed as separate entity
              criteria: criteriaObjects
          };
      });

      onSave(finalTPs);
  };

  // Helper Styles
  const getBloomColor = (level: string) => {
      if (['C1', 'C2'].some(l => level.includes(l))) return 'bg-green-100 text-green-700 border-green-200';
      if (['C3', 'C4'].some(l => level.includes(l))) return 'bg-blue-100 text-blue-700 border-blue-200';
      return 'bg-purple-100 text-purple-700 border-purple-200';
  };

  return (
    <div className="h-full flex flex-col bg-slate-50">
        {/* TOP CONFIGURATION BAR */}
        <div className="bg-white border-b border-slate-200 p-6 shadow-sm z-20">
            <div className="max-w-[1600px] mx-auto">
                <div className="flex items-start justify-between gap-6">

                    {/* INPUT SECTION - STACKED LAYOUT */}
                    <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-6">

                        {/* LEFT: SETTINGS */}
                        <div className="space-y-4">
                            <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Fase</label>
                                <select 
                                    value={phase} 
                                    onChange={e => setPhase(e.target.value)} 
                                    className="w-full border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-primary py-2.5"
                                >
                                    {Object.keys(PHASE_MAP).map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                            <div className="space-y-1">
                                <label className="text-xs font-bold text-slate-500 uppercase">Mata Pelajaran</label>
                                <select 
                                    value={selectedSubject} 
                                    onChange={e => setSelectedSubject(e.target.value)} 
                                    className="w-full border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-primary py-2.5"
                                >
                                    {SUBJECT_OPTIONS.map(subj => (
                                        <option key={subj.id} value={subj.id}>{subj.name}</option>
                                    ))}
                                </select>
                            </div>
                        </div>

                        {/* RIGHT: CP TEXT AREA */}
                        <div className="space-y-1 flex flex-col">
                            <label className="text-xs font-bold text-slate-500 uppercase">Capaian Pembelajaran (CP)</label>
                            <textarea 
                                value={cpText}
                                onChange={e => setCpText(e.target.value)}
                                rows={5} // Increased size
                                placeholder="Paste naskah CP di sini..."
                                className="w-full border-slate-300 rounded-lg text-xs text-slate-700 p-3 focus:ring-primary resize-none flex-1"
                            ></textarea>
                        </div>
                    </div>

                    {/* ACTION BUTTONS */}
                    <div className="flex flex-col gap-3 w-48 self-stretch justify-end">
                        <button 
                            onClick={handleGenerate}
                            disabled={isGenerating}
                            className={`w-full py-3 rounded-xl font-bold text-white text-sm shadow-md transition-all flex justify-center items-center gap-2
                                ${isGenerating ? 'bg-slate-400 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-200'}
                            `}
                        >
                            {isGenerating ? (
                                <>
                                    <span className="size-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
                                    Proses...
                                </>
                            ) : (
                                <>
                                    <span className="material-symbols-outlined text-lg">auto_awesome</span>
                                    Generate AI
                                </>
                            )}
                        </button>
                        <button onClick={onBack} className="w-full py-2 text-slate-400 hover:text-slate-600 font-bold text-xs border border-transparent hover:border-slate-200 rounded-lg transition-all">
                            Batal / Kembali
                        </button>
                    </div>
                </div>
            </div>
        </div>

        {/* MAIN BOARD (SCROLLABLE) */}
        <div className="flex-1 overflow-x-auto overflow-y-hidden p-6 relative">
            <div className="flex gap-6 h-full min-w-max mx-auto">
                {targetClasses.map((clsName) => (
                    <div key={clsName} className="w-[400px] flex flex-col bg-white border border-slate-300 rounded-xl shadow-sm overflow-hidden h-full">
                        {/* Class Header */}
                        <div className="bg-slate-800 text-white py-3 px-4 flex justify-between items-center">
                            <span className="font-bold text-sm tracking-wide">{clsName}</span>
                            <span className="text-[10px] bg-white/20 px-2 py-0.5 rounded text-white/80">
                                {allocatedItems.filter(i => i.targetClass === clsName).length} TP
                            </span>
                        </div>

                        <div className="flex-1 flex flex-col overflow-hidden">
                            {/* Semester 1 */}
                            <div 
                                onDrop={(e) => onDrop(e, clsName, 1)}
                                onDragOver={onDragOver}
                                className="flex-1 bg-blue-50/30 p-3 border-b border-dashed border-slate-300 overflow-y-auto custom-scrollbar flex flex-col gap-3 relative transition-colors hover:bg-blue-100/50"
                            >
                                <div className="sticky top-0 z-10 flex justify-center mb-1 pointer-events-none">
                                    <span className="bg-blue-100 text-blue-700 px-3 py-0.5 rounded-full text-[10px] font-bold shadow-sm border border-blue-200 uppercase tracking-wider">
                                        Semester 1
                                    </span>
                                </div>
                                {allocatedItems.filter(i => i.targetClass === clsName && i.semester === 1).map(item => (
                                    <div 
                                        key={item.id} 
                                        draggable
                                        onDragStart={(e) => onDragStart(e, item.id)}
                                        className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm text-xs relative group cursor-grab active:cursor-grabbing hover:border-blue-400 transition-all"
                                    >
                                        <div className="flex justify-between items-start mb-1.5">
                                            <span className={`text-[9px] px-1.5 py-0.5 rounded font-bold border ${getBloomColor(item.level)}`}>{item.level}</span>
                                            <button onClick={() => handleDeleteItem(item.id)} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <span className="material-symbols-outlined text-sm">close</span>
                                            </button>
                                        </div>
                                        <p className="text-slate-800 leading-snug font-medium">{item.description}</p>
                                        <div className="mt-2 pt-2 border-t border-slate-100 text-[9px] text-slate-500">
                                            <div className="flex items-center gap-1 mb-1">
                                                <span className="material-symbols-outlined text-[10px]">topic</span>
                                                <span className="truncate font-bold text-slate-700">{item.topicTitle}</span>
                                            </div>
                                            {/* Show Preview of KKTP */}
                                            <div className="pl-3 border-l-2 border-slate-200">
                                                <p className="text-[9px] italic text-slate-400">
                                                    {item.criteria.length} KKTP Generated
                                                </p>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>

                            {/* Semester 2 */}
                            <div 
                                onDrop={(e) => onDrop(e, clsName, 2)}
                                onDragOver={onDragOver}
                                className="flex-1 bg-purple-50/30 p-3 overflow-y-auto custom-scrollbar flex flex-col gap-3 relative transition-colors hover:bg-purple-100/50"
                            >
                                <div className="sticky top-0 z-10 flex justify-center mb-1 pointer-events-none">
                                    <span className="bg-purple-100 text-purple-700 px-3 py-0.5 rounded-full text-[10px] font-bold shadow-sm border border-purple-200 uppercase tracking-wider">
                                        Semester 2
                                    </span>
                                </div>
                                {allocatedItems.filter(i => i.targetClass === clsName && i.semester === 2).map(item => (
                                    <div 
                                        key={item.id} 
                                        draggable
                                        onDragStart={(e) => onDragStart(e, item.id)}
                                        className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm text-xs relative group cursor-grab active:cursor-grabbing hover:border-purple-400 transition-all"
                                    >
                                        <div className="flex justify-between items-start mb-1.5">
                                            <span className={`text-[9px] px-1.5 py-0.5 rounded font-bold border ${getBloomColor(item.level)}`}>{item.level}</span>
                                            <button onClick={() => handleDeleteItem(item.id)} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <span className="material-symbols-outlined text-sm">close</span>
