import { GradeData, CalculatedGrade, LearningObjective } from '../types';

/**
 * FUNGSI PERHITUNGAN NILAI OTOMATIS (UPDATED)
 * Logic:
 * 1. Formative (Checkbox): Used for Description/Progress tracking only. Not in Final Score.
 * 2. Summative (Number): Input per Lingkup Materi. Averaged for Final Score.
 * 3. Attitude (Number): Weight added to final score.
 * 
 * Rumus Baru: (AVG(Sumatif per Lingkup Materi) * 90%) + (Sikap * 10%)
 * *Bobot bisa disesuaikan di UI, default hardcoded dulu sesuai request
 */
export const calculateStudentGrade = (
  studentId: string,
  gradeData: GradeData,
  tps: LearningObjective[], 
  kktp: number
): CalculatedGrade => {
  const studentGrades = gradeData[studentId];

  if (!studentGrades) {
    return { avgFormative: 0, avgSummative: 0, finalScore: 0, isPassed: false };
  }

  // 1. Calculate Formative Progress (Checkbox Count)
  // Just for statistical display, not final grade
  let formativeAchieved = 0;
  let formativeTotal = 0;

  const formativeData = studentGrades.formative || {};

  tps.forEach(tp => {
      tp.criteria.forEach(c => {
          formativeTotal++;
          if (formativeData[c.id]) {
              formativeAchieved++;
          }
      });
  });

  const avgFormative = formativeTotal > 0 ? Math.round((formativeAchieved / formativeTotal) * 100) : 0;

  // 2. Calculate Summative Average (Based on Lingkup Materi / Scope Scores)
  // Scopes are keys in summative object
  const summativeData = studentGrades.summative || {};
  const summativeScores = Object.values(summativeData);

  let summativeSum = 0;
  let summativeCount = 0;

  summativeScores.forEach(score => {
      if (typeof score === 'number' && !isNaN(score)) {
          summativeSum += score;
          summativeCount++;
      }
  });

  const avgSummative = summativeCount > 0 ? summativeSum / summativeCount : 0;
  const attitude = studentGrades.attitude || 0;

  // 3. Final Calculation
  // We assume Summative weight is high (e.g. 100% of academic score) mixed with attitude
  // Let's say Academic (Summative) 90% + Attitude 10%

  const finalScoreRaw = (avgSummative * 0.9) + (attitude * 0.1);
  const finalScore = Math.round(finalScoreRaw * 100) / 100;

  return {
    avgFormative, // Returns % of checkboxes checked
    avgSummative: Math.round(avgSummative),
    finalScore,
    isPassed: finalScore >= kktp
  };
};

import { useState, useEffect, useCallback, useMemo } from 'react';
import { z } from 'zod'; 
import { Student, LearningObjective, GradeData, Subject } from '../types';
import { calculateStudentGrade } from '../utils/grading';

const scoreSchema = z.number().min(0, "Min 0").max(100, "Max 100").optional();

interface UseGradingLogicProps {
  students: Student[];
  tps: LearningObjective[];
  subject: Subject;
  initialClass?: string;
  globalGradeData: GradeData;
  setGlobalGradeData: React.Dispatch<React.SetStateAction<GradeData>>;
}

export const useGradingLogic = ({
  students,
  tps,
  subject,
  initialClass,
  globalGradeData,
  setGlobalGradeData
}: UseGradingLogicProps) => {
  // --- STATE ---
  const [activeTab, setActiveTab] = useState<'FORMATIVE' | 'SUMMATIVE'>('FORMATIVE');
  const [errorMap, setErrorMap] = useState<{[key: string]: string}>({});
  const [currentTime, setCurrentTime] = useState(new Date());

  // Weights State (Simplified for now)
  const [showConfig, setShowConfig] = useState(false);
  const [weights, setWeights] = useState({ criteria: 90, attitude: 10 });

  // Filters
  const [selectedClass, setSelectedClass] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>(subject.id);

  // --- EFFECTS ---
  useEffect(() => {
    if (initialClass) setSelectedClass(initialClass);
  }, [initialClass]);

  useEffect(() => {
    const interval = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(interval);
  }, []);

  // --- COMPUTED ---

  const availableClasses = useMemo(() => {
      const classes = new Set(students.map(s => s.className).filter(Boolean));
      return Array.from(classes).sort() as string[];
  }, [students]);

  const filteredStudents = useMemo(() => {
      if (!selectedClass) return [];
      return students.filter(s => s.className === selectedClass);
  }, [students, selectedClass]);

  // Unique Scopes for Summative Columns
  const uniqueScopes = useMemo(() => {
      const scopes = new Set<string>();
      tps.forEach(tp => {
          if (tp.scope) scopes.add(tp.scope);
      });
      return Array.from(scopes).sort();
  }, [tps]);

  // Group TPs by Scope for Formative View visualization (Optional but good)
  // Not strictly needed if we just list TPs, but useful.

  // Stats Calculation
  const stats = useMemo(() => {
      return filteredStudents.reduce((acc, student) => {
          const res = calculateStudentGrade(student.id, globalGradeData, tps, subject.kktp);
          if (res.finalScore > 0) {
              if (res.isPassed) acc.tuntas++; else acc.remedial++;
          }
          return acc;
      }, { tuntas: 0, remedial: 0 });
  }, [filteredStudents, globalGradeData, tps, subject.kktp]);

  // --- HANDLERS ---

  // Handle Formative Checkbox (Boolean)
  const handleFormativeCheck = useCallback((studentId: string, criteriaId: string, checked: boolean) => {
      setGlobalGradeData(prev => {
          const sData = prev[studentId] || { formative: {}, summative: {}, attitude: 0 };
          return {
              ...prev,
              [studentId]: {
                  ...sData,
                  formative: {
                      ...(sData.formative || {}),
                      [criteriaId]: checked
                  }
              }
          };
      });
  }, [setGlobalGradeData]);

  // Handle Summative Input (Number) by Scope
  const handleSummativeScore = useCallback((studentId: string, scopeName: string, value: string) => {
      const numValue = value === '' ? undefined : parseFloat(value);
      const result = scoreSchema.safeParse(numValue);
      const errorKey = `${studentId}-sum-${scopeName}`;

      if (!result.success && value !== '') {
          setErrorMap(prev => ({...prev, [errorKey]: result.error.issues[0].message}));
      } else {
          setErrorMap(prev => {
              const newMap = {...prev};
              delete newMap[errorKey];
              return newMap;
          });
      }

      setGlobalGradeData(prev => {
          const sData = prev[studentId] || { formative: {}, summative: {}, attitude: 0 };
          return {
              ...prev,
              [studentId]: {
                  ...sData,
                  summative: {
                      ...(sData.summative || {}),
                      [scopeName]: numValue !== undefined ? numValue : 0
                  }
              }
          };
      });
  }, [setGlobalGradeData]);

  const handleAttitudeScore = useCallback((studentId: string, value: string) => {
      const numValue = value === '' ? undefined : parseFloat(value);
      setGlobalGradeData(prev => {
          const sData = prev[studentId] || { formative: {}, summative: {}, attitude: 0 };
          return {
              ...prev,
              [studentId]: { ...sData, attitude: numValue || 0 }
          };
      });
  }, [setGlobalGradeData]);

  return {
    state: {
      activeTab,
      errorMap,
      currentTime,
      showConfig,
      weights,
      selectedClass,
      selectedSubject
    },
    setters: {
      setActiveTab,
      setShowConfig,
      setSelectedClass,
      setSelectedSubject
    },
    computed: {
      availableClasses,
      filteredStudents,
      uniqueScopes,
      stats
    },
    handlers: {
      handleFormativeCheck,
      handleSummativeScore,
      handleAttitudeScore
    }
  };
};

