import { useState, useEffect, useCallback, useMemo } from 'react';
import { z } from 'zod'; 
import { Student, LearningObjective, GradeData, Subject } from '../types';
import { calculateStudentGrade } from '../utils/grading';

const scoreSchema = z.number().min(0, "Min 0").max(100, "Max 100").optional();

interface UseGradingLogicProps {
  students: Student[];
  tps: LearningObjective[];
  subject: Subject;
  initialClass?: string;
  globalGradeData: GradeData;
  setGlobalGradeData: React.Dispatch<React.SetStateAction<GradeData>>;
}

export const useGradingLogic = ({
  students,
  tps,
  subject,
  initialClass,
  globalGradeData,
  setGlobalGradeData
}: UseGradingLogicProps) => {
  // --- STATE ---
  const [activeTab, setActiveTab] = useState<'FORMATIVE' | 'SUMMATIVE'>('FORMATIVE');
  const [errorMap, setErrorMap] = useState<{[key: string]: string}>({});
  const [currentTime, setCurrentTime] = useState(new Date());

  // Filters
  const [selectedClass, setSelectedClass] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>(subject.id);

  // --- EFFECTS ---
  useEffect(() => {
    if (initialClass) setSelectedClass(initialClass);
  }, [initialClass]);

  useEffect(() => {
    const interval = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(interval);
  }, []);

  // --- COMPUTED ---

  const availableClasses = useMemo(() => {
      const classes = new Set(students.map(s => s.className).filter(Boolean));
      return Array.from(classes).sort() as string[];
  }, [students]);

  const filteredStudents = useMemo(() => {
      if (!selectedClass) return [];
      return students.filter(s => s.className === selectedClass).sort((a,b) => a.name.localeCompare(b.name));
  }, [students, selectedClass]);

  // 1. SUMMATIVE COLUMNS: Unique Scopes from TPs
  // Kita ambil daftar unik "Lingkup Materi" dari seluruh TP yang ada
  const uniqueScopes = useMemo(() => {
      const scopes = new Set<string>();
      tps.forEach(tp => {
          // Jika TP tidak punya scope, masukkan ke 'Umum'
          scopes.add(tp.scope || 'Materi Umum');
      });
      return Array.from(scopes).sort();
  }, [tps]);

  // 2. FORMATIVE COLUMNS: Group TPs by Scope
  // Struktur: { "Aljabar": [TP1, TP2], "Geometri": [TP3] }
  const tpsByScope = useMemo(() => {
      const grouped: Record<string, LearningObjective[]> = {};
      tps.forEach(tp => {
          const s = tp.scope || 'Materi Umum';
          if (!grouped[s]) grouped[s] = [];
          grouped[s].push(tp);
      });
      return grouped;
  }, [tps]);

  // Stats Calculation
  const stats = useMemo(() => {
      return filteredStudents.reduce((acc, student) => {
          const res = calculateStudentGrade(student.id, globalGradeData, tps, subject.kktp);
          if (res.finalScore > 0) {
              if (res.isPassed) acc.tuntas++; else acc.remedial++;
          }
          return acc;
      }, { tuntas: 0, remedial: 0 });
  }, [filteredStudents, globalGradeData, tps, subject.kktp]);

  // --- HANDLERS ---

  // Handle Formative Checkbox (Boolean)
  const handleFormativeCheck = useCallback((studentId: string, criteriaId: string, checked: boolean) => {
      setGlobalGradeData(prev => {
          const sData = prev[studentId] || { formative: {}, summative: {}, attitude: 0 };
          return {
              ...prev,
              [studentId]: {
                  ...sData,
                  formative: {
                      ...(sData.formative || {}),
                      [criteriaId]: checked
                  }
              }
          };
      });
  }, [setGlobalGradeData]);

  // Handle Summative Input (Number) by Scope
  const handleSummativeScore = useCallback((studentId: string, scopeName: string, value: string) => {
      const numValue = value === '' ? undefined : parseFloat(value);

      // Validation Check
      if (numValue !== undefined && (numValue < 0 || numValue > 100)) {
          // Prevent update if invalid range (simple blocking)
          return; 
      }

      setGlobalGradeData(prev => {
          const sData = prev[studentId] || { formative: {}, summative: {}, attitude: 0 };
          return {
              ...prev,
              [studentId]: {
                  ...sData,
                  summative: {
                      ...(sData.summative || {}),
                      [scopeName]: numValue !== undefined ? numValue : 0
                  }
              }
          };
      });
  }, [setGlobalGradeData]);

  const handleAttitudeScore = useCallback((studentId: string, value: string) => {
      const numValue = value === '' ? undefined : parseFloat(value);
      if (numValue !== undefined && (numValue < 0 || numValue > 100)) return;

      setGlobalGradeData(prev => {
          const sData = prev[studentId] || { formative: {}, summative: {}, attitude: 0 };
          return {
              ...prev,
              [studentId]: { ...sData, attitude: numValue || 0 }
          };
      });
  }, [setGlobalGradeData]);

  return {
    state: {
      activeTab,
      errorMap,
      currentTime,
      selectedClass,
      selectedSubject
    },
    setters: {
      setActiveTab,
      setSelectedClass,
      setSelectedSubject
    },
    computed: {
      availableClasses,
      filteredStudents,
      uniqueScopes,
      tpsByScope, // Exported for Formative View
      stats
    },
    handlers: {
      handleFormativeCheck,
      handleSummativeScore,
      handleAttitudeScore
    }
  };
};

