                                                min="0" max="100"
                                                className="w-full h-12 border-none bg-transparent text-center text-sm font-bold focus:ring-0 focus:bg-yellow-50 focus:text-yellow-700 text-slate-800"
                                                value={props.globalGradeData[student.id]?.attitude ?? ''}
                                                onChange={(e) => handlers.handleAttitudeScore(student.id, e.target.value)}
                                                placeholder="0"
                                                onFocus={(e) => e.target.select()}
                                            />
                                        </td>

                                        {/* Final Result */}
                                        <td className="px-4 text-center bg-purple-50 border-r border-slate-200">
                                            <span className={`text-lg font-black ${result.finalScore >= props.subject.kktp ? 'text-green-600' : 'text-red-500'}`}>
                                                {result.finalScore || '-'}
                                            </span>
                                        </td>

                                        <td className="px-4 text-center">
                                            {result.finalScore > 0 && (
                                                <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider border
                                                    ${result.isPassed 
                                                        ? 'bg-green-100 text-green-700 border-green-200' 
                                                        : 'bg-red-100 text-red-700 border-red-200'
