// Wrapper component to handle routing logic inside BrowserRouter
const AppContent = () => {
  const navigate = useNavigate();

  // --- AUTH STATE ---
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isLoadingAuth, setIsLoadingAuth] = useState(true); 
  const [allUsers, setAllUsers] = useState<User[]>([]);

  // --- SETTINGS STATE ---
  const [adminWaNumber, setAdminWaNumber] = useState(() => {
    return localStorage.getItem('siguru_admin_wa') || '6282335454864';
  });

  // --- APP DATA STATE ---
  const [identity, setIdentity] = useState<IdentityData>(INITIAL_IDENTITY);
  const [students, setStudents] = useState<Student[]>([]); 
  const [classes, setClasses] = useState<ClassInfo[]>([]); 
  const [schedules, setSchedules] = useState<ScheduleItem[]>([]); 
  const [tps, setTps] = useState<LearningObjective[]>([]); 
  const [subject, setSubject] = useState<Subject>({ id: 's1', name: 'Mata Pelajaran', kktp: 75 });
  const [attendanceData, setAttendanceData] = useState<AttendanceData>({});
  const [gradeData, setGradeData] = useState<GradeData>({}); 
  const [journals, setJournals] = useState<JournalEntry[]>([]); 

  // --- AUTH EFFECTS ---
  useEffect(() => {
    if (!isSupabaseConfigured) {
        setIsLoadingAuth(false);
        return;
    }

    const initSession = async () => {
        try {
            const { data: { session }, error } = await supabase.auth.getSession();
            if (error) throw error;
            if (session?.user) await handleUserRestored(session.user);
            else setIsLoadingAuth(false);
        } catch (err) {
            console.error("Session Validation Failed:", err);
            setIsLoadingAuth(false);
        }
    };

    initSession();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === 'SIGNED_IN' && session?.user) handleUserRestored(session.user);
      else if (event === 'SIGNED_OUT') resetAppState();
    });

    return () => subscription.unsubscribe();
  }, []);

  const handleUserRestored = async (authUser: any) => {
      let meta = authUser.user_metadata || {};
      let isActive = false; 

      if (isSupabaseConfigured) {
          try {
            const { data: teacherData } = await supabase
                .from('teachers')
                .select('role, is_active, full_name, level')
                .eq('email', authUser.email)
                .single();

            if (teacherData) {
                meta.role = teacherData.role;
                meta.full_name = teacherData.full_name;
                meta.level = teacherData.level; 
                isActive = teacherData.is_active === true;
            }
          } catch (e) { console.error("Auth restore error", e); }
      }

      const appUser: User = {
          id: authUser.id,
          email: authUser.email || '',
          name: meta.full_name || authUser.email?.split('@')[0] || 'Guru',
          role: authUser.email === 'admin@siguru.com' || meta.role === 'ADMIN' ? 'ADMIN' : (meta.role || 'SUBJECT_TEACHER'),
          level: meta.level || 'SMA',
          isActive: isActive
      };

      if (!appUser.isActive && appUser.email !== 'admin@siguru.com') {
          await supabase.auth.signOut();
          Swal.fire({ title: 'Akun Belum Aktif', text: 'Silahkan hubungi Admin sekolah.', icon: 'warning' });
          setIsLoadingAuth(false);
          return;
      }

      loadUserData(appUser); 
      setCurrentUser(appUser);

      if (appUser.role === 'ADMIN') {
         fetchRealUsersList(); 
         navigate('/admin');
      } else {
         // Only navigate if we are on login page to avoid overriding deep links
         // With HashRouter, window.location.pathname will be the base path, hash will be separate.
         // We check if hash is empty or just #/login
         const hash = window.location.hash;
         if (!hash || hash === '#/login' || hash === '#/') {
             navigate('/dashboard');
         }
      }
      setIsLoadingAuth(false);
  };

  const resetAppState = () => {
      setCurrentUser(null);
      setIdentity(INITIAL_IDENTITY);
      setStudents([]);
      setClasses([]);
      setSchedules([]);
      setTps([]);
      setAttendanceData({});
      setGradeData({});
      setJournals([]);
      setIsLoadingAuth(false);
      sessionStorage.clear();
      navigate('/login');
  };

  const fetchRealUsersList = async () => {
      if (!isSupabaseConfigured) return;
      try {
          const { data } = await supabase.from('teachers').select('*').order('created_at', { ascending: false });
          if (data) {
              const mappedUsers: User[] = data.map((t: any) => ({
                  id: t.id, email: t.email, name: t.full_name, role: t.role,
                  level: t.level || 'SMA', isActive: t.is_active === true, password: t.plain_password 
              }));
              setAllUsers(mappedUsers);
          }
      } catch (err) { console.error("Failed to fetch users", err); }
  };

  const loadUserData = (user: User) => {
        const storageKey = `siguru_data_${user.email}`;
        const savedDataStr = sessionStorage.getItem(storageKey);
        let dataLoaded = false;

        if (savedDataStr) {
          try {
            const data: UserStorageData = JSON.parse(savedDataStr);
            if (data && data.identity) {
                setIdentity(data.identity);
                setStudents(data.students || []);
                setClasses(data.classes || []);
                setSchedules(data.schedules || []);
                setTps(data.tps || []);
                setSubject(data.subject);
                setAttendanceData(data.attendanceData || {});
                setGradeData(data.gradeData || {});
                setJournals(data.journals || []);
                dataLoaded = true;
            } 
          } catch (e) { console.error("Failed to parse saved data", e); }
        }

        if (!dataLoaded) {
            setIdentity({
              ...INITIAL_IDENTITY, 
              teacherName: user.name,
              role: user.role === 'ADMIN' ? 'SUBJECT_TEACHER' : user.role, 
              level: user.level || 'SMA'
            });
        }
  };

  useEffect(() => {
    setIdentity(prev => ({ ...prev, studentCount: students.length }));
  }, [students.length]);

  const saveDataToStorage = useCallback(() => {
    if (!currentUser) return;
    const storageKey = `siguru_data_${currentUser.email}`;
    const payload: UserStorageData = { identity, students, classes, schedules, tps, subject, attendanceData, gradeData, journals };
    sessionStorage.setItem(storageKey, JSON.stringify(payload));
  }, [currentUser, identity, students, classes, schedules, tps, subject, attendanceData, gradeData, journals]);

  useEffect(() => {
    if (currentUser) {
      const timeout = setTimeout(saveDataToStorage, 1000); 
      return () => clearTimeout(timeout);
    }
  }, [saveDataToStorage, currentUser]);

  // --- ACTIONS ---
  const handleLogin = async (data: LoginData) => {
    setIsLoadingAuth(true);
    if (!isSupabaseConfigured) {
        Swal.fire('Error', 'Supabase belum dikonfigurasi.', 'error');
        setIsLoadingAuth(false);
        return;
    }
    try {
        const { error } = await supabase.auth.signInWithPassword({ email: data.email, password: data.password });
        if (error) {
            Swal.fire('Gagal Masuk', error.message, 'error');
            setIsLoadingAuth(false);
        }
    } catch (err: any) {
         console.error("Login Error:", err);
         setIsLoadingAuth(false);
    }
  };

  const handleRegister = async (data: RegisterData) => {
    setIsLoadingAuth(true);
    try {
        const { data: existingTeacher } = await supabase.from('teachers').select('id').eq('email', data.email).single();
        const { data: authData, error: authError } = await supabase.auth.signUp({
            email: data.email, password: data.password,
            options: { data: { full_name: data.name, role: data.role, level: data.level } }
        });

        if (authError) throw authError;

        if (authData.user) {
            if (existingTeacher) {
                await supabase.from('teachers').update({ user_id: authData.user.id, full_name: data.name, role: data.role, level: data.level }).eq('id', existingTeacher.id);
            } else {
                await supabase.from('teachers').insert({ user_id: authData.user.id, email: data.email, full_name: data.name, role: data.role, level: data.level, is_active: false });
            }
            Swal.fire('Registrasi Berhasil', 'Menunggu persetujuan Admin.', 'success');
        }
        setIsLoadingAuth(false);
    } catch (err: any) {
        Swal.fire('Registrasi Gagal', err.message, 'error');
        setIsLoadingAuth(false);
    }
  };

  const handleLogout = async () => {
    Swal.fire({
      title: 'Keluar Aplikasi?', icon: 'question', showCancelButton: true, confirmButtonText: 'Ya, Keluar'
    }).then(async (result: any) => {
      if (result.isConfirmed) {
        saveDataToStorage(); 
        if (isSupabaseConfigured) await supabase.auth.signOut(); 
        else resetAppState(); 
      }
    });
  };

  const handleIdentitySave = useCallback((data: IdentityData) => setIdentity(data), []);
  const handleSaveGeneratedTPs = useCallback((newTps: LearningObjective[]) => {
      setTps(prev => [...prev, ...newTps]);
      Swal.fire('Tersimpan!', `${newTps.length} TP berhasil ditambahkan.`, 'success');
      navigate('/curriculum');
  }, [navigate]);

  // Context Navigation Wrapper
  const handleContextNavigate = (tab: TabView, context: { className?: string, scheduleId?: string } = {}) => {
      // Logic to map legacy TabView to Routes (mostly for Dashboard widgets)
      if (tab === TabView.ATTENDANCE) {
          navigate('/akademik/attendance', { state: context });
      } else if (tab === TabView.JOURNAL) {
          navigate('/akademik/journal', { state: context });
      } else if (tab === TabView.GRADING) {
          navigate('/akademik/grading', { state: context });
      } else {
          // Default fallbacks handled by Sidebar links mostly
          console.log("Navigating to:", tab, context);
      }
  };

  // Helper for admin actions (simplified for brevity as they are passed to AdminPanel)
  const adminActions = {
      onAddUser: async (d: RegisterData) => { /* logic */ }, 
      onDeleteUser: async (id: string) => { /* logic */ },
      onUpdateUser: async (id: string, d: RegisterData) => { /* logic */ },
      onApproveUser: async (id: string) => { /* logic */ },
      onRejectUser: async (id: string) => { /* logic */ },
      onUpdateWaNumber: (num: string) => { 
          setAdminWaNumber(num); 
          localStorage.setItem('siguru_admin_wa', num);
          Swal.fire('Sukses', 'WA diperbarui', 'success');
      }
  };

  // Loading Screen
  if (isLoadingAuth) {
      return (
          <div className="flex h-screen w-full items-center justify-center bg-background-light">
              <div className="flex flex-col items-center gap-4">
                  <div className="size-12 border-4 border-slate-200 border-t-primary rounded-full animate-spin"></div>
                  <p className="text-slate-500 font-bold text-sm animate-pulse">Memuat Data...</p>
              </div>
          </div>
      );
  }

  return (
    <Suspense fallback={<PageLoader />}>
      <Routes>
        {/* PUBLIC ROUTE */}
        <Route 
            path="/login" 
            element={
                currentUser ? <Navigate to="/dashboard" replace /> : 
                <LoginPage onLogin={handleLogin} onRegister={handleRegister} isLoading={isLoadingAuth} adminWaNumber={adminWaNumber} />
            } 
        />

        {/* ADMIN ROUTE */}
        <Route 
            path="/admin" 
            element={
                <ProtectedRoute user={currentUser} allowedRoles={['ADMIN']}>
                    <AdminPanel 
                        users={allUsers} 
                        {...adminActions}
                        onGoToApp={() => navigate('/dashboard')}
                        onLogout={handleLogout}
                        waNumber={adminWaNumber}
                    />
                </ProtectedRoute>
            } 
        />

        {/* PROTECTED APP ROUTES */}
        <Route element={<ProtectedRoute user={currentUser}><MainLayout identity={identity} currentUser={currentUser} onLogout={handleLogout} /></ProtectedRoute>}>
            <Route path="/" element={<Navigate to="/dashboard" replace />} />

            <Route path="dashboard" element={
                <Dashboard 
                    onNavigate={handleContextNavigate} identity={identity} schedules={schedules}
                    classes={classes} students={students} attendanceData={attendanceData}
                    gradeData={gradeData} subject={subject} tps={tps}
                    onSaveIdentity={handleIdentitySave} // Pass callback for onboarding
                />
            } />

            <Route path="identity" element={
                <IdentityForm data={identity} onSave={handleIdentitySave} onBack={() => navigate('/dashboard')} />
            } />

            {/* MASTER DATA */}
            <Route path="master">
                <Route path="classes" element={
                    <ClassManager identity={identity} classes={classes} students={students} onUpdateClasses={setClasses} onBack={() => navigate('/dashboard')} />
                } />
                <Route path="students" element={
                    <StudentManager identity={identity} students={students} classes={classes} onUpdateStudents={setStudents} onUpdateClasses={setClasses} onBack={() => navigate('/dashboard')} />
                } />
                <Route path="schedules" element={
                    <ScheduleManager schedules={schedules} classes={classes} onUpdateSchedules={setSchedules} onBack={() => navigate('/dashboard')} />
                } />
            </Route>

            {/* CURRICULUM */}
            <Route path="curriculum">
                <Route index element={
                    <CurriculumManager identity={identity} subject={subject} tps={tps} onUpdateSubject={(kktp) => setSubject(prev => ({...prev, kktp}))} onUpdateTPs={setTps} onBack={() => navigate('/dashboard')} />
                } />
                <Route path="cp-generator" element={
                    <CPGenerator onSave={handleSaveGeneratedTPs} onBack={() => navigate('/dashboard')} identity={identity} /> // Pass Identity
                } />
            </Route>

            {/* AKADEMIK */}
            <Route path="akademik">
                <Route path="journal" element={
                    <JournalManager journals={journals} onUpdateJournals={setJournals} tps={tps} schedules={schedules} classes={classes} onBack={() => navigate('/dashboard')} />
                } />
                <Route path="grading" element={
                    <GradingSheet students={students} tps={tps} subject={subject} globalGradeData={gradeData} setGlobalGradeData={setGradeData} />
                } />
                <Route path="attendance" element={
                    <AttendanceSheet students={students} subject={subject} schedules={schedules} globalAttendance={attendanceData} setGlobalAttendance={setAttendanceData} />
                } />
            </Route>

            {/* RECAP */}
            <Route path="recap">
                <Route path="grades" element={
                    <RecapManager students={students} subject={subject} identity={identity} mode='GRADES' globalAttendance={attendanceData} gradeData={gradeData} tps={tps} />
                } />
                <Route path="attendance" element={
                    <RecapManager students={students} subject={subject} identity={identity} mode='ATTENDANCE' globalAttendance={attendanceData} gradeData={gradeData} tps={tps} />
                } />
            </Route>
        </Route>

        {/* 404 CATCH ALL */}
        <Route path="*" element={<NotFound />} />
      </Routes>
    </Suspense>
  );
};

export default function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <HashRouter>
        <AppContent />
      </HashRouter>
    </QueryClientProvider>
  );
}

import React, { useState, useMemo, useEffect } from 'react';
import { LearningObjective, AssessmentCriteria, IdentityData } from '../types';
import { GoogleGenAI, Type } from "@google/genai";

declare const Swal: any;

interface Props {
  onSave: (tps: LearningObjective[]) => void;
  onBack: () => void;
  identity?: IdentityData; // Added identity prop
}

// Data Mapping Fase ke Kelas
const PHASE_MAP: { [key: string]: string[] } = {
    'Fase A': ['Kelas 1', 'Kelas 2'],
    'Fase B': ['Kelas 3', 'Kelas 4'],
    'Fase C': ['Kelas 5', 'Kelas 6'],
    'Fase D': ['Kelas 7', 'Kelas 8', 'Kelas 9'],
    'Fase E': ['Kelas 10'],
    'Fase F': ['Kelas 11', 'Kelas 12'],
};

// Map Level to Default Phase
const LEVEL_TO_PHASE_MAP: { [key: string]: string } = {
    'SD': 'Fase A',
    'SMP': 'Fase D',
    'SMA': 'Fase E',
    'SMK': 'Fase E'
};

// Mock Subjects
const SUBJECT_OPTIONS = [
    { id: 'Matematika', name: 'Matematika' },
    { id: 'Bahasa Indonesia', name: 'Bahasa Indonesia' },
    { id: 'Bahasa Inggris', name: 'Bahasa Inggris' },
    { id: 'IPA', name: 'Ilmu Pengetahuan Alam (IPA)' },
    { id: 'IPS', name: 'Ilmu Pengetahuan Sosial (IPS)' },
    { id: 'PPKn', name: 'Pendidikan Pancasila' },
    { id: 'PJOK', name: 'PJOK' },
    { id: 'Seni Budaya', name: 'Seni Budaya' },
    { id: 'Informatika', name: 'Informatika' },
    { id: 'PAI', name: 'Pendidikan Agama Islam' },
    { id: 'PAK', name: 'Pendidikan Agama Kristen' },
    { id: 'Sejarah', name: 'Sejarah' },
    { id: 'Geografi', name: 'Geografi' },
    { id: 'Ekonomi', name: 'Ekonomi' },
    { id: 'Sosiologi', name: 'Sosiologi' },
    { id: 'Fisika', name: 'Fisika' },
    { id: 'Kimia', name: 'Kimia' },
    { id: 'Biologi', name: 'Biologi' }
];

interface AllocationItem {
    id: string;
    code: string;
    description: string;
    level: string; // Cognitive Level
    topicTitle: string; 
    container: string; // 'BANK' or 'ClassName-Semester'
    criteria: { description: string }[]; 
}

export const CPGenerator: React.FC<Props> = ({ onSave, onBack, identity }) => {
  // Input State
  const [phase, setPhase] = useState('Fase E'); 
  const [selectedSubject, setSelectedSubject] = useState('Matematika'); 
  const [cpText, setCpText] = useState('');

  // Data State
  const [isGenerating, setIsGenerating] = useState(false);
  const [allocatedItems, setAllocatedItems] = useState<AllocationItem[]>([]);

  // Drag State
  const [draggedItemId, setDraggedItemId] = useState<string | null>(null);

  // --- AUTO FILL EFFECT ---
  useEffect(() => {
      if (identity) {
          // Auto Phase
          if (identity.level && LEVEL_TO_PHASE_MAP[identity.level]) {
              setPhase(LEVEL_TO_PHASE_MAP[identity.level]);
          }
          // Auto Subject (if subject teacher)
          if (identity.role === 'SUBJECT_TEACHER' && identity.subjectName) {
              // Try to find exact match in options, or just set it
              const match = SUBJECT_OPTIONS.find(s => s.name.toLowerCase() === identity.subjectName.toLowerCase());
              if (match) setSelectedSubject(match.id);
              // Note: If mapel is custom (not in list), simple select won't show it unless we add it dynamically.
              // For now, defaulting to Matematika if not found in standard list is safer, or user picks.
          }
      }
  }, [identity]);

  // --- COMPUTED ---
  const targetClasses = useMemo(() => PHASE_MAP[phase] || [], [phase]);

  // --- AI GENERATION LOGIC ---
  const handleGenerate = async () => {
    if (!cpText.trim()) {
        Swal.fire('Error', 'Teks CP tidak boleh kosong.', 'error');
        return;
    }

    setIsGenerating(true);
    setAllocatedItems([]); 

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const prompt = `
        Role: Expert Curriculum Developer (Kurikulum Merdeka Indonesia).
        Task: Analyze the Capaian Pembelajaran (CP) text below for Subject '${selectedSubject}' in '${phase}'.

        Instructions:
        1. Break down the CP into distinct "Lingkup Materi" (Scope/Topics).
        2. For each Scope, generate specific "Tujuan Pembelajaran" (TP).
        3. For each TP, provide 2-3 "Kriteria Ketercapaian" (KKTP/Indicators).
        4. Determine the Cognitive Level (e.g., C1, C2, C3, C4, C5, C6) based on Bloom's Taxonomy.

        Format the output strictly as a JSON Array.

        CP Text: "${cpText}"
        `;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            lingkup_materi: { type: Type.STRING },
                            tps: {
                                type: Type.ARRAY,
                                items: {
                                    type: Type.OBJECT,
                                    properties: {
                                        kode_tp: { type: Type.STRING, description: "Short code like TP.1" },
                                        deskripsi: { type: Type.STRING },
                                        level_kognitif: { type: Type.STRING },
                                        kktp: { 
                                            type: Type.ARRAY, 
                                            items: { type: Type.STRING } 
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        });

        const rawData = JSON.parse(response.text || '[]');

        // Transform to internal state -> Put into 'BANK' initially
        const newAllocations: AllocationItem[] = [];
        let globalTpIndex = 1;

        rawData.forEach((topic: any) => {
            topic.tps.forEach((tp: any) => {
                newAllocations.push({
                    id: `gen-tp-${Date.now()}-${globalTpIndex}`,
                    code: `TP.${globalTpIndex}`,
                    description: tp.deskripsi,
                    level: tp.level_kognitif,
                    topicTitle: topic.lingkup_materi,
                    container: 'BANK', // Default to Staging Area
                    criteria: (tp.kktp || []).map((k: string) => ({ description: k }))
                });
                globalTpIndex++;
            });
        });

        setAllocatedItems(newAllocations);
        Swal.fire({
            title: 'Analisa Selesai',
            text: `Berhasil mengidentifikasi ${rawData.length} Lingkup Materi dan ${newAllocations.length} TP. Silahkan distribusikan ke kelas.`,
            icon: 'success'
        });

    } catch (error: any) {
        console.error("AI Error:", error);
        Swal.fire('Gagal', error.message, 'error');
    } finally {
        setIsGenerating(false);
    }
  };

  // --- DRAG & DROP LOGIC ---

  const onDragStart = (e: React.DragEvent, itemId: string) => {
      setDraggedItemId(itemId);
      e.dataTransfer.setData('text/plain', itemId);
      e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
  };

  const onDrop = (e: React.DragEvent, targetContainer: string) => {
      e.preventDefault();
      if (!draggedItemId) return;

      setAllocatedItems(prev => prev.map(item => {
          if (item.id === draggedItemId) {
              return { ...item, container: targetContainer };
          }
          return item;
      }));

      setDraggedItemId(null);
  };

  const handleDeleteItem = (id: string) => {
      setAllocatedItems(prev => prev.filter(i => i.id !== id));
  };

  // --- SAVE & RESET ---

  const handleReset = () => {
      Swal.fire({
          title: 'Reset Generator?',
          text: "Semua hasil generate akan dihapus.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          confirmButtonText: 'Ya, Reset'
      }).then((result: any) => {
          if (result.isConfirmed) {
              setAllocatedItems([]);
              setCpText('');
          }
      });
  };

  const handleSaveAll = () => {
      // Filter items that are actually distributed (not in BANK)
      const distributedItems = allocatedItems.filter(i => i.container !== 'BANK');

      if (distributedItems.length === 0) {
          Swal.fire('Belum Ada Distribusi', 'Silahkan drag TP dari Bank TP ke Kelas/Semester terlebih dahulu.', 'warning');
          return;
      }

      // Final transformation
      const finalTPs: LearningObjective[] = distributedItems.map(item => {
          // Parse container string "ClassName-Semester" -> e.g. "Kelas 10-1"
          const [className, semesterStr] = item.container.split('::');

          const criteriaObjects: AssessmentCriteria[] = item.criteria.map((c, idx) => ({
              id: `auto-crit-${item.id}-${idx}`,
              code: `KKTP.${idx + 1}`,
              description: c.description,
              type: 'FORMATIVE'
          }));

          return {
              id: item.id,
              code: item.code,
              description: item.description,
              semester: parseInt(semesterStr) as 1 | 2,
              scopeId: className, // Stores Class Name as ScopeID for curriculum mapping
              subjectId: selectedSubject,
              scope: item.topicTitle, 
              lms: [], 
              criteria: criteriaObjects
          };
      });

      onSave(finalTPs);
  };

  // Helper Styles
  const getBloomColor = (level: string) => {
      if (['C1', 'C2'].some(l => level.includes(l))) return 'bg-green-100 text-green-700 border-green-200';
      if (['C3', 'C4'].some(l => level.includes(l))) return 'bg-blue-100 text-blue-700 border-blue-200';
      return 'bg-purple-100 text-purple-700 border-purple-200';
  };

  return (
    <div className="flex flex-col h-[calc(100vh-80px)] bg-slate-50"> 
        {/* TOP CONFIGURATION BAR */}
        <div className="bg-white border-b border-slate-200 p-5 shadow-sm z-30 shrink-0">
            <div className="max-w-[1800px] mx-auto">
                <div className="flex items-start gap-6">

                    {/* INPUTS */}
                    <div className="flex-1 grid grid-cols-12 gap-6">
                        <div className="col-span-3 space-y-4">
                            <div className="space-y-1">
                                <label className="text-[10px] font-bold text-slate-500 uppercase">Fase</label>
                                <select 
                                    value={phase} 
                                    onChange={e => setPhase(e.target.value)} 
                                    className="w-full border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-primary py-2"
                                >
                                    {Object.keys(PHASE_MAP).map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                            <div className="space-y-1">
                                <label className="text-[10px] font-bold text-slate-500 uppercase">Mata Pelajaran</label>
                                <select 
                                    value={selectedSubject} 
                                    onChange={e => setSelectedSubject(e.target.value)} 
                                    className="w-full border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-primary py-2"
                                >
                                    {SUBJECT_OPTIONS.map(subj => (
                                        <option key={subj.id} value={subj.id}>{subj.name}</option>
                                    ))}
                                </select>
                            </div>
                        </div>

                        <div className="col-span-9 space-y-1 flex flex-col h-full">
                            <label className="text-[10px] font-bold text-slate-500 uppercase">Capaian Pembelajaran (CP) - <span className="text-primary normal-case">Copy paste teks CP dari dokumen kurikulum</span></label>
                            <textarea 
                                value={cpText}
                                onChange={e => setCpText(e.target.value)}
                                placeholder="Paste naskah CP di sini..."
                                className="w-full border-slate-300 rounded-lg text-xs text-slate-700 p-3 focus:ring-primary resize-none h-24"
                            ></textarea>
                        </div>
                    </div>

                    {/* ACTION BUTTONS */}
                    <div className="flex flex-col gap-2 w-48 shrink-0">
                        <button 
                            onClick={handleGenerate}
                            disabled={isGenerating}
                            className={`w-full py-3 rounded-xl font-bold text-white text-sm shadow-md transition-all flex justify-center items-center gap-2 h-14
                                ${isGenerating ? 'bg-slate-400 cursor-not-allowed' : 'bg-gradient-to-r from-primary to-blue-600 hover:shadow-lg hover:scale-[1.02]'}
                            `}
                        >
                            {isGenerating ? (
                                <>
                                    <span className="size-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
                                    Menganalisa...
                                </>
                            ) : (
                                <>
                                    <span className="material-symbols-outlined text-xl">psychology</span>
                                    Generate TP
                                </>
                            )}
                        </button>
                        <button onClick={onBack} className="w-full py-2 text-slate-400 hover:text-slate-600 font-bold text-xs border border-transparent hover:border-slate-200 rounded-lg transition-all">
                            Kembali ke Menu
                        </button>
                    </div>
                </div>
            </div>
        </div>

        {/* MAIN WORKSPACE */}
        <div className="flex-1 flex overflow-hidden">

            {/* LEFT PANEL: STAGING / BANK TP */}
            <div className="w-[350px] bg-white border-r border-slate-200 flex flex-col shrink-0 z-20 shadow-lg">
                <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                    <div>
                        <h3 className="font-bold text-slate-800 flex items-center gap-2">
                            <span className="material-symbols-outlined text-orange-500">inventory_2</span>
                            Bank TP
                        </h3>
                        <p className="text-[10px] text-slate-500">Hasil generate AI masuk di sini</p>
                    </div>
