  onSaveIdentity?: (data: IdentityData) => void;
}

// --- DATA REFERENSI MAPEL ---
const SUBJECTS_SD = [
    'Bahasa Indonesia', 'Matematika', 'IPAS', 'Pendidikan Pancasila', 
    'Seni Budaya', 'PJOK', 'Bahasa Inggris', 'Muatan Lokal', 'PAI', 'PAK'
];

