// Daftar Mapel SMP/SMA (Guru Mapel) - ID menggunakan s1, s2, dst (Sesuai GradingSheet)
// Kita tambahkan pemetaan nama agar match dengan input user (text)
const SECONDARY_SUBJECTS = [
    { id: 's1', name: 'Matematika' },
    { id: 's2', name: 'Fisika' },
    { id: 's3', name: 'Kimia' },
