  // --- CALENDAR TODAY LOGIC ---
  const todaysEvents = useMemo(() => {
      if (!props.calendarEvents) return [];
      const todayStr = new Date().toISOString().split('T')[0];
      return props.calendarEvents.filter(e => e.date === todayStr);
