                                                                size-5 rounded border flex items-center justify-center transition-all duration-200
                                                                ${isChecked 
                                                                    ? 'bg-blue-500 border-blue-500 text-white scale-110 shadow-sm' 
                                                                    : 'bg-white border-slate-300 text-transparent'
