/**
 * Mendapatkan Label Kualitatif berdasarkan Interval Nilai
 * 0-40: Perlu Bimbingan
 * 41-65: Cukup
 * 66-85: Baik
 * 86-100: Sangat Baik
 */
export const getQualitativeLabel = (score: number) => {
    if (score <= 40) return { label: 'Perlu Bimbingan', color: 'text-red-600 bg-red-50 border-red-100' };
    if (score <= 65) return { label: 'Cukup', color: 'text-orange-600 bg-orange-50 border-orange-100' };
    if (score <= 85) return { label: 'Baik', color: 'text-blue-600 bg-blue-50 border-blue-100' };
    return { label: 'Sangat Baik', color: 'text-green-600 bg-green-50 border-green-100' };
};

/**
 * FUNGSI PERHITUNGAN NILAI OTOMATIS (UPDATED)
 * Logic:
 * 1. Formative (Numeric per TP): Averaged across all TPs.
 * 2. Summative (Number): Input per Lingkup Materi. Averaged.
 * 3. Attitude (Number): Weight added to final score.
 * 
 * Rumus Baru: (AVG(Sumatif per Lingkup Materi) * 50%) + (AVG(Formatif per TP) * 40%) + (Sikap * 10%)
 */
export const calculateStudentGrade = (
  studentId: string,
  gradeData: GradeData,
  tps: LearningObjective[], 
  kktp: number
): CalculatedGrade => {
  const studentGrades = gradeData[studentId];

  if (!studentGrades) {
    return { avgFormative: 0, avgSummative: 0, finalScore: 0, isPassed: false };
  }

  // 1. Calculate Formative Average (Score based)
  let formativeSum = 0;
  let formativeCount = 0;

  const formativeData = studentGrades.formative || {};

  // Iterate filtered TPs to ensure we only count relevant ones
  tps.forEach(tp => {
      if (formativeData[tp.id] !== undefined && typeof formativeData[tp.id] === 'number') {
          formativeSum += formativeData[tp.id];
          formativeCount++;
      }
  });

  const avgFormative = formativeCount > 0 ? formativeSum / formativeCount : 0;

  // 2. Calculate Summative Average (Based on Lingkup Materi / Scope Scores)
  // Scopes are keys in summative object
  const summativeData = studentGrades.summative || {};
  const summativeScores = Object.values(summativeData);

  let summativeSum = 0;
  let summativeCount = 0;

  summativeScores.forEach(score => {
      if (typeof score === 'number' && !isNaN(score)) {
          summativeSum += score;
          summativeCount++;
      }
  });

  const avgSummative = summativeCount > 0 ? summativeSum / summativeCount : 0;
  const attitude = studentGrades.attitude || 0;

  // 3. Final Calculation
  // 40% Formative + 50% Summative + 10% Attitude
  const finalScoreRaw = (avgFormative * 0.4) + (avgSummative * 0.5) + (attitude * 0.1);
  const finalScore = Math.round(finalScoreRaw * 100) / 100;

  return {
    avgFormative: Math.round(avgFormative),
    avgSummative: Math.round(avgSummative),
    finalScore: Math.round(finalScore),
    isPassed: finalScore >= kktp
  };
};

import { useState, useEffect, useCallback, useMemo } from 'react';
import { useLocation } from 'react-router-dom';
import { Student, LearningObjective, GradeData, Subject, IdentityData, SUBJECTS_DATA } from '../types';
import { calculateStudentGrade } from '../utils/grading';

interface UseGradingLogicProps {
  students: Student[];
  tps: LearningObjective[];
  subject: Subject;
  initialClass?: string;
  globalGradeData: GradeData;
  setGlobalGradeData: React.Dispatch<React.SetStateAction<GradeData>>;
  identity: IdentityData; 
}

export const useGradingLogic = ({
  students,
  tps,
  subject,
  initialClass,
  globalGradeData,
  setGlobalGradeData,
  identity
}: UseGradingLogicProps) => {
  const location = useLocation();

  // --- STATE ---
  const [activeTab, setActiveTab] = useState<'FORMATIVE' | 'SUMMATIVE'>('FORMATIVE');
  const [currentTime, setCurrentTime] = useState(new Date());

  // Filters
  const [selectedClass, setSelectedClass] = useState<string>('');
  const [selectedSubject, setSelectedSubject] = useState<string>('');

  // KKTP State (Dynamic Parameter)
  const [currentKktp, setCurrentKktp] = useState<number>(75);

  // --- EFFECTS ---

  // 1. Initialize Class
  useEffect(() => {
    if (initialClass) setSelectedClass(initialClass);
  }, [initialClass]);

  // 2. Initialize & Lock Subject based on Identity (POINT 4 OPTIMIZATION)
  useEffect(() => {
      if (identity.role === 'SUBJECT_TEACHER' && identity.subjectName) {
          // Force set subject and lock it logic handles in UI
          setSelectedSubject(identity.subjectName);
      } else if (!selectedSubject) {
          // Default fallback for Class Teacher
          if (identity.level === 'SD') {
              setSelectedSubject(SUBJECTS_DATA.SD.CLASS_TEACHER[0]);
          } else if (identity.level === 'SMP') {
              setSelectedSubject(SUBJECTS_DATA.SMP[0]);
          } else {
              setSelectedSubject(SUBJECTS_DATA.SMA_SMK[0]);
          }
      }
  }, [identity, selectedSubject]);

  // 3. Time Interval
  useEffect(() => {
    const interval = setInterval(() => setCurrentTime(new Date()), 60000);
    return () => clearInterval(interval);
  }, []);

  // --- COMPUTED ---

  const availableClasses = useMemo(() => {
      const classes = new Set(students.map(s => s.className).filter(Boolean));
      return Array.from(classes).sort() as string[];
  }, [students]);

  const filteredStudents = useMemo(() => {
      if (!selectedClass) return [];
      return students.filter(s => s.className === selectedClass).sort((a,b) => a.name.localeCompare(b.name));
  }, [students, selectedClass]);

  // Filter TPs based on Selected Subject
  const filteredTPs = useMemo(() => {
      // In a real app, TPs should have subjectId. 
      // For Subject Teacher, we assume TPs loaded are correct.
      // For Class Teacher, we might need to filter if TPs are mixed.
      // For now returning all TPs assuming parent component filters or TPs are relevant.
      return tps; 
  }, [tps, selectedSubject]);

  const uniqueScopes = useMemo(() => {
      const scopes = new Set<string>();
      filteredTPs.forEach(tp => {
          scopes.add(tp.scope || 'Materi Umum');
      });
      return Array.from(scopes).sort();
  }, [filteredTPs]);

  const tpsByScope = useMemo(() => {
      const grouped: Record<string, LearningObjective[]> = {};
      filteredTPs.forEach(tp => {
          const s = tp.scope || 'Materi Umum';
          if (!grouped[s]) grouped[s] = [];
          grouped[s].push(tp);
      });
      return grouped;
  }, [filteredTPs]);

  // Stats Calculation uses dynamic currentKktp
  const stats = useMemo(() => {
      return filteredStudents.reduce((acc, student) => {
          const res = calculateStudentGrade(student.id, globalGradeData, filteredTPs, currentKktp);
          if (res.finalScore > 0) {
              if (res.isPassed) acc.tuntas++; else acc.remedial++;
          }
          return acc;
      }, { tuntas: 0, remedial: 0 });
  }, [filteredStudents, globalGradeData, filteredTPs, currentKktp]);

  // --- HANDLERS ---

  // Updated: Handle Formative Score (Numeric per TP)
  const handleFormativeScore = useCallback((studentId: string, tpId: string, value: string) => {
      const numValue = value === '' ? undefined : parseFloat(value);

      if (numValue !== undefined && (numValue < 0 || numValue > 100)) return;

      setGlobalGradeData(prev => {
          const sData = prev[studentId] || { formative: {}, summative: {}, attitude: 0 };
          return {
              ...prev,
              [studentId]: {
                  ...sData,
                  formative: {
                      ...(sData.formative || {}),
                      [tpId]: numValue !== undefined ? numValue : 0
                  }
              }
          };
      });
  }, [setGlobalGradeData]);

  const handleSummativeScore = useCallback((studentId: string, scopeName: string, value: string) => {
      const numValue = value === '' ? undefined : parseFloat(value);

      if (numValue !== undefined && (numValue < 0 || numValue > 100)) {
          return; 
      }

      setGlobalGradeData(prev => {
          const sData = prev[studentId] || { formative: {}, summative: {}, attitude: 0 };
          return {
              ...prev,
              [studentId]: {
                  ...sData,
                  summative: {
                      ...(sData.summative || {}),
                      [scopeName]: numValue !== undefined ? numValue : 0
                  }
              }
          };
      });
  }, [setGlobalGradeData]);

  return {
    state: {
      activeTab,
      currentTime,
      selectedClass,
      selectedSubject,
      currentKktp
    },
    setters: {
      setActiveTab,
      setSelectedClass,
      setSelectedSubject,
      setCurrentKktp
    },
    computed: {
      availableClasses,
      filteredStudents,
      uniqueScopes,
      tpsByScope, 
      stats,
      filteredTPs
    },
    handlers: {
      handleFormativeScore,
      handleSummativeScore
    }
  };
};

