                            </div>
                            <div className="flex items-center gap-2">
                                <span className="bg-red-100 text-red-700 px-2 py-1 rounded text-[10px] font-bold">REMEDIAL</span>
                                <span className="text-red-700 font-bold text-sm">{stats.remedial}</span>
                            </div>
