                <span className="size-2 rounded-full bg-green-500 absolute animate-ping opacity-75"></span>
                <span className="size-2 rounded-full bg-green-500 relative block"></span>
            </div>
            Auto-Save Active
        </div>
        <div>
          Last Sync: {state.currentTime.toLocaleTimeString('id-ID', {timeZone: 'Asia/Makassar', hour: '2-digit', minute: '2-digit'})} WITA
        </div>
      </div>
    </div>
  );
};

import { useState, useMemo, useEffect } from 'react';
import ExcelJS from 'exceljs';
import { GoogleGenAI, Type } from "@google/genai";
import { LearningMaterial, LearningObjective, Subject, AssessmentCriteria, IdentityData, AssessmentType, SUBJECTS_DATA } from '../types';

declare const Swal: any;

interface UseCurriculumLogicProps {
  identity: IdentityData;
  tps: LearningObjective[];
  onUpdateTPs: (tps: LearningObjective[]) => void;
}

export const useCurriculumLogic = ({ identity, tps, onUpdateTPs }: UseCurriculumLogicProps) => {
  // --- STATE ---
  const [expandedTpId, setExpandedTpId] = useState<string | null>(null);
  const [generatingTpId, setGeneratingTpId] = useState<string | null>(null);
  const [isAddingTp, setIsAddingTp] = useState(false);
  const [editingTpId, setEditingTpId] = useState<string | null>(null); // NEW: For Edit Mode

  // Forms
  const [newTpForm, setNewTpForm] = useState({ code: '', description: '', semester: '1', scope: '' });
  const [newItemForm, setNewItemForm] = useState<{
      type: 'CRITERIA' | null, 
      parentId: string | null,
      val1: string, 
      val2: string 
  }>({ type: null, parentId: null, val1: '', val2: '' });
  const [newItemType, setNewItemType] = useState<AssessmentType>('FORMATIVE');

  // --- DERIVED SCOPES (Flexible based on Level) ---
  const scopes = useMemo(() => {
      // Default Scopes (Classes)
      if (identity.level === 'SD') {
          return [
              { id: 'Kelas 1', name: 'Kelas 1 (Fase A)' },
              { id: 'Kelas 2', name: 'Kelas 2 (Fase A)' },
              { id: 'Kelas 3', name: 'Kelas 3 (Fase B)' },
              { id: 'Kelas 4', name: 'Kelas 4 (Fase B)' },
              { id: 'Kelas 5', name: 'Kelas 5 (Fase C)' },
              { id: 'Kelas 6', name: 'Kelas 6 (Fase C)' },
          ];
      } else if (identity.level === 'SMP') {
          return [
              { id: 'Kelas 7', name: 'Kelas 7 (Fase D)' },
              { id: 'Kelas 8', name: 'Kelas 8 (Fase D)' },
              { id: 'Kelas 9', name: 'Kelas 9 (Fase D)' },
          ];
      } else { // SMA / SMK
          return [
              { id: 'Kelas 10', name: 'Kelas 10 (Fase E)' },
              { id: 'Kelas 11', name: 'Kelas 11 (Fase F)' },
              { id: 'Kelas 12', name: 'Kelas 12 (Fase F)' },
          ];
      }
  }, [identity.level]);

  // Subject Logic
  const subjectOptions = useMemo(() => {
      if (identity.level === 'SD') {
          return identity.role === 'CLASS_TEACHER' ? SUBJECTS_DATA.SD.CLASS_TEACHER : SUBJECTS_DATA.SD.SUBJECT_TEACHER;
      } else if (identity.level === 'SMP') {
          return SUBJECTS_DATA.SMP;
      } else {
          return SUBJECTS_DATA.SMA_SMK;
      }
  }, [identity.level, identity.role]);

  // Filter States
  const [activeScopeId, setActiveScopeId] = useState<string>(scopes[0].id);

  // Active Subject State
  const [activeSubjectId, setActiveSubjectId] = useState<string>('');

  // Check if active subject is in the predefined list (for "Lainnya" logic)
  const isManualSubject = useMemo(() => {
      return !subjectOptions.some(s => s === activeSubjectId) && activeSubjectId !== '' && activeSubjectId !== 'Lainnya';
  }, [activeSubjectId, subjectOptions]);

  useEffect(() => {
      // Initialize active subject on load
      if (!activeSubjectId) {
          if (identity.role === 'SUBJECT_TEACHER' && identity.subjectName) {
              setActiveSubjectId(identity.subjectName);
          } else {
              setActiveSubjectId(subjectOptions[0]);
          }
      }
  }, [identity, subjectOptions, activeSubjectId]);

  useEffect(() => {
      const exists = scopes.find(s => s.id === activeScopeId);
      if (!exists && scopes.length > 0) setActiveScopeId(scopes[0].id);
  }, [scopes, activeScopeId]);

  const filteredTPs = useMemo(() => {
      return tps.filter(tp => {
          const scopeMatch = tp.scopeId === activeScopeId;
          const subjectMatch = tp.subjectId ? tp.subjectId === activeSubjectId : true; 
          return scopeMatch && subjectMatch;
      });
  }, [tps, activeScopeId, activeSubjectId]);

  // Grouping for View (Hierarchy Down: Scope -> TP)
  const tpsByScope = useMemo(() => {
      const groups: Record<string, LearningObjective[]> = {};
      filteredTPs.forEach(tp => {
          const s = tp.scope || 'Lingkup Materi Umum';
          if (!groups[s]) groups[s] = [];
          groups[s].push(tp);
      });
      return groups;
  }, [filteredTPs]);

  // Unique Scopes for Autocomplete
  const uniqueScopes = useMemo(() => {
      return Array.from(new Set(tps.map(t => t.scope || ''))).filter(Boolean).sort();
  }, [tps]);

  // --- HANDLERS (CRUD) ---

  const handleAddTP = () => {
    if(!newTpForm.description) {
        Swal.fire('Error', 'Deskripsi TP harus diisi.', 'error');
        return;
    }

    // GENERATE STANDARD CODE LOGIC (Format: SUB-PHASE-SEM-NUM)
    // 1. Subject Code (3 Huruf Uppercase)
    const subCode = (activeSubjectId || 'GEN').substring(0, 3).toUpperCase();

    // 2. Phase Code
    const activeScopeObj = scopes.find(s => s.id === activeScopeId);
    const phaseMatch = activeScopeObj?.name.match(/Fase\s+([A-F])/i);
    const phaseCode = phaseMatch ? phaseMatch[1] : 'X';

    // 3. Semester
    const semCode = newTpForm.semester;

    // 4. Index (Count existing TPs in this Subject+Scope+Semester)
    // If editing, keep original code unless user changed it manually
    let finalCode = newTpForm.code;

    if (!finalCode) {
        const existingCount = tps.filter(t => 
            t.subjectId === activeSubjectId && 
            t.scopeId === activeScopeId && 
            t.semester.toString() === semCode
        ).length;
        const nextIndex = existingCount + 1;
        finalCode = `${subCode}-${phaseCode}-${semCode}-${nextIndex}`;
    } else {
        finalCode = finalCode.toUpperCase();
    }

    if (editingTpId) {
        // UPDATE MODE
        const updatedTPs = tps.map(tp => {
            if (tp.id === editingTpId) {
                return {
                    ...tp,
                    code: finalCode,
                    description: newTpForm.description,
                    semester: Number(newTpForm.semester) as 1 | 2,
                    scope: newTpForm.scope || 'Lingkup Materi Umum'
                };
            }
            return tp;
        });
        onUpdateTPs(updatedTPs);
        setEditingTpId(null);
    } else {
        // ADD MODE
        const newTp: LearningObjective = {
            id: Date.now().toString(),
            code: finalCode, 
            description: newTpForm.description,
            semester: Number(newTpForm.semester) as 1 | 2,
            scopeId: activeScopeId,
            subjectId: activeSubjectId, 
            scope: newTpForm.scope || 'Lingkup Materi Umum',
            lms: [],
            criteria: []
        };
        onUpdateTPs([...tps, newTp]);
    }

    setIsAddingTp(false);
    setNewTpForm({ code: '', description: '', semester: '1', scope: '' });
  };

  const handleEditTP = (tp: LearningObjective) => {
      setNewTpForm({
          code: tp.code,
          description: tp.description,
          semester: tp.semester ? tp.semester.toString() : '1',
          scope: tp.scope || ''
      });
      setEditingTpId(tp.id);
      setIsAddingTp(true);
      window.scrollTo({ top: 0, behavior: 'smooth' }); // Scroll to form
  };

  const handleCancelEdit = () => {
      setIsAddingTp(false);
      setEditingTpId(null);
      setNewTpForm({ code: '', description: '', semester: '1', scope: '' });
  };

  const handleDeleteTP = (id: string) => {
      Swal.fire({
          title: 'Hapus Tujuan Pembelajaran?',
          text: "Seluruh Kriteria yang ada di dalamnya akan ikut terhapus!",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateTPs(tps.filter(t => t.id !== id));
              Swal.fire('Terhapus!', 'TP berhasil dihapus.', 'success')
          }
      });
  };

  const handleAddItem = () => {
      if(!newItemForm.val1 || !newItemForm.val2 || !newItemForm.parentId || !newItemForm.type) return;

      const updatedTPs = tps.map(tp => {
          if(tp.id === newItemForm.parentId) {
              return {
                  ...tp,
                  criteria: [...tp.criteria, { 
                      id: Date.now().toString(), 
                      code: newItemForm.val1.toUpperCase(), 
                      description: newItemForm.val2,
                      type: newItemType 
                  }]
              };
          }
          return tp;
      });

      onUpdateTPs(updatedTPs);
      setNewItemForm({ type: null, parentId: null, val1: '', val2: '' });
      setNewItemType('FORMATIVE');
  };

  const handleDeleteSubItem = (tpId: string, itemId: string, type: 'CRITERIA') => {
      Swal.fire({
          title: 'Hapus Item?',
          text: "Item ini akan dihapus permanen.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          cancelButtonText: 'Batal'
      }).then((result: any) => {
          if (result.isConfirmed) {
              const updatedTPs = tps.map(tp => {
                  if(tp.id === tpId) {
                      return { ...tp, criteria: tp.criteria.filter(c => c.id !== itemId) };
                  }
                  return tp;
              });
              onUpdateTPs(updatedTPs);
          }
      });
  };

  // --- AI GENERATION (KRITERIA ONLY) ---
  const generateTpDetails = async (tp: LearningObjective) => {
      if (tp.criteria.length > 0) {
          const result = await Swal.fire({
              title: 'TP Sudah Memiliki Kriteria',
              text: "Melanjutkan akan menambahkan kriteria baru. Lanjutkan?",
              icon: 'warning',
              showCancelButton: true,
              confirmButtonText: 'Ya, Tambahkan',
              cancelButtonText: 'Batal'
          });
          if (!result.isConfirmed) return;
      }

      setGeneratingTpId(tp.id);

      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
          const prompt = `
            Role: Expert Curriculum Developer for Indonesian School (Kurikulum Merdeka).
            Context: Subject '${activeSubjectId}' for Grade '${activeScopeId}'.
            Task: Based on the Learning Objective (TP) below, generate strictly:

            2 to 3 specific 'Assessment Criteria' (Kriteria Ketercapaian Tujuan Pembelajaran / KKTP). 
            - These are indicators to check if student achieved the TP.
            - Keep it concise.

            TP Description: "${tp.description}" (Code: ${tp.code})
            Scope: "${tp.scope}"

            Output must be valid JSON object with array 'criteria'.
          `;

          const response = await ai.models.generateContent({
              model: "gemini-3-flash-preview",
              contents: prompt,
              config: {
                  responseMimeType: "application/json",
                  responseSchema: {
                      type: Type.OBJECT,
                      properties: {
                          criteria: {
                              type: Type.ARRAY,
                              items: {
                                  type: Type.OBJECT,
                                  properties: {
                                      code: { type: Type.STRING },
                                      description: { type: Type.STRING },
                                      type: { type: Type.STRING, enum: ["FORMATIVE", "SUMMATIVE"] }
                                  }
                              }
                          }
                      }
                  }
              }
          });

          const json = JSON.parse(response.text || '{}');

          if (json.criteria) {
              const newCriteria: AssessmentCriteria[] = json.criteria.map((cr: any, idx: number) => ({
                  id: `gen-cr-${Date.now()}-${idx}`,
                  code: cr.code || `KR.${tp.criteria.length + idx + 1}`,
                  description: cr.description,
                  type: (cr.type === 'SUMMATIVE' ? 'SUMMATIVE' : 'FORMATIVE') as AssessmentType
              }));

              const updatedTPs = tps.map(t => {
                  if (t.id === tp.id) {
                      return {
                          ...t,
                          criteria: [...t.criteria, ...newCriteria]
                      };
                  }
                  return t;
              });

              onUpdateTPs(updatedTPs);
              setExpandedTpId(tp.id);
              Swal.fire({
                  title: 'Generate Berhasil',
                  text: `Ditambahkan ${newCriteria.length} Kriteria Penilaian.`,
                  icon: 'success',
                  timer: 2000
              });
          }

      } catch (error: any) {
          console.error(error);
          Swal.fire('Gagal Generate', error.message, 'error');
      } finally {
          setGeneratingTpId(null);
      }
  };

  // --- EXPORT ---
  const handleExportCurriculum = async () => {
    if (filteredTPs.length === 0) return;

    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet('Kurikulum');

    const headerRow = sheet.addRow([
        'No', 'Semester', 'Mata Pelajaran', 'Lingkup Materi (Scope)', 'Kelas', 'Kode TP', 'Tujuan Pembelajaran (TP)', 'Kriteria Ketercapaian (KKTP)'
    ]);

    headerRow.eachCell((cell) => {
        cell.font = { bold: true, color: { argb: 'FFFFFFFF' } };
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF137FEC' } };
        cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
        cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
    });

    const activeScopeName = scopes.find(s => s.id === activeScopeId)?.name || activeScopeId;
    let rowIndex = 1;

    filteredTPs.forEach((tp) => {
        if (tp.criteria.length > 0) {
            tp.criteria.forEach(cr => {
                const row = sheet.addRow([
                    rowIndex, `Semester ${tp.semester}`, activeSubjectId, tp.scope || 'Umum', activeScopeName,
                    tp.code, tp.description, `[${cr.type}] ${cr.description}`
                ]);
                row.eachCell((cell) => {
                    cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                    cell.alignment = { vertical: 'top', wrapText: true };
                });
            });
        } else {
             const row = sheet.addRow([
                    rowIndex, `Semester ${tp.semester}`, activeSubjectId, tp.scope || 'Umum', activeScopeName,
                    tp.code, tp.description, '-'
            ]);
            row.eachCell((cell) => {
                cell.border = { top: {style:'thin'}, left: {style:'thin'}, bottom: {style:'thin'}, right: {style:'thin'} };
                cell.alignment = { vertical: 'top', wrapText: true };
            });
        }
        rowIndex++;
    });

    sheet.getColumn(7).width = 50;
    sheet.getColumn(8).width = 40;
    sheet.getColumn(3).width = 20;
    sheet.getColumn(4).width = 25;

    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = window.URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `Kurikulum_Kriteria_${activeScopeName.replace(/\s/g, '_')}_${activeSubjectId}.xlsx`;
    anchor.click();
    window.URL.revokeObjectURL(url);

    Swal.fire({
        title: 'Export Berhasil!',
        text: 'Data Kurikulum & KKTP telah berhasil diunduh.',
        icon: 'success',
        timer: 2000,
        showConfirmButton: false
    });
  };

  return {
    state: {
        expandedTpId,
        generatingTpId,
        isAddingTp,
        newTpForm,
        newItemForm,
        newItemType,
        activeScopeId,
        activeSubjectId,
        isManualSubject,
        scopes,
        subjectOptions,
        uniqueScopes, // Export for autocomplete
        editingTpId // Exported state
    },
    setters: {
        setExpandedTpId,
        setIsAddingTp,
        setNewTpForm,
        setNewItemForm,
        setNewItemType,
        setActiveScopeId,
        setActiveSubjectId
    },
    computed: {
        filteredTPs,
        tpsByScope // Export grouped data
    },
    handlers: {
        handleAddTP,
        handleDeleteTP,
        handleAddItem,
        handleDeleteSubItem,
        generateTpDetails,
        handleExportCurriculum,
        handleEditTP, // Exported handler
        handleCancelEdit // Exported handler
    }
  };
};

import React, { useState, useMemo, useEffect } from 'react';
import { LearningObjective, AssessmentCriteria, IdentityData, SUBJECTS_DATA } from '../types';
import { GoogleGenAI, Type } from "@google/genai";

declare const Swal: any;

interface Props {
  onSave: (tps: LearningObjective[]) => void;
  onBack: () => void;
  identity?: IdentityData; // Added identity prop
}

// Data Mapping Fase ke Kelas
const PHASE_MAP: { [key: string]: string[] } = {
    'Fase A': ['Kelas 1', 'Kelas 2'],
    'Fase B': ['Kelas 3', 'Kelas 4'],
    'Fase C': ['Kelas 5', 'Kelas 6'],
    'Fase D': ['Kelas 7', 'Kelas 8', 'Kelas 9'],
    'Fase E': ['Kelas 10'],
    'Fase F': ['Kelas 11', 'Kelas 12'],
};

// Map Level to Default Phase
const LEVEL_TO_PHASE_MAP: { [key: string]: string } = {
    'SD': 'Fase A',
    'SMP': 'Fase D',
    'SMA': 'Fase E',
    'SMK': 'Fase E'
};

interface AllocationItem {
    id: string;
    code: string;
    description: string;
    level: string; // Cognitive Level
    topicTitle: string; 
    container: string; // 'BANK' or 'ClassName-Semester'
    criteria: { description: string }[]; 
}

export const CPGenerator: React.FC<Props> = ({ onSave, onBack, identity }) => {
  // Input State
  const [phase, setPhase] = useState('Fase E'); 
  const [selectedSubject, setSelectedSubject] = useState('Matematika'); 
  const [cpText, setCpText] = useState('');

  // Data State
  const [isGenerating, setIsGenerating] = useState(false);
  const [allocatedItems, setAllocatedItems] = useState<AllocationItem[]>([]);

  // Drag State
  const [draggedItemId, setDraggedItemId] = useState<string | null>(null);

  // Derive Subject Options based on identity if available, else default to SMA
  const subjectOptions = useMemo(() => {
      if (!identity) return SUBJECTS_DATA.SMA_SMK;
      if (identity.level === 'SD') return identity.role === 'CLASS_TEACHER' ? SUBJECTS_DATA.SD.CLASS_TEACHER : SUBJECTS_DATA.SD.SUBJECT_TEACHER;
      if (identity.level === 'SMP') return SUBJECTS_DATA.SMP;
      return SUBJECTS_DATA.SMA_SMK;
  }, [identity]);

  // --- AUTO FILL EFFECT ---
  useEffect(() => {
      if (identity) {
          // Auto Phase
          if (identity.level && LEVEL_TO_PHASE_MAP[identity.level]) {
              setPhase(LEVEL_TO_PHASE_MAP[identity.level]);
          }
          // Auto Subject (if subject teacher)
          if (identity.role === 'SUBJECT_TEACHER' && identity.subjectName) {
              if (subjectOptions.includes(identity.subjectName)) {
                  setSelectedSubject(identity.subjectName);
              }
          }
      }
  }, [identity, subjectOptions]);

  // --- COMPUTED ---
  const targetClasses = useMemo(() => PHASE_MAP[phase] || [], [phase]);

  // --- AI GENERATION LOGIC ---
  const handleGenerate = async () => {
    if (!cpText.trim()) {
        Swal.fire('Error', 'Teks CP tidak boleh kosong.', 'error');
        return;
    }

    setIsGenerating(true);
    setAllocatedItems([]); 

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const prompt = `
        Role: Expert Curriculum Developer (Kurikulum Merdeka Indonesia).
        Task: Analyze the Capaian Pembelajaran (CP) text below for Subject '${selectedSubject}' in '${phase}'.

        Instructions:
        1. Break down the CP into distinct "Lingkup Materi" (Scope/Topics).
        2. For each Scope, generate specific "Tujuan Pembelajaran" (TP).
        3. For each TP, provide 2-3 "Kriteria Ketercapaian" (KKTP/Indicators).
        4. Determine the Cognitive Level (e.g., C1, C2, C3, C4, C5, C6) based on Bloom's Taxonomy.

        Format the output strictly as a JSON Array.

        CP Text: "${cpText}"
        `;

        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            lingkup_materi: { type: Type.STRING },
                            tps: {
                                type: Type.ARRAY,
                                items: {
                                    type: Type.OBJECT,
                                    properties: {
                                        kode_tp: { type: Type.STRING, description: "Short code like TP.1" },
                                        deskripsi: { type: Type.STRING },
                                        level_kognitif: { type: Type.STRING },
                                        kktp: { 
                                            type: Type.ARRAY, 
                                            items: { type: Type.STRING } 
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        });

        const rawData = JSON.parse(response.text || '[]');

        // Transform to internal state -> Put into 'BANK' initially
        const newAllocations: AllocationItem[] = [];
        let globalTpIndex = 1;

        rawData.forEach((topic: any) => {
            topic.tps.forEach((tp: any) => {
                newAllocations.push({
                    id: `gen-tp-${Date.now()}-${globalTpIndex}`,
                    code: `TP.${globalTpIndex}`,
                    description: tp.deskripsi,
                    level: tp.level_kognitif,
                    topicTitle: topic.lingkup_materi,
                    container: 'BANK', // Default to Staging Area
                    criteria: (tp.kktp || []).map((k: string) => ({ description: k }))
                });
                globalTpIndex++;
            });
        });

        setAllocatedItems(newAllocations);
        Swal.fire({
            title: 'Analisa Selesai',
            text: `Berhasil mengidentifikasi ${rawData.length} Lingkup Materi dan ${newAllocations.length} TP. Silahkan distribusikan ke kelas.`,
            icon: 'success'
        });

    } catch (error: any) {
        console.error("AI Error:", error);
        Swal.fire('Gagal', error.message, 'error');
    } finally {
        setIsGenerating(false);
    }
  };

  // --- DRAG & DROP LOGIC ---

  const onDragStart = (e: React.DragEvent, itemId: string) => {
      setDraggedItemId(itemId);
      e.dataTransfer.setData('text/plain', itemId);
      e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
  };

  const onDrop = (e: React.DragEvent, targetContainer: string) => {
      e.preventDefault();
      if (!draggedItemId) return;

      setAllocatedItems(prev => prev.map(item => {
          if (item.id === draggedItemId) {
              return { ...item, container: targetContainer };
          }
          return item;
      }));

      setDraggedItemId(null);
  };

  const handleDeleteItem = (id: string) => {
      setAllocatedItems(prev => prev.filter(i => i.id !== id));
  };

  // --- SAVE & RESET ---

  const handleReset = () => {
      Swal.fire({
          title: 'Reset Generator?',
          text: "Semua hasil generate akan dihapus.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          confirmButtonText: 'Ya, Reset'
      }).then((result: any) => {
          if (result.isConfirmed) {
              setAllocatedItems([]);
              setCpText('');
          }
      });
  };

  const handleSaveAll = () => {
      // Filter items that are actually distributed (not in BANK)
      const distributedItems = allocatedItems.filter(i => i.container !== 'BANK');

      if (distributedItems.length === 0) {
          Swal.fire('Belum Ada Distribusi', 'Silahkan drag TP dari Bank TP ke Kelas/Semester terlebih dahulu.', 'warning');
          return;
      }

      // Grouping to generate standard codes
      // Format: SubjectCode-PhaseCode-Sem-Index
      const subjectCode = selectedSubject.substring(0, 3).toUpperCase();
      const phaseCode = phase.split(' ')[1] || 'X'; // "Fase E" -> "E"

      // Track index per group (Scope + Semester) to maintain sequence
      const sequenceTracker: Record<string, number> = {};

      // Final transformation
      const finalTPs: LearningObjective[] = distributedItems.map(item => {
          // Parse container string "ClassName-Semester" -> e.g. "Kelas 10-1"
          const [className, semesterStr] = item.container.split('::');

          // Generate Key for sequence: ClassName-Semester
          const key = `${className}-${semesterStr}`;
          if (!sequenceTracker[key]) sequenceTracker[key] = 0;
          sequenceTracker[key]++;

          // GENERATE STANDARD CODE
          const code = `${subjectCode}-${phaseCode}-${semesterStr}-${sequenceTracker[key]}`;

          const criteriaObjects: AssessmentCriteria[] = item.criteria.map((c, idx) => ({
              id: `auto-crit-${item.id}-${idx}`,
              code: `KKTP.${idx + 1}`,
              description: c.description,
              type: 'FORMATIVE'
          }));

          return {
              id: item.id,
              code: code,
              description: item.description,
              semester: parseInt(semesterStr) as 1 | 2,
              scopeId: className, // Stores Class Name as ScopeID for curriculum mapping
              subjectId: selectedSubject,
              scope: item.topicTitle, 
              lms: [], 
              criteria: criteriaObjects
          };
      });

      onSave(finalTPs);
  };

  // Helper Styles
  const getBloomColor = (level: string) => {
      if (['C1', 'C2'].some(l => level.includes(l))) return 'bg-green-100 text-green-700 border-green-200';
      if (['C3', 'C4'].some(l => level.includes(l))) return 'bg-blue-100 text-blue-700 border-blue-200';
      return 'bg-purple-100 text-purple-700 border-purple-200';
  };

  return (
    <div className="flex flex-col h-[calc(100vh-80px)] bg-slate-50"> 
        {/* TOP CONFIGURATION BAR */}
        <div className="bg-white border-b border-slate-200 p-5 shadow-sm z-30 shrink-0">
            <div className="max-w-[1800px] mx-auto">
                <div className="flex items-start gap-6">

                    {/* INPUTS */}
                    <div className="flex-1 grid grid-cols-12 gap-6">
                        <div className="col-span-3 space-y-4">
                            <div className="space-y-1">
                                <label className="text-[10px] font-bold text-slate-500 uppercase">Fase</label>
                                <select 
                                    value={phase} 
                                    onChange={e => setPhase(e.target.value)} 
                                    className="w-full border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-primary py-2"
                                >
                                    {Object.keys(PHASE_MAP).map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                            <div className="space-y-1">
                                <label className="text-[10px] font-bold text-slate-500 uppercase">Mata Pelajaran</label>
                                <select 
                                    value={selectedSubject} 
                                    onChange={e => setSelectedSubject(e.target.value)} 
                                    className="w-full border-slate-300 rounded-lg text-sm font-bold text-slate-800 focus:ring-primary py-2"
                                >
                                    {subjectOptions.map(subj => (
                                        <option key={subj} value={subj}>{subj}</option>
                                    ))}
                                </select>
                            </div>
                        </div>

                        <div className="col-span-9 space-y-1 flex flex-col h-full">
                            <div className="flex justify-between items-center">
                                <label className="text-[10px] font-bold text-slate-500 uppercase">Capaian Pembelajaran (CP) - <span className="text-primary normal-case">Copy paste teks CP dari dokumen kurikulum</span></label>
                                <a 
                                    href="https://uploads.belajar.id/document/files/Kepka_BSKAP_No_01k17e8396ajn15j3hcw0k773b.pdf" 
                                    target="_blank" 
                                    rel="noreferrer"
                                    className="text-[10px] font-bold text-blue-600 hover:text-blue-800 flex items-center gap-1 bg-blue-50 px-2 py-0.5 rounded border border-blue-200"
                                >
                                    <span className="material-symbols-outlined text-sm">open_in_new</span>
                                    Lihat CP Terbaru
                                </a>
                            </div>
                            <textarea 
                                value={cpText}
                                onChange={e => setCpText(e.target.value)}
                                placeholder="Paste naskah CP di sini..."
                                className="w-full border-slate-300 rounded-lg text-xs text-slate-700 p-3 focus:ring-primary resize-none h-24"
                            ></textarea>
                        </div>
                    </div>

                    {/* ACTION BUTTONS */}
                    <div className="flex flex-col gap-2 w-48 shrink-0">
                        <button 
                            onClick={handleGenerate}
                            disabled={isGenerating}
                            className={`w-full py-3 rounded-xl font-bold text-white text-sm shadow-md transition-all flex justify-center items-center gap-2 h-14
                                ${isGenerating ? 'bg-slate-400 cursor-not-allowed' : 'bg-gradient-to-r from-primary to-blue-600 hover:shadow-lg hover:scale-[1.02]'}
                            `}
                        >
                            {isGenerating ? (
                                <>
                                    <span className="size-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
                                    Menganalisa...
                                </>
                            ) : (
                                <>
                                    <span className="material-symbols-outlined text-xl">psychology</span>
                                    Generate TP
                                </>
                            )}
                        </button>
                    </div>
                </div>
            </div>
        </div>

        {/* MAIN WORKSPACE */}
        <div className="flex-1 flex overflow-hidden">

            {/* LEFT PANEL: STAGING / BANK TP */}
            <div className="w-[350px] bg-white border-r border-slate-200 flex flex-col shrink-0 z-20 shadow-lg">
                <div className="p-4 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                    <div>
                        <h3 className="font-bold text-slate-800 flex items-center gap-2">
                            <span className="material-symbols-outlined text-orange-500">inventory_2</span>
                            Bank TP
                        </h3>
                        <p className="text-[10px] text-slate-500">Hasil generate AI masuk di sini</p>
                    </div>
                    <span className="bg-orange-100 text-orange-700 px-2 py-1 rounded text-xs font-bold">
                        {allocatedItems.filter(i => i.container === 'BANK').length} Item
                    </span>
                </div>

                <div 
                    className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-100/50 custom-scrollbar"
                    onDragOver={onDragOver}
                    onDrop={(e) => onDrop(e, 'BANK')}
                >
                    {allocatedItems.filter(i => i.container === 'BANK').length === 0 && (
                        <div className="flex flex-col items-center justify-center h-40 text-slate-400 text-center p-4 border-2 border-dashed border-slate-200 rounded-xl">
                            <span className="material-symbols-outlined text-3xl mb-2">auto_awesome</span>
                            <p className="text-xs">Hasil generate akan muncul di sini.</p>
                        </div>
                    )}

                    {allocatedItems.filter(i => i.container === 'BANK').map(item => (
                        <div 
                            key={item.id} 
                            draggable
                            onDragStart={(e) => onDragStart(e, item.id)}
                            className="bg-white p-3 rounded-xl border border-slate-200 shadow-sm text-xs relative group cursor-grab active:cursor-grabbing hover:border-orange-400 hover:shadow-md transition-all"
                        >
                            <div className="flex justify-between items-start mb-2">
                                <span className={`text-[9px] px-1.5 py-0.5 rounded font-bold border ${getBloomColor(item.level)}`}>{item.level}</span>
                                <div className="flex gap-1">
                                    <span className="material-symbols-outlined text-slate-300 text-base">drag_indicator</span>
                                </div>
                            </div>
                            <p className="text-slate-800 font-medium leading-snug mb-2">{item.description}</p>
                            <div className="pt-2 border-t border-slate-100 flex items-center gap-1 text-[10px] text-slate-500">
                                <span className="material-symbols-outlined text-[12px] text-blue-500">topic</span>
                                <span className="truncate font-bold">{item.topicTitle}</span>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* RIGHT PANEL: DISTRIBUTION BOARD */}
            <div className="flex-1 overflow-x-auto overflow-y-hidden bg-slate-50 p-6">
                <div className="flex gap-6 h-full min-w-max">
                    {targetClasses.map((clsName) => (
