                                                                )) : (
                                                                    <tr>
                                                                        <td colSpan={4} className="px-4 py-8 text-center text-slate-400 italic text-xs">Belum ada kriteria penilaian. Gunakan Generate AI di atas atau tambah manual.</td>
                                                                    </tr>
