import { useState, useEffect, useMemo } from 'react';
import ExcelJS from 'exceljs';
import { JournalEntry, LearningObjective, ScheduleItem, ClassInfo } from '../types';

declare const Swal: any;

interface UseJournalLogicProps {
  journals: JournalEntry[];
  onUpdateJournals: (journals: JournalEntry[]) => void;
  tps: LearningObjective[];
  schedules: ScheduleItem[];
  classes: ClassInfo[];
  initialContext?: { className?: string, scheduleId?: string };
}

export const useJournalLogic = ({
  journals,
  onUpdateJournals,
  tps,
  schedules,
  classes,
  initialContext
}: UseJournalLogicProps) => {
  // --- STATE ---
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // FILTER STATES
  const [filterClass, setFilterClass] = useState<string>('');
  const [filterSubject, setFilterSubject] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');

  // Default Form Data
  const [formData, setFormData] = useState<Omit<JournalEntry, 'id' | 'created_at'>>({
      date: new Date().toISOString().split('T')[0],
      className: '',
      scheduleId: '',
      subjectName: '', 
      startTime: '',
      endTime: '',
      tpId: '',
      lmId: '',
      activity: '',
      reflection: '',
      followUp: ''
  });

  // --- DERIVED LISTS ---
  const availableClasses = useMemo(() => {
      return [...new Set(schedules.map(s => s.className))].sort();
  }, [schedules]);

  const availableSubjects = useMemo(() => {
      return [...new Set(schedules.map(s => s.subject))].sort();
  }, [schedules]);

  const filteredJournals = useMemo(() => {
      return journals.filter(j => {
          const matchClass = filterClass ? j.className === filterClass : false;
          const matchSubject = filterSubject ? j.subjectName === filterSubject : false;
          const query = searchQuery.toLowerCase();
          const matchSearch = j.activity.toLowerCase().includes(query) || 
                              j.reflection.toLowerCase().includes(query);
          return matchClass && matchSubject && matchSearch;
      }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [journals, filterClass, filterSubject, searchQuery]);

  const activeTP = useMemo(() => tps.find(tp => tp.id === formData.tpId), [formData.tpId, tps]);

  // FIXED: Strictly use LMs from Curriculum (No Virtual Fallback)
  const availableLMs = useMemo(() => {
      if (!activeTP) return [];
      return activeTP.lms || []; 
  }, [activeTP]);

  // --- EFFECTS ---
  useEffect(() => {
    if (initialContext?.scheduleId && !isModalOpen) {
        const schedule = schedules.find(s => s.id === initialContext.scheduleId);
        if (schedule) {
            setFormData({
                date: new Date().toISOString().split('T')[0],
                className: schedule.className,
                scheduleId: schedule.id,
                subjectName: schedule.subject,
                startTime: schedule.startTime,
                endTime: schedule.endTime,
                tpId: '',
                lmId: '',
                activity: '',
                reflection: '',
                followUp: ''
            });
            setIsModalOpen(true);
        }
    }
    if (initialContext?.className) setFilterClass(initialContext.className);
    if (initialContext?.scheduleId) {
        const schedule = schedules.find(s => s.id === initialContext.scheduleId);
        if(schedule) setFilterSubject(schedule.subject);
    }
  }, [initialContext, schedules]);

  // --- HANDLERS ---

  const handleScheduleChange = (scheduleId: string) => {
      const schedule = schedules.find(s => s.id === scheduleId);
      if (schedule) {
          setFormData(prev => ({
              ...prev,
              scheduleId: schedule.id,
              className: schedule.className,
              subjectName: schedule.subject,
              startTime: schedule.startTime,
              endTime: schedule.endTime
          }));
      } else {
          setFormData(prev => ({ 
              ...prev, scheduleId: '', className: '', subjectName: '', startTime: '', endTime: '' 
          }));
      }
  };

  const handleSave = (e: React.FormEvent) => {
      e.preventDefault();

      if (!formData.scheduleId) {
          Swal.fire('Error', 'Wajib memilih Jadwal Mengajar.', 'error');
          return;
      }
      if (!formData.date || !formData.className || !formData.tpId || !formData.activity) {
          Swal.fire('Error', 'Tanggal, Kelas, TP, dan Kegiatan wajib diisi.', 'error');
          return;
      }

      if (editingId) {
          const updated = journals.map(j => j.id === editingId ? { ...j, ...formData } : j);
          onUpdateJournals(updated);
          Swal.fire('Berhasil', 'Jurnal berhasil diperbarui.', 'success');
      } else {
          const newEntry: JournalEntry = {
              id: Date.now().toString(),
              created_at: new Date().toISOString(),
              ...formData
          };
          onUpdateJournals([newEntry, ...journals]);
          Swal.fire('Berhasil', 'Jurnal baru berhasil disimpan.', 'success');
      }
      setIsModalOpen(false);
      setEditingId(null);
  };

  const handleEdit = (journal: JournalEntry) => {
      setEditingId(journal.id);
      setFormData({ ...journal });
      setIsModalOpen(true);
  };

  const handleDelete = (id: string) => {
      Swal.fire({
          title: 'Hapus Jurnal?',
          text: "Data yang dihapus tidak dapat dikembalikan.",
          icon: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          confirmButtonText: 'Ya, Hapus'
      }).then((result: any) => {
          if (result.isConfirmed) {
              onUpdateJournals(journals.filter(j => j.id !== id));
              Swal.fire('Terhapus', 'Jurnal berhasil dihapus.', 'success');
          }
      });
  };

  const handleExportWord = () => {
    if (filteredJournals.length === 0) return;

    // We assume data is loaded from storage wrapper
    const savedDataStr = localStorage.getItem(Object.keys(localStorage).find(k => k.startsWith('siguru_data_')) || '');
    let identity = { schoolName: 'Nama Sekolah', teacherName: 'Nama Guru', nip: 'NIP...', principalName: 'Kepala Sekolah', principalNip: 'NIP Kepsek' };
    if (savedDataStr) {
        const parsed = JSON.parse(savedDataStr);
        if (parsed.identity) identity = parsed.identity;
    }

    const title = `JURNAL KEGIATAN PEMBELAJARAN`;
    const subtitle = `KELAS ${filterClass || 'SEMUA'} - ${filterSubject || 'SEMUA'}`;

    // HTML TEMPLATE FOR WORD
    let html = `
    <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
    <head><meta charset='utf-8'><title>Jurnal Guru</title>
    <style>
        @page Section1 {
            size: 595.45pt 841.7pt; /* A4 Portrait */
            margin: 1.5cm 1.5cm 1.5cm 1.5cm;
            mso-header-margin: 0.5in; 
            mso-footer-margin: 0.5in; 
            mso-paper-source: 0;
        }
        div.Section1 { page: Section1; }
        body { font-family: 'Times New Roman', serif; font-size: 11pt; }
        h1, h2 { text-align: center; margin: 0; padding: 0; }
        h1 { font-size: 14pt; font-weight: bold; }
        h2 { font-size: 12pt; font-weight: bold; margin-bottom: 10px; }
        table { border-collapse: collapse; width: 100%; margin-bottom: 20px; }
        td, th { border: 1px solid black; padding: 5px; vertical-align: top; }
        th { background-color: #f0f0f0; font-weight: bold; text-align: center; }
        .signature-table { border: none; width: 100%; margin-top: 30px; page-break-inside: avoid; }
        .signature-table td { border: none; text-align: center; padding: 0; }
    </style>
    </head>
    <body>
    <div class=Section1>
        <h1>${identity.schoolName}</h1>
        <h2>${title}<br/>${subtitle}</h2>
        <br/>
        <table>
            <thead>
                <tr>
                    <th style='width: 5%'>No</th>
                    <th style='width: 15%'>Hari / Tgl</th>
                    <th style='width: 15%'>Kelas / Jam</th>
                    <th style='width: 35%'>Uraian Kegiatan / Materi</th>
                    <th style='width: 30%'>Catatan (Refleksi & TL)</th>
                </tr>
            </thead>
            <tbody>
    `;

    filteredJournals.forEach((j, i) => {
        const dateStr = new Date(j.date).toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
        const tp = tps.find(t => t.id === j.tpId);

        html += `
            <tr>
                <td style='text-align: center'>${i + 1}</td>
                <td>${dateStr}</td>
                <td>
                    <b>${j.className}</b><br/>
                    ${j.startTime} - ${j.endTime}<br/>
                    <span style='font-size: 9pt'>${j.subjectName}</span>
                </td>
                <td>
                    <b>TP: ${tp ? tp.code : '-'}</b><br/>
                    ${j.activity}
                </td>
                <td>
                    <b>Refleksi:</b><br/>${j.reflection || '-'}<br/><br/>
                    <b>Tindak Lanjut:</b><br/>${j.followUp || '-'}
                </td>
            </tr>
        `;
    });

    html += `
            </tbody>
        </table>

        <table class="signature-table">
            <tr>
                <td style="width: 70%"></td>
                <td style="width: 30%">
                    Mengetahui,<br/>
                    Kepala Sekolah
                    <br/><br/><br/><br/>
                    <b><u>${identity.principalName || '..........................'}</u></b><br/>
                    NIP. ${identity.principalNip || '..........................'}
                </td>
            </tr>
            <tr>
                <td colspan="2" style="text-align: left; padding-top: 20px;">
                    Guru Mata Pelajaran
                    <br/><br/><br/><br/>
                    <b><u>${identity.teacherName}</u></b><br/>
                    NIP. ${identity.nip || '-'}
                </td>
            </tr>
        </table>
    </div></body></html>`;

    const blob = new Blob(['\ufeff', html], {
        type: 'application/msword'
    });

    // Create download link
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `Jurnal_${filterClass || 'All'}_${new Date().toISOString().split('T')[0]}.doc`; 
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    Swal.fire('Export Berhasil', 'Jurnal berhasil diunduh dalam format Word.', 'success');
  };

  const closeModal = () => {
      setIsModalOpen(false);
      setEditingId(null);
      setFormData({
          date: new Date().toISOString().split('T')[0],
          className: '',
          scheduleId: '',
          subjectName: '',
          startTime: '',
          endTime: '',
          tpId: '',
          lmId: '',
          activity: '',
          reflection: '',
          followUp: ''
      });
  };

  return {
    state: { isModalOpen, editingId, filterClass, filterSubject, searchQuery, formData },
    setters: { setIsModalOpen, setFilterClass, setFilterSubject, setSearchQuery, setFormData },
    computed: { availableClasses, availableSubjects, filteredJournals, activeTP, availableLMs },
    handlers: { 
        handleScheduleChange, 
        handleSave, 
        handleEdit, 
        handleDelete, 
        handleExportWord,
        closeModal
    }
  };
};

